    public int numMagicSquaresInside(int[][] grid) {
        if (grid == null || grid.length < 3 || grid[0].length < 3) {
            return 0;
        }
        int m = grid.length;
        int n = grid[0].length;
        int count = 0;
        for (int i = 0; i <= m - 3; i++) {
            for (int j = 0; j <= n - 3; j++) {
                if (isMagic(grid, i, j)) {
                    count++;
                }
            }
        }
        return count;
    }

    private boolean isMagic(int[][] g, int r, int c) {
        // Center must be 5
        if (g[r + 1][c + 1] != 5) {
            return false;
        }

        // Check distinctness and range 1-9
        boolean[] seen = new boolean[10];
        for (int i = r; i < r + 3; i++) {
            for (int j = c; j < c + 3; j++) {
                int val = g[i][j];
                if (val < 1 || val > 9 || seen[val]) {
                    return false;
                }
                seen[val] = true;
            }
        }

        int target = g[r][c] + g[r][c + 1] + g[r][c + 2];
        // Rows
        if (g[r + 1][c] + g[r + 1][c + 1] + g[r + 1][c + 2] != target) return false;
        if (g[r + 2][c] + g[r + 2][c + 1] + g[r + 2][c + 2] != target) return false;
        // Columns
        if (g[r][c] + g[r + 1][c] + g[r + 2][c] != target) return false;
        if (g[r][c + 1] + g[r + 1][c + 1] + g[r + 2][c + 1] != target) return false;
        if (g[r][c + 2] + g[r + 1][c + 2] + g[r + 2][c + 2] != target) return false;
        // Diagonals
        if (g[r][c] + g[r + 1][c + 1] + g[r + 2][c + 2] != target) return false;
        if (g[r][c + 2] + g[r + 1][c + 1] + g[r + 2][c] != target) return false;

        return true;
    }
}

