            int sum = g[i][c] + g[i][c + 1] + g[i][c + 2];
            if (sum != magicSum) return false;
        }

        // Check columns
        for (int j = c; j < c + 3; j++) {
            int sum = g[r][j] + g[r + 1][j] + g[r + 2][j];
