        int[][] sub = new int[3][3];
        Set<Integer> seen = new HashSet<>(9);
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                int val = grid[r + i][c + j];
                if (val < 1 || val > 9) return false;
                if (!seen.add(val)) return false;
