        int target = 15;
        // rows
        for (int i = 0; i < 3; i++) {
            int sum = sub[i][0] + sub[i][1] + sub[i][2];
            if (sum != target) return false;
        }
        // columns
        for (int j = 0; j < 3; j++) {
            int sum = sub[0][j] + sub[1][j] + sub[2][j];
