                if (isMagicSquare(grid, i, j)) {
                    count++;
                }
            }
        }

        return count;
    }

    private boolean isMagicSquare(int[][] grid, int r, int c) {
        // Check distinctness and range 1-9
        Set<Integer> seen = new HashSet<>();
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                int val = grid[r + i][c + j];
                if (val < 1 || val > 9 || !seen.add(val)) {
                    return false;
                }
            }
        }

        // Check row sums
        for (int i = 0; i < 3; i++) {
            int rowSum = grid[r + i][c] + grid[r + i][c + 1] + grid[r + i][c + 2];
            if (rowSum != 15) return false;
        }

        // Check column sums
        for (int j = 0; j < 3; j++) {
            int colSum = grid[r][c + j] + grid[r + 1][c + j] + grid[r + 2][c + j];
            if (colSum != 15) return false;
        }

        // Check main diagonal
        int diagSum = grid[r][c] + grid[r + 1][c + 1] + grid[r + 2][c + 2];
        if (diagSum != 15) return false;

        // Check anti-diagonal
        int antiDiagSum = grid[r][c + 2] + grid[r + 1][c + 1] + grid[r + 2][c];
        if (antiDiagSum != 15) return false;

        return true;
    }
