public class Solution {
    public int[][] flipAndInvertImage(int[][] image) {
        int n = image.length;
        for (int i = 0; i < n; i++) {
            int left = 0, right = n - 1;
            while (left <= right) {
                if (left == right) {
                    image[i][left] ^= 1; // invert middle element
                } else {
                    int temp = image[i][left] ^ 1; // invert left
                    image[i][left] = image[i][right] ^ 1; // invert right and assign to left
                    image[i][right] = temp; // assign inverted left to right
                }
                left++;
                right--;
            }
        }
        return image;
    }
}

