public class Solution {
    public int[][] flipAndInvertImage(int[][] image) {
        for (int[] row : image) {
            int left = 0;
            int right = row.length - 1;
            while (left < right) {
                // Swap and invert both elements
                int temp = 1 - row[left];
                row[left] = 1 - row[right];
                row[right] = temp;
                left++;
                right--;
            }
            // If the row length is odd, invert the middle element
            if (left == right) {
                row[left] = 1 - row[left];
            }
        }
        return image;
    }
}

