import java.util.*;

public class Solution {
    public int largestIsland(int[][] grid) {
        int n = grid.length;
        if (n == 0) return 0;
        int totalCells = n * n;
        int[] parent = new int[totalCells];
        int[] size = new int[totalCells];
        for (int i = 0; i < totalCells; i++) {
            parent[i] = i;
            size[i] = 0;
        }

        // Initialize union-find for cells with 1
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 1) {
                    int idx = r * n + c;
                    size[idx] = 1;
                    // Union with top and left neighbors to avoid duplicate checks
                    if (r > 0 && grid[r - 1][c] == 1) {
                        union(idx, (r - 1) * n + c, parent, size);
                    }
                    if (c > 0 && grid[r][c - 1] == 1) {
                        union(idx, r * n + (c - 1), parent, size);
                    }
                }
            }
        }

        int maxIsland = 0;
        // If the grid is all ones, return total cells
        for (int i = 0; i < totalCells; i++) {
            if (size[i] > maxIsland) maxIsland = size[i];
        }
        if (maxIsland == totalCells) return maxIsland;

        // For each zero, consider flipping it
        int[] dirs = {0, 1, 0, -1, 0};
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 0) {
                    Set<Integer> seen = new HashSet<>();
                    int newSize = 1; // the flipped cell
                    for (int d = 0; d < 4; d++) {
                        int nr = r + dirs[d];
                        int nc = c + dirs[d + 1];
                        if (nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] == 1) {
                            int root = find(nr * n + nc, parent);
                            if (seen.add(root)) {
                                newSize += size[root];
                            }
                        }
                    }
                    if (newSize > maxIsland) maxIsland = newSize;
                }
            }
        }
        return maxIsland;
    }

    private int find(int x, int[] parent) {
        if (parent[x] != x) {
            parent[x] = find(parent[x], parent);
        }
        return parent[x];
    }

    private void union(int a, int b, int[] parent, int[] size) {
        int rootA = find(a, parent);
        int rootB = find(b, parent);
        if (rootA == rootB) return;
        if (size[rootA] < size[rootB]) {
            int temp = rootA;
            rootA = rootB;
            rootB = temp;
        }
        parent[rootB] = rootA;
        size[rootA] += size[rootB];
    }
}

