public class Solution {

    public int largestIsland(int[][] grid) {
        int n = grid.length;
        if (n == 0) return 0;
        int totalCells = n * n;
        DSU dsu = new DSU(totalCells);

        // Directions: up, down, left, right
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        // First pass: union all adjacent 1's
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 1) {
                    int idx = r * n + c;
                    for (int[] d : dirs) {
                        int nr = r + d[0];
                        int nc = c + d[1];
                        if (nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] == 1) {
                            int nIdx = nr * n + nc;
                            dsu.union(idx, nIdx);
                        }
                    }
                }
            }
        }

        // Map root to component size
        HashMap<Integer, Integer> rootSize = new HashMap<>();
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 1) {
                    int idx = r * n + c;
                    int root = dsu.find(idx);
                    rootSize.put(root, dsu.size[root]); // size already stored
                }
            }
        }

        // If all cells are 1, return n*n
        if (rootSize.isEmpty() == false && rootSize.size() == 1 && rootSize.values().iterator().next() == n * n) {
            return n * n;
        }

        int maxIsland = 0;
        // Evaluate each zero cell
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 0) {
                    HashSet<Integer> seenRoots = new HashSet<>();
                    int potentialSize = 1; // the flipped cell itself
                    for (int[] d : dirs) {
                        int nr = r + d[0];
                        int nc = c + d[1];
                        if (nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] == 1) {
                            int neighborIdx = nr * n + nc;
                            int root = dsu.find(neighborIdx);
                            if (seenRoots.add(root)) {
                                potentialSize += dsu.size[root];
                            }
                        }
                    }
                    if (potentialSize > maxIsland) {
                        maxIsland = potentialSize;
                    }
                }
            }
        }

        // If no zero was present (grid all 1s), maxIsland remains 0; in that case return n*n
        return maxIsland == 0 ? n * n : maxIsland;
    }

    // Disjoint Set Union (Union Find) implementation
    private static class DSU {
        int[] parent;
        int[] size;

        DSU(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = -1; // -1 indicates no component (i.e., grid cell is 0)
                size[i] = 0;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX == rootY) return;

            // Union by size (attach smaller to larger)
            if (size[rootX] < size[rootY]) {
                int temp = rootX;
                rootX = rootY;
                rootY = temp;
            }
            parent[rootY] = rootX;
            size[rootX] += size[rootY];
        }
    }
}

