import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

public class Solution {

    public int largestIsland(int[][] grid) {
        int n = grid.length;
        if (n == 0) return 0;
        // Directions: up, down, left, right
        int[] dirs = {-1, 0, 1, 0, -1};

        // Map from island id to its size
        Map<Integer, Integer> sizeMap = new HashMap<>();
        int id = 2; // start labeling from 2 to avoid ambiguity with 0 and 1

        // Label islands and compute sizes
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 1) {
                    int sz = dfs(grid, r, c, id, dirs);
                    sizeMap.put(id, sz);
                    id++;
                }
            }
        }

        // If there is no zero, the whole grid is already an island
        if (sizeMap.isEmpty()) return n * n;

        int best = 0;
        // Evaluate flipping each zero
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 0) {
                    Set<Integer> neighborIds = new HashSet<>();
                    for (int d = 0; d < 4; d++) {
                        int nr = r + dirs[d];
                        int nc = c + dirs[d + 1];
                        if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                            int nid = grid[nr][nc];
                            if (nid > 1) {
                                neighborIds.add(nid);
                            }
                        }
                    }
                    int combined = 1; // the flipped cell itself
                    for (int nid : neighborIds) {
                        combined += sizeMap.get(nid);
                    }
                    if (combined > best) best = combined;
                }
            }
        }

        return best;
    }

    private int dfs(int[][] grid, int r, int c, int id, int[] dirs) {
        int n = grid.length;
        if (r < 0 || r >= n || c < 0 || c >= n || grid[r][c] != 1) {
            return 0;
        }
        grid[r][c] = id;
        int size = 1;
        for (int d = 0; d < 4; d++) {
            int nr = r + dirs[d];
            int nc = c + dirs[d + 1];
            size += dfs(grid, nr, nc, id, dirs);
        }
        return size;
    }
}

