import java.util.HashMap;
import java.util.HashSet;
import java.util.Set;

public class Solution {
    public int largestIsland(int[][] grid) {
        int n = grid.length;
        int totalCells = n * n;
        // DSU arrays
        int[] parent = new int[totalCells];
        int[] size = new int[totalCells];
        for (int i = 0; i < totalCells; i++) {
            parent[i] = i;
            size[i] = 1;
        }

        // lambda for index conversion
        java.util.function.IntUnaryOperator idx = r -> r * n;

        // Directions
        int[][] dirs = {{-1,0},{1,0},{0,-1},{0,1}};

        // Union for all 1 cells
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 1) {
                    int cur = idx.applyAsInt(r) + c;
                    for (int[] d : dirs) {
                        int nr = r + d[0];
                        int nc = c + d[1];
                        if (nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] == 1) {
                            int nb = idx.applyAsInt(nr) + nc;
                            union(cur, nb, parent, size);
                        }
                    }
                }
            }
        }

        // Compute current max size (in case no zeros)
        int maxIsland = 0;
        for (int i = 0; i < totalCells; i++) {
            if (grid[i / n][i % n] == 1) {
                int root = find(i, parent);
                maxIsland = Math.max(maxIsland, size[root]);
            }
        }

        // Try flipping each zero
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 0) {
                    Set<Integer> seen = new HashSet<>();
                    int potentialSize = 1; // the flipped cell
                    for (int[] d : dirs) {
                        int nr = r + d[0];
                        int nc = c + d[1];
                        if (nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] == 1) {
                            int neighborIdx = idx.applyAsInt(nr) + nc;
                            int root = find(neighborIdx, parent);
                            if (seen.add(root)) {
                                potentialSize += size[root];
                            }
                        }
                    }
                    maxIsland = Math.max(maxIsland, potentialSize);
                }
            }
        }

        return maxIsland;
    }

    private int find(int x, int[] parent) {
        if (parent[x] != x) {
            parent[x] = find(parent[x], parent);
        }
        return parent[x];
    }

    private void union(int a, int b, int[] parent, int[] size) {
        int ra = find(a, parent);
        int rb = find(b, parent);
        if (ra == rb) return;
        if (size[ra] < size[rb]) {
            int temp = ra;
            ra = rb;
            rb = temp;
        }
        parent[rb] = ra;
        size[ra] += size[rb];
    }
}

