import java.util.HashSet;

public class Solution {

    public int largestIsland(int[][] grid) {
        int n = grid.length;
        if (n == 0) return 0;
        int size = n * n;
        int[] parent = new int[size];
        int[] compSize = new int[size];
        for (int i = 0; i < size; i++) {
            parent[i] = i;
            compSize[i] = 0;
        }

        // Helper to convert 2D to 1D
        int index(int r, int c) {
            return r * n + c;
        }

        // Union Find functions
        class DSU {
            int find(int x) {
                while (x != parent[x]) {
                    parent[x] = parent[parent[x]];
                    x = parent[x];
                }
                return x;
            }

            void union(int a, int b) {
                int ra = find(a);
                int rb = find(b);
                if (ra == rb) return;
                if (compSize[ra] < compSize[rb]) {
                    int temp = ra;
                    ra = rb;
                    rb = temp;
                }
                parent[rb] = ra;
                compSize[ra] += compSize[rb];
            }
        }
        DSU dsu = new DSU();

        // Initialize components for 1s
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 1) {
                    int curIdx = index(r, c);
                    compSize[curIdx] = 1;
                    for (int k = 0; k < 4; k++) {
                        int nr = r + dr[k];
                        int nc = c + dc[k];
                        if (nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] == 1) {
                            dsu.union(curIdx, index(nr, nc));
                        }
                    }
                }
            }
        }

        int maxIsland = 0;
        boolean hasZero = false;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 0) {
                    hasZero = true;
                    HashSet<Integer> seen = new HashSet<>();
                    int potentialSize = 1; // the flipped cell
                    for (int k = 0; k < 4; k++) {
                        int nr = r + dr[k];
                        int nc = c + dc[k];
                        if (nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] == 1) {
                            int root = dsu.find(index(nr, nc));
                            if (seen.add(root)) {
                                potentialSize += compSize[root];
                            }
                        }
                    }
                    maxIsland = Math.max(maxIsland, potentialSize);
                } else {
                    int root = dsu.find(index(r, c));
                    maxIsland = Math.max(maxIsland, compSize[root]);
                }
            }
        }

        // If no zeros, the whole grid is an island
        if (!hasZero) return n * n;
        return maxIsland;
    }
}

