import java.util.List;
import java.util.Arrays;
import java.util.ArrayDeque;

public class Solution {
    /**
     * Returns the number of car fleets that will arrive at the destination.
     *
     * @param target   the distance to the destination
     * @param position array of cars' starting positions
     * @param speed    array of cars' speeds
     * @return the number of car fleets
     */
    public int carFleet(int target, int[] position, int[] speed) {
        int n = position.length;
        // Pair each car's position and speed
        int[][] cars = new int[n][2];
        for (int i = 0; i < n; i++) {
            cars[i][0] = position[i];
            cars[i][1] = speed[i];
        }

        // Sort cars by starting position in descending order (furthest first)
        Arrays.sort(cars, new Comparator<int[]>() {
            @Override
            public int compare(int[] a, int[] b) {
                return Integer.compare(b[0], a[0]);
            }
        });

        // Stack to keep track of arrival times of fleets
        ArrayDeque<Double> stack = new ArrayDeque<>();

        for (int i = 0; i < n; i++) {
            double time = (double)(target - cars[i][0]) / cars[i][1];
            // If this car's arrival time is greater or equal to the fleet ahead,
            // it will become part of that fleet, otherwise it forms a new fleet.
            while (!stack.isEmpty() && time >= stack.peek()) {
                stack.pop();
            }
            stack.push(time);
        }

        return stack.size();
    }
}

