public class Solution {
    public int[] shortestToChar(String s, char c) {
        int n = s.length();
        int[] ans = new int[n];
        int prev = -1;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == c) {
                prev = i;
                ans[i] = 0;
            } else {
                ans[i] = (prev == -1) ? Integer.MAX_VALUE : i - prev;
            }
        }
        prev = -1;
        for (int i = n - 1; i >= 0; i--) {
            if (s.charAt(i) == c) {
                prev = i;
            } else {
                if (prev != -1) {
                    int dist = prev - i;
                    if (dist < ans[i]) {
                        ans[i] = dist;
                    }
                }
            }
        }
        return ans;
    }
}

