import java.util.Arrays;

public class Solution {
    public int[] shortestToChar(String s, char c) {
        int n = s.length();
        int[] answer = new int[n];
        int distance = n + 1; // large initial distance

        // Left to right pass
        if (s.charAt(0) == c) {
            distance = 0;
        }
        answer[0] = distance;
        for (int i = 1; i < n; i++) {
            if (s.charAt(i) == c) {
                distance = 0;
            } else {
                distance++;
            }
            answer[i] = distance;
        }

        // Right to left pass
        distance = n + 1;
        if (s.charAt(n - 1) == c) {
            distance = 0;
        }
        answer[n - 1] = Math.min(answer[n - 1], distance);
        for (int i = n - 2; i >= 0; i--) {
            if (s.charAt(i) == c) {
                distance = 0;
            } else {
                distance++;
            }
            answer[i] = Math.min(answer[i], distance);
        }

        return answer;
    }
}

