public class Solution {
    public int maxDistToClosest(int[] seats) {
        int n = seats.length;
        int maxDistance = 0;
        int lastOccupied = -1;

        // Find first occupied seat to calculate leading zeros
        for (int i = 0; i < n; i++) {
            if (seats[i] == 1) {
                lastOccupied = i;
                break;
            }
        }

        // Distance from start to first person
        maxDistance = lastOccupied;

        // Iterate through the array to find middle gaps
        for (int i = lastOccupied + 1; i < n; i++) {
            if (seats[i] == 1) {
                int dist = (i - lastOccupied) / 2;
                if (dist > maxDistance) {
                    maxDistance = dist;
                }
                lastOccupied = i;
            }
        }

        // Distance from last person to the end
        int trailing = n - 1 - lastOccupied;
        if (trailing > maxDistance) {
            maxDistance = trailing;
        }

        return maxDistance;
    }
}

