        if (s.contains("@")) {
            return maskEmail(s);
        } else {
            return maskPhone(s);
        }
    }

    private String maskEmail(String s) {
        int at = s.indexOf('@');
        String name = s.substring(0, at);
        String domain = s.substring(at + 1);

        char first = Character.toLowerCase(name.charAt(0));
        char last = Character.toLowerCase(name.charAt(name.length() - 1));
        StringBuilder sb = new StringBuilder();
        sb.append(first);
        sb.append("*****");
        sb.append(last);
        sb.append('@');
        sb.append(domain.toLowerCase());
        return sb.toString();
    }

    private String maskPhone(String s) {
        StringBuilder digits = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (Character.isDigit(c)) {
                digits.append(c);
            }
        }
        int total = digits.length();
        int localStart = total - 10;
        String local = digits.substring(localStart);
        String last4 = local.substring(6);

        int ccLen = total - 10;
        switch (ccLen) {
            case 0:
                return "-*-".concat(last4);
            case 1:
                return "+---".concat(last4);
            case 2:
                return "+--*-".concat(last4);
            case 3:
                return "+---".concat(last4);
            default:
                // In case of unexpected length, default to minimal mask
                return "-*-".concat(last4);
        }
    }
}

