    private double solve(int a, int b, double[][] memo) {
        if (a <= 0 && b <= 0) {
            return 0.5; // both empty simultaneously
        }
        if (a <= 0) {
            return 1.0; // A empty first
        }
        if (b <= 0) {
            return 0.0; // B empty first
        }
        if (memo[a][b] >= 0) {
            return memo[a][b];
        }
        double prob = (
                solve(a - 4, b, memo) +   // 100A, 0B
                solve(a - 3, b - 1, memo) + // 75A, 25B
                solve(a - 2, b - 2, memo) + // 50A, 50B
                solve(a - 1, b - 3, memo)   // 25A, 75B
        ) / 4.0;
        memo[a][b] = prob;
        return prob;
    }
}

