public class Solution {
    public double new21Game(int n, int k, int w) {
        if (k == 0 || n < k) return 1.0;
        double[] dp = new double[n + 1];
        dp[0] = 1.0;
        double windowSum = 1.0; // sum of dp[i-1] to dp[i-w]
        for (int i = 1; i <= n; i++) {
            if (i < k) {
                dp[i] = windowSum / w;
            } else {
                dp[i] = 0.0;
            }
            // Update window sum for next iteration
            if (i < k) {
                windowSum += dp[i];
            }
            if (i - w >= 0) {
                windowSum -= dp[i - w];
            }
        }
        double result = 0.0;
        for (int i = k; i <= n; i++) {
            result += dp[i];
        }
        return result;
    }
}

