public class Solution {
    public double new21Game(int n, int k, int w) {
        if (k == 0) return 1.0;
        if (n < k) return 0.0;

        // Probability of having exactly i points before drawing stops (i < k)
        double[] g = new double[k];
        double windowSum = 0.0;

        g[0] = 1.0;
        windowSum += g[0];
        for (int i = 1; i < k; i++) {
            g[i] = windowSum / w;
            windowSum += g[i];
            if (i >= w) {
                windowSum -= g[i - w];
            }
        }

        // Prefix sums of g for fast range sum queries
        double[] prefixG = new double[k];
        prefixG[0] = g[0];
        for (int i = 1; i < k; i++) {
            prefixG[i] = prefixG[i - 1] + g[i];
        }

        double answer = 0.0;
        int upper = Math.min(n, k - 1 + w);
        for (int i = k; i <= upper; i++) {
            int low = Math.max(0, i - w);
            int high = i - 1;
            double sumG = prefixG[high] - (low > 0 ? prefixG[low - 1] : 0.0);
            answer += sumG / w;
        }

        return answer;
    }
}

