import java.util.*;

public class Solution {
    public int minimumLengthEncoding(String[] words) {
        // Use a trie to store reversed words
        class Node {
            Map<Character, Node> children = new HashMap<>();
        }

        Node root = new Node();
        Node[] nodeRefs = new Node[words.length];
        for (int i = 0; i < words.length; i++) {
            String w = words[i];
            Node cur = root;
            for (int j = w.length() - 1; j >= 0; j--) {
                char c = w.charAt(j);
                cur = cur.children.computeIfAbsent(c, k -> new Node());
            }
            cur.children.put('#', null); // Mark end of word
            nodeRefs[i] = cur;
        }

        Set<Node> counted = new HashSet<>();
        int total = 0;
        for (int i = 0; i < words.length; i++) {
            Node n = nodeRefs[i];
            if (!counted.contains(n) && n.children.size() == 1 && n.children.containsKey('#')) {
                total += words[i].length() + 1;
                counted.add(n);
            }
        }
        return total;
    }
}

