            } else {
                left[i] = 0;
            }
        }

        // decreasing lengths starting at i
        for (int i = n - 2; i >= 0; i--) {
            if (arr[i] > arr[i + 1]) {
                right[i] = right[i + 1] + 1;
            } else {
                right[i] = 0;
            }
        }

        int maxLen = 0;
        for (int i = 0; i < n; i++) {
            if (left[i] > 0 && right[i] > 0) {
                int len = left[i] + right[i] + 1;
                if (len > maxLen) maxLen = len;
            }
        }
        return maxLen;
    }
}

