public class Solution {
    public int shortestSubarray(int[] nums, int k) {
        // Handle trivial case where any subarray qualifies
        if (k <= 0) {
            return 1;
        }

        int n = nums.length;
        long[] pref = new long[n + 1];
        for (int i = 0; i < n; i++) {
            pref[i + 1] = pref[i] + nums[i];
        }

        int ans = n + 1; // initialize with an impossible large value
        Deque<Integer> deque = new ArrayDeque<>();

        for (int i = 0; i <= n; i++) {
            // Check if current prefix sum allows a valid subarray
            while (!deque.isEmpty() && pref[i] - pref[deque.peekFirst()] >= k) {
                ans = Math.min(ans, i - deque.pollFirst());
            }
            // Maintain monotonic increasing order of prefix sums in the deque
            while (!deque.isEmpty() && pref[i] <= pref[deque.peekLast()]) {
                deque.pollLast();
            }
            deque.offerLast(i);
        }

        return ans <= n ? ans : -1;
    }
}

