public class Solution {
    public List<String> ambiguousCoordinates(String s) {
        List<String> result = new ArrayList<>();
        // remove parentheses
        String inner = s.substring(1, s.length() - 1);
        int n = inner.length();
        for (int split = 1; split < n; split++) {
            String left = inner.substring(0, split);
            String right = inner.substring(split);
            List<String> leftOptions = generateOptions(left);
            List<String> rightOptions = generateOptions(right);
            for (String l : leftOptions) {
                for (String r : rightOptions) {
                    result.add("(" + l + ", " + r + ")");
                }
            }
        }
        return result;
    }

    private List<String> generateOptions(String part) {
        List<String> options = new ArrayList<>();
        int len = part.length();
        if (len == 1) {
            options.add(part);
            return options;
        }
        // If part starts with '0' and ends with '0', no valid representation
        if (part.charAt(0) == '0' && part.charAt(len - 1) == '0') {
            return options;
        }
        // If part starts with '0', only decimal after first digit
        if (part.charAt(0) == '0') {
            options.add("0." + part.substring(1));
            return options;
        }
        // If part ends with '0', only integer representation
        if (part.charAt(len - 1) == '0') {
            options.add(part);
            return options;
        }
        // Integer form
        options.add(part);
        // Decimal forms
        for (int i = 1; i < len; i++) {
            String num = part.substring(0, i) + "." + part.substring(i);
            options.add(num);
        }
        return options;
    }
}

