public class Solution {
    public List<String> ambiguousCoordinates(String s) {
        List<String> result = new ArrayList<>();
        // Remove surrounding parentheses
        String digits = s.substring(1, s.length() - 1);
        int n = digits.length();
        for (int split = 1; split < n; split++) {
            String leftPart = digits.substring(0, split);
            String rightPart = digits.substring(split);
            List<String> leftCandidates = generateCandidates(leftPart);
            List<String> rightCandidates = generateCandidates(rightPart);
            for (String left : leftCandidates) {
                for (String right : rightCandidates) {
                    result.add("(" + left + ", " + right + ")");
                }
            }
        }
        return result;
    }

    private List<String> generateCandidates(String num) {
        List<String> candidates = new ArrayList<>();
        int len = num.length();
        if (len == 1) {
            candidates.add(num);
            return candidates;
        }
        // Integer candidate
        if (num.charAt(0) != '0') {
            candidates.add(num);
        }
        // Decimal candidates
        if (num.charAt(0) == '0') {
            // Only "0.xxx" is allowed
            String fractional = num.substring(1);
            if (!fractional.isEmpty() && fractional.charAt(fractional.length() - 1) != '0') {
                candidates.add("0." + fractional);
            }
        } else {
            // Place decimal point at all possible positions
            for (int pos = 1; pos < len; pos++) {
                String fractional = num.substring(pos);
                if (fractional.charAt(fractional.length() - 1) != '0') {
                    candidates.add(num.substring(0, pos) + "." + fractional);
                }
            }
        }
        return candidates;
    }
}

