public class Solution {
    public List<String> ambiguousCoordinates(String s) {
        List<String> res = new ArrayList<>();
        int n = s.length();
        // Remove outer parentheses for easier substring handling
        for (int split = 1; split < n - 1; split++) {
            String part1 = s.substring(1, split + 1);
            String part2 = s.substring(split + 1, n - 1);
            List<String> options1 = generateOptions(part1);
            List<String> options2 = generateOptions(part2);
            for (String a : options1) {
                for (String b : options2) {
                    res.add("(" + a + ", " + b + ")");
                }
            }
        }
        return res;
    }

    private List<String> generateOptions(String digits) {
        List<String> list = new ArrayList<>();
        int len = digits.length();

        // Integer form
        if (isValidInteger(digits)) {
            list.add(digits);
        }

        // Decimal forms
        for (int pos = 1; pos < len; pos++) {
            String left = digits.substring(0, pos);
            String right = digits.substring(pos);

            if (isValidInteger(left) && isValidFraction(right)) {
                list.add(left + "." + right);
            }
        }
        return list;
    }

    private boolean isValidInteger(String s) {
        if (s.length() == 0) return false;
        if (s.length() > 1 && s.charAt(0) == '0') return false;
        return true;
    }

    private boolean isValidFraction(String s) {
        if (s.length() == 0) return false;
        if (s.charAt(s.length() - 1) == '0') return false;
        return true;
    }
}

