public class Solution {
    public List<String> ambiguousCoordinates(String s) {
        List<String> result = new ArrayList<>();
        // remove surrounding parentheses
        String inner = s.substring(1, s.length() - 1);
        int n = inner.length();

        for (int i = 1; i < n; i++) {
            String leftPart = inner.substring(0, i);
            String rightPart = inner.substring(i);

            List<String> leftOptions = generate(leftPart);
            List<String> rightOptions = generate(rightPart);

            for (String left : leftOptions) {
                for (String right : rightOptions) {
                    result.add("(" + left + ", " + right + ")");
                }
            }
        }

        return result;
    }

    private List<String> generate(String part) {
        List<String> options = new ArrayList<>();
        int len = part.length();

        if (len == 1) {
            options.add(part);
            return options;
        }

        // If the part starts with '0', only a decimal form is allowed (e.g., "0.12").
        if (part.charAt(0) == '0') {
            // Ensure there is at least one digit after the decimal point and
            // the number does not end with '0'.
            if (part.charAt(len - 1) != '0') {
                options.add("0." + part.substring(1));
            }
            return options;
        }

        // If the part ends with '0', decimal form would have trailing zero -> not allowed.
        if (part.charAt(len - 1) == '0') {
            options.add(part);
            return options;
        }

        // General case: both integer and decimal forms are possible.
        options.add(part); // integer form

        for (int i = 1; i < len; i++) {
            String intPart = part.substring(0, i);
            String decPart = part.substring(i);
            // Decimal part must not end with '0'.
            if (decPart.charAt(decPart.length() - 1) != '0') {
                options.add(intPart + "." + decPart);
            }
        }

        return options;
    }
}

