import java.util.*;

public class Solution {
    public int[] hitBricks(int[][] grid, int[][] hits) {
        int m = grid.length;
        int n = grid[0].length;
        int total = m * n;
        int virtualTop = total; // index for virtual top node

        // DSU structures
        int[] parent = new int[total + 1];
        int[] size = new int[total + 1];
        for (int i = 0; i <= total; i++) {
            parent[i] = i;
            size[i] = 1;
        }

        // Helper to convert 2D to 1D
        int idx(int r, int c) {
            return r * n + c;
        }

        // Copy original grid to check if a brick existed at a hit location
        int[][] original = new int[m][n];
        for (int i = 0; i < m; i++) {
            System.arraycopy(grid[i], 0, original[i], 0, n);
        }

        // Mark hits on the grid
        for (int[] hit : hits) {
            int r = hit[0], c = hit[1];
            if (grid[r][c] == 1) {
                grid[r][c] = 0;
            }
        }

        // Directions
        int[][] dirs = {{-1,0},{1,0},{0,-1},{0,1}};

        // Initial union of bricks that remain after all hits
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 1) {
                    int cur = idx(r, c);
                    if (r == 0) {
                        union(cur, virtualTop, parent, size);
                    }
                    for (int[] d : dirs) {
                        int nr = r + d[0], nc = c + d[1];
                        if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] == 1) {
                            union(cur, idx(nr, nc), parent, size);
                        }
                    }
                }
            }
        }

        int[] res = new int[hits.length];
        // Process hits in reverse
        for (int i = hits.length - 1; i >= 0; i--) {
            int r = hits[i][0], c = hits[i][1];
            if (original[r][c] == 0) {
                res[i] = 0;
                continue;
            }
            int before = size[find(virtualTop, parent)];
            // Restore the brick
            grid[r][c] = 1;
            int cur = idx(r, c);
            if (r == 0) {
                union(cur, virtualTop, parent, size);
            }
            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] == 1) {
                    union(cur, idx(nr, nc), parent, size);
                }
            }
            int after = size[find(virtualTop, parent)];
            int fallen = after - before - 1;
            res[i] = Math.max(0, fallen);
        }

        return res;
    }

    private int find(int x, int[] parent) {
        while (x != parent[x]) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    private void union(int a, int b, int[] parent, int[] size) {
        int pa = find(a, parent);
        int pb = find(b, parent);
        if (pa == pb) return;
        if (size[pa] < size[pb]) {
            int tmp = pa;
            pa = pb;
            pb = tmp;
        }
        parent[pb] = pa;
        size[pa] += size[pb];
    }
}

