public class Solution {
    public int[] hitBricks(int[][] grid, int[][] hits) {
        int m = grid.length;
        int n = grid[0].length;
        int total = m * n;
        int top = total; // virtual top node index
        int[] parent = new int[total + 1];
        int[] size = new int[total + 1];
        for (int i = 0; i <= total; i++) {
            parent[i] = i;
            size[i] = 0;
        }

        // deep copy of original grid to check existence of bricks
        int[][] orig = new int[m][n];
        for (int i = 0; i < m; i++) {
            System.arraycopy(grid[i], 0, orig[i], 0, n);
        }

        // remove all hit bricks
        for (int[] h : hits) {
            int r = h[0], c = h[1];
            if (r < 0 || r >= m || c < 0 || c >= n) continue;
            grid[r][c] = 0;
        }

        // initial union find setup
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    int idx = i * n + j;
                    parent[idx] = idx;
                    size[idx] = 1;
                    if (i == 0) {
                        union(parent, size, idx, top);
                    }
                    // connect to left and up to avoid double work
                    if (i > 0 && grid[i - 1][j] == 1) {
                        union(parent, size, idx, (i - 1) * n + j);
                    }
                    if (j > 0 && grid[i][j - 1] == 1) {
                        union(parent, size, idx, i * n + (j - 1));
                    }
                }
            }
        }

        int[] res = new int[hits.length];
        for (int k = hits.length - 1; k >= 0; k--) {
            int r = hits[k][0], c = hits[k][1];
            if (r < 0 || r >= m || c < 0 || c >= n || orig[r][c] == 0) {
                res[k] = 0;
                continue;
            }
            // restore brick
            grid[r][c] = 1;
            int idx = r * n + c;
            parent[idx] = idx;
            size[idx] = 1;
            int before = size[find(parent, top)];
            if (r == 0) {
                union(parent, size, idx, top);
            }
            if (r > 0 && grid[r - 1][c] == 1) {
                union(parent, size, idx, (r - 1) * n + c);
            }
            if (r < m - 1 && grid[r + 1][c] == 1) {
                union(parent, size, idx, (r + 1) * n + c);
            }
            if (c > 0 && grid[r][c - 1] == 1) {
                union(parent, size, idx, r * n + (c - 1));
            }
            if (c < n - 1 && grid[r][c + 1] == 1) {
                union(parent, size, idx, r * n + (c + 1));
            }
            int after = size[find(parent, top)];
            int fallen = after - before - 1;
            res[k] = Math.max(0, fallen);
        }
        return res;
    }

    private int find(int[] parent, int x) {
        if (parent[x] != x) {
            parent[x] = find(parent, parent[x]);
        }
        return parent[x];
    }

    private void union(int[] parent, int[] size, int a, int b) {
        int ra = find(parent, a);
        int rb = find(parent, b);
        if (ra == rb) return;
        if (size[ra] < size[rb]) {
            int tmp = ra;
            ra = rb;
            rb = tmp;
        }
        parent[rb] = ra;
        size[ra] += size[rb];
    }
}

