                if (g[r][c] == 1) {
                    int id = 1 + r * n + c;
                    if (r == 0) dsu.union(id, 0);
                    // connect with left neighbor
                    if (c > 0 && g[r][c - 1] == 1) dsu.union(id, 1 + r * n + (c - 1));
                    // connect with upper neighbor
                    if (r > 0 && g[r - 1][c] == 1) dsu.union(id, 1 + (r - 1) * n + c);
                }
            }
        }

        int[] res = new int[hits.length];
        for (int i = hits.length - 1; i >= 0; i--) {
            int r = hits[i][0], c = hits[i][1];
            if (!hitBrick[i]) {
                res[i] = 0;
                continue;
            }
            int before = dsu.size(dsu.find(0));
            int id = 1 + r * n + c;
            g[r][c] = 1;
            if (r == 0) dsu.union(id, 0);
            if (r > 0 && g[r - 1][c] == 1) dsu.union(id, 1 + (r - 1) * n + c);
