            if (c < n - 1 && g[r][c + 1] == 1) dsu.union(id, 1 + r * n + (c + 1));
            int after = dsu.size(dsu.find(0));
            res[i] = Math.max(0, after - before - 1);
        }
        return res;
    }

    private static class DSU {
        int[] parent, sz;

        DSU(int n) {
            parent = new int[n];
            sz = new int[n];
            for (int i = 0; i < n; i++) {
