public class Solution {
    public int[] hitBricks(int[][] grid, int[][] hits) {
        int m = grid.length;
        int n = grid[0].length;
        int total = m * n;
        int virtualTop = total; // index of virtual top node

        // Copy of grid after all hits applied
        int[][] g = new int[m][n];
        for (int i = 0; i < m; i++) {
            System.arraycopy(grid[i], 0, g[i], 0, n);
        }
        for (int[] hit : hits) {
            int r = hit[0], c = hit[1];
            if (g[r][c] == 1) {
                g[r][c] = 0; // remove brick
            }
        }

        UnionFind uf = new UnionFind(total + 1, virtualTop);

        // Initialize union find with remaining bricks
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (g[i][j] == 1) {
                    int idx = i * n + j;
                    uf.setSize(idx, 1);
                    if (i == 0) {
                        uf.union(idx, virtualTop);
                    }
                    // union with left neighbor
                    if (j > 0 && g[i][j - 1] == 1) {
                        uf.union(idx, idx - 1);
                    }
                    // union with upper neighbor
                    if (i > 0 && g[i - 1][j] == 1) {
                        uf.union(idx, idx - n);
                    }
                }
            }
        }

        int[] res = new int[hits.length];
        for (int k = hits.length - 1; k >= 0; k--) {
            int r = hits[k][0];
            int c = hits[k][1];
            if (grid[r][c] == 0) {
                res[k] = 0;
                continue;
            }
            int idx = r * n + c;
            int before = uf.size(virtualTop);
            g[r][c] = 1; // restore brick
            uf.setSize(idx, 1);
            if (r == 0) {
                uf.union(idx, virtualTop);
            }
            // union with neighbors
            if (r > 0 && g[r - 1][c] == 1) {
                uf.union(idx, idx - n);
            }
            if (r < m - 1 && g[r + 1][c] == 1) {
                uf.union(idx, idx + n);
            }
            if (c > 0 && g[r][c - 1] == 1) {
                uf.union(idx, idx - 1);
            }
            if (c < n - 1 && g[r][c + 1] == 1) {
                uf.union(idx, idx + 1);
            }
            int after = uf.size(virtualTop);
            int added = after - before - 1;
            res[k] = Math.max(0, added);
        }

        return res;
    }

    // Union Find with component sizes
    private static class UnionFind {
        private final int[] parent;
        private final int[] size;
        private final int virtualTop;

        UnionFind(int n, int virtualTop) {
            this.parent = new int[n];
            this.size = new int[n];
            this.virtualTop = virtualTop;
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return;
            if (size[ra] < size[rb]) {
                parent[ra] = rb;
                size[rb] += size[ra];
            } else {
                parent[rb] = ra;
                size[ra] += size[rb];
            }
        }

        int size(int x) {
            return size[find(x)];
        }

        void setSize(int idx, int val) {
            parent[idx] = idx;
            size[idx] = val;
        }
    }
