import java.util.*;

public class Solution {
    public int[] hitBricks(int[][] grid, int[][] hits) {
        int m = grid.length;
        int n = grid[0].length;
        int total = m * n;
        int virtualTop = total; // index for virtual top node

        // Copy grid to avoid modifying original
        int[][] g = new int[m][n];
        for (int i = 0; i < m; i++) {
            System.arraycopy(grid[i], 0, g[i], 0, n);
        }

        // Mark hits, removing bricks
        for (int[] hit : hits) {
            int r = hit[0], c = hit[1];
            if (g[r][c] == 1) {
                g[r][c] = 0;
            }
        }

        // DSU initialization
        DSU dsu = new DSU(total + 1); // +1 for virtual top

        // Connect initial bricks
        int[][] dirs = {{1,0}, {-1,0}, {0,1}, {0,-1}};
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (g[i][j] == 1) {
                    int idx = i * n + j;
                    // Connect to virtual top if on top row
                    if (i == 0) {
                        dsu.union(idx, virtualTop);
                    }
                    // Union with neighbors that are bricks
                    for (int[] d : dirs) {
                        int ni = i + d[0];
                        int nj = j + d[1];
                        if (ni >= 0 && ni < m && nj >= 0 && nj < n && g[ni][nj] == 1) {
                            dsu.union(idx, ni * n + nj);
                        }
                    }
                }
            }
        }

        int hitsLen = hits.length;
        int[] res = new int[hitsLen];
        // Process hits in reverse
        for (int k = hitsLen - 1; k >= 0; k--) {
            int r = hits[k][0], c = hits[k][1];
            if (grid[r][c] == 0) {
                // No brick originally; nothing falls
                res[k] = 0;
                continue;
            }

            int before = dsu.size(virtualTop);
            int idx = r * n + c;
            g[r][c] = 1; // restore brick

            // Connect restored brick
            if (r == 0) {
                dsu.union(idx, virtualTop);
            }
            for (int[] d : dirs) {
                int ni = r + d[0];
                int nj = c + d[1];
                if (ni >= 0 && ni < m && nj >= 0 && nj < n && g[ni][nj] == 1) {
                    dsu.union(idx, ni * n + nj);
                }
            }

            int after = dsu.size(virtualTop);
            // bricks that fell are difference minus the restored brick itself
            res[k] = Math.max(0, after - before - 1);
        }
        return res;
    }

    // Union-Find (Disjoint Set Union) with size tracking
    private static class DSU {
        int[] parent;
        int[] sz;
        DSU(int n) {
            parent = new int[n];
            sz = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                sz[i] = 1;
            }
        }
        int find(int x) {
            if (parent[x] != x) parent[x] = find(parent[x]);
            return parent[x];
        }
        void union(int x, int y) {
            int rx = find(x);
            int ry = find(y);
            if (rx == ry) return;
            if (sz[rx] < sz[ry]) {
                parent[rx] = ry;
                sz[ry] += sz[rx];
            } else {
                parent[ry] = rx;
                sz[rx] += sz[ry];
            }
        }
        int size(int x) {
            return sz[find(x)];
        }
    }
}

