import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    public String findReplaceString(String s, int[] indices, String[] sources, String[] targets) {
        int n = indices.length;
        // Create an array of operations
        Operation[] ops = new Operation[n];
        for (int i = 0; i < n; i++) {
            ops[i] = new Operation(indices[i], sources[i], targets[i]);
        }
        // Sort operations by index ascending
        Arrays.sort(ops, Comparator.comparingInt(o -> o.index));

        StringBuilder sb = new StringBuilder();
        int pos = 0; // current position in original string

        for (Operation op : ops) {
            // Append unchanged part before this operation
            if (op.index > pos) {
                sb.append(s, pos, op.index);
            }
            // Check if source matches at this index
            if (s.startsWith(op.source, op.index)) {
                sb.append(op.target);
                pos = op.index + op.source.length();
            } else {
                // No match: keep the original character at this index
                sb.append(s.charAt(op.index));
                pos = op.index + 1;
            }
        }
        // Append the remaining part of the string
        if (pos < s.length()) {
            sb.append(s.substring(pos));
        }
        return sb.toString();
    }

    // Helper class to store each replacement operation
    private static class Operation {
        int index;
        String source;
        String target;

        Operation(int index, String source, String target) {
            this.index = index;
            this.source = source;
            this.target = target;
        }
    }
}

