public class Solution {
    private static class Operation {
        String source;
        String target;
        Operation(String source, String target) {
            this.source = source;
            this.target = target;
        }
    }

    public String findReplaceString(String s, int[] indices, String[] sources, String[] targets) {
        // Map each index to its corresponding source and target strings
        Map<Integer, Operation> map = new HashMap<>();
        for (int i = 0; i < indices.length; i++) {
            map.put(indices[i], new Operation(sources[i], targets[i]));
        }

        // Sort the indices to process replacements from left to right
        int[] sortedIndices = indices.clone();
        Arrays.sort(sortedIndices);

        StringBuilder result = new StringBuilder();
        int prev = 0; // tracks the start of the next segment to copy

        for (int idx : sortedIndices) {
            Operation op = map.get(idx);
            String src = op.source;
            // Verify that the source string actually matches at this index
            if (s.startsWith(src, idx)) {
                // Append text from prev to current index
                result.append(s, prev, idx);
                // Append the replacement target
                result.append(op.target);
                // Update prev to the index after the replaced source
                prev = idx + src.length();
            }
            // If source doesn't match, simply ignore this operation
        }

        // Append any remaining part of the original string
        result.append(s, prev, s.length());
        return result.toString();
    }
