public class Solution {
    public int[][] spiralMatrixIII(int rows, int cols, int rStart, int cStart) {
        int total = rows * cols;
        int[][] result = new int[total][2];
        int index = 0;
        int r = rStart, c = cStart;
        result[index++] = new int[]{r, c};
        int step = 1; // number of steps to move in current direction
        // directions: right, down, left, up
        int[][] dirs = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
        while (index < total) {
            for (int d = 0; d < 4 && index < total; d++) {
                int dr = dirs[d][0];
                int dc = dirs[d][1];
                int steps = step;
                // For the first two directions (right and down) we use current step,
                // then increase step after completing two directions.
                for (int s = 0; s < steps && index < total; s++) {
                    r += dr;
                    c += dc;
                    result[index++] = new int[]{r, c};
                }
                // Increase step after moving right and down (i.e., after even d)
                if (d % 2 == 1) {
                    step++;
                }
            }
        }
        return result;
    }
}

