                        path.add(new int[]{y, x});
                        visited++;
                        if (visited == rows * cols) {
                            break;
                        }
                    }
                }
                dirIdx = (dirIdx + 1) % 4;
                // increase step after moving east and south (i.e., after two directions)
                if (i % 2 == 1) {
                    step++;
                }
                if (visited == rows * cols) {
                    break;
                }
            }
        }

        int[][] result = new int[path.size()][2];
        for (int i = 0; i < path.size(); i++) {
