public class Solution {
    public String pushDominoes(String dominoes) {
        int n = dominoes.length();
        char[] res = new char[n];
        int[] leftDist = new int[n];
        int[] rightDist = new int[n];
        int lastR = -1;
        for (int i = 0; i < n; i++) {
            char c = dominoes.charAt(i);
            if (c == 'R') {
                lastR = i;
                leftDist[i] = 0;
            } else if (c == '.') {
                if (lastR != -1) {
                    leftDist[i] = i - lastR;
                } else {
                    leftDist[i] = Integer.MAX_VALUE;
                }
            } else { // 'L'
                leftDist[i] = Integer.MAX_VALUE;
            }
        }

        int lastL = -1;
        for (int i = n - 1; i >= 0; i--) {
            char c = dominoes.charAt(i);
            if (c == 'L') {
                lastL = i;
                rightDist[i] = 0;
            } else if (c == '.') {
                if (lastL != -1) {
                    rightDist[i] = lastL - i;
                } else {
                    rightDist[i] = Integer.MAX_VALUE;
                }
            } else { // 'R'
                rightDist[i] = Integer.MAX_VALUE;
            }
        }

        for (int i = 0; i < n; i++) {
            char c = dominoes.charAt(i);
            if (c == 'L' || c == 'R') {
                res[i] = c;
            } else {
                int l = leftDist[i];
                int r = rightDist[i];
                if (l == Integer.MAX_VALUE && r == Integer.MAX_VALUE) {
                    res[i] = '.';
                } else if (l == r) {
                    res[i] = '.';
                } else if (l < r) {
                    res[i] = 'R';
                } else {
                    res[i] = 'L';
                }
            }
        }

        return new String(res);
    }
}

