public class Solution {
    public String pushDominoes(String dominoes) {
        int n = dominoes.length();
        int[] left = new int[n];
        int[] right = new int[n];
        int force = 0;

        // propagate forces from left to right (R)
        for (int i = 0; i < n; i++) {
            char c = dominoes.charAt(i);
            if (c == 'R') {
                force = n;                     // max distance
            } else if (c == 'L') {
                force = 0;                     // cancel any R to the left
            } else { // '.'
                force = Math.max(force - 1, 0);
            }
            left[i] = force;
