        force = 0;
        for (int i = n - 1; i >= 0; i--) {
            char c = dominoes.charAt(i);
            if (c == 'L') {
                force = n;                     // max distance
            } else if (c == 'R') {
                force = 0;                     // cancel any L to the right
            } else { // '.'
                force = Math.max(force - 1, 0);
            }
            right[i] = force;
        }

        // Build final state
        StringBuilder sb = new StringBuilder(n);
        for (int i = 0; i < n; i++) {
            if (left[i] > right[i]) {
                sb.append('R');
            } else if (right[i] > left[i]) {
                sb.append('L');
            } else {
