public class Solution {
    public boolean xorGame(int[] nums) {
        // If the XOR of all elements is initially 0, the first player (Alice) already wins.
        int totalXor = 0;
        for (int num : nums) {
            totalXor ^= num;
        }
        if (totalXor == 0) {
            return true;
        }

        // Count the number of odd numbers in the array.
        int oddCount = 0;
        for (int num : nums) {
            if ((num & 1) != 0) {
                oddCount++;
            }
        }

        // If there are more than one odd numbers, Alice can always force a win.
        // Otherwise, Bob wins.
        return oddCount > 1;
    }
}

