    public boolean xorGame(int[] nums) {
        // Compute overall XOR of the array
        int totalXor = 0;
        for (int num : nums) {
            totalXor ^= num;
        }

        // If XOR is already zero, Alice wins immediately
        if (totalXor == 0) {
            return true;
        }

        // Count occurrences of each number
        Map<Integer, Integer> freq = new HashMap<>();
        for (int num : nums) {
            freq.merge(num, 1, Integer::sum);
        }

        // Count numbers equal to the total XOR
        int count = 0;
        for (int key : freq.keySet()) {
            if (key == totalXor) {
                count++;
            }
        }

        // Alice can win if at least one such element exists
        return count > 0;
    }
}

