import java.util.Arrays;

public class Solution {
    public boolean stoneGame(int[] piles) {
        int n = piles.length;
        // dp[l][r] – maximum difference Alice can achieve over Bob
        int[][] dp = new int[n][n];

        // Base case: single pile
        for (int i = 0; i < n; i++) {
            dp[i][i] = piles[i];
        }

        // Build up the table for increasing lengths
        for (int len = 2; len <= n; len++) {
            for (int l = 0; l + len - 1 < n; l++) {
                int r = l + len - 1;
                int takeLeft  = piles[l] - dp[l + 1][r];
                int takeRight = piles[r] - dp[l][r - 1];
                dp[l][r] = Math.max(takeLeft, takeRight);
            }
        }

        return dp[0][n - 1] > 0;
    }
}

