import java.util.PriorityQueue;
import java.util.Collections;
import java.util.Arrays;

public class Solution {
    public int minRefuelStops(int target, int startFuel, int[][] stations) {
        // Ensure stations are sorted by position
        Arrays.sort(stations, (a, b) -> Integer.compare(a[0], b[0]));
        // Max-heap to store fuels of stations we have passed
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
        int fuel = startFuel;
        int stops = 0;
        int idx = 0;
        int n = stations.length;

        while (fuel < target) {
            // Add all stations we can reach with current fuel
            while (idx < n && stations[idx][0] <= fuel) {
                maxHeap.offer(stations[idx][1]);
                idx++;
            }
            // If we cannot reach target and no station to refuel from
            if (maxHeap.isEmpty()) {
                return -1;
            }
            // Refuel at the station with the most fuel
            fuel += maxHeap.poll();
            stops++;
        }
        return stops;
    }
}

