import java.util.PriorityQueue;

public class Solution {
    public int minRefuelStops(int target, int startFuel, int[][] stations) {
        // Edge case: no stations needed
        if (stations == null || stations.length == 0) {
            return target <= startFuel ? 0 : -1;
        }

        // Sort stations by position
        java.util.Arrays.sort(stations, (a, b) -> Integer.compare(a[0], b[0]));

        // Max-heap that stores fuel amounts of stations we have passed
        PriorityQueue<Integer> maxFuel = new PriorityQueue<>((a, b) -> Integer.compare(b, a));
        int stops = 0;
        int maxReach = 0;      // furthest distance reachable with current fuel
        int currentFuel = startFuel;

        for (int[] station : stations) {
            int pos = station[0];
            int fuel = station[1];

            // While we cannot reach this station, refuel at the best previous station
            while (currentFuel < pos) {
                if (maxFuel.isEmpty()) {
                    return -1; // impossible to reach
                }
                currentFuel += maxFuel.poll();
                stops++;
            }

            // We can reach this station
            maxFuel.offer(fuel);
            maxReach = Math.max(maxReach, pos + currentFuel);

            // Check if destination can be reached
            if (maxReach >= target) {
                return stops;
            }
        }

        return -1;
    }
}

