import java.util.PriorityQueue;

public class Solution {
    public int minRefuelStops(int target, int startFuel, int[][] stations) {
        // Edge case: already at the destination
        if (target <= startFuel) return 0;

        // Sort stations by position (ascending)
        java.util.Arrays.sort(stations, (a, b) -> Integer.compare(a[0], b[0]));

        // Max‑heap (priority queue) to store fuel amounts we can use
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(
                (a, b) -> Integer.compare(b, a));

        int fuel = startFuel;   // current fuel in the car
        int stops = 0;          // number of refuels performed
        int prevPos = 0;        // previous station position (or start)

        for (int[] station : stations) {
            int dist = station[0] - prevPos; // distance to next station
            // Consume fuel to reach this station
            fuel -= dist;

            // While we cannot reach the current station and we have stations to refuel at
            while (!maxHeap.isEmpty() && fuel < 0) {
                fuel += maxHeap.poll(); // refuel at the best previous station
                stops++;
            }

            // If still cannot reach, impossible
            if (fuel < 0) return -1;

            // Add this station's fuel to the heap
            maxHeap.offer(station[1]);

            // Update previous position
            prevPos = station[0];
        }

        // After the last station, we need to reach target
        return stops;
    }
}

