public class Solution {
    public int minRefuelStops(int target, int startFuel, int[][] stations) {
        Arrays.sort(stations, (a, b) -> Integer.compare(a[0], b[0]));
        int n = stations.length;
        long fuel = startFuel;          // use long to avoid overflow
        long prev = 0;                  // previous station position
        int stops = 0;
        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> b - a); // max‑heap

        for (int[] station : stations) {
            long dist = station[0] - prev;
            while (fuel < dist) {
                if (pq.isEmpty()) return -1;
                fuel += pq.poll();
                stops++;
            }
            prev = station[0];
            pq.offer(station[1]); // fuel available at this station
        }
        // final leg from last station to target
        long dist = target - prev;
        while (fuel < dist) {
            if (pq.isEmpty()) return -1;
            fuel += pq.poll();
            stops++;
        }
        return stops;
    }
}

