public class Solution {
    public int minRefuelStops(int target, int startFuel, int[][] stations) {
        // Edge cases
        if (target == 0) return 0;
        if (stations == null || stations.length == 0) return -1;

        // Sort stations by position
        java.util.Arrays.sort(stations, (a, b) -> Integer.compare(a[0], b[0]));

        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(java.util.Comparator.reverseOrder());
        int stops = 0;
        int fuel = startFuel;
        int prev = 0;

        for (int[] station : stations) {
            int dist = station[0];
            int f = station[1];

            // Reach this station
            while (fuel < dist - prev) {
                if (maxHeap.isEmpty()) return -1; // cannot reach next station
                fuel += maxHeap.poll(); // refuel with largest available fuel
                stops++;
            }
            // Refuel at the current station
            maxHeap.offer(f);
            prev = dist;
        }
        return stops;
    }
}

