public class Solution {
    public int consecutiveNumbersSum(int n) {
        // Remove all factors of 2 from n
        while ((n & 1) == 0) {
            n >>= 1;
        }
        int count = 1;
        int m = n;
        for (int i = 3; i * i <= m; i += 2) {
            int exp = 0;
            while (m % i == 0) {
                m /= i;
                exp++;
            }
            if (exp > 0) {
                count *= (exp + 1);
            }
        }
        if (m > 1) {
            // Remaining odd prime factor
            count *= 2;
        }
        return count;
    }
}

