public class Solution {
    public int consecutiveNumbersSum(int n) {
        // Count the number of odd divisors of n, which equals the number of ways to
        // express n as a sum of consecutive positive integers.
        int ways = 1;
        // Remove all factors of 2
        while ((n & 1) == 0) {
            n >>= 1;
        }
        // Factor the remaining odd part
