public class Solution {
    public int projectionArea(int[][] grid) {
        int n = grid.length;
        if (n == 0) return 0;

        int top = 0, front = 0, side = 0;

        // Top view: count cells with height > 0
        for (int[] row : grid) {
            for (int val : row) {
                if (val > 0) top++;
            }
        }

        // Front view: count cells with height > 0 in each column
        for (int col = 0; col < n; col++) {
            for (int row = 0; row < n; row++) {
                if (grid[row][col] > 0) front++;
            }
        }

        // Side view: count distinct heights in each row
        for (int[] row : grid) {
            Set<Integer> seen = new HashSet<>();
            for (int val : row) {
                if (val > 0) seen.add(val);
            }
            side += seen.size();
        }

        return top + front + side;
    }
}

