            bestProf[m] = maxProf;
            m++;
        }

        long total = 0;
        for (int ability : worker) {
            int idx = Arrays.binarySearch(diff, 0, m, ability);
            if (idx < 0) {
                idx = -idx - 2;
            }
            if (idx >= 0) {
                total += bestProf[idx];
            }
        }
        return (int) total;
    }
