import java.util.Arrays;

public class Solution {
    public int maxProfitAssignment(int[] difficulty, int[] profit, int[] worker) {
        int n = difficulty.length;
        int[][] jobs = new int[n][2];
        for (int i = 0; i < n; i++) {
            jobs[i][0] = difficulty[i];
            jobs[i][1] = profit[i];
        }
        Arrays.sort(jobs, (a, b) -> Integer.compare(a[0], b[0]));

        // Build prefix maximum profit array
        int[] maxProfit = new int[n];
        int currentMax = 0;
        for (int i = 0; i < n; i++) {
            currentMax = Math.max(currentMax, jobs[i][1]);
            maxProfit[i] = currentMax;
        }

        long total = 0;
        for (int ability : worker) {
            int idx = upperBound(jobs, ability);
            if (idx >= 0) {
                total += maxProfit[idx];
            }
        }
        return (int) total;
    }

    // Returns the index of the last job whose difficulty <= ability
    private int upperBound(int[][] jobs, int ability) {
        int l = 0, r = jobs.length - 1, ans = -1;
        while (l <= r) {
            int mid = l + (r - l) / 2;
            if (jobs[mid][0] <= ability) {
                ans = mid;
                l = mid + 1;
            } else {
                r = mid - 1;
            }
        }
        return ans;
    }
}

