public class Solution {
    private TreeNode prev;
    private TreeNode newRoot;

    public TreeNode increasingBST(final TreeNode root) {
        if (root == null) {
            return null;
        }
        prev = null;
        newRoot = null;
        inorder(root);
        return newRoot;
    }

    private void inorder(TreeNode node) {
        if (node == null) {
            return;
        }
        inorder(node.left);

        if (prev == null) {
            newRoot = node;
        } else {
            prev.right = node;
        }
        node.left = null;
        prev = node;

        inorder(node.right);
    }
}

