public class Solution {
    public boolean reorderedPowerOf2(int n) {
        // Count digits of n
        int[] countN = getDigitCount(n);
        // Powers of two up to 2^30 (since 2^30 > 1e9)
        for (int i = 0; i <= 30; i++) {
            int power = 1 << i; // 2^i
            int[] countP = getDigitCount(power);
            if (Arrays.equals(countN, countP)) {
                return true;
            }
        }
        return false;
    }

    // Helper to count the frequency of each digit (0-9)
    private int[] getDigitCount(int num) {
        int[] count = new int[10];
        // Handle number zero separately
        if (num == 0) {
            count[0] = 1;
            return count;
        }
        while (num > 0) {
            count[num % 10]++;
            num /= 10;
        }
        return count;
    }
}

