    public String orderlyQueue(String s, int k) {
        if (s == null || s.length() == 0) return "";
        // Priority queue (min‑heap) that keeps the smallest character at the top
        PriorityQueue<Character> pq = new PriorityQueue<>((a, b) -> a - b);

        // Insert the first k characters into the heap
        for (int i = 0; i < k; i++) {
            pq.offer(s.charAt(i));
        }

        StringBuilder sb = new StringBuilder();

        // Build the result by always taking the smallest character available
        for (int i = 0; i < s.length(); i++) {
            sb.append(pq.poll());
        }

        return sb.toString();
    }
}

