public class Solution {

    private static class DSU {
        private final int[] parent;
        private final int[] rank;
        DSU(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) parent[i] = i;
        }
        int find(int x) {
            if (parent[x] != x) parent[x] = find(parent[x]);
            return parent[x];
        }
        boolean union(int a, int b) {
            int ra = find(a), rb = find(b);
            if (ra == rb) return false;
            if (rank[ra] < rank[rb]) parent[ra] = rb;
            else if (rank[ra] > rank[rb]) parent[rb] = ra;
            else {
                parent[rb] = ra;
                rank[ra]++;
            }
            return true;
        }
    }

    public String orderlyQueue(String s, int k) {
        if (s == null || s.length() == 0) return s;
        if (k == 1) {
            // Only one letter can be moved at a time – return the string
            // sorted by rotating each character to its lexicographically smallest position.
            char[] arr = s.toCharArray();
            Arrays.sort(arr);
            return new String(arr);
        }

        int n = s.length();
        DSU dsu = new DSU(n);
        // Union indices with distance <= k
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n && j - i <= k; j++) {
                dsu.union(i, j);
            }
        }

        // Build components
        List<List<Character>> comps = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            int root = dsu.find(i);
            while (root >= comps.size()) comps.add(new ArrayList<>());
            comps.get(root).add(s.charAt(i));
        }

        // For each component, sort its characters
        for (List<Character> comp : comps) {
            comp.sort(null);
        }

        // Reconstruct result
        StringBuilder sb = new StringBuilder();
        int idx = 0;
        for (int i = 0; i < n; i++) {
            int root = dsu.find(i);
            sb.append(comps.get(root).remove(0));
        }
        return sb.toString();
    }
}

