public class Solution {
    /**
     * Finds the peak index in a mountain array.
     *
     * @param arr the input array, guaranteed to be a mountain array of length >= 3
     * @return the index i such that arr[0] < arr[1] < ... < arr[i] > arr[i+1] > ... > arr[n-1]
     */
    public int peakIndexInMountainArray(int[] arr) {
        // The peak must be somewhere between indices 1 and n-2 (inclusive),
        // because arr[0] < arr[1] and arr[n-2] > arr[n-1].
        int left = 1;
        int right = arr.length - 2;

        while (left < right) {
            int mid = left + (right - left) / 2;
            if (arr[mid] < arr[mid + 1]) {
                // We are still ascending, move the left bound right.
                left = mid + 1;
            } else {
                // arr[mid] is a peak or to the right of a peak.
                right = mid;
            }
        }

        // left == right is the peak index
        return left;
    }
}

