            if (lenS < 3 && lenS != lenW) {
                return false;
            }
            if (lenS >= 3 && lenW <= lenS) {
                // ok
            } else if (lenS >= 3 && lenW > lenS) {
                return false;
            }
        }

        return i == n && j == m;
    }
