            char c = sChar.get(i);
            int k = j;
            while (k < m && w.charAt(k) == c) k++;
            int lenW = k - j;

            int lenS = sLen.get(i);

            if (lenW > lenS) return false;
            if (lenS < 3 && lenS != lenW) return false;

            i++;
            j = k;
        }

        return i == groups && j == m;
    }
}

