public class Solution {
    public int expressiveWords(String s, String[] words) {
        int count = 0;
        for (String w : words) {
            if (isStretchy(s, w)) {
                count++;
            }
        }
        return count;
    }

    private boolean isStretchy(String s, String w) {
        int i = 0, j = 0;
        int n = s.length(), m = w.length();

        while (i < n && j < m) {
            char cs = s.charAt(i);
            char cw = w.charAt(j);
            if (cs != cw) {
                return false;
            }

            int iCount = 0;
            while (i < n && s.charAt(i) == cs) {
                iCount++;
                i++;
            }

            int jCount = 0;
            while (j < m && w.charAt(j) == cw) {
                jCount++;
                j++;
            }

            if (jCount > iCount) {
                return false;
            }
            if (iCount < 3 && iCount != jCount) {
                return false;
            }
        }

        return i == n && j == m;
    }
}

package referenz;


import java.util.*;

public class Solution {
    public int expressiveWords(String s, String[] words) {
        Group[] sGroups = groupProcess(s);
        int count = 0;
        for (String w : words) {
            Group[] wGroups = groupProcess(w);
            if (canStretch(sGroups, wGroups)) {
                count++;
            }
        }
        return count;
    }

    private static class Group {
        char c;
        int len;
        Group(char c, int len) {
            this.c = c;
            this.len = len;
        }
    }

    private Group[] groupProcess(String str) {
        int n = str.length();
        List<Group> list = new ArrayList<>();
        int i = 0;
        while (i < n) {
            char curr = str.charAt(i);
            int j = i;
            while (j < n && str.charAt(j) == curr) j++;
            list.add(new Group(curr, j - i));
            i = j;
        }
        return list.toArray(new Group[0]);
    }

    private boolean canStretch(Group[] sGroups, Group[] wGroups) {
        if (sGroups.length != wGroups.length) return false;
        for (int i = 0; i < sGroups.length; i++) {
            Group sg = sGroups[i];
            Group wg = wGroups[i];
            if (sg.c != wg.c) return false;
            if (sg.len < 3) {
                if (sg.len != wg.len) return false;
            } else {
                if (wg.len > sg.len) return false;
            }
        }
        return true;
    }
}

