import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int kSimilarity(String a, String b) {
        Map<String, Integer> memo = new HashMap<>();
        return dfs(a, b, memo);
    }

    private int dfs(String a, String b, Map<String, Integer> memo) {
        if (a.equals(b)) {
            return 0;
        }
        if (memo.containsKey(a)) {
            return memo.get(a);
        }

        char[] arr = a.toCharArray();
        int i = 0;
        while (i < arr.length && arr[i] == b.charAt(i)) {
            i++;
        }

        int minSwaps = Integer.MAX_VALUE;
        for (int j = i + 1; j < arr.length; j++) {
            if (arr[j] == b.charAt(i) && arr[j] != b.charAt(j)) {
                swap(arr, i, j);
                String next = new String(arr);
                int swaps = 1 + dfs(next, b, memo);
                if (swaps < minSwaps) {
                    minSwaps = swaps;
                }
                swap(arr, i, j); // backtrack
            }
        }

        memo.put(a, minSwaps);
        return minSwaps;
    }

    private void swap(char[] arr, int i, int j) {
        char temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

