            pos++;
        }
        if (pos == s1.length) {
            return 0;
        }

        String key = new String(s1);
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        int best = Integer.MAX_VALUE;
        for (int i = pos + 1; i < s1.length; i++) {
            if (s1[i] == s2[pos] && s1[i] != s2[i]) {
                swap(s1, pos, i);
                best = Math.min(best, 1 + dfs(s1, s2, pos + 1, memo));
                swap(s1, pos, i);
            }
        }

        memo.put(key, best);
        return best;
    }

    private void swap(char[] arr, int i, int j) {
        char tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
