        }
        char[] arr = a.toCharArray();
        Map<String, Integer> memo = new HashMap<>();
        return dfs(arr, 0, b, memo);
    }

    private int dfs(char[] a, int idx, String target, Map<String, Integer> memo) {
        int n = a.length;
        while (idx < n && a[idx] == target.charAt(idx)) {
            idx++;
        }
        if (idx == n) {
            return 0;
        }

        String key = new String(a);
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        int best = Integer.MAX_VALUE;
        char need = target.charAt(idx);

        for (int i = idx + 1; i < n; i++) {
            if (a[i] == need && a[i] != target.charAt(i)) {
                swap(a, idx, i);
                int cur = 1 + dfs(a, idx + 1, target, memo);
                if (cur < best) {
                    best = cur;
                }
                swap(a, idx, i);
            }
        }

        memo.put(key, best);
        return best;
    }

    private void swap(char[] a, int i, int j) {
        char temp = a[i];
        a[i] = a[j];
        a[j] = temp;
    }
