import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int kSimilarity(String a, String b) {
        return dfs(a.toCharArray(), b.toCharArray(), new HashMap<>());
    }

    private int dfs(char[] a, char[] b, Map<String, Integer> memo) {
        String key = new String(a);
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        int n = a.length;
        int i = 0;
        while (i < n && a[i] == b[i]) {
            i++;
        }

        if (i == n) {
            return 0; // already equal
        }

        int min = Integer.MAX_VALUE;
        for (int j = i + 1; j < n; j++) {
            if (a[j] == b[i] && a[j] != b[j]) {
                swap(a, i, j);
                int res = dfs(a, b, memo);
                if (res < min) {
                    min = res;
                }
                swap(a, i, j); // backtrack
            }
        }

        int ans = 1 + min;
        memo.put(key, ans);
        return ans;
    }

    private void swap(char[] arr, int i, int j) {
        char tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }
}

