public class Solution {

    public int primePalindrome(int n) {
        if (n < 2) return 2; // smallest prime palindrome

        // 2, 3, 5 and 11 are primes and palindromes
        if (n <= 11) return n;

        // If n is even, the next palindrome is n + 9
        if (n % 2 == 0) return n + 9;

        // Search odd numbers only
        for (int candidate = n; candidate <= Integer.MAX_VALUE; candidate += 2) {
            if (isPalindrome(candidate) && isPrime(candidate)) {
                return candidate;
            }
        }
        // According to the problem statement this line never runs
        return -1;
    }

    private boolean isPalindrome(int num) {
        int rev = 0;
        int temp = num;
        while (temp > 0) {
            rev = rev * 10 + temp % 10;
            temp /= 10;
        }
        return rev == num;
    }

    private boolean isPrime(int num) {
        if (num < 2) return false;
        if (num == 2) return true;
        if (num % 2 == 0) return false;

        int sqrt = (int) Math.sqrt(num);
        for (int i = 3; i <= sqrt; i += 2) {
            if (num % i == 0) return false;
        }
        return true;
    }
}

