public class Solution {

    public static int primePalindrome(int n) {
        if (n <= 2) return 2;          // 2 is the only 1‑digit prime palindrome
        if (n % 2 == 0) return n + 1; // make n odd to increase chances

        for (long candidate = n | 1L; candidate <= 200_000_000L; candidate += 2) {
            if (isPalindrome(candidate) && isPrime(candidate))
                return (int) candidate;
        }
        return -1; // should never reach here
    }

    private static boolean isPalindrome(long num) {
        long rev = 0, x = num;
        while (x > 0) {
            rev = rev * 10 + x % 10;
            x /= 10;
        }
        return rev == num;
    }

    private static boolean isPrime(long num) {
        if (num < 2) return false;
        if (num % 2 == 0) return num == 2;
        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) return false;
        }
        return true;
    }
}

