public class Solution {

    // Return the smallest prime palindrome >= n
    public int smallestPrimePalindrome(int n) {
        if (n <= 2) return 2;              // 2 is the only even prime palindrome

        for (int candidate = n; ; candidate++) {
            if (candidate % 2 == 0 && candidate > 2) candidate++;   // Skip all even numbers > 2
            if (isPalindrome(candidate) && isPrime(candidate)) return candidate;
        }
    }

    // Check if a number is a palindrome
    private boolean isPalindrome(int x) {
        String s = Integer.toString(x);
        int l = 0, r = s.length() - 1;
        while (l < r) {
            if (s.charAt(l) != s.charAt(r)) return false;
            l++; r--;
        }
        return true;
    }

    // Check if a number is prime
    private boolean isPrime(int x) {
        if (x < 2) return false;
        if (x == 2) return true;
        if (x % 2 == 0) return false;
        int limit = (int) Math.sqrt(x);
        for (int i = 3; i <= limit; i += 2) {
            if (x % i == 0) return false;
        }
        return true;
    }
}

