public class Solution {
    public int primePalindrome(int n) {
        // Handle the trivial small values
        if (n <= 2) {
            return 2;
        }
        // For n == 3, 5 or 7 the answer is 2
        if (n <= 5) {
            return 2;
        }

        // Make sure we start with an odd candidate
        int candidate = Math.max(n, 5);
        if (candidate % 2 == 0) {
            candidate++; // make it odd
        }

        while (true) {
            if (isPalindrome(candidate) && isPrime(candidate)) {
                return candidate;
            }
            candidate += 2; // only odd numbers need checking
        }
    }

    private boolean isPalindrome(int x) {
        String s = Integer.toString(x);
        int i = 0, j = s.length() - 1;
        while (i < j) {
            if (s.charAt(i) != s.charAt(j)) {
                return false;
            }
            i++;
            j--;
        }
        return true;
    }

    private boolean isPrime(int x) {
        if (x < 2) {
            return false;
        }
        if (x % 2 == 0) {
            return x == 2;
        }
        int limit = (int) Math.sqrt(x);
        for (int i = 3; i <= limit; i += 2) {
            if (x % i == 0) {
                return false;
            }
        }
        return true;
    }
}

