public class Solution {
    public int minSwap(int[] listA, int[] listB) {
        int n = listA.length;
        int INF = Integer.MAX_VALUE / 2;
        int keep = 0;   // no swap at position 0
        int swap = 1;   // swap at position 0

        for (int i = 1; i < n; i++) {
            int newKeep = INF;
            int newSwap = INF;

            // Case 1: keep both at i
            if (listA[i - 1] < listA[i] && listB[i - 1] < listB[i]) {
                newKeep = Math.min(newKeep, keep);
                newSwap = Math.min(newSwap, swap + 1);
            }

            // Case 2: swap at i
            if (listA[i - 1] < listB[i] && listB[i - 1] < listA[i]) {
                newKeep = Math.min(newKeep, swap);
                newSwap = Math.min(newSwap, keep + 1);
            }

            keep = newKeep;
            swap = newSwap;
        }

        return Math.min(keep, swap);
    }
}

