public class Solution {
    public int minSwap(int[] listA, int[] listB) {
        int n = listA.length;
        if (n == 0) return 0;
        // dpNoSwap: min swaps up to i with no swap at i
        // dpSwap: min swaps up to i with swap at i
        int dpNoSwap = 0;        // i==0, no swap
        int dpSwap = 1;          // i==0, swapped

        for (int i = 1; i < n; i++) {
            int nextNoSwap = Integer.MAX_VALUE / 2;
            int nextSwap = Integer.MAX_VALUE / 2;

            // Case 1: keep order at i
            if (listA[i - 1] < listA[i] && listB[i - 1] < listB[i]) {
                // no swap at i
                nextNoSwap = Math.min(nextNoSwap, dpNoSwap);
                // swap at i
                nextSwap = Math.min(nextSwap, dpSwap + 1);
            }

            // Case 2: swap at i
            if (listA[i - 1] < listB[i] && listB[i - 1] < listA[i]) {
                // no swap at i but swap at i-1
                nextNoSwap = Math.min(nextNoSwap, dpSwap);
                // swap at i but no swap at i-1
                nextSwap = Math.min(nextSwap, dpNoSwap + 1);
            }

            dpNoSwap = nextNoSwap;
            dpSwap = nextSwap;
        }

        return Math.min(dpNoSwap, dpSwap);
    }
}

