public class Solution {
    private Map<String, Integer> memo = new HashMap<>();

    public int kSimilarity(String a, String b) {
        if (a.equals(b)) return 0;
        return dfs(a, b);
    }

    private int dfs(String s, String target) {
        if (s.equals(target)) return 0;
        if (memo.containsKey(s)) return memo.get(s);

        int firstDiff = -1;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) != target.charAt(i)) {
                firstDiff = i;
                break;
            }
        }

        int minSwaps = Integer.MAX_VALUE;
        char sFirst = s.charAt(firstDiff);
        for (int j = firstDiff + 1; j < s.length(); j++) {
            if (s.charAt(j) == target.charAt(firstDiff) && s.charAt(j) != target.charAt(j)) {
                String swapped = swap(s, firstDiff, j);
                int subResult = dfs(swapped, target);
                if (subResult + 1 < minSwaps) {
                    minSwaps = subResult + 1;
                }
            }
        }

        memo.put(s, minSwaps);
        return minSwaps;
    }

    private String swap(String s, int i, int j) {
        char[] arr = s.toCharArray();
        char tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
