import java.util.HashSet;
import java.util.LinkedList;
import java.util.Queue;
import java.util.Set;

public class Solution {
    public int kSimilarity(String a, String b) {
        if (a.equals(b)) return 0;
        Set<String> visited = new HashSet<>();
        Queue<String> queue = new LinkedList<>();
        queue.offer(a);
        visited.add(a);
        int depth = 0;
        while (!queue.isEmpty()) {
            int size = queue.size();
            depth++;
            for (int s = 0; s < size; s++) {
                String curr = queue.poll();
                int i = 0;
                while (i < curr.length() && curr.charAt(i) == b.charAt(i)) {
                    i++;
                }
                for (int j = i + 1; j < curr.length(); j++) {
                    if (curr.charAt(j) == b.charAt(i) && curr.charAt(j) != curr.charAt(i)) {
                        String newStr = swap(curr, i, j);
                        if (newStr.equals(b)) return depth;
                        if (visited.add(newStr)) {
                            queue.offer(newStr);
                        }
                    }
                }
            }
        }
        return -1; // should never reach here for anagrams
    }

    private String swap(String s, int i, int j) {
        char[] arr = s.toCharArray();
        char temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        return new String(arr);
    }
}

