public class Solution {
    public String shiftingLetters(String s, int[] shifts) {
        int n = s.length();
        int[] suffix = new int[n];
        for (int i = n - 1; i >= 0; i--) {
            long sum = shifts[i];
            if (i + 1 < n) {
                sum += suffix[i + 1];
            }
            suffix[i] = (int) (sum % 26);
        }
        char[] chars = s.toCharArray();
        for (int i = 0; i < n; i++) {
            chars[i] = (char) ('a' + (chars[i] - 'a' + suffix[i]) % 26);
        }
        return new String(chars);
    }
}

