public class Solution {
    public int matrixScore(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int score = 0;

        // Ensure the most significant bit (first column) is 1 for all rows
        int msbWeight = 1 << (n - 1);
        score += msbWeight * m; // all rows will have 1 in first column after optimal toggles

        // Count 1s for each other column after toggling rows to set first column to 1
        int[] onesCount = new int[n];
        for (int i = 0; i < m; i++) {
            boolean rowToggled = (grid[i][0] == 0);
            for (int j = 1; j < n; j++) {
                int bit = grid[i][j];
                if (rowToggled) {
                    bit ^= 1; // toggle the bit
                }
                if (bit == 1) {
                    onesCount[j]++;
                }
            }
        }

        // For each remaining column, decide whether to toggle it
        for (int j = 1; j < n; j++) {
            int ones = onesCount[j];
            int zeros = m - ones;
            int effectiveOnes = Math.max(ones, zeros);
            int weight = 1 << (n - 1 - j);
            score += effectiveOnes * weight;
        }

        return score;
    }
}

