import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int[] sumOfDistancesInTree(int n, int[][] edges) {
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }

        int[] count = new int[n]; // number of nodes in subtree rooted at i
        int[] sum = new int[n];   // sum of distances from i to nodes in its subtree
        int[] ans = new int[n];   // final answer

        dfs1(0, -1, graph, count, sum);
        dfs2(0, -1, graph, count, sum, ans, n);
        return ans;
    }

    private void dfs1(int node, int parent, List<Integer>[] graph, int[] count, int[] sum) {
        count[node] = 1;
        for (int nei : graph[node]) {
            if (nei == parent) continue;
            dfs1(nei, node, graph, count, sum);
            count[node] += count[nei];
            sum[node] += sum[nei] + count[nei];
        }
    }

    private void dfs2(int node, int parent, List<Integer>[] graph, int[] count, int[] sum, int[] ans, int n) {
        ans[node] = sum[node];
        for (int nei : graph[node]) {
            if (nei == parent) continue;
            // move root from node to nei
            int origSumNode = sum[node];
            int origSumNei = sum[nei];

            // update sum for node and nei as if nei becomes root
            sum[node] -= sum[nei] + count[nei];
            count[node] -= count[nei];
            sum[nei] += sum[node] + count[node];
            count[nei] += count[node];

            dfs2(nei, node, graph, count, sum, ans, n);

            // restore original values
            sum[node] = origSumNode;
            count[node] = count[node] + count[nei] - count[nei]; // no change needed
            sum[nei] = origSumNei;
            count[nei] = count[nei];
        }
    }
}

