        }

        int[] size = new int[n];       // number of nodes in subtree rooted at i
        int[] ans = new int[n];        // final answer
        int[] rootSum = new int[1];    // sum of distances from root to all nodes

        // First DFS: compute subtree sizes and distance sum for root (node 0)
        dfs1(0, -1, graph, size, rootSum);

        // Assign answer for root
        ans[0] = rootSum[0];

        // Second DFS: compute answers for all nodes using DP relation
        dfs2(0, -1, graph, size, ans, n);

        return ans;
    }

    private void dfs1(int node, int parent, List<Integer>[] graph,
                      int[] size, int[] rootSum) {
        size[node] = 1;
        for (int nei : graph[node]) {
            if (nei == parent) continue;
            dfs1(nei, node, graph, size, rootSum);
            size[node] += size[nei];
            rootSum[0] += size[nei]; // each node in nei's subtree is one edge farther from root
        }
    }

    private void dfs2(int node, int parent, List<Integer>[] graph,
                      int[] size, int[] ans, int n) {
        for (int nei : graph[node]) {
            if (nei == parent) continue;
            ans[nei] = ans[node] + n - 2 * size[nei];
            dfs2(nei, node, graph, size, ans, n);
        }
    }
}

