import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Stack;

public class Solution {
    public int[] sumOfDistancesInTree(int n, int[][] edges) {
        if (n == 0) return new int[0];
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
        }
        for (int[] edge : edges) {
            int u = edge[0], v = edge[1];
            adj[u].add(v);
            adj[v].add(u);
        }

        int[] size = new int[n];
        int[] distSum = new int[n];
        int[] parent = new int[n];
        Arrays.fill(parent, -1);

        // First DFS: post-order to compute size and distSum for root
        Stack<int[]> stack = new Stack<>();
        stack.push(new int[]{0, -1, 0}); // node, parent, state
        while (!stack.isEmpty()) {
            int[] cur = stack.pop();
            int node = cur[0];
            int par = cur[1];
            int state = cur[2];
            if (state == 0) {
                parent[node] = par;
                stack.push(new int[]{node, par, 1});
                for (int nei : adj[node]) {
                    if (nei == par) continue;
                    stack.push(new int[]{nei, node, 0});
                }
            } else {
                int sz = 1;
                int sum = 0;
                for (int nei : adj[node]) {
                    if (nei == par) continue;
                    sz += size[nei];
                    sum += distSum[nei] + size[nei];
                }
                size[node] = sz;
                distSum[node] = sum;
            }
        }

        int[] answer = new int[n];
        answer[0] = distSum[0];

        // Second DFS: pre-order to compute answer for all nodes
        Stack<Integer> stack2 = new Stack<>();
        stack2.push(0);
        while (!stack2.isEmpty()) {
            int node = stack2.pop();
            for (int nei : adj[node]) {
                if (nei == parent[node]) continue;
                answer[nei] = answer[node] - size[nei] + (n - size[nei]);
                stack2.push(nei);
            }
        }

        return answer;
    }
}

