import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Solution {
    private static final int MOD = 1_000_000_007;

    public int rectangleArea(int[][] rectangles) {
        int n = rectangles.length;
        int[] yVals = new int[2 * n];
        int idx = 0;
        for (int[] rect : rectangles) {
            yVals[idx++] = rect[1];
            yVals[idx++] = rect[3];
        }
        Arrays.sort(yVals);
        int m = 0;
        for (int i = 0; i < yVals.length; i++) {
            if (i == 0 || yVals[i] != yVals[i - 1]) {
                yVals[m++] = yVals[i];
            }
        }
        yVals = Arrays.copyOf(yVals, m);

        // Build events
        List<Event> events = new ArrayList<>(2 * n);
        for (int[] rect : rectangles) {
            int x1 = rect[0], y1 = rect[1], x2 = rect[2], y2 = rect[3];
            int y1Idx = Arrays.binarySearch(yVals, y1);
            int y2Idx = Arrays.binarySearch(yVals, y2);
            events.add(new Event(x1, y1Idx, y2Idx, 1));
            events.add(new Event(x2, y1Idx, y2Idx, -1));
        }
        events.sort((a, b) -> Integer.compare(a.x, b.x));

        SegmentTree st = new SegmentTree(yVals);
        long area = 0;
        int prevX = events.get(0).x;
        for (Event e : events) {
            int curX = e.x;
            long dx = (long) curX - prevX;
            long coveredY = st.totalCovered();
            area = (area + dx * coveredY) % MOD;
            st.update(e.y1, e.y2, e.type);
            prevX = curX;
        }
        return (int) area;
    }

    private static class Event {
        int x, y1, y2, type;
        Event(int x, int y1, int y2, int type) {
            this.x = x;
            this.y1 = y1;
            this.y2 = y2;
            this.type = type;
        }
    }

    private static class SegmentTree {
        private final int[] yVals;
        private final int n;
        private final int[] count;
        private final long[] length;

        SegmentTree(int[] yVals) {
            this.yVals = yVals;
            this.n = yVals.length - 1; // number of segments
            int size = 4 * n;
            count = new int[size];
            length = new long[size];
        }

        void update(int l, int r, int val) {
            update(1, 0, n - 1, l, r - 1, val);
        }

        private void update(int node, int nl, int nr, int l, int r, int val) {
            if (l > nr || r < nl) return;
            if (l <= nl && nr <= r) {
                count[node] += val;
                pushUp(node, nl, nr);
                return;
            }
            int mid = (nl + nr) >> 1;
            update(node << 1, nl, mid, l, r, val);
            update(node << 1 | 1, mid + 1, nr, l, r, val);
            pushUp(node, nl, nr);
        }

        private void pushUp(int node, int nl, int nr) {
            if (count[node] > 0) {
                length[node] = (long) yVals[nr + 1] - yVals[nl];
            } else if (nl == nr) {
                length[node] = 0;
            } else {
                length[node] = length[node << 1] + length[node << 1 | 1];
            }
        }

        long totalCovered() {
            return length[1];
        }
    }
}

