            if (count[node] > 0) {
                total[node] = y[r] - y[l];
            } else {
                if (l + 1 == r) {
                    total[node] = 0;
                } else {
                    total[node] = total[node << 1] + total[node << 1 | 1];
                }
            }
        }
    }

    public int rectangleArea(int[][] rectangles) {
