            }
        }
        yArr = Arrays.copyOf(yArr, m);

        // Map y values to indices
        for (Event e : events) {
            e.y1 = Arrays.binarySearch(yArr, e.y1);
            e.y2 = Arrays.binarySearch(yArr, e.y2);
        }

        // Sort events by x
        events.sort(Comparator.comparingInt(a -> a.x));

        SegmentTree seg = new SegmentTree(yArr);
        long area = 0;
        int prevX = events.get(0).x;
