            this.type = type;
        }
    }

    // Segment tree to maintain covered length
    private static class SegmentTree {
        private final long[] yCoords;
        private final int[] count;
        private final long[] length;

        SegmentTree(long[] yCoords) {
            this.yCoords = yCoords;
            int n = yCoords.length;
            count = new int[4 * n];
            length = new long[4 * n];
        }

        void update(int node, int l, int r, int ul, int ur, int val) {
            if (ul >= r || ur <= l) return;
            if (ul <= l && r <= ur) {
                count[node] += val;
            } else {
                int mid = (l + r) >>> 1;
                update(node << 1, l, mid, ul, ur, val);
                update(node << 1 | 1, mid, r, ul, ur, val);
            }
            if (count[node] > 0) {
                length[node] = yCoords[r] - yCoords[l];
            } else {
                if (l + 1 == r) {
                    length[node] = 0;
                } else {
                    length[node] = length[node << 1] + length[node << 1 | 1];
                }
            }
        }

        long query() {
            return length[1];
        }
    }

    public int rectangleArea(int[][] rectangles) {
        int n = rectangles.length;
        List<Event> events = new ArrayList<>(2 * n);
        List<Long> yList = new ArrayList<>(2 * n);

        for (int[] rect : rectangles) {
            int x1 = rect[0], y1 = rect[1], x2 = rect[2], y2 = rect[3];
            events.add(new Event(x1, y1, y2, 1));
            events.add(new Event(x2, y1, y2, -1));
            yList.add((long) y1);
            yList.add((long) y2);
        }

        // Coordinate compression
        long[] yCoords = yList.stream().distinct().sorted().mapToLong(Long::longValue).toArray();

        // Map y values to indices
        for (Event e : events) {
            e.y1 = Arrays.binarySearch(yCoords, e.y1);
            e.y2 = Arrays.binarySearch(yCoords, e.y2);
        }

        events.sort(Comparator.comparingInt(o -> o.x));

        SegmentTree st = new SegmentTree(yCoords);
        long area = 0;
        int prevX = events.get(0).x;
        int size = events.size();
        int i = 0;
        while (i < size) {
            int currX = events.get(i).x;
            long dx = currX - prevX;
            long coveredY = st.query();
            area = (area + (dx % MOD) * (coveredY % MOD)) % MOD;

            // Process all events at currX
            while (i < size && events.get(i).x == currX) {
                Event e = events.get(i);
                st.update(1, 0, yCoords.length - 1, e.y1, e.y2, e.type);
