import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

public class Solution {
    private static final long MOD = 1_000_000_007L;

    public int rectangleArea(int[][] rectangles) {
        // Collect all y-coordinates for compression
        List<Long> yList = new ArrayList<>();
        for (int[] rect : rectangles) {
            yList.add((long) rect[1]);
            yList.add((long) rect[3]);
        }
        Collections.sort(yList);
        List<Long> uniqY = new ArrayList<>();
        Long prev = null;
        for (Long v : yList) {
            if (!v.equals(prev)) {
                uniqY.add(v);
                prev = v;
            }
        }
        int m = uniqY.size();
        long[] y = new long[m];
        for (int i = 0; i < m; i++) y[i] = uniqY.get(i);

        // Build events
        List<Event> events = new ArrayList<>(rectangles.length * 2);
        for (int[] rect : rectangles) {
            int x1 = rect[0];
            int y1 = rect[1];
            int x2 = rect[2];
            int y2 = rect[3];
            int y1Idx = lowerBound(y, y1);
            int y2Idx = lowerBound(y, y2);
            events.add(new Event(x1, y1Idx, y2Idx, 1));
            events.add(new Event(x2, y1Idx, y2Idx, -1));
        }
        events.sort(Comparator.comparingInt(e -> e.x));

        // Sweep line
        SegmentTree st = new SegmentTree(y);
        long area = 0;
        int i = 0;
        while (i < events.size()) {
            int currX = events.get(i).x;
            // Process all events at this x
            while (i < events.size() && events.get(i).x == currX) {
                Event e = events.get(i);
                st.update(1, 0, st.size, e.y1, e.y2, e.type);
                i++;
            }
            if (i < events.size()) {
                int nextX = events.get(i).x;
                long coveredY = st.total();
                long dx = (long) nextX - currX;
                area = (area + (coveredY % MOD) * (dx % MOD)) % MOD;
            }
        }
        return (int) area;
    }

    private static int lowerBound(long[] arr, int target) {
        int l = 0, r = arr.length;
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (arr[mid] < target) l = mid + 1;
            else r = mid;
        }
        return l;
    }

    private static class Event {
        int x, y1, y2, type;
        Event(int x, int y1, int y2, int type) {
            this.x = x;
            this.y1 = y1;
            this.y2 = y2;
            this.type = type;
        }
    }

    private static class SegmentTree {
        int size;
        int[] count;
        long[] len;
        long[] y;

        SegmentTree(long[] y) {
            this.y = y;
            this.size = y.length - 1;
            this.count = new int[4 * size];
            this.len = new long[4 * size];
        }

        void update(int node, int l, int r, int ul, int ur, int val) {
            if (ul >= r || ur <= l) return;
            if (ul <= l && r <= ur) {
                count[node] += val;
            } else {
                int mid = (l + r) >>> 1;
                update(node * 2, l, mid, ul, ur, val);
                update(node * 2 + 1, mid, r, ul, ur, val);
            }
            if (count[node] > 0) {
                len[node] = y[r] - y[l];
            } else {
                if (l + 1 == r) {
                    len[node] = 0;
                } else {
                    len[node] = len[node * 2] + len[node * 2 + 1];
                }
            }
        }

        long total() {
            return len[1];
        }
    }
}

