import java.util.*;

public class Solution {
    private static final long MOD = 1_000_000_007L;

    private static class Event implements Comparable<Event> {
        int x;
        int y1, y2;
        int type; // +1 for entering, -1 for leaving

        Event(int x, int y1, int y2, int type) {
            this.x = x;
            this.y1 = y1;
            this.y2 = y2;
            this.type = type;
        }

        @Override
        public int compareTo(Event other) {
            return Integer.compare(this.x, other.x);
        }
    }

    private static class SegmentTree {
        private final long[] len; // covered length of node interval
        private final int[] count; // coverage count
        private final int[] y; // compressed y coordinates
        private final int n; // number of intervals

        SegmentTree(int[] y) {
            this.y = y;
            this.n = y.length - 1; // intervals between consecutive y's
            int size = 4 * n + 5;
            len = new long[size];
            count = new int[size];
        }

        void update(int l, int r, int val) {
            update(1, 0, n, l, r, val);
        }

        private void update(int node, int nl, int nr, int l, int r, int val) {
            if (l >= nr || r <= nl) {
                return;
            }
            if (l <= nl && nr <= r) {
                count[node] += val;
                pushUp(node, nl, nr);
                return;
            }
            int mid = (nl + nr) >>> 1;
            update(node << 1, nl, mid, l, r, val);
            update(node << 1 | 1, mid, nr, l, r, val);
            pushUp(node, nl, nr);
        }

        private void pushUp(int node, int nl, int nr) {
            if (count[node] > 0) {
                len[node] = (long) y[nr] - y[nl];
            } else if (nl + 1 == nr) {
                len[node] = 0;
            } else {
                len[node] = len[node << 1] + len[node << 1 | 1];
            }
        }

        long getTotalCovered() {
            return len[1];
        }
    }

    public int rectangleArea(int[][] rectangles) {
        int n = rectangles.length;
        int[] yVals = new int[2 * n];
        List<Event> events = new ArrayList<>(2 * n);
        for (int i = 0; i < n; i++) {
            int x1 = rectangles[i][0];
            int y1 = rectangles[i][1];
            int x2 = rectangles[i][2];
            int y2 = rectangles[i][3];
            events.add(new Event(x1, y1, y2, 1));
            events.add(new Event(x2, y1, y2, -1));
            yVals[2 * i] = y1;
            yVals[2 * i + 1] = y2;
        }

        Arrays.sort(yVals);
        int[] yUnique = Arrays.stream(yVals).distinct().toArray();

        // Map original y to indices in yUnique
        Map<Integer, Integer> yIndex = new HashMap<>(yUnique.length * 2);
        for (int i = 0; i < yUnique.length; i++) {
            yIndex.put(yUnique[i], i);
        }

        for (Event e : events) {
            e.y1 = yIndex.get(e.y1);
            e.y2 = yIndex.get(e.y2);
        }

        Collections.sort(events);

        SegmentTree segTree = new SegmentTree(yUnique);

        long area = 0;
        int prevX = events.get(0).x;
        int idx = 0;
        while (idx < events.size()) {
            int curX = events.get(idx).x;
            long deltaX = (long) curX - prevX;
            area = (area + deltaX * segTree.getTotalCovered()) % MOD;

            while (idx < events.size() && events.get(idx).x == curX) {
                Event e = events.get(idx);
                segTree.update(e.y1, e.y2, e.type);
                idx++;
            }
            prevX = curX;
        }

        return (int) area;
    }
}

