public class Solution {
    public int[] advantageCount(int[] nums1, int[] nums2) {
        int n = nums1.length;
        int[] result = new int[n];

        // Sort nums1 ascending
        int[] sortedNums1 = nums1.clone();
        Arrays.sort(sortedNums1);

        // Create array of indices for nums2 and sort by nums2 values ascending
        Integer[] indices = new Integer[n];
        for (int i = 0; i < n; i++) {
            indices[i] = i;
        }
        Arrays.sort(indices, Comparator.comparingInt(i -> nums2[i]));

        int low = 0;
        int high = n - 1;

        for (int idx : indices) {
            if (sortedNums1[high] > nums2[idx]) {
                result[idx] = sortedNums1[high];
                high--;
            } else {
                result[idx] = sortedNums1[low];
                low++;
            }
        }

        return result;
    }
}

