        }

        // Create array of indices sorted by nums2 values ascending
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, Comparator.comparingInt(i -> nums2[i]));

        // Result array
        int[] res = new int[n];

        for (int i : idx) {
            int target = nums2[i];
            // Find smallest number > target
            Integer key = map.higherKey(target);
            if (key == null) {
                // No advantage, use smallest available
                key = map.firstKey();
            }
            res[i] = key;
            // Decrease count
            int cnt = map.get(key);
            if (cnt == 1) {
                map.remove(key);
            } else {
                map.put(key, cnt - 1);
            }
        }
        return res;
    }
}

