    private static final int MOD = 1_000_000_007;
    private static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    public int distinctSequences(int n) {
        if (n <= 0) return 0;
        // dp[prev][prev2] where prev2 can be 0..6 (0 means none)
        long[][] dp = new long[7][7];
        // position 1
        for (int v = 1; v <= 6; v++) {
            dp[v][0] = 1;
        }
        if (n == 1) {
            long sum = 0;
            for (int v = 1; v <= 6; v++) sum = (sum + dp[v][0]) % MOD;
            return (int) sum;
        }
        // position 2
        long[][] next = new long[7][7];
        for (int prev = 1; prev <= 6; prev++) {
            for (int cur = 1; cur <= 6; cur++) {
                if (cur == prev) continue; // no equal adjacent
                if (gcd(prev, cur) != 1) continue;
                next[cur][prev] = (next[cur][prev] + dp[prev][0]) % MOD;
            }
        }
        dp = next;
        if (n == 2) {
            long sum = 0;
            for (int v = 1; v <= 6; v++) {
                for (int p2 = 1; p2 <= 6; p2++) {
                    sum = (sum + dp[v][p2]) % MOD;
                }
            }
            return (int) sum;
        }
        // positions 3..n
        for (int pos = 3; pos <= n; pos++) {
            next = new long[7][7];
            for (int prev = 1; prev <= 6; prev++) {
                for (int prev2 = 1; prev2 <= 6; prev2++) {
                    long ways = dp[prev][prev2];
                    if (ways == 0) continue;
                    for (int cur = 1; cur <= 6; cur++) {
                        if (cur == prev || cur == prev2) continue;
                        if (gcd(prev, cur) != 1) continue;
                        next[cur][prev] = (next[cur][prev] + ways) % MOD;
                    }
                }
            }
            dp = next;
        }
        long result = 0;
        for (int v = 1; v <= 6; v++) {
            for (int p2 = 1; p2 <= 6; p2++) {
                result = (result + dp[v][p2]) % MOD;
            }
        }
        return (int) result;
    }
}

