public class Solution {
    private static final int MOD = 1_000_000_007;
    private static final int M = 6; // dice sides

    public int distinctSequences(int n) {
        if (n == 1) return M; // any single roll

        // Precompute gcd and adjacency allowed (gcd==1)
        boolean[][] allowed = new boolean[M + 1][M + 1];
        for (int i = 1; i <= M; i++) {
            for (int j = 1; j <= M; j++) {
                if (gcd(i, j) == 1) allowed[i][j] = true;
            }
        }

        // DP for length 2
        int[][] curr = new int[M + 1][M + 1];
        for (int a = 1; a <= M; a++) {
            for (int b = 1; b <= M; b++) {
                if (allowed[a][b]) curr[a][b] = 1;
            }
        }

        if (n == 2) {
            long sum = 0;
            for (int a = 1; a <= M; a++) {
                for (int b = 1; b <= M; b++) {
                    sum += curr[a][b];
                }
            }
            return (int) (sum % MOD);
        }

        // DP for length >=3
        int[][] next = new int[M + 1][M + 1];
        for (int len = 3; len <= n; len++) {
            for (int a = 1; a <= M; a++) { // a = previous previous
                for (int b = 1; b <= M; b++) { // b = previous
                    int cnt = curr[a][b];
                    if (cnt == 0) continue;
                    for (int x = 1; x <= M; x++) { // new value
                        if (!allowed[b][x]) continue; // gcd condition
                        if (x == a) continue; // gap rule
                        next[b][x] = (next[b][x] + cnt) % MOD;
                    }
                }
            }
            // swap curr and next, reset next
            int[][] temp = curr;
            curr = next;
            next = temp;
            for (int i = 1; i <= M; i++) Arrays.fill(next[i], 0);
        }

        long result = 0;
        for (int a = 1; a <= M; a++) {
            for (int b = 1; b <= M; b++) {
                result += curr[a][b];
            }
        }
        return (int) (result % MOD);
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

