public class Solution {
    private static final int MOD = 1_000_000_007;
    private static final int SIZE = 6; // dice faces 1-6
    private static final int STATE = SIZE * SIZE; // 36 states

    private static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    // multiply two matrices a and b (both STATE x STATE)
    private static long[][] mul(long[][] a, long[][] b) {
        long[][] res = new long[STATE][STATE];
        for (int i = 0; i < STATE; i++) {
            for (int k = 0; k < STATE; k++) {
                if (a[i][k] == 0) continue;
                long aik = a[i][k];
                for (int j = 0; j < STATE; j++) {
                    res[i][j] = (res[i][j] + aik * b[k][j]) % MOD;
                }
            }
        }
        return res;
    }

    // exponentiate matrix m to power p
    private static long[][] power(long[][] m, long p) {
        long[][] res = new long[STATE][STATE];
        for (int i = 0; i < STATE; i++) res[i][i] = 1;
        while (p > 0) {
            if ((p & 1) == 1) res = mul(m, res);
            m = mul(m, m);
            p >>= 1;
        }
        return res;
    }

    public int distinctSequences(int n) {
        if (n == 1) return SIZE % MOD;
        if (n == 2) {
            long cnt = 0;
            for (int a = 1; a <= 6; a++) {
                for (int b = 1; b <= 6; b++) {
                    if (a == b) continue;
                    if (gcd(a, b) == 1) cnt++;
                }
            }
            return (int) (cnt % MOD);
        }

        // build transition matrix
        long[][] trans = new long[STATE][STATE];
        for (int prev = 1; prev <= 6; prev++) {
            for (int prev2 = 1; prev2 <= 6; prev2++) {
                int from = (prev - 1) * SIZE + (prev2 - 1);
                for (int cur = 1; cur <= 6; cur++) {
                    if (cur == prev || cur == prev2) continue; // distance <=2
                    if (gcd(prev, cur) != 1) continue;
                    int to = (cur - 1) * SIZE + (prev - 1);
                    trans[to][from] = (trans[to][from] + 1) % MOD;
                }
            }
        }

        // base vector for length 2
        long[] base = new long[STATE];
        for (int prev = 1; prev <= 6; prev++) {
            for (int cur = 1; cur <= 6; cur++) {
                if (prev == cur) continue;
                if (gcd(prev, cur) != 1) continue;
                int idx = (cur - 1) * SIZE + (prev - 1);
                base[idx] = (base[idx] + 1) % MOD;
            }
        }

        // exponentiate transition
        long[][] transPow = power(trans, n - 2);

        // multiply transPow with base vector
        long[] vec = new long[STATE];
        for (int i = 0; i < STATE; i++) {
            long sum = 0;
            for (int j = 0; j < STATE; j++) {
                sum = (sum + transPow[i][j] * base[j]) % MOD;
            }
            vec[i] = sum;
        }

        // sum all entries
        long total = 0;
        for (long v : vec) total = (total + v) % MOD;
        return (int) total;
    }
}

