public class Solution {
    private static final int MOD = 1_000_000_007;
    private static final int MAX = 6;

    public int distinctSequences(int n) {
        if (n <= 0) return 0;
        // Precompute gcd table
        int[][] gcd = new int[MAX + 1][MAX + 1];
        for (int i = 1; i <= MAX; i++) {
            for (int j = 1; j <= MAX; j++) {
                gcd[i][j] = gcd(i, j);
            }
        }

        // dp[prev][curr] for current length
        long[][] dp = new long[MAX + 1][MAX + 1]; // index 0 used as sentinel for no previous value
        // initialization for length 1
        for (int curr = 1; curr <= MAX; curr++) {
            dp[0][curr] = 1;
        }

        // iterate lengths from 1 to n-1
        for (int len = 1; len < n; len++) {
            long[][] nextDp = new long[MAX + 1][MAX + 1];
            for (int prev = 0; prev <= MAX; prev++) {
                for (int curr = 1; curr <= MAX; curr++) {
                    long ways = dp[prev][curr];
                    if (ways == 0) continue;
                    for (int nxt = 1; nxt <= MAX; nxt++) {
                        if (nxt == curr) continue;               // adjacent cannot be equal
                        if (prev != 0 && nxt == prev) continue;   // distance 2 cannot be equal
                        if (gcd[curr][nxt] != 1) continue;        // gcd of adjacent must be 1
                        nextDp[curr][nxt] = (nextDp[curr][nxt] + ways) % MOD;
                    }
                }
            }
            dp = nextDp;
        }

        // sum all sequences of length n
        long result = 0;
        for (int prev = 0; prev <= MAX; prev++) {
            for (int curr = 1; curr <= MAX; curr++) {
                result += dp[prev][curr];
                if (result >= MOD) result -= MOD;
            }
        }
        return (int) result;
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
