                    int curWays = dp[prev][prevPrev];
                    if (curWays == 0) continue;
                    for (int nxt = 1; nxt <= MAX_VAL; nxt++) {
                        if (nxt == prev || nxt == prevPrev) continue;
                        if (gcdCache[prev][nxt] != 1) continue;
                        int val = (int) ((next[nxt][prev] + curWays) % MOD);
                        next[nxt][prev] = val;
                    }
                }
            }
            int[][] temp = dp;
            dp = next;
            next = temp;
        }

        long total = 0;
        for (int a = 1; a <= MAX_VAL; a++) {
            for (int b = 0; b <= MAX_VAL; b++) {
                total += dp[a][b];
                if (total >= MOD) total -= MOD;
            }
        }
        return (int) total;
    }
}

