import java.util.HashSet;
import java.util.Set;
import java.util.Arrays;

public class Solution {
    public long countExcellentPairs(int[] nums, int k) {
        Set<Integer> uniqueSet = new HashSet<>();
        for (int num : nums) {
            uniqueSet.add(num);
        }
        int n = uniqueSet.size();
        if (n == 0) return 0L;

        int[] popCounts = new int[n];
        int idx = 0;
        for (int val : uniqueSet) {
            popCounts[idx++] = Integer.bitCount(val);
        }

        Arrays.sort(popCounts);
        long result = 0L;
        for (int pc : popCounts) {
            int need = k - pc;
            if (need <= 0) {
                result += n;
            } else {
                int pos = lowerBound(popCounts, need);
                result += n - pos;
            }
        }
        return result;
    }

    // Find first index where arr[i] >= target
    private int lowerBound(int[] arr, int target) {
        int l = 0, r = arr.length;
        while (l < r) {
            int m = (l + r) >>> 1;
            if (arr[m] < target) {
                l = m + 1;
            } else {
                r = m;
            }
        }
        return l;
    }
}

