public class Solution {
    public int minPathCost(int[][] grid, int[][] moveCost) {
        int m = grid.length;
        int n = grid[0].length;

        // dp[r][c] - minimum cost to reach cell (r, c)
        long[][] dp = new long[m][n];
        final long INF = Long.MAX_VALUE / 4;

        // initialize first row
        for (int c = 0; c < n; c++) {
            dp[0][c] = grid[0][c];
        }

        // iterate over rows
        for (int r = 1; r < m; r++) {
            for (int c = 0; c < n; c++) {
                long best = INF;
                for (int p = 0; p < n; p++) {
                    int prevVal = grid[r - 1][p];
                    long candidate = dp[r - 1][p] + moveCost[prevVal][c];
                    if (candidate < best) {
                        best = candidate;
                    }
                }
                dp[r][c] = grid[r][c] + best;
            }
        }

        // find minimum in last row
        long answer = INF;
        for (int c = 0; c < n; c++) {
            if (dp[m - 1][c] < answer) {
                answer = dp[m - 1][c];
            }
        }

        return (int) answer;
    }
}

