        Map<String, Integer> colCount = new HashMap<>();

        // Count rows
        for (int i = 0; i < n; i++) {
            String key = Arrays.toString(grid[i]);
            rowCount.put(key, rowCount.getOrDefault(key, 0) + 1);
        }

        // Count columns
        for (int j = 0; j < n; j++) {
            int[] col = new int[n];
            for (int i = 0; i < n; i++) {
                col[i] = grid[i][j];
            }
