public class Solution {
    private static class UnionFind {
        int[] parent;
        int[] size;
        int count;

        UnionFind(int n) {
            parent = new int[n];
            size = new int[n];
            count = n;
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union(int x, int y) {
            int px = find(x);
            int py = find(y);
            if (px == py) return;
            if (size[px] < size[py]) {
                int tmp = px;
                px = py;
                py = tmp;
            }
            parent[py] = px;
            size[px] += size[py];
            count--;
        }

        int getSize(int x) {
            return size[find(x)];
        }
    }

    public long countPairs(int n, int[][] edges) {
        UnionFind uf = new UnionFind(n);
        for (int[] e : edges) {
            uf.union(e[0], e[1]);
        }

        // Map root to component size
        Map<Integer, Integer> compSize = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int root = uf.find(i);
            compSize.put(root, uf.getSize(i));
        }

        long result = 0;
        long processed = 0;
        for (int sz : compSize.values()) {
            result += sz * processed;
            processed += sz;
        }
        return result;
    }
}

