public class Solution {
    public long countPairs(int n, int[][] edges) {
        int[] parent = new int[n];
        int[] sz = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            sz[i] = 1;
        }

        for (int[] e : edges) {
            int a = e[0];
            int b = e[1];
            union(a, b, parent, sz);
