        for (int i = 0; i < n; i++) {
            if (parent[i] == i) {
                long s = sz[i];
                totalPairs -= s * (s - 1) / 2;
            }
        }
        return totalPairs;
    }

    private int find(int x, int[] parent) {
        if (parent[x] != x) {
            parent[x] = find(parent[x], parent);
        }
        return parent[x];
    }

    private void union(int a, int b, int[] parent, int[] sz) {
        int pa = find(a, parent);
        int pb = find(b, parent);
        if (pa == pb) {
            return;
        }
        if (sz[pa] < sz[pb]) {
            int temp = pa;
            pa = pb;
            pb = temp;
        }
        parent[pb] = pa;
        sz[pa] += sz[pb];
    }
}

