public class Solution {
    // Union-Find (Disjoint Set Union) implementation
    private static class DSU {
        int[] parent;
        int[] sz;

        DSU(int n) {
            parent = new int[n];
            sz = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                sz[i] = 1;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]); // Path compression
            }
            return parent[x];
        }

        void union(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return;
            // Union by size
            if (sz[ra] < sz[rb]) {
                int temp = ra;
                ra = rb;
                rb = temp;
            }
            parent[rb] = ra;
            sz[ra] += sz[rb];
        }

        int getSize(int x) {
            return sz[find(x)];
        }
    }

    public long countPairs(int n, int[][] edges) {
        DSU dsu = new DSU(n);

        // Merge connected nodes
        for (int[] edge : edges) {
            dsu.union(edge[0], edge[1]);
        }

        // Count component sizes
        Map<Integer, Integer> compSize = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int root = dsu.find(i);
            compSize.merge(root, 1, Integer::sum);
        }

        long totalPairs = (long) n * (n - 1) / 2;
        long connectedPairs = 0;
        for (int size : compSize.values()) {
            connectedPairs += (long) size * (size - 1) / 2;
        }

        return totalPairs - connectedPairs;
    }
}

