import java.util.Deque;
import java.util.ArrayDeque;

public class Solution {
    public int maximumRobots(int[] chargeTimes, int[] runningCosts, long budget) {
        int n = chargeTimes.length;
        int left = 0;
        long sumRunning = 0;
        int maxSize = 0;
        Deque<Integer> maxDeque = new ArrayDeque<>(); // indices of chargeTimes in decreasing order

        for (int right = 0; right < n; right++) {
            // add new element to window
            sumRunning += runningCosts[right];
            while (!maxDeque.isEmpty() && chargeTimes[maxDeque.peekLast()] <= chargeTimes[right]) {
                maxDeque.pollLast();
            }
            maxDeque.offerLast(right);

            // shrink window while cost exceeds budget
            while (left <= right) {
                long maxCharge = chargeTimes[maxDeque.peekFirst()];
                long cost = maxCharge + (long)(right - left + 1) * sumRunning;
                if (cost <= budget) {
                    break;
                }
                // remove leftmost element
                if (maxDeque.peekFirst() == left) {
                    maxDeque.pollFirst();
                }
                sumRunning -= runningCosts[left];
                left++;
            }

            // update answer
            maxSize = Math.max(maxSize, right - left + 1);
        }

        return maxSize;
    }
}

