            // Shrink window from left while cost exceeds budget
            while (left <= right) {
                long maxCharge = chargeTimes[maxDeque.peekFirst()];
                long cost = maxCharge + (right - left + 1L) * sumRunning;
                if (cost <= budget) {
                    break;
                }
                // remove leftmost robot
                if (maxDeque.peekFirst() == left) {
                    maxDeque.pollFirst();
                }
                sumRunning -= runningCosts[left];
                left++;
            }

            // Update answer
            maxRobots = Math.max(maxRobots, right - left + 1);
        }
        return maxRobots;
    }
}

