public class Solution {
    public int shortestSequence(int[] rolls, int k) {
        int n = rolls.length;
        // next[pos][c] = next index >= pos where rolls[index] == c+1, or -1 if none
        int[][] next = new int[n + 1][k];
        for (int c = 0; c < k; c++) {
            next[n][c] = -1;
        }
        for (int pos = n - 1; pos >= 0; pos--) {
            // copy from next[pos+1]
            for (int c = 0; c < k; c++) {
                next[pos][c] = next[pos + 1][c];
            }
            int val = rolls[pos] - 1; // zero-based
            if (val >= 0 && val < k) {
                next[pos][val] = pos;
            }
        }

        int[] dp = new int[n + 1];
        dp[n] = 1; // empty suffix: any single character is missing

        for (int pos = n - 1; pos >= 0; pos--) {
            int best = Integer.MAX_VALUE;
            for (int c = 0; c < k; c++) {
                int nxt = next[pos][c];
                if (nxt == -1) {
                    best = 1;
                    break; // cannot get better than 1
                } else {
                    int candidate = 1 + dp[nxt + 1];
                    if (candidate < best) {
