import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;

public class Solution {
    public int shortestSequence(int[] rolls, int k) {
        int n = rolls.length;
        // next[pos+1][value] gives earliest index >= pos+1 with rolls[idx]==value
        int[][] next = new int[n + 1][k + 1];
        for (int v = 1; v <= k; v++) {
            next[n][v] = -1;
        }
        for (int i = n - 1; i >= 0; i--) {
            System.arraycopy(next[i + 1], 1, next[i], 1, k);
            next[i][rolls[i]] = i;
        }

        Deque<int[]> queue = new ArrayDeque<>();
        // state: {depth, pos} where pos is index of last matched element, -1 initially
        queue.add(new int[]{0, -1});

        while (!queue.isEmpty()) {
            int[] state = queue.poll();
            int depth = state[0];
            int pos = state[1];
            int idx = pos + 1; // next index to search from
            for (int val = 1; val <= k; val++) {
                int nxt = next[idx][val];
                if (nxt == -1) {
                    return depth + 1;
                } else {
                    queue.add(new int[]{depth + 1, nxt});
                }
            }
        }
        // theoretically unreachable
        return -1;
    }
}

