            if (left - 1 >= 0) {
                sum = (sum - prefix[left - 1] + MOD) % MOD;
            }
            share[i] = (int) sum;
            dp[i] = share[i];
            prefix[i] = (int) ((prefix[i - 1] + dp[i]) % MOD);
        }

        int ans = prefix[n];
        int subIndex = n - forget;
        if (subIndex >= 0) {
            ans = (ans - prefix[subIndex] + MOD) % MOD;
        }
        return ans;
    }
}

