public class Solution {
    private static final int MOD = 1_000_000_007;

    public int peopleAwareOfSecret(int n, int delay, int forget) {
        if (n <= 0) return 0;
        int[] dp = new int[n + 1];        // people who discover secret on day i
        int[] forgetArr = new int[n + 1]; // people who forget on day i
        long totalSharers = 0;            // people currently sharing on day i
        long active = 0;                  // people who know the secret on day i

        dp[1] = 1;
        active = 1; // only the first person knows on day 1

        for (int i = 2; i <= n; i++) {
            // remove people who forget today from the sharer pool
            if (forgetArr[i] != 0) {
                totalSharers = (totalSharers - forgetArr[i] + MOD) % MOD;
            }

            // new people start sharing today
            int newSharers = 0;
            if (i - delay >= 1) {
                newSharers = dp[i - delay];
            }
            totalSharers = (totalSharers + newSharers) % MOD;

            // people who discover secret today
            dp[i] = (int) totalSharers;

            // schedule forgetting for these new discoverers
            int forgetDay = i + forget;
            if (forgetDay <= n) {
                forgetArr[forgetDay] = (forgetArr[forgetDay] + dp[i]) % MOD;
            }

            // update active people count
            active = (active + dp[i]) % MOD;
            if (i - forget >= 1) {
                active = (active - dp[i - forget] + MOD) % MOD;
            }
        }

        return (int) active;
    }
