public class Solution {
    public long minimumReplacement(int[] nums) {
        int n = nums.length;
        long ops = 0;
        long last = nums[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            long cur = nums[i];
            if (cur <= last) {
                last = cur;
            } else {
                long k = (cur + last - 1) / last; // minimal number of parts
                ops += k - 1;
                last = (cur + k - 1) / k; // largest part after splitting
            }
        }
        return ops;
    }
}

