public class Solution {
    public int maximumsSplicedArray(int[] nums1, int[] nums2) {
        int n = nums1.length;
        long sum1 = 0, sum2 = 0;
        for (int i = 0; i < n; i++) {
            sum1 += nums1[i];
            sum2 += nums2[i];
        }

        // Compute maximum subarray sum of diff = nums2[i] - nums1[i]
        long maxDiff = Long.MIN_VALUE;
        long current = 0;
        for (int i = 0; i < n; i++) {
            long val = (long) nums2[i] - nums1[i];
            current = Math.max(val, current + val);
            maxDiff = Math.max(maxDiff, current);
        }

        // Compute maximum subarray sum of -diff = nums1[i] - nums2[i]
        long maxNegDiff = Long.MIN_VALUE;
        current = 0;
        for (int i = 0; i < n; i++) {
            long val = (long) nums1[i] - nums2[i];
            current = Math.max(val, current + val);
            maxNegDiff = Math.max(maxNegDiff, current);
        }

        long maxSum1AfterSwap = sum1 + maxDiff;
        long maxSum2AfterSwap = sum2 + maxNegDiff;

        long result = Math.max(Math.max(sum1, sum2), Math.max(maxSum1AfterSwap, maxSum2AfterSwap));
        return (int) result;
    }
}

