public class Solution {
    public int maximumsSplicedArray(int[] nums1, int[] nums2) {
        int n = nums1.length;
        long sum1 = 0L, sum2 = 0L, totalDiff = 0L;
        // Compute differences and sums
        for (int i = 0; i < n; i++) {
            sum1 += nums1[i];
            sum2 += nums2[i];
            totalDiff += (long) nums2[i] - nums1[i];
        }

        // Kadane for maximum subarray sum on diff array
        long currentMax = 0L;
        long maxSub = Long.MIN_VALUE;
        // Kadane for minimum subarray sum on diff array
        long currentMin = 0L;
        long minSub = Long.MAX_VALUE;

        for (int i = 0; i < n; i++) {
            long diff = (long) nums2[i] - nums1[i];

            // Max subarray
            currentMax = Math.max(diff, currentMax + diff);
            maxSub = Math.max(maxSub, currentMax);

            // Min subarray
            currentMin = Math.min(diff, currentMin + diff);
            minSub = Math.min(minSub, currentMin);
        }

        long Fmax = 2L * maxSub - totalDiff;
        long Fmin = 2L * minSub - totalDiff;
        long F0   = -totalDiff; // no swap

        long maxAbsF = Math.max(Math.abs(Fmax), Math.max(Math.abs(Fmin), Math.abs(F0)));

        long totalSum = sum1 + sum2;
        long answer = (totalSum + maxAbsF) / 2L;
        return (int) answer;
    }
}

