            c[i] = c[n - 1 - i];
            c[n - 1 - i] = tmp;
        }

        int[] childSum = new int[k];
        int[] best = {Integer.MAX_VALUE};

        dfs(0, c, childSum, best);
        return best[0];
    }

    private void dfs(int idx, int[] c, int[] childSum, int[] best) {
        if (idx == c.length) {
            int max = 0;
            for (int s : childSum) {
                if (s > max) max = s;
            }
            if (max < best[0]) best[0] = max;
            return;
        }

        int val = c[idx];
        for (int i = 0; i < childSum.length; i++) {
            // skip duplicate states: if this child has same sum as previous child, skip
            if (i > 0 && childSum[i] == childSum[i - 1]) continue;

            childSum[i] += val;
            // pruning: if current max already >= best, skip
            int currentMax = 0;
            for (int s : childSum) {
                if (s > currentMax) currentMax = s;
            }
            if (currentMax < best[0]) {
                dfs(idx + 1, c, childSum, best);
            }
            childSum[i] -= val;
        }
    }
}

