        best = Integer.MAX_VALUE;
        dfs(0, cookies, loads);
        return best;
    }

    private void dfs(int index, int[] cookies, int[] loads) {
        if (index == cookies.length) {
            int maxLoad = 0;
            for (int load : loads) {
                if (load > maxLoad) {
                    maxLoad = load;
                }
            }
            if (maxLoad < best) {
                best = maxLoad;
            }
            return;
        }

        int current = cookies[index];
        for (int i = 0; i < loads.length; i++) {
            if (i > 0 && loads[i] == loads[i - 1]) continue; // skip duplicate loads
            if (loads[i] + current >= best) continue; // prune

            loads[i] += current;
            dfs(index + 1, cookies, loads);
            loads[i] -= current;
        }
    }

    private void reverse(int[] arr) {
        int i = 0, j = arr.length - 1;
        while (i < j) {
            int tmp = arr[i];
            arr[i] = arr[j];
            arr[j] = tmp;
            i++;
            j--;
        }
    }
