import java.util.ArrayDeque;
import java.util.Deque;

public class Solution {
    public int validSubarraySize(int[] nums, int threshold) {
        int n = nums.length;
        int low = 1, high = n, ans = -1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (exists(nums, threshold, mid)) {
                ans = mid;
                low = mid + 1; // try to find a larger k
            } else {
                high = mid - 1;
            }
        }
        return ans;
    }

    private boolean exists(int[] nums, int threshold, int k) {
        Deque<Integer> dq = new ArrayDeque<>();
        int n = nums.length;
        for (int i = 0; i < n; i++) {
            while (!dq.isEmpty() && nums[dq.peekLast()] >= nums[i]) {
                dq.pollLast();
            }
            dq.offerLast(i);
            if (dq.peekFirst() <= i - k) {
                dq.pollFirst();
            }
            if (i >= k - 1) {
                int minVal = nums[dq.peekFirst()];
                long product = (long) k * (long) minVal;
                if ((long) threshold < product) {
                    return true;
                }
            }
        }
        return false;
    }
}

