public class Solution {
    public int validSubarraySize(int[] nums, int threshold) {
        int n = nums.length;
        int[] left = new int[n];
        int[] right = new int[n];
        Deque<Integer> stack = new ArrayDeque<>();

        // Previous smaller element
        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty() && nums[stack.peek()] >= nums[i]) {
                stack.pop();
            }
            left[i] = stack.isEmpty() ? -1 : stack.peek();
            stack.push(i);
        }

        stack.clear();

        // Next smaller element
        for (int i = n - 1; i >= 0; i--) {
            while (!stack.isEmpty() && nums[stack.peek()] >= nums[i]) {
                stack.pop();
            }
            right[i] = stack.isEmpty() ? n : stack.peek();
            stack.push(i);
        }

        int best = -1;

        for (int i = 0; i < n; i++) {
            int val = nums[i];
            if (val == 0) continue; // cannot satisfy threshold > 0
            int len = right[i] - left[i] - 1;
            // Need val * len > threshold
            if ((long) val * len > (long) threshold) {
                if (len > best) {
                    best = len;
                }
            }
        }

        return best;
    }
}

