            while (!dq.isEmpty() && nums[dq.peekLast()] >= nums[r]) {
                dq.pollLast();
            }
            dq.offerLast(r);

            // Remove indices out of current window
            int l = r - k + 1;
            while (!dq.isEmpty() && dq.peekFirst() < l) {
                dq.pollFirst();
            }

            if (r >= k - 1) {
                long prod = (long) k * (long) nums[dq.peekFirst()];
                if (prod > (long) threshold) {
                    return true;
                }
            }
        }
        return false;
