public class Solution {
    public int secondsToRemoveOccurrences(String s) {
        int zeroCount = 0;        // number of zeros seen so far
        int prevTime = 0;         // time needed for the previous '1'
        int answer = 0;           // maximum time over all '1's

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '0') {
                zeroCount++;
            } else { // c == '1'
                int currentTime;
                if (zeroCount == 0) {
                    currentTime = 0;
                } else {
                    currentTime = Math.max(prevTime + 1, zeroCount);
                }
                prevTime = currentTime;
                if (currentTime > answer) {
                    answer = currentTime;
                }
            }
        }
        return answer;
    }
}

