    public int countIncreasingPaths(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        long[][] dp = new long[m][n];

        // Create list of cells with their coordinates and values
        int total = m * n;
        int[][] cells = new int[total][3]; // {value, i, j}
        int idx = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                cells[idx][0] = grid[i][j];
                cells[idx][1] = i;
                cells[idx][2] = j;
                idx++;
            }
        }

        // Sort cells in descending order of value
        Arrays.sort(cells, (a, b) -> Integer.compare(b[0], a[0]));

        int[] dirX = {1, -1, 0, 0};
        int[] dirY = {0, 0, 1, -1};

        for (int[] cell : cells) {
            int val = cell[0];
            int i = cell[1];
            int j = cell[2];
            long count = 1; // path consisting of the cell itself
            for (int d = 0; d < 4; d++) {
                int ni = i + dirX[d];
                int nj = j + dirY[d];
                if (ni >= 0 && ni < m && nj >= 0 && nj < n && grid[ni][nj] > val) {
                    count += dp[ni][nj];
                    if (count >= MOD) count -= MOD;
                }
            }
            dp[i][j] = count % MOD;
        }

        long result = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                result += dp[i][j];
                if (result >= MOD) result -= MOD;
            }
        }
