public class Solution {
    public int countSpecialNumbers(int n) {
        String s = Integer.toString(n);
        int len = s.length();
        long[][][] dp = new long[len + 1][1 << 10][2];
        dp[0][0][1] = 1;
        for (int pos = 0; pos < len; pos++) {
            for (int mask = 0; mask < (1 << 10); mask++) {
                for (int tight = 0; tight <= 1; tight++) {
                    long cur = dp[pos][mask][tight];
                    if (cur == 0) continue;
                    int limit = tight == 1 ? s.charAt(pos) - '0' : 9;
                    for (int d = 0; d <= limit; d++) {
                        if (pos == 0 && d == 0) continue;
                        if ((mask & (1 << d)) != 0) continue;
                        int newMask = mask | (1 << d);
                        int newTight = (tight == 1 && d == limit) ? 1 : 0;
                        dp[pos + 1][newMask][newTight] += cur;
                    }
                }
            }
        }
        long countLen = 0;
        for (int mask = 0; mask < (1 << 10); mask++) {
            countLen += dp[len][mask][0];
            countLen += dp[len][mask][1];
        }
        long total = countLen;
        for (int L = 1; L < len; L++) {
            total += 9 * permute(9, L - 1);
        }
        return (int) total;
    }

    private long permute(int n, int k) {
        long res = 1;
        for (int i = 0; i < k; i++) {
            res *= (n - i);
        }
        return res;
    }
}

