import java.util.*;

public class Solution {
    public int countSpecialNumbers(int n) {
        char[] digits = Integer.toString(n).toCharArray();
        int len = digits.length;
        int count = 0;

        // Count numbers with fewer digits than n
        for (int l = 1; l < len; l++) {
            count += 9 * perm(9, l - 1);
        }

        // Count numbers with the same length as n
        boolean[] used = new boolean[10];
        int usedCount = 0;
        for (int i = 0; i < len; i++) {
            int d = digits[i] - '0';
            int start = (i == 0) ? 1 : 0;
            for (int k = start; k < d; k++) {
                if (used[k]) continue;
                int remaining = len - i - 1;
                int available = 9 - usedCount; // digits not used yet
                count += perm(available, remaining);
            }
            if (used[d]) break;
            used[d] = true;
            usedCount++;
        }

        // Add n itself if all digits are distinct
        boolean allUnique = true;
        for (int i = 0; i < len; i++) {
            for (int j = i + 1; j < len; j++) {
                if (digits[i] == digits[j]) {
                    allUnique = false;
                    break;
                }
            }
            if (!allUnique) break;
        }
        if (allUnique) count++;

        return count;
    }

    private int perm(int n, int k) {
        int res = 1;
        for (int i = 0; i < k; i++) {
            res *= (n - i);
        }
        return res;
    }
}

