public class Solution {
    public int countSpecialNumbers(int n) {
        long target = n;
        int[] count = new int[1];
        boolean[] used = new boolean[10];
        for (int d = 1; d <= 9; d++) {
            if (d > target) break;
            used[d] = true;
            dfs(d, used, count, target);
            used[d] = false;
        }
        return count[0];
    }

    private void dfs(long current, boolean[] used, int[] count, long target) {
        if (current > target) return;
        count[0]++;
        if (current > target / 10) return;
        for (int d = 0; d <= 9; d++) {
            if (!used[d]) {
                used[d] = true;
                dfs(current * 10 + d, used, count, target);
                used[d] = false;
            }
        }
    }
}

