import java.util.*;

public class Solution {
    public int countSpecialNumbers(int n) {
        String s = Integer.toString(n);
        int len = s.length();
        long[][][] memo = new long[len + 1][1 << 10][2];
        for (int i = 0; i <= len; i++) {
            for (int j = 0; j < (1 << 10); j++) {
                Arrays.fill(memo[i][j], -1L);
            }
        }
        return (int) dfs(0, 0, 1, s, memo);
    }

    private long dfs(int pos, int mask, int tight, String s, long[][][] memo) {
        if (pos == s.length()) return 1;
        if (memo[pos][mask][tight] != -1) return memo[pos][mask][tight];
        long res = 0;
        int limit = tight == 1 ? s.charAt(pos) - '0' : 9;
        for (int d = 0; d <= limit; d++) {
            if (pos == 0 && d == 0) continue; // leading zero not allowed
            if ((mask & (1 << d)) != 0) continue;
            int newMask = mask | (1 << d);
            int newTight = (tight == 1 && d == limit) ? 1 : 0;
            res += dfs(pos + 1, newMask, newTight, s, memo);
        }
        memo[pos][mask][tight] = res;
        return res;
    }
}

