public class Solution {
    private static final int MOD = 1_000_000_007;

    public int distinctNames(String[] ideas) {
        // Map from suffix to total count of words having that suffix
        Map<String, Integer> suffixCount = new HashMap<>();
        // Map from suffix to a map of first letters to counts
        Map<String, Map<Character, Integer>> suffixFirstCount = new HashMap<>();

        for (String word : ideas) {
            // For each word, generate all suffixes starting from index 1
            for (int i = 1; i < word.length(); i++) {
                String suffix = word.substring(i);
                suffixCount.merge(suffix, 1, Integer::sum);

                Map<Character, Integer> firstMap = suffixFirstCount.computeIfAbsent(suffix, k -> new HashMap<>());
                char first = word.charAt(0);
                firstMap.merge(first, 1, Integer::sum);
            }
        }

        long result = 0;
        for (String word : ideas) {
            for (int i = 1; i < word.length(); i++) {
                String suffix = word.substring(i);
                int total = suffixCount.getOrDefault(suffix, 0);
                int sameFirst = suffixFirstCount.get(suffix).getOrDefault(word.charAt(0), 0);
                result += total - sameFirst;
                result %= MOD;
            }
        }
        return (int) result;
    }
}

