public class Solution {
    public long countValidNames(String[] ideas) {
        if (ideas == null) throw new IllegalArgumentException("Input array cannot be null");
        int n = ideas.length;
        Set<String> set = new HashSet<>(n * 2);
        for (String s : ideas) {
            if (s != null) set.add(s);
        }

        // Map first letter -> sorted list of suffixes
        Map<Character, List<String>> prefixMap = new HashMap<>(26);
        for (String word : ideas) {
            char c = word.charAt(0);
            String suffix = word.substring(1);
            prefixMap.computeIfAbsent(c, k -> new java.util.ArrayList<>()).add(suffix);
        }
        for (List<String> list : prefixMap.values()) {
            list.sort(null); // natural ordering
        }

        long[] partnerCount = new long[n];
        int idx = 0;
        for (Map.Entry<Character, List<String>> e : prefixMap.entrySet()) {
            List<String> suffixes = e.getValue();
            int m = suffixes.size();
            for (int i = 0; i < m; i++) {
                String s = suffixes.get(i);
                boolean exists = set.contains(s);
                if (!exists) partnerCount[idx]++; // partner for this word
                idx++;
            }
        }

        // Count valid pairs
        Set<String> result = new HashSet<>();
        idx = 0;
        for (Map.Entry<Character, List<String>> e : prefixMap.entrySet()) {
            List<String> suffixes = e.getValue();
            int m = suffixes.size();
            for (int i = 0; i < m; i++) {
                String s1 = suffixes.get(i);
                char c1 = s1.charAt(0);
                // find partner words with same first letter
                for (int j = i + 1; j < m; j++) {
                    String s2 = suffixes.get(j);
                    // swapped names
                    String new1 = c1 + s1;
                    String new2 = s2.charAt(0) + s2;
                    // both must not be in set
                    if (!set.contains(new1) && !set.contains(new2)) {
                        result.add(new1 + " " + new2);
                    }
                }
            }
        }
        return result.size();
    }
}

