public class Solution {

    public long numCompanyNames(String[] ideas) {
        // Map from first letter to set of suffixes (words without the first letter)
        Map<Character, Set<String>> prefixMap = new HashMap<>();
        // Set of all words for quick lookup
        Set<String> allWords = new HashSet<>();

        for (String word : ideas) {
            allWords.add(word);
            char first = word.charAt(0);
            String suffix = word.substring(1);
            prefixMap.computeIfAbsent(first, k -> new HashSet<>()).add(suffix);
        }

        long result = 0;
        // Get all distinct first letters
        Character[] letters = prefixMap.keySet().toArray(new Character[0]);

        // Iterate over all unordered pairs of distinct first letters
        for (int i = 0; i < letters.length; i++) {
            char a = letters[i];
            Set<String> setA = prefixMap.get(a);
            for (int j = i + 1; j < letters.length; j++) {
                char b = letters[j];
                Set<String> setB = prefixMap.get(b);

                int badA = 0;
                for (String suffix : setA) {
                    if (allWords.contains(b + suffix)) {
                        badA++;
                    }
                }

                int badB = 0;
                for (String suffix : setB) {
                    if (allWords.contains(a + suffix)) {
                        badB++;
                    }
                }

                long goodA = setA.size() - badA;
                long goodB = setB.size() - badB;
                result += goodA * goodB;
            }
        }

        return result;
    }
}

