public class Solution {
    public int distinctNames(String[] ideas) {
        Set<String> all = new HashSet<>(Arrays.asList(ideas));
        List<String>[] groups = new ArrayList[26];
        for (int i = 0; i < 26; i++) groups[i] = new ArrayList<>();

        for (String s : ideas) {
