            String suffix = s.substring(1);
            groups[first - 'a'].add(suffix);
        }

        long result = 0;
        for (int i = 0; i < 26; i++) {
            if (groups[i].isEmpty()) continue;
            for (int j = i + 1; j < 26; j++) {
                if (groups[j].isEmpty()) continue;
                int cntI = 0;
                int cntJ = 0;
                char charJ = (char) ('a' + j);
                char charI = (char) ('a' + i);

                for (String suf : groups[i]) {
                    if (!all.contains(charJ + suf)) cntI++;
                }
                for (String suf : groups[j]) {
                    if (!all.contains(charI + suf)) cntJ++;
                }
                result += (long) cntI * cntJ * 2;
            }
        }
        return (int) result;
    }
