import java.util.Arrays;
import java.util.HashSet;
import java.util.PriorityQueue;

public class Solution {
    private static class Node {
        long sum;
        int idx;
        Node(long sum, int idx) {
            this.sum = sum;
            this.idx = idx;
        }
    }

    private static class Pair {
        long sum;
        int idx;
        Pair(long sum, int idx) {
            this.sum = sum;
            this.idx = idx;
        }
        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Pair)) return false;
            Pair p = (Pair) o;
            return sum == p.sum && idx == p.idx;
        }
        @Override
        public int hashCode() {
            int result = Long.hashCode(sum);
            result = 31 * result + Integer.hashCode(idx);
            return result;
        }
    }

    public long kSum(int[] nums, int k) {
        int n = nums.length;
        Arrays.sort(nums);
        // sort in descending order
        for (int i = 0; i < n / 2; i++) {
            int tmp = nums[i];
            nums[i] = nums[n - 1 - i];
            nums[n - 1 - i] = tmp;
        }

        PriorityQueue<Node> pq = new PriorityQueue<>((a, b) -> Long.compare(b.sum, a.sum));
        HashSet<Pair> visited = new HashSet<>();

        pq.offer(new Node(0L, 0));
        visited.add(new Pair(0L, 0));

        long result = 0;
        for (int cnt = 0; cnt < k; cnt++) {
            Node cur = pq.poll();
            result = cur.sum;
            int idx = cur.idx;
            if (idx < n) {
                long sum1 = cur.sum + nums[idx];
                Pair p1 = new Pair(sum1, idx + 1);
                if (visited.add(p1)) {
                    pq.offer(new Node(sum1, idx + 1));
                }
                long sum2 = cur.sum;
                Pair p2 = new Pair(sum2, idx + 1);
                if (visited.add(p2)) {
                    pq.offer(new Node(sum2, idx + 1));
                }
            }
        }
        return result;
    }
}

