import java.util.Arrays;

public class Solution {
    public long kSum(int[] nums, int k) {
        int n = nums.length;
        int n1 = n / 2;
        int n2 = n - n1;

        long[] a = new long[n1];
        long[] b = new long[n2];
        for (int i = 0; i < n1; i++) a[i] = nums[i];
        for (int i = 0; i < n2; i++) b[i] = nums[n1 + i];

        long[] sums1 = subsetSums(a);
        long[] sums2 = subsetSums(b);
        Arrays.sort(sums1);
        Arrays.sort(sums2);

        long low = sums1[0] + sums2[0];
        long high = sums1[sums1.length - 1] + sums2[sums2.length - 1];

        long ans = low;
        while (low <= high) {
            long mid = low + ((high - low) >> 1);
            if (countGe(mid, sums1, sums2) >= k) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return ans;
    }

    private long[] subsetSums(long[] arr) {
        int m = arr.length;
        int size = 1 << m;
        long[] sums = new long[size];
        for (int mask = 0; mask < size; mask++) {
            long sum = 0;
            for (int i = 0; i < m; i++) {
                if ((mask & (1 << i)) != 0) sum += arr[i];
            }
            sums[mask] = sum;
        }
        return sums;
    }

    private long countGe(long target, long[] s1, long[] s2) {
        long count = 0;
        for (long val : s1) {
            long need = target - val;
            int idx = lowerBound(s2, need);
            count += s2.length - idx;
        }
        return count;
    }

    private int lowerBound(long[] arr, long key) {
        int l = 0, r = arr.length;
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (arr[mid] < key) l = mid + 1;
            else r = mid;
        }
        return l;
    }
}

