import java.io.*;
import java.util.*;

public class Solution {

    // ---------- helper for reversing a long array ----------
    private static void reverse(long[] arr) {
        int n = arr.length;
        for (int i = 0; i < n / 2; i++) {
            long tmp = arr[i];
            arr[i] = arr[n - 1 - i];
            arr[n - 1 - i] = tmp;
        }
    }

    // ---------- encoding of a pair (i , j) into a single long ----------
    private static long encode(int i, int j) {
        return ((long) i << 32) | (j & 0xffffffffL);
    }

    // ---------- node used in the priority queue ----------
    private static class Node {
        long sum;
        int i;   // row index in leftSum
        int j;   // column index in rightSum
        Node(long sum, int i, int j) {
            this.sum = sum;
            this.i = i;
            this.j = j;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        // ----- read input -----
        int n = Integer.parseInt(br.readLine().trim());
        long[] a = new long[n];
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) a[i] = Long.parseLong(st.nextToken());
        long k = Long.parseLong(br.readLine().trim());   // may be up to 2^n

        int n1 = n / 2;
        int n2 = n - n1;

        // ----- all subset sums of left half -----
        int sizeL = 1 << n1;
        long[] leftSum = new long[sizeL];
        for (int mask = 1; mask < sizeL; mask++) {
            int bit = Integer.numberOfTrailingZeros(mask);
            int prev = mask ^ (1 << bit);
            leftSum[mask] = leftSum[prev] + a[bit];
        }

        // ----- all subset sums of right half -----
        int sizeR = 1 << n2;
        long[] rightSum = new long[sizeR];
        for (int mask = 1; mask < sizeR; mask++) {
            int bit = Integer.numberOfTrailingZeros(mask);
            int prev = mask ^ (1 << bit);
            rightSum[mask] = rightSum[prev] + a[n1 + bit];
        }

        // ----- sort decreasingly ----------
        Arrays.sort(leftSum);
        Arrays.sort(rightSum);
        reverse(leftSum);
        reverse(rightSum);

        // ----- max-heap to generate k-th largest pair sum ----------
        PriorityQueue<Node> pq = new PriorityQueue<>(
                (o1, o2) -> Long.compare(o2.sum, o1.sum)   // decreasing order
        );
        Set<Long> visited = new HashSet<>((int) (k * 2 + 10));

        long initialSum = leftSum[0] + rightSum[0];
        pq.add(new Node(initialSum, 0, 0));
        visited.add(encode(0, 0));

        long answer = 0;
        long cnt = 0;
        while (cnt < k && !pq.isEmpty()) {
            Node cur = pq.poll();
            answer = cur.sum;
            cnt++;

            // move down in the matrix (i + 1)
            if (cur.i + 1 < sizeL) {
                long key = encode(cur.i + 1, cur.j);
                if (!visited.contains(key)) {
                    long newSum = leftSum[cur.i + 1] + rightSum[cur.j];
                    pq.add(new Node(newSum, cur.i + 1, cur.j));
                    visited.add(key);
                }
            }

            // move right in the matrix (j + 1)
            if (cur.j + 1 < sizeR) {
                long key = encode(cur.i, cur.j + 1);
                if (!visited.contains(key)) {
                    long newSum = leftSum[cur.i] + rightSum[cur.j + 1];
                    pq.add(new Node(newSum, cur.i, cur.j + 1));
                    visited.add(key);
                }
            }
        }

        System.out.println(answer);
    }
}

