public class Solution {
    public long kSum(int[] nums, int k) {
        int n = nums.length;
        int leftLen = n / 2;
        int rightLen = n - leftLen;

        long[] leftSums = new long[1 << leftLen];
        long[] rightSums = new long[1 << rightLen];

        // compute subset sums for left half
        for (int mask = 0; mask < (1 << leftLen); mask++) {
            long sum = 0;
            for (int i = 0; i < leftLen; i++) {
                if ((mask & (1 << i)) != 0) {
                    sum += nums[i];
                }
            }
            leftSums[mask] = sum;
        }

        // compute subset sums for right half
        for (int mask = 0; mask < (1 << rightLen); mask++) {
            long sum = 0;
            for (int i = 0; i < rightLen; i++) {
                if ((mask & (1 << i)) != 0) {
                    sum += nums[leftLen + i];
                }
            }
            rightSums[mask] = sum;
        }

        // sort descending
        Arrays.sort(leftSums);
        Arrays.sort(rightSums);
        long[] leftDesc = new long[leftSums.length];
        long[] rightDesc = new long[rightSums.length];
        int idx = leftSums.length - 1;
        for (int i = 0; i < leftSums.length; i++) {
            leftDesc[i] = leftSums[idx--];
        }
        idx = rightSums.length - 1;
        for (int i = 0; i < rightSums.length; i++) {
            rightDesc[i] = rightSums[idx--];
        }

        // priority queue for top k sums of two sorted arrays
        PriorityQueue<Node> pq = new PriorityQueue<>((a, b) -> Long.compare(b.sum, a.sum));
        HashSet<Long> visited = new HashSet<>();

        pq.offer(new Node(0, 0, leftDesc[0] + rightDesc[0]));
        visited.add(encode(0, 0));

        long answer = 0;
        for (int cnt = 0; cnt < k; cnt++) {
            Node cur = pq.poll();
            answer = cur.sum;

            int i = cur.i;
            int j = cur.j;
            if (i + 1 < leftDesc.length) {
                long key = encode(i + 1, j);
                if (visited.add(key)) {
                    pq.offer(new Node(i + 1, j, leftDesc[i + 1] + rightDesc[j]));
                }
            }
            if (j + 1 < rightDesc.length) {
                long key = encode(i, j + 1);
                if (visited.add(key)) {
                    pq.offer(new Node(i, j + 1, leftDesc[i] + rightDesc[j + 1]));
                }
            }
        }
        return answer;
    }

    private long encode(int i, int j) {
        return (((long) i) << 32) | (j & 0xffffffffL);
    }

    private static class Node {
        int i, j;
        long sum;

        Node(int i, int j, long sum) {
            this.i = i;
            this.j = j;
            this.sum = sum;
        }
    }
}

