public class Solution {
    public long kSum(int[] nums, int k) {
        // Separate positive and negative numbers
        List<Integer> pos = new ArrayList<>();
        List<Integer> neg = new ArrayList<>();
        for (int v : nums) {
            if (v >= 0) pos.add(v);
            else neg.add(v);
        }

        // Generate all subset sums of positives
        List<Long> posSums = new ArrayList<>();
        posSums.add(0L);
        for (int v : pos) {
            int sz = posSums.size();
            for (int i = 0; i < sz; i++) {
                posSums.add(posSums.get(i) + v);
            }
        }

        // Generate all subset sums of negatives
        List<Long> negSums = new ArrayList<>();
        negSums.add(0L);
        for (int v : neg) {
            int sz = negSums.size();
            for (int i = 0; i < sz; i++) {
                negSums.add(negSums.get(i) + v);
            }
        }

        // Convert lists to arrays and sort descending
        long[] posArr = new long[posSums.size()];
        for (int i = 0; i < posArr.length; i++) posArr[i] = posSums.get(i);
        long[] negArr = new long[negSums.size()];
        for (int i = 0; i < negArr.length; i++) negArr[i] = negSums.get(i);

        Arrays.sort(posArr);
        reverse(posArr);
        Arrays.sort(negArr);
        reverse(negArr);

        // Max-heap to get top k sums of posArr[i] + negArr[j]
        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> -a[2]));
        int nPos = posArr.length;
        int nNeg = negArr.length;
        Set<Long> visited = new HashSet<>();

        pq.offer(new long[]{0, 0, posArr[0] + negArr[0]});
        visited.add(0L * nNeg + 0L);

        long result = 0;
        for (int cnt = 0; cnt < k; cnt++) {
            long[] cur = pq.poll();
            int i = (int) cur[0];
            int j = (int) cur[1];
            result = cur[2];

            if (i + 1 < nPos) {
                long key = (long)(i + 1) * nNeg + j;
                if (visited.add(key)) {
                    pq.offer(new long[]{i + 1, j, posArr[i + 1] + negArr[j]});
                }
            }
            if (j + 1 < nNeg) {
                long key = (long)i * nNeg + (j + 1);
                if (visited.add(key)) {
                    pq.offer(new long[]{i, j + 1, posArr[i] + negArr[j + 1]});
                }
            }
        }
        return result;
    }

    private void reverse(long[] arr) {
        int l = 0, r = arr.length - 1;
        while (l < r) {
            long tmp = arr[l];
            arr[l] = arr[r];
            arr[r] = tmp;
            l++;
            r--;
        }
    }
}

