public class Solution {
    public long countSubarrays(int[] nums, long k) {
        int n = nums.length;
        long count = 0;
        int r = -1;
        long sum = 0;
        int len = 0;
        for (int l = 0; l < n; l++) {
            while (r + 1 < n) {
                long newSum = sum + nums[r + 1];
                int newLen = len + 1;
                // Check if newSum * newLen < k without overflow
                if (newSum <= (k - 1) / newLen) {
                    r++;
                    sum = newSum;
                    len = newLen;
                } else {
                    break;
                }
            }
            count += len;
            if (len > 0) {
                sum -= nums[l];
                len--;
            }
        }
        return count;
    }
}

