public class Solution {
    public long countSubarrays(int[] nums, long k) {
        if (k <= 0) return 0L;
        long count = 0L;
        int n = nums.length;
        int left = 0;
        long sum = 0L;

        for (int right = 0; right < n; right++) {
            sum += nums[right];
            int len = right - left + 1;

            // Shrink window from the left while product >= k
            while (left <= right && len > 0 && sum > (k - 1) / len) {
                sum -= nums[left];
                left++;
                len = right - left + 1;
            }

            count += len;
        }
        return count;
    }
}

