public class Solution {
    public long countSubarrays(int[] nums, long k) {
        int n = nums.length;
        long count = 0;
        int left = 0, right = 0;
        long sum = 0;
        while (left < n) {
            // Expand right as far as possible while maintaining score < k
            while (right < n) {
                long newSum = sum + nums[right];
                long newLen = right - left + 1;
                if (newSum * newLen < k) {
                    sum = newSum;
                    right++;
                } else {
                    break;
                }
            }
            // All subarrays starting at left and ending before right satisfy the condition
            count += (right - left);
            if (left == right) {
                // Cannot expand further, move both pointers forward
                left++;
                right++;
            } else {
                // Remove the leftmost element and move left pointer
                sum -= nums[left];
                left++;
            }
        }
        return count;
    }
}

