public class Solution {
    public int minOperations(int[] nums, int[] numsDivide) {
        int gcd = numsDivide[0];
        for (int i = 1; i < numsDivide.length; i++) {
            gcd = gcd(gcd, numsDivide[i]);
        }

        // Collect all divisors of gcd
        List<Integer> divisors = new ArrayList<>();
        for (int i = 1; i * i <= gcd; i++) {
            if (gcd % i == 0) {
                divisors.add(i);
                if (i != gcd / i) {
                    divisors.add(gcd / i);
                }
            }
        }

        // For fast lookup of presence in nums
        Set<Integer> numSet = new HashSet<>();
        for (int v : nums) {
            numSet.add(v);
        }

        int minDel = Integer.MAX_VALUE;

        for (int d : divisors) {
            if (!numSet.contains(d)) continue; // must have at least one d
            int del = 0;
            for (int v : nums) {
                if (v < d) del++;
            }
            if (del < minDel) minDel = del;
        }

        return minDel == Integer.MAX_VALUE ? -1 : minDel;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

