import java.util.ArrayList;
import java.util.List;

public class Solution {
    private int n;
    private int[] nums;
    private List<Integer>[] graph;
    private int[] parent;
    private int[] subXor;
    private int[] tin;
    private int[] tout;
    private int timer;

    private static class EdgeInfo {
        int child;
        int xor;
        EdgeInfo(int child, int xor) {
            this.child = child;
            this.xor = xor;
        }
    }

    public int minScore(int[] nums, int[][] edges) {
        this.n = nums.length;
        this.nums = nums;
        graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }

        parent = new int[n];
        subXor = new int[n];
        tin = new int[n];
        tout = new int[n];
        timer = 0;

        dfs(0, -1);

        int totalXor = subXor[0];

        // Build edge info list
        EdgeInfo[] edgeInfos = new EdgeInfo[edges.length];
        for (int i = 0; i < edges.length; i++) {
            int u = edges[i][0];
            int v = edges[i][1];
            int child;
            if (parent[u] == v) child = u;
            else child = v;
            edgeInfos[i] = new EdgeInfo(child, subXor[child]);
        }

        int minScore = Integer.MAX_VALUE;
        int m = edges.length;
        for (int i = 0; i < m; i++) {
            EdgeInfo e1 = edgeInfos[i];
            int sub1 = e1.xor;
            int comp1 = totalXor ^ sub1;
            for (int j = i + 1; j < m; j++) {
                EdgeInfo e2 = edgeInfos[j];
                int sub2 = e2.xor;
                int xorA, xorB, xorC;
                if (isAncestor(e1.child, e2.child)) {
                    // e2 inside component A
                    xorA = sub2;
                    xorB = sub1 ^ sub2;
                    xorC = comp1;
                } else {
                    // e2 inside component B
                    xorA = sub2;
                    xorB = comp1 ^ sub2;
                    xorC = sub1;
                }
                int max = Math.max(xorA, Math.max(xorB, xorC));
                int min = Math.min(xorA, Math.min(xorB, xorC));
                int score = max - min;
                if (score < minScore) minScore = score;
            }
        }
        return minScore;
    }

    private void dfs(int node, int par) {
        parent[node] = par;
        tin[node] = ++timer;
        int xor = nums[node];
        for (int nei : graph[node]) {
            if (nei == par) continue;
            dfs(nei, node);
            xor ^= subXor[nei];
        }
        subXor[node] = xor;
        tout[node] = ++timer;
    }

    private boolean isAncestor(int anc, int desc) {
        return tin[anc] <= tin[desc] && tout[desc] <= tout[anc];
    }
}

