import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Deque;
import java.util.List;

public class Solution {

    private static class Edge {
        int parent;
        int child;

        Edge(int parent, int child) {
            this.parent = parent;
            this.child = child;
        }
    }

    public int minScore(int[] nums, int[][] edgesInput) {
        int n = nums.length;
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
        }
        for (int[] e : edgesInput) {
            int a = e[0];
            int b = e[1];
            adj[a].add(b);
            adj[b].add(a);
        }

        int[] parent = new int[n];
        Arrays.fill(parent, -1);
        int[] subXor = new int[n];
        int[] tin = new int[n];
        int[] tout = new int[n];
        int timer = 0;

        List<Edge> edgeList = new ArrayList<>();

        // Iterative DFS to compute parent, subXor, tin, tout
        int[] state = new int[n]; // 0 = pre, 1 = post
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(0);
        parent[0] = -1;

        while (!stack.isEmpty()) {
            int u = stack.pop();
            if (state[u] == 0) {
                tin[u] = ++timer;
                state[u] = 1;
                stack.push(u);
                for (int v : adj[u]) {
                    if (v == parent[u]) continue;
                    parent[v] = u;
                    edgeList.add(new Edge(u, v));
                    stack.push(v);
                }
            } else {
                int xor = nums[u];
                for (int v : adj[u]) {
                    if (v == parent[u]) continue;
                    xor ^= subXor[v];
                }
                subXor[u] = xor;
                tout[u] = ++timer;
            }
        }

        int totalXor = subXor[0];
        int minScore = Integer.MAX_VALUE;
        int m = edgeList.size();

        for (int i = 0; i < m; i++) {
            Edge e1 = edgeList.get(i);
            int c1 = e1.child;
            int A = subXor[c1];
            for (int j = i + 1; j < m; j++) {
                Edge e2 = edgeList.get(j);
                int c2 = e2.child;
                int B = subXor[c2];
                int comp1, comp2, comp3;

                if (isAncestor(tin, tout, c1, c2)) {
                    // c1 is ancestor of c2
                    comp1 = B;               // subtree of c2
                    comp2 = A ^ B;           // rest of subtree c1
                    comp3 = totalXor ^ A;    // rest of the whole tree
                } else if (isAncestor(tin, tout, c2, c1)) {
                    // c2 is ancestor of c1
                    comp1 = A;               // subtree of c1
                    comp2 = B ^ A;           // rest of subtree c2
                    comp3 = totalXor ^ B;    // rest of the whole tree
                } else {
                    // disjoint
                    comp1 = A;
                    comp2 = B;
                    comp3 = totalXor ^ A ^ B;
                }

                int maxVal = Math.max(Math.max(comp1, comp2), comp3);
                int minVal = Math.min(Math.min(comp1, comp2), comp3);
                int score = maxVal - minVal;
                if (score < minScore) {
                    minScore = score;
                }
            }
        }

        return minScore;
    }

    private boolean isAncestor(int[] tin, int[] tout, int u, int v) {
        return tin[u] <= tin[v] && tout[v] <= tout[u];
    }
}

