public class Solution {

    public int minimumScore(int n, int[] nums, int[][] edges) {
        List<Integer>[] g = new ArrayList[n];
        for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
        for (int[] e : edges) {
            g[e[0]].add(e[1]);
            g[e[1]].add(e[0]);
        }

        int[] parent = new int[n];
        int[] depth = new int[n];
        int[] subtreeXor = new int[n];
        int[] entry = new int[n];
        int[] exit = new int[n];
        int[] timer = new int[1];

        dfs1(0, -1, g, parent, depth, subtreeXor, entry, exit, timer);

        int totalXor = subtreeXor[0];

        // store child side for each edge
        int m = edges.length;
        int[] child = new int[m];
        for (int i = 0; i < m; i++) {
            int u = edges[i][0];
            int v = edges[i][1];
            child[i] = (parent[u] == v) ? u : v; // child is deeper node
        }

        int best = Integer.MAX_VALUE;
        for (int i = 0; i < m; i++) {
            int c1 = child[i];
            int xor1 = subtreeXor[c1];
            int rest1 = totalXor ^ xor1;
            for (int j = i + 1; j < m; j++) {
                int c2 = child[j];
                int xor2 = subtreeXor[c2];
                if (isDescendant(c1, c2, entry, exit)) {
                    // c2 lies in subtree of c1
                    int a = xor1 ^ xor2; // rest of component A after removing c2
                    int b = rest1;       // component B unchanged
                    int[] arr = {xor2, a, b};
                    int min = Math.min(Math.min(arr[0], arr[1]), arr[2]);
                    int max = Math.max(Math.max(arr[0], arr[1]), arr[2]);
                    best = Math.min(best, max - min);
                } else if (isDescendant(c2, c1, entry, exit)) {
                    // c1 lies in subtree of c2
                    int a = xor2 ^ xor1; // rest of component B after removing c1
                    int b = rest1;       // component A unchanged
                    int[] arr = {xor1, a, b};
                    int min = Math.min(Math.min(arr[0], arr[1]), arr[2]);
                    int max = Math.max(Math.max(arr[0], arr[1]), arr[2]);
                    best = Math.min(best, max - min);
                } else {
                    // edges in different branches
                    int compA = xor1;
                    int compC = xor2;
                    int compRest = rest1 ^ xor2; // B split into C and rest
                    int[] arr = {compA, compC, compRest};
                    int min = Math.min(Math.min(arr[0], arr[1]), arr[2]);
                    int max = Math.max(Math.max(arr[0], arr[1]), arr[2]);
                    best = Math.min(best, max - min);
                }
            }
        }
        return best;
    }

    private void dfs1(int u, int p, List<Integer>[] g, int[] parent, int[] depth,
                      int[] subtreeXor, int[] entry, int[] exit, int[] timer) {
        parent[u] = p;
        entry[u] = timer[0]++;
        subtreeXor[u] = 0;
        for (int v : g[u]) {
            if (v == p) continue;
            depth[v] = depth[u] + 1;
            dfs1(v, u, g, parent, depth, subtreeXor, entry, exit, timer);
            subtreeXor[u] ^= subtreeXor[v];
        }
        subtreeXor[u] ^= g[u].isEmpty() ? 0 : 0; // placeholder; actual value added after recursion
        // Since nums are not passed here, we need to add nums value to subtreeXor later
        // We'll modify after building adjacency
        exit[u] = timer[0]++;
    }

    private boolean isDescendant(int anc, int desc, int[] entry, int[] exit) {
        return entry[anc] <= entry[desc] && exit[desc] <= exit[anc];
    }
}

