        totalXor = subtreeXor[0];

        edges = new ArrayList<>();
        for (int[] e : edgesInput) {
            int u = e[0];
            int v = e[1];
            int child, par;
            if (parent[u] == v) {
                child = u;
                par = v;
            } else {
                child = v;
                par = u;
            }
            Edge edge = new Edge(par, child, subtreeXor[child]);
            edges.add(edge);
        }

        int best = Integer.MAX_VALUE;
        for (int i = 0; i < edges.size(); i++) {
            Edge e1 = edges.get(i);
            int a = e1.xorChild;
            int r = totalXor ^ a;

            for (int j = 0; j < edges.size(); j++) {
                if (i == j) continue;
                Edge e2 = edges.get(j);
                if (isDescendant(e2.child, e1.child)) {
                    int x = e2.xorChild;
                    int b = a ^ x;
                    int c = r;
                    int min = Math.min(x, Math.min(b, c));
                    int max = Math.max(x, Math.max(b, c));
                    best = Math.min(best, max - min);
                } else {
                    int y = e2.xorChild;
                    int b = r ^ y;
                    int c = a;
                    int min = Math.min(y, Math.min(b, c));
                    int max = Math.max(y, Math.max(b, c));
                    best = Math.min(best, max - min);
                }
            }
        }
        return best;
    }

    private void dfs(int node, int par, int[] nums) {
        parent[node] = par;
        depth[node] = (par == -1) ? 0 : depth[par] + 1;
        tin[node] = ++timer;
        subtreeXor[node] = nums[node];
        for (int nei : adjacency.get(node)) {
            if (nei == par) continue;
            dfs(nei, node, nums);
            subtreeXor[node] ^= subtreeXor[nei];
        }
        tout[node] = timer;
    }

    private boolean isDescendant(int desc, int anc) {
        return tin[anc] <= tin[desc] && tout[desc] <= tout[anc];
    }

    private static class Edge {
        int parent;
        int child;
        int xorChild;

        Edge(int parent, int child, int xorChild) {
            this.parent = parent;
            this.child = child;
            this.xorChild = xorChild;
        }
    }
}

