public class Solution {
    public int[] maximumSegmentSum(int[] nums, int[] removeQueries) {
        int n = nums.length;
        int[] res = new int[n];
        int[] parent = new int[n];
        int[] sum = new int[n];
        boolean[] active = new boolean[n];
        Arrays.fill(parent, -1);
        for (int i = 0; i < n; i++) {
            sum[i] = nums[i];
        }
        int maxSum = 0;
        for (int i = n - 1; i >= 0; i--) {
            int idx = removeQueries[i];
            active[idx] = true;
            parent[idx] = idx;
            if (idx - 1 >= 0 && active[idx - 1]) {
                union(idx, idx - 1, parent, sum);
            }
            if (idx + 1 < n && active[idx + 1]) {
                union(idx, idx + 1, parent, sum);
            }
            maxSum = Math.max(maxSum, sum[find(idx, parent)]);
            res[i] = maxSum;
        }
        return res;
    }

    private int find(int x, int[] parent) {
        if (parent[x] != x) {
            parent[x] = find(parent[x], parent);
        }
        return parent[x];
    }

    private void union(int a, int b, int[] parent, int[] sum) {
        int ra = find(a, parent);
        int rb = find(b, parent);
        if (ra == rb) return;
        parent[rb] = ra;
        sum[ra] += sum[rb];
    }
}

