public class Solution {
    public int[] maximumSegmentSum(int[] nums, int[] removeQueries) {
        int n = nums.length;
        UF uf = new UF(n);
        boolean[] present = new boolean[n];
        int[] ans = new int[n];
        long maxSum = 0;
        for (int i = n - 1; i >= 0; i--) {
            int idx = removeQueries[i];
            present[idx] = true;
            uf.add(idx, nums[idx]);
            if (idx > 0 && present[idx - 1]) uf.union(idx, idx - 1);
            if (idx + 1 < n && present[idx + 1]) uf.union(idx, idx + 1);
            maxSum = Math.max(maxSum, uf.sum(uf.find(idx)));
            ans[i] = (int) maxSum;
        }
        return ans;
    }

    // Union-Find with component sum tracking
    private static class UF {
        int[] parent;
        int[] size;
        long[] compSum;
        UF(int n) {
            parent = new int[n];
            size = new int[n];
            compSum = new long[n];
            Arrays.fill(parent, -1); // -1 indicates inactive
        }

        // activate a node with its value
        void add(int x, int val) {
            parent[x] = x;
            size[x] = 1;
            compSum[x] = val;
        }

        int find(int x) {
            if (parent[x] != x) parent[x] = find(parent[x]);
            return parent[x];
        }

        void union(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return;
            if (size[ra] < size[rb]) { // swap
                int tmp = ra; ra = rb; rb = tmp;
            }
            parent[rb] = ra;
            size[ra] += size[rb];
            compSum[ra] += compSum[rb];
        }

        long sum(int x) {
            return compSum[find(x)];
        }
    }
}

