public class Solution {

    // Union-Find structure with path compression and union by size
    private static class UF {
        int[] parent;
        int[] size;
        long[] sum;

        UF(int n) {
            parent = new int[n];
            size = new int[n];
            sum = new long[n];
            Arrays.fill(parent, -1); // -1 indicates inactive
        }

        // activate element at index idx with value val
        void activate(int idx, long val) {
            parent[idx] = idx;
            size[idx] = 1;
            sum[idx] = val;
        }

        // find representative of idx
        int find(int idx) {
            if (parent[idx] != idx) {
                parent[idx] = find(parent[idx]);
            }
            return parent[idx];
        }

        // union two elements if they are active
        long union(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return sum[ra];
            // union by size
            if (size[ra] < size[rb]) {
                int tmp = ra;
                ra = rb;
                rb = tmp;
            }
            parent[rb] = ra;
            size[ra] += size[rb];
            sum[ra] += sum[rb];
            return sum[ra];
        }
    }

    public int[] maximumSegmentSum(int[] nums, int[] removeQueries) {
        int n = nums.length;
        int[] answer = new int[n];
        UF uf = new UF(n);
        boolean[] active = new boolean[n];

        long currentMax = 0;
        // Process removals in reverse (i.e., additions)
        for (int i = n - 1; i >= 0; i--) {
            int idx = removeQueries[i];
            active[idx] = true;
            uf.activate(idx, nums[idx]);

            // Check left neighbor
            if (idx - 1 >= 0 && active[idx - 1]) {
                currentMax = Math.max(currentMax, uf.union(idx, idx - 1));
            }
            // Check right neighbor
            if (idx + 1 < n && active[idx + 1]) {
                currentMax = Math.max(currentMax, uf.union(idx, idx + 1));
            }
            // After adding, currentMax is the maximum sum
            answer[i] = (int) currentMax;
        }
        return answer;
    }
}

