    private static class UF {
        private final int[] parent;
        private final long[] sum;
        private final int[] size;

        public UF(int n, int[] nums) {
            parent = new int[n];
            sum = new long[n];
            size = new int[n];
            Arrays.fill(parent, -1); // not active yet
            for (int i = 0; i < n; i++) {
                sum[i] = nums[i];
            }
