        public void makeSet(int x) {
            parent[x] = x;
            size[x] = 1;
            // sum already initialized with nums[x]
        }

        public int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        public void union(int x, int y) {
