            int ry = find(y);
            if (rx == ry) return;
            // Union by size
            if (size[rx] < size[ry]) {
                int temp = rx;
                rx = ry;
                ry = temp;
            }
            parent[ry] = rx;
            size[rx] += size[ry];
            sum[rx] += sum[ry];
        }

        public long getSum(int x) {
            int root = find(x);
            return sum[root];
        }
    }
