import java.util.Arrays;

public class Solution {
    public int[] maximumSegmentSum(int[] nums, int[] removeQueries) {
        int n = nums.length;
        int[] ans = new int[n];
        DSU dsu = new DSU(n);
        boolean[] active = new boolean[n];
        long[] sum = new long[n];
        long max = 0;

        for (int i = n - 1; i >= 0; --i) {
            int idx = removeQueries[i];
            active[idx] = true;
            sum[idx] = nums[idx];
            dsu.makeSet(idx);

            if (idx - 1 >= 0 && active[idx - 1]) {
                int root1 = dsu.find(idx);
                int root2 = dsu.find(idx - 1);
                if (root1 != root2) {
                    dsu.union(root1, root2);
                    sum[dsu.find(idx)] = sum[root1] + sum[root2];
                }
            }

            if (idx + 1 < n && active[idx + 1]) {
                int root1 = dsu.find(idx);
                int root2 = dsu.find(idx + 1);
                if (root1 != root2) {
                    dsu.union(root1, root2);
                    sum[dsu.find(idx)] = sum[root1] + sum[root2];
                }
            }

            max = Math.max(max, sum[dsu.find(idx)]);
            ans[i] = (int) max;
        }

        return ans;
    }

    private static class DSU {
        private final int[] parent;
        private final int[] rank;

        DSU(int n) {
            parent = new int[n];
            rank = new int[n];
            Arrays.fill(parent, -1);
        }

        void makeSet(int x) {
            parent[x] = x;
            rank[x] = 0;
        }

        int find(int x) {
            if (parent[x] == x) return x;
            return parent[x] = find(parent[x]);
        }

        void union(int x, int y) {
            int xr = find(x);
            int yr = find(y);
            if (xr == yr) return;
            if (rank[xr] < rank[yr]) {
                parent[xr] = yr;
            } else if (rank[xr] > rank[yr]) {
                parent[yr] = xr;
            } else {
                parent[yr] = xr;
                rank[xr]++;
            }
        }
    }
}

