public class Solution {
    public boolean validPartition(int[] nums) {
        int n = nums.length;
        if (n < 2) return false;
        boolean[] dp = new boolean[n + 1];
        dp[0] = true;
        for (int i = 1; i <= n; i++) {
            // Check for pair
            if (i >= 2 && dp[i - 2] && nums[i - 2] == nums[i - 1]) {
                dp[i] = true;
            }
            // Check for triplet of equal numbers
            if (!dp[i] && i >= 3 && dp[i - 3]
                    && nums[i - 3] == nums[i - 2] && nums[i - 2] == nums[i - 1]) {
                dp[i] = true;
            }
            // Check for triplet of consecutive increasing numbers
            if (!dp[i] && i >= 3 && dp[i - 3]
                    && nums[i - 3] + 1 == nums[i - 2]
                    && nums[i - 2] + 1 == nums[i - 1]) {
                dp[i] = true;
            }
        }
        return dp[n];
    }
}

