public class Solution {
    private static final int MOD = 1_000_000_007;

    public int idealArrays(int n, int maxValue) {
        int[][] dp = new int[n + 1][maxValue + 1];

        // Base case: arrays of length 1
        for (int v = 1; v <= maxValue; v++) {
            dp[1][v] = 1;
        }

        // Build DP for lengths 2..n
        for (int len = 2; len <= n; len++) {
            for (int v = 1; v <= maxValue; v++) {
                int val = dp[len - 1][v];
                if (val == 0) continue;
                for (int m = v; m <= maxValue; m += v) {
                    dp[len][m] += val;
                    if (dp[len][m] >= MOD) dp[len][m] -= MOD;
                }
            }
        }

        // Sum all arrays of length n
        int ans = 0;
        for (int v = 1; v <= maxValue; v++) {
            ans += dp[n][v];
            if (ans >= MOD) ans -= MOD;
        }
        return ans;
    }
}

