import java.util.*;

public class Solution {
    private static final long MOD = 1_000_000_007L;

    public int idealArrays(int n, int maxValue) {
        Map<Integer, Integer> primeExp = factorize(maxValue);
        if (primeExp.isEmpty()) {
            return 1;
        }

        int maxExp = Collections.max(primeExp.values());
        int limit = n + maxExp; // maximum value needed for factorial

        long[] fact = new long[limit + 1];
        long[] invFact = new long[limit + 1];
        fact[0] = 1;
        for (int i = 1; i <= limit; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[limit] = modPow(fact[limit], MOD - 2);
        for (int i = limit - 1; i >= 0; i--) {
            invFact[i] = invFact[i + 1] * (i + 1) % MOD;
        }

        long ans = 1;
        int k = n - 1;
        for (int e : primeExp.values()) {
            long ways = comb(e + k, k, fact, invFact);
            ans = ans * ways % MOD;
        }
        return (int) ans;
    }

    private Map<Integer, Integer> factorize(int x) {
        Map<Integer, Integer> map = new HashMap<>();
        for (int p = 2; p * p <= x; p++) {
            if (x % p == 0) {
                int cnt = 0;
                while (x % p == 0) {
                    x /= p;
                    cnt++;
                }
                map.put(p, cnt);
            }
        }
        if (x > 1) {
            map.put(x, 1);
        }
        return map;
    }

    private long comb(int n, int k, long[] fact, long[] invFact) {
        if (k < 0 || k > n) return 0;
        return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
    }

    private long modPow(long a, long e) {
        long res = 1;
        a %= MOD;
        while (e > 0) {
            if ((e & 1) == 1) {
                res = res * a % MOD;
            }
            a = a * a % MOD;
            e >>= 1;
        }
        return res;
    }
}

