import java.util.HashMap;
import java.util.Map;

public class Solution {
    public String bestHand(int[] ranks, char[] suits) {
        // Check for Flush
        Map<Character, Integer> suitCount = new HashMap<>();
        for (char s : suits) {
            suitCount.put(s, suitCount.getOrDefault(s, 0) + 1);
        }
        if (suitCount.size() == 1) {
            return "Flush";
        }

        // Count ranks
        Map<Integer, Integer> rankCount = new HashMap<>();
        int maxCount = 0;
        for (int r : ranks) {
            int cnt = rankCount.getOrDefault(r, 0) + 1;
            rankCount.put(r, cnt);
            if (cnt > maxCount) {
                maxCount = cnt;
            }
        }

        if (maxCount == 3) {
            return "Three of a Kind";
        } else if (maxCount == 2) {
            return "Pair";
        } else {
            return "High Card";
        }
    }
}

