public class Solution {
    public int longestCycle(int[] edges) {
        int n = edges.length;
        int[] visitTime = new int[n];
        int[] depth = new int[n];
        boolean[] visited = new boolean[n];
        int traversalId = 1;
        int maxLen = -1;

        for (int i = 0; i < n; i++) {
            if (visited[i]) continue;
            int cur = i;
            int step = 0;
            while (cur != -1 && !visited[cur]) {
                visited[cur] = true;
                visitTime[cur] = traversalId;
                depth[cur] = step;
                step++;
                int next = edges[cur];
                if (next == -1) break;
                if (visitTime[next] == traversalId) {
                    int cycleLen = depth[cur] - depth[next] + 1;
                    if (cycleLen > maxLen) maxLen = cycleLen;
                    break;
                }
                cur = next;
            }
            traversalId++;
        }
        return maxLen;
    }
}

