public class Solution {
    public int longestCycle(int[] edges) {
        int n = edges.length;
        int[] state = new int[n]; // 0=unvisited,1=visiting,2=visited
        int[] depth = new int[n];
        int ans = -1;

        for (int i = 0; i < n; i++) {
            if (state[i] != 0) continue;
            int cur = i;
            int step = 0;
            List<Integer> path = new ArrayList<>();

            while (cur != -1) {
                if (state[cur] == 0) {
                    state[cur] = 1;
                    depth[cur] = step;
                    step++;
                    path.add(cur);
                    cur = edges[cur];
                } else {
                    if (state[cur] == 1) {
                        int cycleLen = step - depth[cur];
                        if (cycleLen > ans) ans = cycleLen;
                    }
                    break;
                }
            }

            for (int node : path) {
                state[node] = 2;
            }
        }
        return ans;
    }
}

