public class Solution {
    private int[] state;          // 0 = unvisited, 1 = visiting, 2 = visited
    private int[] depth;          // depth of each node when first visited
    private int maxCycle;         // maximum cycle length found
    private int[] edges;

    public int longestCycle(int[] edges) {
        this.edges = edges;
        int n = edges.length;
        state = new int[n];
        depth = new int[n];
        maxCycle = -1;

        for (int i = 0; i < n; i++) {
            if (state[i] == 0) {
                dfs(i, 0);
            }
        }
        return maxCycle;
    }

    private void dfs(int node, int currDepth) {
        state[node] = 1;          // mark as visiting
        depth[node] = currDepth;  // record depth

        int next = edges[node];
        if (next != -1) {
            if (state[next] == 0) {
                dfs(next, currDepth + 1);
            } else if (state[next] == 1) { // found a cycle
                int cycleLen = currDepth + 1 - depth[next];
                if (cycleLen > maxCycle) {
                    maxCycle = cycleLen;
                }
            }
            // else state[next] == 2: already processed, ignore
        }

        state[node] = 2;          // mark as visited
    }
}

