import java.util.Arrays;

public class Solution {
    public int longestCycle(int[] edges) {
        int n = edges.length;
        int[] visited = new int[n];          // 0 = unvisited, 1 = visited
        int[] idx = new int[n];             // step index of node in current path, -1 if not in current path
        Arrays.fill(idx, -1);
        int maxLen = -1;

        for (int i = 0; i < n; i++) {
            if (visited[i] != 0) continue;

            int cur = i;
            int step = 0;
            // traverse until we hit a visited node or no outgoing edge
            while (cur != -1 && visited[cur] == 0) {
                visited[cur] = 1;
                idx[cur] = step++;
                cur = edges[cur];
            }
            // if we reached a node that is part of the current path, we found a cycle
            if (cur != -1 && idx[cur] != -1) {
                int len = step - idx[cur];
                if (len > maxLen) maxLen = len;
            }
            // reset idx values for nodes in the current traversal
            cur = i;
            while (cur != -1 && idx[cur] != -1) {
                int next = edges[cur];
                idx[cur] = -1;
                cur = next;
            }
        }
        return maxLen == -1 ? -1 : maxLen;
    }
}

