public class Solution {
    public long minSumSquareDiff(int[] nums1, int[] nums2, int k1, int k2) {
        int n = nums1.length;
        int[] diff = new int[n];
        int maxDiff = 0;
        for (int i = 0; i < n; i++) {
            diff[i] = Math.abs(nums1[i] - nums2[i]);
            if (diff[i] > maxDiff) maxDiff = diff[i];
        }

        int[] freq = new int[maxDiff + 1];
        for (int d : diff) freq[d]++;

        long k = (long) k1 + k2;
        int cur = maxDiff;
        while (k > 0 && cur > 0) {
            while (cur > 0 && freq[cur] == 0) cur--;
            if (cur == 0) break;
            int take = (int) Math.min(freq[cur], k);
            freq[cur] -= take;
            freq[cur - 1] += take;
            k -= take;
            if (freq[cur] == 0) cur--;
        }

        long sum = 0;
        for (int i = 0; i <= maxDiff; i++) {
            if (freq[i] != 0) {
                sum += (long) freq[i] * i * i;
            }
        }
        return sum;
    }
}

