public class Solution {
    public long minSumSquareDiff(int[] nums1, int[] nums2, int k1, int k2) {
        int n = nums1.length;
        int[] absDiff = new int[n];
        int maxDiff = 0;
        for (int i = 0; i < n; i++) {
            int d = Math.abs(nums1[i] - nums2[i]);
            absDiff[i] = d;
            if (d > maxDiff) maxDiff = d;
        }

        int k = k1 + k2;
        if (k == 0) {
            long sum = 0;
            for (int d : absDiff) sum += (long) d * d;
            return sum;
        }

        // frequency array of differences
        int[] freq = new int[maxDiff + 1];
        for (int d : absDiff) freq[d]++;

        // Reduce differences starting from the largest
        for (int d = maxDiff; d > 0 && k > 0; d--) {
            int cnt = freq[d];
            if (cnt == 0) continue;

            int needed = cnt; // to reduce all to d-1
            if (k >= needed) {
                // reduce all
                freq[d] = 0;
                freq[d - 1] += cnt;
                k -= needed;
            } else {
                // reduce only k elements
                freq[d] -= k;
                freq[d - 1] += k;
                k = 0;
                break;
            }
        }

        // compute resulting sum of squares
        long result = 0;
        for (int d = 0; d <= maxDiff; d++) {
            if (freq[d] != 0) {
                result += (long) d * d * freq[d];
            }
        }
        return result;
    }
}

