public class Solution {
    public boolean checkXMatrix(int[][] grid) {
        int n = grid.length;
        if (n == 0) return false;
        for (int i = 0; i < n; i++) {
            // check main diagonal
            if (grid[i][i] == 0) return false;
            // check anti-diagonal
            if (grid[i][n - 1 - i] == 0) return false;
        }
        for (int i = 0; i < n; i++) {
