public class Solution {
    public int maximumRows(int[][] matrix, int numSelect) {
        int m = matrix.length;
        if (m == 0) return 0;
        int n = matrix[0].length;
        numSelect = Math.min(numSelect, n);

        long[] rowMasks = new long[m];
        for (int i = 0; i < m; i++) {
            long mask = 0L;
            for (int j = 0; j < n; j++) {
                if (matrix[i][j] == 1) {
                    mask |= (1L << j);
                }
            }
            rowMasks[i] = mask;
        }

        if (numSelect == 0) {
            int cnt = 0;
            for (long mask : rowMasks) {
                if (mask == 0L) cnt++;
            }
            return cnt;
        }

        best = 0;
        dfs(0, 0, 0L, rowMasks, n, numSelect);
        return best;
    }

    private int best = 0;

    private void dfs(int start, int chosen, long selectedMask, long[] rowMasks, int n, int numSelect) {
        if (chosen == numSelect) {
            int count = 0;
            for (long mask : rowMasks) {
                if ((mask & ~selectedMask) == 0L) count++;
            }
            if (count > best) best = count;
            return;
        }
        for (int i = start; i < n; i++) {
            dfs(i + 1, chosen + 1, selectedMask | (1L << i), rowMasks, n, numSelect);
        }
    }
}

