import java.util.Arrays;

public class Solution {
    public int maximumRows(int[][] matrix, int numSelect) {
        int m = matrix.length;
        int n = matrix[0].length;
        long[] rowMask = new long[m];
        for (int i = 0; i < m; i++) {
            long mask = 0L;
            for (int j = 0; j < n; j++) {
                if (matrix[i][j] == 1) {
                    mask |= 1L << j;
                }
            }
            rowMask[i] = mask;
        }

        // Sort rows by number of 1's to help pruning
        Integer[] idx = new Integer[m];
        for (int i = 0; i < m; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> Long.bitCount(rowMask[a]) - Long.bitCount(rowMask[b]));

        long[] sortedMask = new long[m];
        for (int i = 0; i < m; i++) sortedMask[i] = rowMask[idx[i]];

        int[] best = {0};
        dfs(0, 0L, 0, sortedMask, m, numSelect, best);
        return best[0];
    }

    private void dfs(int pos, long unionMask, int cnt, long[] masks, int m, int k, int[] best) {
        if (cnt > best[0]) best[0] = cnt;
        if (pos == m) return;
        if (cnt + (m - pos) <= best[0]) return; // prune

        // Option: skip current row
        dfs(pos + 1, unionMask, cnt, masks, m, k, best);

        // Option: include current row if it fits
        long newMask = unionMask | masks[pos];
        if (Long.bitCount(newMask) <= k) {
            dfs(pos + 1, newMask, cnt + 1, masks, m, k, best);
        }
    }
}

