import java.util.*;

public class Solution {
    public int maximumRows(int[][] matrix, int numSelect) {
        int m = matrix.length;
        int n = matrix[0].length;

        long[] masks = new long[m];
        for (int i = 0; i < m; i++) {
            long mask = 0;
            for (int j = 0; j < n; j++) {
                if (matrix[i][j] == 1) {
                    mask |= 1L << j;
                }
            }
            masks[i] = mask;
        }

        // Keep only rows that can possibly be covered
        List<Integer> idx = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            if (Long.bitCount(masks[i]) <= numSelect) {
                idx.add(i);
            }
        }

        long[] availMasks = new long[idx.size()];
        for (int i = 0; i < idx.size(); i++) {
            availMasks[i] = masks[idx.get(i)];
        }

        if (numSelect > n) {
            return 0;
        }

        int best = 0;
        if (numSelect == 0) {
            for (long mask : availMasks) {
                if (mask == 0) {
                    best++;
                }
            }
            return best;
        }

        long comb = (1L << numSelect) - 1;
        long limit = 1L << n;
        while (comb < limit) {
            int count = 0;
            for (long mask : availMasks) {
                if ((mask & comb) == mask) {
                    count++;
                }
            }
            if (count > best) {
                best = count;
            }
            long x = comb & -comb;
            long y = comb + x;
            comb = (((comb & ~y) / x) >> 1) | y;
        }

        return best;
    }
}

