                    mask |= (1 << j);
                }
            }
            rowMasks[i] = mask;
        }

        int maxCovered = 0;
        int limit = 1 << n;
        for (int subset = 0; subset < limit; subset++) {
            if (Integer.bitCount(subset) != numSelect) continue;
            int covered = 0;
            for (int mask : rowMasks) {
                if ((mask & ~subset) == 0) { // mask is subset of subset
                    covered++;
                }
            }
            if (covered > maxCovered) maxCovered = covered;
        }
        return maxCovered;
    }
}

