public class Solution {
    public long sellingWood(int m, int n, int[][] prices) {
        long[][] dp = new long[m + 1][n + 1];
        long[][] price = new long[m + 1][n + 1];

        // Store the best price for each exact shape
        for (int[] p : prices) {
            int h = p[0];
            int w = p[1];
            long val = p[2];
            if (h <= m && w <= n) {
                price[h][w] = Math.max(price[h][w], val);
            }
        }

        for (int h = 1; h <= m; h++) {
            for (int w = 1; w <= n; w++) {
                long best = price[h][w]; // selling whole piece if available
                // Try horizontal cuts
                for (int cut = 1; cut < h; cut++) {
                    best = Math.max(best, dp[cut][w] + dp[h - cut][w]);
                }
                // Try vertical cuts
                for (int cut = 1; cut < w; cut++) {
                    best = Math.max(best, dp[h][cut] + dp[h][w - cut]);
                }
                dp[h][w] = best;
            }
        }
        return dp[m][n];
    }
}

