import java.util.*;

public class Solution {
    // Using topological sort to solve this problem
    public int[][] buildMatrix(int k, int[][] rowC, int[][] colC) {
        int[] rowOrder = topoSort(k, rowC);
        if (rowOrder == null) return new int[0][0];
        int[] colOrder = topoSort(k, colC);
        if (colOrder == null) return new int[0][0];

        int[][] matrix = new int[k][k];
        int[] rowPos = new int[k + 1];
        int[] colPos = new int[k + 1];
        for (int i = 0; i < k; i++) {
            rowPos[rowOrder[i]] = i;
            colPos[colOrder[i]] = i;
        }
        for (int num = 1; num <= k; num++) {
            matrix[rowPos[num]][colPos[num]] = num;
        }
        return matrix;
    }

    private int[] topoSort(int k, int[][] conditions) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i <= k; i++) graph.add(new ArrayList<>());
        int[] indegree = new int[k + 1];
        for (int[] edge : conditions) {
            int from = edge[0];
            int to = edge[1];
            graph.get(from).add(to);
            indegree[to]++;
        }
        Queue<Integer> q = new LinkedList<>();
        for (int i = 1; i <= k; i++) {
            if (indegree[i] == 0) q.offer(i);
        }
        int[] order = new int[k];
        int idx = 0;
        while (!q.isEmpty()) {
            int cur = q.poll();
            order[idx++] = cur;
            for (int nxt : graph.get(cur)) {
                if (--indegree[nxt] == 0) q.offer(nxt);
            }
        }
        if (idx != k) return null; // cycle detected
        return order;
    }
}

