public class Solution {
    // Helper method to perform topological sort on constraints
    private List<Integer> topoSort(int k, int[][] constraints) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i <= k; i++) graph.add(new ArrayList<>());
        int[] indegree = new int[k + 1];

        for (int[] edge : constraints) {
            int u = edge[0];
            int v = edge[1];
            graph.get(u).add(v);
            indegree[v]++;
        }

        Queue<Integer> q = new LinkedList<>();
        for (int i = 1; i <= k; i++) {
            if (indegree[i] == 0) q.offer(i);
        }

        List<Integer> order = new ArrayList<>();
        while (!q.isEmpty()) {
            int u = q.poll();
            order.add(u);
            for (int v : graph.get(u)) {
                if (--indegree[v] == 0) q.offer(v);
            }
        }

        if (order.size() != k) return Collections.emptyList(); // cycle detected
