public class Solution {
    public int minimumNumbers(int nums, int k) {
        // Handle empty set case
        if (nums == 0) {
            return 0;
        }

        // Special case when k == 0
        if (k == 0) {
            if (nums % 10 != 0) {
                return -1;
            }
            // Each number is at least 10
            return (nums + 9) / 10;
        }

        // For k > 0
        for (int m = 1; m <= 10; m++) {
            if (nums >= m * k && (nums - m * k) % 10 == 0) {
                return m;
            }
        }
        return -1;
    }
}

