public class Solution {
    public int minimumNumbers(int nums, int k) {
        // If the required sum is 0, the empty set is valid.
        if (nums == 0) {
            return 0;
        }

        // Special handling for units digit 0
        if (k == 0) {
            // Any positive integer ending with 0 must be at least 10.
            // The sum can be exactly one such number if nums is divisible by 10.
            return nums % 10 == 0 ? 1 : -1;
        }

        // For k > 0, the minimal number of terms is at most 10.
        // Iterate from 1 to 10 to find the smallest feasible count.
        for (int t = 1; t <= 10; t++) {
            int remaining = nums - t * k;
            if (remaining < 0) {
                break;
            }
            if (remaining % 10 == 0) {
                return t;
            }
        }

        // No feasible set exists
        return -1;
    }
}

