public class Solution {
    public int[] smallestTrimmedNumbers(String[] nums, int[][] queries) {
        int n = nums.length;
        int q = queries.length;
        int maxTrim = 0;
        for (int[] query : queries) {
            maxTrim = Math.max(maxTrim, query[1]);
        }

        int len = nums[0].length();
        // Precompute sorted indices for each trim length
        int[][] sortedIndices = new int[maxTrim + 1][n];
        for (int trim = 1; trim <= maxTrim; trim++) {
            int[] idx = new int[n];
            for (int i = 0; i < n; i++) {
                idx[i] = i;
            }
            final int t = trim;
            Arrays.sort(idx, new Comparator<Integer>() {
                @Override
                public int compare(Integer a, Integer b) {
                    String sa = nums[a].substring(len - t);
                    String sb = nums[b].substring(len - t);
                    int cmp = sa.compareTo(sb);
                    if (cmp != 0) {
                        return cmp;
                    }
                    return a - b;
                }
            });
            for (int i = 0; i < n; i++) {
                sortedIndices[trim][i] = idx[i];
            }
        }

        int[] answer = new int[q];
        for (int i = 0; i < q; i++) {
            int k = queries[i][0];
            int trim = queries[i][1];
            answer[i] = sortedIndices[trim][k - 1];
        }
        return answer;
    }
}

