public class Solution {
    public int countHousePlacements(int n) {
        final long MOD = 1_000_000_007L;
        long a = 0; // F0
        long b = 1; // F1
        for (int i = 0; i < n + 2; i++) {
            long temp = (a + b) % MOD;
            a = b;
            b = temp;
        }
        long waysOneSide = a % MOD; // F_{n+2}
        long result = (waysOneSide * waysOneSide) % MOD;
        return (int) result;
    }
