public class Solution {
    private static final long MOD = 1_000_000_007L;

    public int countHousePlacements(int n) {
        long f = fib(n + 2, MOD).first;      // number of ways for one side
        long result = (f * f) % MOD;         // both sides are independent
        return (int) result;
    }

    // fast doubling method for Fibonacci numbers
    private static Pair fib(long n, long mod) {
        if (n == 0) return new Pair(0, 1);
        Pair p = fib(n >> 1, mod);
        long a = p.first;   // F(k)
        long b = p.second;  // F(k+1)
        long c = (a * ((2 * b % mod - a + mod) % mod)) % mod; // F(2k)
        long d = (a * a % mod + b * b % mod) % mod;           // F(2k+1)
        if ((n & 1) == 0) {
            return new Pair(c, d);
        } else {
            return new Pair(d, (c + d) % mod);
        }
    }

    private static class Pair {
        long first, second;
        Pair(long first, long second) {
            this.first = first;
            this.second = second;
        }
    }
}

