        boolean[] visited = new boolean[n];
        ArrayDeque<Integer> stack = new ArrayDeque<>();
        stack.push(0);
        visited[0] = true;
        int count = 0;
        while (!stack.isEmpty()) {
            int node = stack.pop();
            count++;
            for (int nb : graph[node]) {
                if (!banned[nb] && !visited[nb]) {
                    visited[nb] = true;
                    stack.push(nb);
                }
            }
        }
        return count;
    }
}

