import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

public class Solution {
    public int latestTimeCatchTheBus(int[] buses, int[] passengers, int capacity) {
        Arrays.sort(buses);
        Arrays.sort(passengers);
        Set<Integer> passengerSet = new HashSet<>();
        for (int p : passengers) passengerSet.add(p);

        int passengerIdx = 0;
        int lastBusIdx = buses.length - 1;
        int lastBusDeparture = buses[lastBusIdx];
        int lastPassengerOnLastBus = -1;

        for (int busIdx = 0; busIdx < buses.length; busIdx++) {
            int t = buses[busIdx];
            int boarded = 0;
            while (passengerIdx < passengers.length && passengers[passengerIdx] <= t && boarded < capacity) {
                boarded++;
                passengerIdx++;
            }
            if (busIdx == lastBusIdx) {
                if (boarded < capacity) {
                    // Bus not full
                    int candidate = t;
                    while (passengerSet.contains(candidate)) {
                        candidate--;
                    }
                    return candidate;
                } else {
                    // Bus full, last passenger boarded at passengers[passengerIdx - 1]
                    lastPassengerOnLastBus = passengers[passengerIdx - 1];
                    int candidate = lastPassengerOnLastBus - 1;
                    while (passengerSet.contains(candidate)) {
                        candidate--;
                    }
                    return candidate;
                }
            }
        }
        // Should never reach here
        return -1;
    }
}

