import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

public class Solution {
    public int latestTimeCatchTheBus(int[] buses, int[] passengers, int capacity) {
        Arrays.sort(buses);
        Arrays.sort(passengers);
        Set<Integer> occupied = new HashSet<>();
        for (int p : passengers) occupied.add(p);

        int passengerIdx = 0;
        int lastBoarded = -1;
        int cntLastBus = 0;

        for (int i = 0; i < buses.length; i++) {
            int busTime = buses[i];
            int cnt = 0;
            while (cnt < capacity && passengerIdx < passengers.length && passengers[passengerIdx] <= busTime) {
                lastBoarded = passengers[passengerIdx];
                passengerIdx++;
                cnt++;
            }
            if (i == buses.length - 1) {
                cntLastBus = cnt;
            }
        }

        int lastBusTime = buses[buses.length - 1];
        if (cntLastBus < capacity) {
            // last bus has a free seat
            for (int t = lastBusTime; t >= 0; t--) {
                if (!occupied.contains(t)) {
                    return t;
                }
            }
            return 0;
        } else {
            // last bus is full, need to find time before the last boarded passenger
            int t = lastBoarded - 1;
            while (t >= 0 && occupied.contains(t)) {
                t--;
            }
            return t;
        }
    }
}

