public class Solution {
    public int longestSubsequence(String s, int k) {
        int n = s.length();
        int zerosCount = 0;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '0') zerosCount++;
        }

        Map<Integer, Integer> dp = new HashMap<>();
        dp.put(0, 0); // value -> max ones taken

        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            Map<Integer, Integer> next = new HashMap<>();
            if (c == '0') {
                for (Map.Entry<Integer, Integer> entry : dp.entrySet()) {
                    int val = entry.getKey();
                    int ones = entry.getValue();
                    long newVal = ((long) val) * 2;
                    if (newVal <= k) {
                        int nv = (int) newVal;
                        next.merge(nv, ones, Math::max);
                    }
                }
            } else { // c == '1'
                for (Map.Entry<Integer, Integer> entry : dp.entrySet()) {
                    int val = entry.getKey();
                    int ones = entry.getValue();
                    // skip
                    next.merge(val, ones, Math::max);
                    // take
                    long newVal = ((long) val) * 2 + 1;
                    if (newVal <= k) {
                        int nv = (int) newVal;
                        next.merge(nv, ones + 1, Math::max);
                    }
                }
            }
            dp = next;
        }

        int maxOnes = 0;
        for (int ones : dp.values()) {
            if (ones > maxOnes) maxOnes = ones;
        }
        return zerosCount + maxOnes;
    }
}

