public class Solution {
    public int longestSubsequence(String s, int k) {
        int n = s.length();
        // Prefix zero count: number of zeros up to index i (exclusive)
        int[] prefZeros = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefZeros[i + 1] = prefZeros[i] + (s.charAt(i) == '0' ? 1 : 0);
        }

        int best = 0;
        // Case: all zeros subsequence
        best = Math.max(best, prefZeros[n]);

        // For each position of '1' as the first chosen bit
        for (int pos = 0; pos < n; pos++) {
            if (s.charAt(pos) != '1') continue;

            int leadingZeros = prefZeros[pos];
            // DP map: value -> max length of subsequence (including the '1' at pos)
            Map<Integer, Integer> dp = new HashMap<>();
            dp.put(1, 1);

            for (int i = pos + 1; i < n; i++) {
                int bit = s.charAt(i) - '0';
                Map<Integer, Integer> next = new HashMap<>(dp);
                for (Map.Entry<Integer, Integer> entry : dp.entrySet()) {
                    int val = entry.getKey();
                    int len = entry.getValue();
                    int newVal = val * 2 + bit;
                    if (newVal <= k) {
                        int newLen = len + 1;
                        Integer cur = next.get(newVal);
                        if (cur == null || newLen > cur) {
                            next.put(newVal, newLen);
                        }
                    }
                }
                dp = next;
            }

            // Find maximum length achievable after pos
            int maxLenAfter = 0;
            for (int len : dp.values()) {
                if (len > maxLenAfter) maxLenAfter = len;
            }
            int totalLen = leadingZeros + maxLenAfter;
            if (totalLen > best) best = totalLen;
        }

        return best;
    }
}

