public class Solution {
    public int longestSubsequence(String s, int k) {
        int n = s.length();
        // Precompute next zero positions
        int[] nextZero = new int[n + 1];
        nextZero[n] = -1;
        for (int i = n - 1; i >= 0; --i) {
            if (s.charAt(i) == '0') {
                nextZero[i] = i;
            } else {
                nextZero[i] = nextZero[i + 1];
            }
        }

        for (int len = n; len >= 0; --len) {
            String subseq = smallestSubsequence(s, len, nextZero, n);
            long val = 0;
            boolean ok = true;
            for (int i = 0; i < len; ++i) {
                val = (val << 1) + (subseq.charAt(i) - '0');
                if (val > k) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
        return 0; // fallback, should not reach here
    }

    private String smallestSubsequence(String s, int L, int[] nextZero, int n) {
        if (L == 0) return "";
        StringBuilder sb = new StringBuilder(L);
        int pos = 0;
        for (int i = 0; i < L; ++i) {
            int remaining = L - i;
            int maxStart = n - remaining;
            int idx0 = nextZero[pos];
            if (idx0 != -1 && idx0 <= maxStart) {
                sb.append('0');
                pos = idx0 + 1;
            } else {
                sb.append('1');
                pos = pos + 1; // first available char is '1'
            }
        }
        return sb.toString();
    }
}

