public class Solution {
    public int longestSubsequence(String s, int k) {
        int n = s.length();
        long INF = Long.MAX_VALUE / 4;
        long[][] dp = new long[n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            for (int l = 0; l <= n; l++) {
                dp[i][l] = INF;
            }
        }
        dp[0][0] = 0;
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            int bit = (c == '1') ? 1 : 0;
            for (int l = 0; l <= i; l++) {
                long cur = dp[i][l];
                if (cur == INF) continue;
                // Skip current character
                if (cur < dp[i + 1][l]) dp[i + 1][l] = cur;
                // Take current character
                long newVal = cur * 2 + bit;
                if (newVal <= k) {
                    if (newVal < dp[i + 1][l + 1]) dp[i + 1][l + 1] = newVal;
                }
            }
        }
        for (int l = n; l >= 0; l--) {
            if (dp[n][l] <= k) return l;
        }
        return 0;
    }
}

