public class Solution {
    public int longestSubsequence(String s, int k) {
        int n = s.length();
        long K = k;
        int best = 0; // empty subsequence is always valid
        for (int len = 1; len <= n; len++) {
            int currPos = 0;
            long val = 0;
            boolean valid = true;
            for (int i = 0; i < len; i++) {
                int remaining = len - i - 1;
                int limit = n - remaining; // last index we can pick to leave enough chars
                int minBit = 2; // larger than possible bit
                int minIndex = -1;
                for (int j = currPos; j <= limit; j++) {
                    int bit = s.charAt(j) - '0';
                    if (bit < minBit) {
                        minBit = bit;
                        minIndex = j;
                        if (bit == 0) break; // cannot get smaller
                    }
                }
                if (minIndex == -1) {
                    valid = false;
                    break;
                }
                val = (val << 1) + minBit;
                if (val > K) {
                    valid = false;
                    break;
                }
                currPos = minIndex + 1;
            }
            if (!valid) {
                break; // longer lengths will only produce larger minimal values
            }
            best = len;
        }
        return best;
    }
}

