public class Solution {
    public int countSubarrays(int[] nums, int k) {
        int n = nums.length;
        int idx = -1;
        for (int i = 0; i < n; i++) {
            if (nums[i] == k) {
                idx = i;
                break;
            }
        }
        if (idx == -1) return 0; // k not found, though problem guarantees it

        // Count balances on the left side (including k)
        Map<Integer, Integer> leftCount = new HashMap<>();
        int balance = 0;
        leftCount.put(0, 1); // empty prefix before k
        for (int i = idx - 1; i >= 0; i--) {
            if (nums[i] > k) balance++;
            else balance--; // nums[i] < k
            leftCount.put(balance, leftCount.getOrDefault(balance, 0) + 1);
        }

        // Iterate on the right side (including k) and accumulate answer
        long result = 0;
        balance = 0;
        for (int i = idx; i < n; i++) {
            if (i > idx) {
                if (nums[i] > k) balance++;
                else balance--;
            }
            // Subarray median k requires leftBalance + rightBalance == 0 or 1
            result += leftCount.getOrDefault(-balance, 0);
            result += leftCount.getOrDefault(1 - balance, 0);
        }

        return (int) result;
    }
}

