        }

        long ans = 0;
        for (int j = pos; j < n; j++) {
            int cur = prefix[j + 1];
            ans += freq.getOrDefault(cur, 0) + freq.getOrDefault(cur - 1, 0);
        }
        return (int) ans;
    }
