public class Solution {
    public int countSubarraysWithMedianK(int[] nums, int k) {
        int n = nums.length;
        int pos = -1;
        for (int i = 0; i < n; i++) {
            if (nums[i] == k) {
                pos = i;
                break;
            }
        }
        if (pos == -1) {
            return 0; // k not found, should not happen with given constraints
        }

        // Prefix sums of transformed array
        int[] pref = new int[n + 1];
        int sum = 0;
        pref[0] = 0;
        for (int i = 0; i < n; i++) {
            if (nums[i] > k) {
                sum += 1;
            } else if (nums[i] < k) {
                sum -= 1;
            } // nums[i] == k contributes 0
            pref[i + 1] = sum;
        }

        int offset = n; // to shift negative indices
        int size = 2 * n + 3; // enough for values from -n-1 to n+1
        int[] freq = new int[size];

        // Frequency of prefix sums for left indices up to and including pos
        for (int l = 0; l <= pos; l++) {
            int idx = pref[l] + offset;
            freq[idx]++;
        }

        long ans = 0;
        for (int r = pos; r < n; r++) {
            int target = pref[r + 1];
            int idx0 = target + offset;
            ans += freq[idx0];

            int idx1 = target - 1 + offset;
            if (idx1 >= 0 && idx1 < size) {
                ans += freq[idx1];
            }
        }

        return (int) ans;
    }
}

