public class Solution {
    public int unequalTriplets(int[] nums) {
        int n = nums.length;
        if (n < 3) return 0;

        Map<Integer, Integer> freq = new HashMap<>();
        for (int num : nums) {
            freq.put(num, freq.getOrDefault(num, 0) + 1);
        }

        long total = (long) n * (n - 1) * (n - 2) / 6;
        long twoEqual = 0;
        long allEqual = 0;

        for (int f : freq.values()) {
            if (f >= 2) {
                twoEqual += (long) f * (f - 1) / 2 * (n - f);
            }
            if (f >= 3) {
                allEqual += (long) f * (f - 1) * (f - 2) / 6;
            }
        }

        long result = total - twoEqual - allEqual;
        return (int) result;
    }
}

