import java.util.*;

public class Solution {
    public long countPairs(int[] nums1, int[] nums2, int diff) {
        int n = nums1.length;
        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = (long) nums1[i] - nums2[i];
        }

        long[] vals = new long[2 * n];
        for (int i = 0; i < n; i++) {
            vals[2 * i] = a[i];
            vals[2 * i + 1] = a[i] + diff;
        }
        Arrays.sort(vals);
        int m = 0;
        for (int i = 0; i < vals.length; i++) {
            if (i == 0 || vals[i] != vals[i - 1]) {
                vals[m++] = vals[i];
            }
        }
        vals = Arrays.copyOf(vals, m);

        BIT bit = new BIT(m);
        long ans = 0;
        for (int j = 0; j < n; j++) {
            long queryVal = a[j] + diff;
            int idxQuery = upperBound(vals, queryVal);
            ans += bit.query(idxQuery);
            int idxInsert = lowerBound(vals, a[j]);
            bit.update(idxInsert, 1);
        }
        return ans;
    }

    private int lowerBound(long[] arr, long target) {
        int l = 0, r = arr.length;
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (arr[mid] < target) l = mid + 1;
            else r = mid;
        }
        return l + 1; // 1-based index for BIT
    }

    private int upperBound(long[] arr, long target) {
        int l = 0, r = arr.length;
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (arr[mid] <= target) l = mid + 1;
            else r = mid;
        }
        return l; // number of elements <= target
    }

    private static class BIT {
        private final int n;
        private final int[] tree;

        BIT(int n) {
            this.n = n;
            this.tree = new int[n + 2];
        }

        void update(int idx, int delta) {
            for (int i = idx; i <= n; i += i & -i) {
                tree[i] += delta;
            }
        }

        long query(int idx) {
            long sum = 0;
            for (int i = idx; i > 0; i -= i & -i) {
                sum += tree[i];
            }
            return sum;
        }
    }
}

