        long result = 0;
        for (int j = 0; j < n; j++) {
            long threshold = a[j] + diff;
            int idx = upperBound(all, threshold); // number of elements <= threshold
            result += bit.sum(idx);
            int pos = lowerBound(all, a[j]); // index of a[j]
            bit.add(pos + 1, 1); // Fenwick is 1-indexed
        }
        return result;
    }

    private int lowerBound(long[] arr, long target) {
        int l = 0, r = arr.length;
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (arr[mid] < target) l = mid + 1;
            else r = mid;
        }
        return l;
    }

    private int upperBound(long[] arr, long target) {
        int l = 0, r = arr.length;
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (arr[mid] <= target) l = mid + 1;
            else r = mid;
        }
        return l;
    }

    // Fenwick tree (Binary Indexed Tree) for prefix sums
    private static class Fenwick {
        private final int n;
        private final long[] bit;

        Fenwick(int n) {
            this.n = n;
            this.bit = new long[n + 2];
        }

        void add(int idx, long delta) {
            for (int i = idx; i <= n; i += i & -i) {
                bit[i] += delta;
            }
        }

        long sum(int idx) {
            long res = 0;
            for (int i = idx; i > 0; i -= i & -i) {
                res += bit[i];
            }
            return res;
        }
    }
}

