    public long countPairs(int[] nums1, int[] nums2, int diff) {
        int n = nums1.length;
        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = (long) nums1[i] - nums2[i];
        }

        // Prepare values for compression
        long[] allVals = new long[2 * n];
        for (int i = 0; i < n; i++) {
            allVals[i] = a[i];
            allVals[i + n] = a[i] + diff;
        }
        Arrays.sort(allVals);
        int m = 1;
        for (int i = 1; i < allVals.length; i++) {
            if (allVals[i] != allVals[i - 1]) {
                allVals[m++] = allVals[i];
            }
        }
        allVals = Arrays.copyOf(allVals, m);

        Fenwick fenwick = new Fenwick(m);
        long ans = 0;
        for (int j = 0; j < n; j++) {
            long queryVal = a[j] + diff;
            int pos = Arrays.binarySearch(allVals, queryVal);
            int idxQuery;
            if (pos >= 0) {
                idxQuery = pos + 1;
            } else {
                idxQuery = -pos - 1; // insertion point
            }
            ans += fenwick.query(idxQuery);

            int posAdd = Arrays.binarySearch(allVals, a[j]);
            int idxAdd = posAdd + 1;
            fenwick.update(idxAdd, 1);
        }
        return ans;
    }

    private static class Fenwick {
        private final long[] tree;

        Fenwick(int size) {
            tree = new long[size + 2];
        }

        void update(int idx, long delta) {
            while (idx < tree.length) {
                tree[idx] += delta;
                idx += idx & -idx;
            }
        }

        long query(int idx) {
            long sum = 0;
            while (idx > 0) {
                sum += tree[idx];
                idx -= idx & -idx;
            }
            return sum;
        }
    }
