import java.util.ArrayList;
import java.util.List;

public class Solution {

    /**
     * Counts the subarrays of {@code nums} whose greatest common divisor equals {@code k}.
     *
     * @param nums the input array of integers
     * @param k    the target greatest common divisor
     * @return the number of contiguous subarrays whose GCD is exactly {@code k}
     */
    public long subarrayGCD(int[] nums, int k) {
        if (nums == null || nums.length == 0 || k == 0) {
            return 0;
        }

        long result = 0;
        int n = nums.length;
        int i = 0;

        while (i < n) {
            // Skip elements that are not divisible by k
            if (nums[i] % k != 0) {
                i++;
                continue;
            }

            // Find contiguous segment where every element is divisible by k
            int j = i;
            while (j < n && nums[j] % k == 0) {
                j++;
            }

            // Process segment [i, j)
            List<long[]> prev = new ArrayList<>();
            for (int idx = i; idx < j; idx++) {
                long val = Math.abs(nums[idx] / (long) k);

                List<long[]> curr = new ArrayList<>();
                curr.add(new long[]{val, 1});

                for (long[] pair : prev) {
                    long g = gcd(pair[0], val);
                    if (curr.get(curr.size() - 1)[0] == g) {
                        curr.get(curr.size() - 1)[1] += pair[1];
                    } else {
                        curr.add(new long[]{g, pair[1]});
                    }
                }

                for (long[] pair : curr) {
                    if (pair[0] == 1) {
                        result += pair[1];
                    }
                }

                prev = curr;
            }

            i = j;
        }

        return result;
    }

    /**
     * Computes the greatest common divisor of two non-negative integers.
     *
     * @param a first integer
     * @param b second integer
     * @return the GCD of {@code a} and {@code b}
     */
    private long gcd(long a, long b) {
        while (b != 0) {
            long temp = a % b;
            a = b;
            b = temp;
        }
        return Math.abs(a);
    }
}

