                map.put(diff0, w[0]);
                map.put(diff1, w[1]);
                map.put(diff2, w[2]);
                // The odd one will have unique key
                for (String key : map.keySet()) {
                    int count = 0;
                    for (int i = 0; i < n; i++) {
                        if (key.equals(getDiff(w[i]))) count++;
                    }
                    if (count == 1) return map.get(key);
                }
            }
        }
        return w[0];
    }

    private String getDiff(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length() - 1; i++) {
            int diff = s.charAt(i + 1) - s.charAt(i);
            sb.append(diff);
            sb.append(',');
        }
        return sb.toString();
    }
}

