import java.util.*;

public class Solution {
    public String oddString(String[] w) {
        if (w == null || w.length == 0) return "";
        int n = w[0].length();
        String diff1 = diffString(w[0], n);
        String diff2 = diffString(w[1], n);
        String diff3 = diffString(w[2], n);

        String majority;
        if (diff1.equals(diff2)) {
            majority = diff1;
        } else if (diff1.equals(diff3)) {
            majority = diff1;
        } else {
            majority = diff2;
        }

        for (String word : w) {
            if (!diffString(word, n).equals(majority)) {
                return word;
            }
        }
        return ""; // fallback, should not happen
    }

    private String diffString(String s, int n) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n - 1; i++) {
            sb.append(s.charAt(i + 1) - s.charAt(i)).append(',');
        }
        return sb.toString();
    }
}

