import com_github_leetcode.TreeNode;
import java.util.HashMap;
import java.util.Map;

public class Solution {
    private Map<Integer, Integer> valueToOutsideDepth = new HashMap<>();
    private Map<Integer, Integer> valueToSubMaxDepth = new HashMap<>();

    public int[] treeQueries(TreeNode root, int[] queries) {
        // First DFS to compute depth and subMaxDepth
        dfsCompute(root, 0);
        // Second DFS to compute maxDepthOutside for each node
        dfsComputeOutside(root, -1);
        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            ans[i] = valueToOutsideDepth.get(queries[i]);
        }
        return ans;
    }

    private void dfsCompute(TreeNode node, int depth) {
        if (node == null) return;
        int maxDepth = depth;
        if (node.left != null) {
            dfsCompute(node.left, depth + 1);
            maxDepth = Math.max(maxDepth, valueToSubMaxDepth.get(node.left.val));
        }
        if (node.right != null) {
            dfsCompute(node.right, depth + 1);
            maxDepth = Math.max(maxDepth, valueToSubMaxDepth.get(node.right.val));
        }
        valueToSubMaxDepth.put(node.val, maxDepth);
    }

    private void dfsComputeOutside(TreeNode node, int maxDepthOutside) {
        if (node == null) return;
        valueToOutsideDepth.put(node.val, maxDepthOutside);
        int leftMax = -1, rightMax = -1;
        if (node.left != null) leftMax = valueToSubMaxDepth.get(node.left.val);
        if (node.right != null) rightMax = valueToSubMaxDepth.get(node.right.val);

        if (node.left != null) {
            int siblingMax = rightMax;
            int childOutside = Math.max(maxDepthOutside, siblingMax);
            dfsComputeOutside(node.left, childOutside);
        }
        if (node.right != null) {
            int siblingMax = leftMax;
            int childOutside = Math.max(maxDepthOutside, siblingMax);
            dfsComputeOutside(node.right, childOutside);
        }
    }
}

