import com_github_leetcode.TreeNode;
import java.util.HashMap;
import java.util.Map;

public class Solution {
    // Arrays indexed by node value (1..n)
    private int[] depth;
    private int[] subMaxDepth;  // maximum depth from node to leaf (edges)
    private int[] outside;      // maximum depth among nodes not in subtree of node
    private Map<Integer, Integer> valToIndex;  // value -> index (value itself)
    private int n;

    public int[] treeQueries(TreeNode root, int[] queries) {
        // First pass: count nodes and create mapping
        n = countNodes(root);
        depth = new int[n + 1];
        subMaxDepth = new int[n + 1];
        outside = new int[n + 1];
        valToIndex = new HashMap<>(n * 2);
        assignIndex(root);

        // Compute depths and subMaxDepth
        dfsDepthSub(root, 0);

        // Compute outside values
        computeOutside(root, -1);

        // Prepare answer
        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int v = queries[i];
            int idx = valToIndex.get(v);
            ans[i] = Math.max(0, outside[idx]);  // if outside[idx] == -1, answer is 0
        }
        return ans;
    }

    private int countNodes(TreeNode node) {
        if (node == null) return 0;
        return 1 + countNodes(node.left) + countNodes(node.right);
    }

    private void assignIndex(TreeNode node) {
        if (node == null) return;
        valToIndex.put(node.val, node.val); // value itself is unique id
        assignIndex(node.left);
        assignIndex(node.right);
    }

    private void dfsDepthSub(TreeNode node, int d) {
        if (node == null) return;
        depth[node.val] = d;
        int left = 0, right = 0;
        if (node.left != null) {
            dfsDepthSub(node.left, d + 1);
            left = subMaxDepth[node.left.val];
        }
        if (node.right != null) {
            dfsDepthSub(node.right, d + 1);
            right = subMaxDepth[node.right.val];
        }
        subMaxDepth[node.val] = Math.max(left, right);
    }

    private void computeOutside(TreeNode node, int parentOutside) {
        if (node == null) return;
        int p = node.val;
        // Prepare top two absolute depths among children
        int top1 = -1, top2 = -1, top1Child = -1;
        if (node.left != null) {
            int d = depth[p] + 1 + subMaxDepth[node.left.val];
            if (d > top1) {
                top2 = top1;
                top1 = d;
                top1Child = node.left.val;
            } else if (d > top2) {
                top2 = d;
            }
        }
        if (node.right != null) {
            int d = depth[p] + 1 + subMaxDepth[node.right.val];
            if (d > top1) {
                top2 = top1;
                top1 = d;
                top1Child = node.right.val;
            } else if (d > top2) {
                top2 = d;
            }
        }

        // Process children
        if (node.left != null) {
            int siblingBest = (node.left.val == top1Child) ? top2 : top1;
            int childOutside = Math.max(parentOutside, siblingBest);
            outside[node.left.val] = childOutside;
            computeOutside(node.left, childOutside);
        }
        if (node.right != null) {
            int siblingBest = (node.right.val == top1Child) ? top2 : top1;
            int childOutside = Math.max(parentOutside, siblingBest);
            outside[node.right.val] = childOutside;
            computeOutside(node.right, childOutside);
        }

        // Set outside for current node if needed (not used for root)
        outside[p] = parentOutside;
    }
}

