import com_github_leetcode.TreeNode;
import java.util.*;

public class Solution {
    public int[] subtreeQueries(TreeNode root, int[] queries) {
        int n = countNodes(root);
        int[] depth = new int[n + 1];
        int[] dp = new int[n + 1];
        int[] up = new int[n + 1];

        dfs1(root, 0, depth, dp);
        dfs2(root, -1, depth, dp, up);

        int[] result = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            result[i] = up[queries[i]];
        }
        return result;
    }

    private int countNodes(TreeNode node) {
        if (node == null) return 0;
        return 1 + countNodes(node.left) + countNodes(node.right);
    }

    private void dfs1(TreeNode node, int curDepth, int[] depthArr, int[] dpArr) {
        depthArr[node.val] = curDepth;
        int maxDp = 0;
        if (node.left != null) {
            dfs1(node.left, curDepth + 1, depthArr, dpArr);
            maxDp = Math.max(maxDp, dpArr[node.left.val] + 1);
        }
        if (node.right != null) {
            dfs1(node.right, curDepth + 1, depthArr, dpArr);
            maxDp = Math.max(maxDp, dpArr[node.right.val] + 1);
        }
        dpArr[node.val] = maxDp;
    }

    private void dfs2(TreeNode node, int upVal, int[] depthArr, int[] dpArr, int[] upArr) {
        upArr[node.val] = upVal;

        if (node.left != null) {
            int otherCand = -1;
            if (node.right != null) {
                otherCand = dpArr[node.right.val] + 1;
            }
            int childUp = Math.max(Math.max(upVal, depthArr[node.val]), depthArr[node.val] + otherCand);
            dfs2(node.left, childUp, depthArr, dpArr, upArr);
        }

        if (node.right != null) {
            int otherCand = -1;
            if (node.left != null) {
                otherCand = dpArr[node.left.val] + 1;
            }
            int childUp = Math.max(Math.max(upVal, depthArr[node.val]), depthArr[node.val] + otherCand);
            dfs2(node.right, childUp, depthArr, dpArr, upArr);
        }
    }
}

package referenz;

import com_github_leetcode.TreeNode;
import java.util.ArrayList;
import java.util.List;

public class Solution {
    private int[] depth;
    private int[] subtreeMaxDepth;
    private int[] outsideMaxDepth;
    private int[] entry;
    private int[] exit;
    private List<Integer>[] children;
    private int timer;

    public int[] treeQueries(TreeNode root, int[] queries) {
        // First pass: determine maximum node value to size arrays
        int maxVal = 0;
        countNodes(root, maxValHolder -> maxVal = Math.max(maxVal, maxValHolder));

        // Initialize arrays
        int size = maxVal + 1;
        depth = new int[size];
        subtreeMaxDepth = new int[size];
        outsideMaxDepth = new int[size];
        entry = new int[size];
        exit = new int[size];
        children = new List[size];
        for (int i = 0; i < size; i++) {
            children[i] = new ArrayList<>();
        }

        // Second pass: compute depths, subtree max depths, and Euler tour entries
        timer = 0;
        dfs1(root, 0);

        // Third pass: compute outside max depths via rerooting
        dfs2(root.val, -1);

        // Build answer
        int[] answer = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            answer[i] = outsideMaxDepth[queries[i]];
        }
        return answer;
    }

    // Helper to count nodes and find max value
    private void countNodes(TreeNode node, java.util.function.IntConsumer consumer) {
        if (node == null) return;
        consumer.accept(node.val);
        countNodes(node.left, consumer);
        countNodes(node.right, consumer);
    }

    // First DFS to compute depth and subtree max depth
    private void dfs1(TreeNode node, int d) {
        int val = node.val;
        depth[val] = d;
        entry[val] = timer++;
        int max = depth[val];
        if (node.left != null) {
            children[val].add(node.left.val);
            dfs1(node.left, d + 1);
            max = Math.max(max, subtreeMaxDepth[node.left.val]);
        }
        if (node.right != null) {
            children[val].add(node.right.val);
            dfs1(node.right, d + 1);
            max = Math.max(max, subtreeMaxDepth[node.right.val]);
        }
        subtreeMaxDepth[val] = max;
        exit[val] = timer - 1;
    }

    // Second DFS to compute outside max depth for each node
    private void dfs2(int val, int parentOutside) {
        outsideMaxDepth[val] = parentOutside;
        int k = children[val].size();
        if (k == 0) return;
        int[] pre = new int[k];
        int[] suf = new int[k];
        for (int i = 0; i < k; i++) {
            int child = children[val].get(i);
            pre[i] = (i == 0) ? subtreeMaxDepth[child] : Math.max(pre[i - 1], subtreeMaxDepth[child]);
        }
        for (int i = k - 1; i >= 0; i--) {
            int child = children[val].get(i);
            suf[i] = (i == k - 1) ? subtreeMaxDepth[child] : Math.max(suf[i + 1], subtreeMaxDepth[child]);
        }
        for (int i = 0; i < k; i++) {
            int child = children[val].get(i);
            int maxOther = depth[val];
            if (k > 1) {
                int left = (i > 0) ? pre[i - 1] : -1;
                int right = (i < k - 1) ? suf[i + 1] : -1;
                int siblingMax = Math.max(left, right);
                if (siblingMax > maxOther) maxOther = siblingMax;
            }
            int childOutside = Math.max(parentOutside, maxOther);
            dfs2(child, childOutside);
        }
    }
}

