import com_github_leetcode.TreeNode;
import java.util.*;

public class Solution {
    public int[] treeQueries(TreeNode root, int[] queries) {
        int n = countNodes(root);
        int[] depth = new int[n + 1];
        int[] subtreeMaxDepth = new int[n + 1];
        int[] childLeft = new int[n + 1];
        int[] childRight = new int[n + 1];
        dfs1(root, 0, depth, subtreeMaxDepth, childLeft, childRight);
        int[] maxChild1 = new int[n + 1];
        int[] maxChild2 = new int[n + 1];
        for (int v = 1; v <= n; v++) {
            int max1 = -1, max2 = -1;
            int c = childLeft[v];
            if (c != 0) {
                int val = subtreeMaxDepth[c];
                if (val > max1) {
                    max2 = max1;
                    max1 = val;
                } else if (val > max2) {
                    max2 = val;
                }
            }
            c = childRight[v];
            if (c != 0) {
                int val = subtreeMaxDepth[c];
                if (val > max1) {
                    max2 = max1;
                    max1 = val;
                } else if (val > max2) {
                    max2 = val;
                }
            }
            maxChild1[v] = max1;
            maxChild2[v] = max2;
        }
        int globalMaxDepth = subtreeMaxDepth[root.val];
        int[] outsideDepth = new int[n + 1];
        dfsOut(root, -1, depth, subtreeMaxDepth, childLeft, childRight, maxChild1, maxChild2, outsideDepth);
        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int q = queries[i];
            if (subtreeMaxDepth[q] < globalMaxDepth) {
                ans[i] = globalMaxDepth;
            } else {
                ans[i] = outsideDepth[q];
            }
        }
        return ans;
    }

    private int countNodes(TreeNode node) {
        if (node == null) return 0;
        return 1 + countNodes(node.left) + countNodes(node.right);
    }

    private void dfs1(TreeNode node, int d, int[] depth, int[] subtreeMaxDepth,
                      int[] childLeft, int[] childRight) {
        int v = node.val;
        depth[v] = d;
        subtreeMaxDepth[v] = d;
        if (node.left != null) {
            childLeft[v] = node.left.val;
            dfs1(node.left, d + 1, depth, subtreeMaxDepth, childLeft, childRight);
            subtreeMaxDepth[v] = Math.max(subtreeMaxDepth[v], subtreeMaxDepth[node.left.val]);
        }
        if (node.right != null) {
            childRight[v] = node.right.val;
            dfs1(node.right, d + 1, depth, subtreeMaxDepth, childLeft, childRight);
            subtreeMaxDepth[v] = Math.max(subtreeMaxDepth[v], subtreeMaxDepth[node.right.val]);
        }
    }

    private void dfsOut(TreeNode node, int bestOutsideAncestors,
                        int[] depth, int[] subtreeMaxDepth,
                        int[] childLeft, int[] childRight,
                        int[] maxChild1, int[] maxChild2,
                        int[] outsideDepth) {
        int v = node.val;
        outsideDepth[v] = bestOutsideAncestors;
        int max1 = maxChild1[v];
        int max2 = maxChild2[v];

        if (node.left != null) {
            int c = node.left.val;
            int siblingMax = (subtreeMaxDepth[c] == max1) ? max2 : max1;
            int candidate = Math.max(depth[v], Math.max(siblingMax, bestOutsideAncestors));
            dfsOut(node.left, candidate, depth, subtreeMaxDepth, childLeft, childRight,
                    maxChild1, maxChild2, outsideDepth);
        }
        if (node.right != null) {
            int c = node.right.val;
            int siblingMax = (subtreeMaxDepth[c] == max1) ? max2 : max1;
            int candidate = Math.max(depth[v], Math.max(siblingMax, bestOutsideAncestors));
            dfsOut(node.right, candidate, depth, subtreeMaxDepth, childLeft, childRight,
                    maxChild1, maxChild2, outsideDepth);
        }
    }
}

