import java.util.*;

public class Solution {
    public long minimumTotalDistance(List<Integer> robot, int[][] f) {
        int n = robot.size();
        int[] robots = new int[n];
        for (int i = 0; i < n; i++) {
            robots[i] = robot.get(i);
        }
        Arrays.sort(robots);

        TreeMap<Integer, Long> factoryMap = new TreeMap<>();
        for (int[] fac : f) {
            int pos = fac[0];
            int limit = fac[1];
            if (limit > 0) {
                factoryMap.put(pos, (long) limit);
            }
        }

        long totalDistance = 0L;
        for (int r : robots) {
            Map.Entry<Integer, Long> left = factoryMap.floorEntry(r);
            Map.Entry<Integer, Long> right = factoryMap.ceilingEntry(r);

            Map.Entry<Integer, Long> chosen;
            if (left == null) {
                chosen = right;
            } else if (right == null) {
                chosen = left;
            } else {
                int distLeft = r - left.getKey();
                int distRight = right.getKey() - r;
                chosen = (distLeft <= distRight) ? left : right;
            }

            int factoryPos = chosen.getKey();
            totalDistance += Math.abs((long) r - factoryPos);

            long remaining = chosen.getValue() - 1;
            if (remaining == 0) {
                factoryMap.remove(factoryPos);
            } else {
                factoryMap.put(factoryPos, remaining);
            }
        }

        return totalDistance;
    }
}

