import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.ArrayList;

public class Solution {
    public long minimumTotalDistance(List<Integer> robot, int[][] f) {
        int n = robot.size();
        int m = f.length;

        // sort robots
        int[] robots = new int[n];
        for (int i = 0; i < n; i++) {
            robots[i] = robot.get(i);
        }
        Arrays.sort(robots);

        // sort factories by position
        Arrays.sort(f, (a, b) -> Integer.compare(a[0], b[0]));

        // prefix sums of robot positions
        long[] pref = new long[n + 1];
        for (int i = 1; i <= n; i++) {
            pref[i] = pref[i - 1] + robots[i - 1];
        }

        // dp[i][j] minimal distance using first i factories to repair first j robots
        long INF = Long.MAX_VALUE / 4;
        long[][] dp = new long[m + 1][n + 1];
        for (int i = 0; i <= m; i++) {
            Arrays.fill(dp[i], INF);
        }
        dp[0][0] = 0;

        for (int i = 1; i <= m; i++) {
            int pos = f[i - 1][0];
            int limit = f[i - 1][1];
            for (int j = 0; j <= n; j++) {
                // try assigning k robots to this factory
                int maxK = Math.min(limit, j);
                for (int k = 0; k <= maxK; k++) {
                    long prev = dp[i - 1][j - k];
                    if (prev == INF) continue;
                    long cost = 0;
                    if (k > 0) {
                        int l = j - k; // 0-based index of first robot assigned
                        int r = j - 1; // last robot assigned
                        // indices in pref are 1-based
                        int left = l + 1;
                        int right = r + 1;
                        // find mid where robot <= pos
                        int lo = left;
                        int hi = right;
                        int mid = right + 1;
                        while (lo <= hi) {
                            int midp = (lo + hi) >>> 1;
                            if (robots[midp - 1] <= pos) {
                                mid = midp;
                                lo = midp + 1;
                            } else {
                                hi = midp - 1;
                            }
                        }
                        long sumLeft = pref[mid] - pref[left - 1];
                        long sumRight = pref[right] - pref[mid];
                        long cntLeft = mid - left + 1;
                        long cntRight = right - mid;
                        cost = pos * cntLeft - sumLeft + sumRight - pos * cntRight;
                    }
                    dp[i][j] = Math.min(dp[i][j], prev + cost);
                }
            }
        }

        return dp[m][n];
    }
}

