public class Solution {
    public long minimumTotalDistance(List<Integer> robot, int[][] f) {
        int n = robot.size();
        int[][] factories = new int[f.length][2];
        for (int i = 0; i < f.length; i++) {
            factories[i][0] = f[i][0];
            factories[i][1] = f[i][1];
        }
        Arrays.sort(factories, Comparator.comparingInt(a -> a[0]));
        int[] robots = new int[n];
        for (int i = 0; i < n; i++) robots[i] = robot.get(i);
