        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int[] fac : factories) {
            int pos = fac[0];
            int limit = fac[1];
            long[] ndp = new long[n + 1];
            Arrays.fill(ndp, INF);
            for (int k = 0; k <= n; k++) {
                if (dp[k] == INF) continue;
                // t = 0
                ndp[k] = Math.min(ndp[k], dp[k]);
                long cost = 0;
                for (int t = 1; t <= limit && k + t <= n; t++) {
                    cost += Math.abs((long) pos - robots[k + t - 1]);
                    ndp[k + t] = Math.min(ndp[k + t], dp[k] + cost);
                }
            }
            dp = ndp;
        }
        return dp[n];
    }
}

package referenz;


import java.util.*;

public class Solution {
    public long minimumTotalDistance(List<Integer> robot, int[][] f) {
        int n = robot.size();
        int m = f.length;
        int[] robots = new int[n];
        for (int i = 0; i < n; i++) robots[i] = robot.get(i);
        Arrays.sort(robots);

        // Sort factories by position
        Arrays.sort(f, Comparator.comparingInt(a -> a[0]));
        // Prefix sums of robot positions
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + robots[i];

        long INF = Long.MAX_VALUE / 4;
        long[][] dp = new long[m + 1][n + 1];
        for (int i = 0; i <= m; i++) Arrays.fill(dp[i], INF);
        dp[0][0] = 0;

        for (int i = 1; i <= m; i++) {
            int cap = f[i - 1][1];
            int pos = f[i - 1][0];
            for (int k = 0; k <= n; k++) {
                int tMin = Math.max(0, k - cap);
                long best = INF;
                for (int t = tMin; t <= k; t++) {
                    if (dp[i - 1][t] == INF) continue;
                    long cost = segmentCost(t, k - 1, pos, robots, prefix);
                    long candidate = dp[i - 1][t] + cost;
                    if (candidate < best) best = candidate;
                }
                dp[i][k] = best;
            }
        }
        return dp[m][n];
    }

    // Compute cost of assigning robots[l..r] to factory at position pos
    private long segmentCost(int l, int r, int pos, int[] robots, long[] prefix) {
        if (l > r) return 0;
        int split = lowerBound(robots, pos + 1, l, r + 1); // first index > pos
        long leftCnt = split - l;
        long sumLeft = prefix[split] - prefix[l];
        long rightCnt = r - split + 1;
        long sumRight = prefix[r + 1] - prefix[split];
        long cost = leftCnt * pos - sumLeft + sumRight - rightCnt * pos;
        return cost;
    }

    // First index in arr in [left, right) such that arr[idx] >= target
    private int lowerBound(int[] arr, int target, int left, int right) {
        while (left < right) {
            int mid = (left + right) >>> 1;
            if (arr[mid] < target) left = mid + 1;
            else right = mid;
