import java.util.*;

public class Solution {
    public long minimumTotalDistance(List<Integer> robot, int[][] f) {
        int n = robot.size();
        int m = f.length;
        int[] robots = new int[n];
        for (int i = 0; i < n; ++i) robots[i] = robot.get(i);
        Arrays.sort(robots);

        // sort factories by position ascending
        Arrays.sort(f, Comparator.comparingInt(a -> a[0]));

        final long INF = Long.MAX_VALUE / 4;
        long[] dpPrev = new long[n + 1];
        long[] dpCurr = new long[n + 1];
        Arrays.fill(dpPrev, INF);
        dpPrev[0] = 0;

        for (int idx = 0; idx < m; ++idx) {
            int pos = f[idx][0];
            int limit = f[idx][1];

            long[] preCost = new long[n + 1];
            preCost[0] = 0;
            for (int i = 1; i <= n; ++i) {
                preCost[i] = preCost[i - 1] + Math.abs((long) robots[i - 1] - pos);
            }

            Arrays.fill(dpCurr, INF);
            dpCurr[0] = 0;

            ArrayDeque<Integer> deque = new ArrayDeque<>();

            for (int j = 0; j <= n; ++j) {
                int low = Math.max(0, j - limit);

                // Remove indices that are out of window
                while (!deque.isEmpty() && deque.peekFirst() < low) {
                    deque.pollFirst();
                }

                // Add current index j to deque (it can be used for future calculations)
                if (dpPrev[j] < INF) {
                    long val = dpPrev[j] - preCost[j];
                    while (!deque.isEmpty()) {
                        int k = deque.peekLast();
                        long kv = dpPrev[k] - preCost[k];
                        if (val <= kv) {
                            deque.pollLast();
                        } else {
                            break;
                        }
                    }
                    deque.offerLast(j);
                }

                if (j > 0) {
                    if (!deque.isEmpty()) {
                        int k = deque.peekFirst();
                        dpCurr[j] = preCost[j] + (dpPrev[k] - preCost[k]);
                    } else {
                        dpCurr[j] = INF;
                    }
                }
            }

            long[] temp = dpPrev;
            dpPrev = dpCurr;
            dpCurr = temp;
        }

        return dpPrev[n];
    }
}

