import java.util.PriorityQueue;

public class Solution {
    public int minGroups(int[][] intervals) {
        if (intervals == null || intervals.length == 0) {
            return 0;
        }
        // Sort intervals by their left endpoints (ascending)
        Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));

        // Min-heap to keep track of the right ends of active intervals
        PriorityQueue<Integer> minHeap = new PriorityQueue<>();
        int maxGroups = 0;

        for (int[] interval : intervals) {
            int left = interval[0];
            int right = interval[1];

            // Remove intervals that finish before the current interval starts
            // Since intervals are inclusive, we only remove if left > current end
            while (!minHeap.isEmpty() && left > minHeap.peek()) {
                minHeap.poll();
            }

            // Add current interval's end to the heap
            minHeap.offer(right);

            // Update maximum number of simultaneous intervals
            maxGroups = Math.max(maxGroups, minHeap.size());
        }

        return maxGroups;
    }
}

