public class Solution {
    public int minGroups(int[][] intervals) {
        if (intervals == null || intervals.length == 0) {
            return 0;
        }

        // Sort intervals by starting time
        Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));

        // Min-heap to keep track of the earliest ending interval in each group
        PriorityQueue<Integer> pq = new PriorityQueue<>();

        int maxGroups = 0;

        for (int[] interval : intervals) {
            int start = interval[0];
            int end = interval[1];

            // Remove all intervals that finish strictly before the current start
            // Since intervals that end at start still intersect (inclusive), we need end < start to free a group
            while (!pq.isEmpty() && pq.peek() < start) {
                pq.poll();
            }

            // Assign current interval to a group (push its end time)
            pq.offer(end);

            // Update maximum number of groups used so far
            maxGroups = Math.max(maxGroups, pq.size());
        }

        return maxGroups;
    }
}

