            answer[i][1] = (ceil == null) ? -1 : ceil;
        }

        return answer;
    }

    private void populateSet(TreeNode node, TreeSet<Integer> set) {
        if (node == null) return;
        set.add(node.val);
        populateSet(node.left, set);
        populateSet(node.right, set);
    }
