public class Solution {
    public int[][] closestNodes(TreeNode root, int[] queries) {
        int n = queries.length;
        int[][] answer = new int[n][2];
        for (int i = 0; i < n; i++) {
            int q = queries[i];
            int pred = -1;
            int succ = -1;
            TreeNode node = root;

            while (node != null) {
                if (node.val == q) {
                    pred = succ = node.val;
                    break;
                } else if (node.val < q) {
                    pred = node.val;
                    node = node.right;
                } else {
                    succ = node.val;
                    node = node.left;
                }
            }
            answer[i][0] = pred;
            answer[i][1] = succ;
        }
        return answer;
    }
}

