public class Solution {
    public int deleteString(String s) {
        int n = s.length();
        if (n == 0) return 0;

        // 64-bit rolling hash
        long base = 911382323L;
        long[] pow = new long[n + 1];
        long[] h = new long[n + 1];
        pow[0] = 1;
        for (int i = 0; i < n; i++) {
            pow[i + 1] = pow[i] * base;
            h[i + 1] = h[i] * base + s.charAt(i);
        }

        java.util.function.IntBinaryOperator getHash = (l, r) -> {
            long hash = h[r + 1] - h[l] * pow[r - l + 1];
            return (int) hash; // cast to int for comparison; collisions are extremely unlikely
        };

        int[] dp = new int[n + 1];
        dp[n] = 0;
        for (int pos = n - 1; pos >= 0; pos--) {
            int best = 1; // delete entire suffix
            int maxI = (n - pos) / 2;
            for (int i = 1; i <= maxI; i++) {
                if (getHash.applyAsInt(pos, pos + i - 1) == getHash.applyAsInt(pos + i, pos + 2 * i - 1)) {
                    best = Math.max(best, 1 + dp[pos + i]);
                }
            }
            dp[pos] = best;
        }
        return dp[0];
    }
}

