            int maxOps = 1;
            int limit = (n - pos) / 2;
            for (int i = 1; i <= limit; i++) {
                int lcpLen = getLCP(pos, pos + i, rank, rmq, n);
                if (lcpLen >= i) {
                    maxOps = 1 + dp[pos + i];
                    break; // minimal i found
                }
            }
            dp[pos] = maxOps;
        }

        return dp[0];
    }

    private int[] buildSuffixArray(String s) {
        int n = s.length();
        Integer[] saIdx = new Integer[n];
        for (int i = 0; i < n; i++) saIdx[i] = i;
        int[] rank = new int[n];
        for (int i = 0; i < n; i++) rank[i] = s.charAt(i);

        int k = 1;
        while (k < n) {
            final int kk = k;
            Arrays.sort(saIdx, (a, b) -> {
                if (rank[a] != rank[b]) return Integer.compare(rank[a], rank[b]);
                int ra = a + kk < n ? rank[a + kk] : -1;
                int rb = b + kk < n ? rank[b + kk] : -1;
                return Integer.compare(ra, rb);
            });

            int[] tmp = new int[n];
            tmp[saIdx[0]] = 0;
            for (int i = 1; i < n; i++) {
                int prev = saIdx[i - 1];
                int cur = saIdx[i];
                int curRank = rank[cur];
                int prevRank = rank[prev];
                int curNext = cur + kk < n ? rank[cur + kk] : -1;
                int prevNext = prev + kk < n ? rank[prev + kk] : -1;

                tmp[cur] = tmp[prev];
                if (curRank != prevRank || curNext != prevNext) tmp[cur] = tmp[prev] + 1;
            }
            rank = tmp;
            if (rank[saIdx[n - 1]] == n - 1) break;
            k <<= 1;
        }

        int[] sa = new int[n];
        for (int i = 0; i < n; i++) sa[i] = saIdx[i];
        return sa;
    }

    private int[] buildLCPArray(String s, int[] sa, int[] rank) {
        int n = s.length();
        int[] lcp = new int[n];
        int h = 0;
        for (int i = 0; i < n; i++) {
            int r = rank[i];
            if (r == 0) {
                lcp[0] = 0;
                continue;
            }
            int j = sa[r - 1];
            while (i + h < n && j + h < n && s.charAt(i + h) == s.charAt(j + h)) h++;
            lcp[r] = h;
            if (h > 0) h--;
        }
        return lcp;
    }

    private int getLCP(int i, int j, int[] rank, RMQ rmq, int n) {
        if (i == j) return n - i;
        int ri = rank[i];
        int rj = rank[j];
        if (ri > rj) {
            int tmp = ri;
            ri = rj;
            rj = tmp;
        }
        // lcp between suffixes i and j is min over lcp[ri+1 .. rj]
        return rmq.query(ri + 1, rj);
    }

    // RMQ (Range Minimum Query) using Sparse Table
    private static class RMQ {
        private final int[][] st;
        private final int[] log;

        RMQ(int[] arr) {
            int n = arr.length;
            log = new int[n + 2];
            log[1] = 0;
            for (int i = 2; i <= n + 1; i++) log[i] = log[i >> 1] + 1;
            int maxLog = log[n] + 1;
            st = new int[maxLog][n];
            System.arraycopy(arr, 0, st[0], 0, n);
            for (int k = 1; k < maxLog; k++) {
                int len = 1 << k;
                int half = len >> 1;
                int limit = n - len + 1;
                for (int i = 0; i < limit; i++) {
                    st[k][i] = Math.min(st[k - 1][i], st[k - 1][i + half]);
                }
            }
        }

        int query(int l, int r) { // inclusive
            if (l > r) return Integer.MAX_VALUE;
            int k = log[r - l + 1];
            return Math.min(st[k][l], st[k][r - (1 << k) + 1]);
        }
    }
}

