class Solution {
    public int deleteString(String s) {
        int n = s.length();
        if (n == 0) return 0;

        final long MOD = 1_000_000_007L;
        final long BASE = 911382323L;

        long[] pow = new long[n + 1];
        long[] pref = new long[n + 1];
        pow[0] = 1;
        for (int i = 1; i <= n; i++) {
            pow[i] = (pow[i - 1] * BASE) % MOD;
        }
        for (int i = 0; i < n; i++) {
            pref[i + 1] = (pref[i] * BASE + (s.charAt(i) - 'a' + 1)) % MOD;
        }

        java.util.function.BiFunction<Integer, Integer, Long> getHash = (l, r) -> {
            long hash = pref[r + 1] - (pref[l] * pow[r - l + 1]) % MOD;
            if (hash < 0) hash += MOD;
            return hash;
        };

        int[] dp = new int[n + 1];
        dp[n] = 0;

        for (int i = n - 1; i >= 0; i--) {
            int best = 1; // delete whole string
            int maxLen = (n - i) / 2;
            for (int len = 1; len <= maxLen; len++) {
                long h1 = getHash.apply(i, i + len - 1);
                long h2 = getHash.apply(i + len, i + 2 * len - 1);
                if (h1 == h2) {
                    best = Math.max(best, 1 + dp[i + len]);
                }
            }
            dp[i] = best;
        }
        return dp[0];
    }
}

