public class Solution {
    public int[] smallestSubarrays(int[] nums) {
        int n = nums.length;
        int[] answer = new int[n];
        if (n == 0) return answer;

        // Compute suffix ORs
        int[] suffixOR = new int[n];
        suffixOR[n - 1] = nums[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            suffixOR[i] = suffixOR[i + 1] | nums[i];
        }

        int[] bitCount = new int[31];
        int curOr = 0;
        int j = -1; // right pointer of current window

        for (int i = 0; i < n; i++) {
            // Remove element leaving the window
            if (i > 0) {
                int val = nums[i - 1];
                int x = val;
                while (x != 0) {
                    int b = Integer.numberOfTrailingZeros(x);
                    bitCount[b]--;
                    if (bitCount[b] == 0) {
                        curOr ^= (1 << b);
                    }
                    x &= x - 1;
                }
            }

            // Extend window until OR matches suffixOR[i]
            while (curOr != suffixOR[i] && j + 1 < n) {
                j++;
                int val = nums[j];
                int x = val;
                while (x != 0) {
                    int b = Integer.numberOfTrailingZeros(x);
                    if (bitCount[b] == 0) {
                        curOr |= (1 << b);
                    }
                    bitCount[b]++;
                    x &= x - 1;
                }
            }

            // At this point curOr == suffixOR[i]
            answer[i] = j - i + 1;
        }

        return answer;
    }
}

