import java.util.PriorityQueue;

public class Solution {
    private static class Node {
        int cost;
        int idx;
        Node(int cost, int idx) {
            this.cost = cost;
            this.idx = idx;
        }
    }

    public long totalCost(int[] costs, int k, int candidates) {
        int n = costs.length;
        PriorityQueue<Node> left = new PriorityQueue<>((a, b) -> {
            if (a.cost != b.cost) return Integer.compare(a.cost, b.cost);
            return Integer.compare(a.idx, b.idx);
        });
        PriorityQueue<Node> right = new PriorityQueue<>((a, b) -> {
            if (a.cost != b.cost) return Integer.compare(a.cost, b.cost);
            return Integer.compare(a.idx, b.idx);
        });

        int leftIdx = 0;
        int rightIdx = n - 1;

        // Initialize left heap
        while (leftIdx <= rightIdx && left.size() < candidates) {
            left.offer(new Node(costs[leftIdx], leftIdx));
            leftIdx++;
        }

        // Initialize right heap
        while (rightIdx >= leftIdx && right.size() < candidates) {
            right.offer(new Node(costs[rightIdx], rightIdx));
            rightIdx--;
        }

        long total = 0;
        for (int i = 0; i < k; i++) {
            Node pick;
            if (left.isEmpty()) {
                pick = right.poll();
                // add next from right side if available
                if (rightIdx >= leftIdx) {
                    right.offer(new Node(costs[rightIdx], rightIdx));
                    rightIdx--;
                }
            } else if (right.isEmpty()) {
                pick = left.poll();
                // add next from left side if available
                if (leftIdx <= rightIdx) {
                    left.offer(new Node(costs[leftIdx], leftIdx));
                    leftIdx++;
                }
            } else {
                Node leftTop = left.peek();
                Node rightTop = right.peek();
                if (leftTop.cost < rightTop.cost || (leftTop.cost == rightTop.cost && leftTop.idx < rightTop.idx)) {
                    pick = left.poll();
                    if (leftIdx <= rightIdx) {
                        left.offer(new Node(costs[leftIdx], leftIdx));
                        leftIdx++;
                    }
                } else {
                    pick = right.poll();
                    if (rightIdx >= leftIdx) {
                        right.offer(new Node(costs[rightIdx], rightIdx));
                        rightIdx--;
                    }
                }
            }
            total += pick.cost;
        }

        return total;
    }
}

