        Worker(int cost, int idx) {
            this.cost = cost;
            this.idx = idx;
        }
        @Override
        public int compareTo(Worker other) {
            if (this.cost != other.cost) return Integer.compare(this.cost, other.cost);
            return Integer.compare(this.idx, other.idx);
        }
    }

    public long totalCost(int[] costs, int k, int candidates) {
        int n = costs.length;
        int left = 0;
        int right = n - 1;
        PriorityQueue<Worker> leftPQ = new PriorityQueue<>();
        PriorityQueue<Worker> rightPQ = new PriorityQueue<>();

        // Initialize left candidates
        for (int i = 0; i < candidates && left <= right; i++) {
            leftPQ.offer(new Worker(costs[left], left));
            left++;
        }
        // Initialize right candidates
        for (int i = 0; i < candidates && left <= right; i++) {
            rightPQ.offer(new Worker(costs[right], right));
            right--;
        }

        long total = 0;
        for (int hired = 0; hired < k; hired++) {
            Worker chosen;
            if (leftPQ.isEmpty()) {
                chosen = rightPQ.poll();
                // Add next from right side if available
                if (left <= right) {
                    rightPQ.offer(new Worker(costs[right], right));
                    right--;
                }
            } else if (rightPQ.isEmpty()) {
                chosen = leftPQ.poll();
                // Add next from left side if available
                if (left <= right) {
                    leftPQ.offer(new Worker(costs[left], left));
                    left++;
                }
            } else {
                Worker leftTop = leftPQ.peek();
                Worker rightTop = rightPQ.peek();
                if (leftTop.cost < rightTop.cost || (leftTop.cost == rightTop.cost && leftTop.idx < rightTop.idx)) {
                    chosen = leftPQ.poll();
                    if (left <= right) {
                        leftPQ.offer(new Worker(costs[left], left));
                        left++;
                    }
                } else {
                    chosen = rightPQ.poll();
                    if (left <= right) {
                        rightPQ.offer(new Worker(costs[right], right));
                        right--;
                    }
                }
            }
            total += chosen.cost;
        }
        return total;
    }
}

