public class Solution {
    public long totalCost(int[] costs, int k, int candidates) {
        int n = costs.length;
        int left = 0;
        int right = n - 1;

        Comparator<int[]> comp = Comparator.comparingInt((int[] a) -> a[0])
                                           .thenComparingInt(a -> a[1]);

        PriorityQueue<int[]> leftPQ = new PriorityQueue<>(comp);
        PriorityQueue<int[]> rightPQ = new PriorityQueue<>(comp);

        // Initial filling of the two priority queues
        while (left <= right && leftPQ.size() < candidates) {
            leftPQ.offer(new int[]{costs[left], left});
            left++;
        }
        while (left <= right && rightPQ.size() < candidates) {
            rightPQ.offer(new int[]{costs[right], right});
            right--;
        }

        long total = 0;
        for (int i = 0; i < k; i++) {
            int[] pick;
            boolean fromLeft;

            if (leftPQ.isEmpty()) {
                pick = rightPQ.poll();
                fromLeft = false;
            } else if (rightPQ.isEmpty()) {
                pick = leftPQ.poll();
                fromLeft = true;
            } else {
                int[] l = leftPQ.peek();
                int[] r = rightPQ.peek();
                if (l[0] < r[0] || (l[0] == r[0] && l[1] < r[1])) {
                    pick = leftPQ.poll();
                    fromLeft = true;
                } else {
                    pick = rightPQ.poll();
                    fromLeft = false;
                }
            }

            total += pick[0];

            if (fromLeft) {
                if (left <= right) {
                    leftPQ.offer(new int[]{costs[left], left});
                    left++;
                }
            } else {
                if (left <= right) {
                    rightPQ.offer(new int[]{costs[right], right});
                    right--;
                }
            }
        }

        return total;
    }
