public class Solution {
    public Solution() {
        // Constructor
    }

    public int[] sumPrefixScores(String[] words) {
        if (words == null || words.length == 0) {
            return new int[0];
        }

        // Build Trie
        int maxNodes = 1; // root
        for (String w : words) {
            maxNodes += w.length();
        }

        int[][] next = new int[maxNodes][26];
        int[] count = new int[maxNodes];
        for (int i = 0; i < maxNodes; i++) {
            Arrays.fill(next[i], -1);
        }

        int nodeCount = 1; // root is 0
        for (String w : words) {
            int node = 0;
            for (int i = 0; i < w.length(); i++) {
                int idx = w.charAt(i) - 'a';
                if (next[node][idx] == -1) {
                    next[node][idx] = nodeCount++;
                }
                node = next[node][idx];
                count[node]++; // increment count for this prefix
            }
        }

        // Compute answers
        int[] answer = new int[words.length];
        for (int i = 0; i < words.length; i++) {
            String w = words[i];
            int node = 0;
            int sum = 0;
            for (int j = 0; j < w.length(); j++) {
                int idx = w.charAt(j) - 'a';
                node = next[node][idx];
                sum += count[node];
            }
            answer[i] = sum;
        }
        return answer;
    }
}

