                bestId.put(creator, id);
            }
        }

        long maxTotal = 0;
        for (long v : totalViews.values()) {
            if (v > maxTotal) {
                maxTotal = v;
            }
        }

        List<List<String>> result = new ArrayList<>();
        for (String creator : totalViews.keySet()) {
            if (totalViews.get(creator) == maxTotal) {
                List<String> pair = new ArrayList<>();
                pair.add(creator);
                pair.add(bestId.get(creator));
                result.add(pair);
            }
        }

        return result;
    }
}

