public class Solution {
    public int destroyTargets(int[] nums, int space) {
        if (nums == null || nums.length == 0) {
            return 0;
        }

        // Map from residue to [count, minValue]
        Map<Integer, int[]> map = new HashMap<>();

        if (space == 0) {
            // Special case: only numbers equal to the seed can be destroyed
            for (int num : nums) {
                int[] entry = map.getOrDefault(num, new int[]{0, num});
                entry[0]++; // count
                // minValue is the number itself
                map.put(num, entry);
            }
        } else {
            for (int num : nums) {
                int residue = num % space;
                int[] entry = map.getOrDefault(residue, new int[]{0, num});
                entry[0]++; // count
                if (num < entry[1]) {
                    entry[1] = num; // update min value
                }
                map.put(residue, entry);
            }
        }

        int bestCount = -1;
        int bestSeed = Integer.MAX_VALUE;

        for (int[] entry : map.values()) {
            int count = entry[0];
            int seed = entry[1];
            if (count > bestCount || (count == bestCount && seed < bestSeed)) {
                bestCount = count;
                bestSeed = seed;
            }
        }

        return bestSeed;
    }
}

