public class Solution {
    public int destroyTargets(int[] nums, int space) {
        if (space == 0) {
            int min = Integer.MAX_VALUE;
            for (int v : nums) {
                if (v < min) min = v;
            }
            return min;
        }

        Map<Integer, List<Integer>> modMap = new HashMap<>();
        for (int num : nums) {
            int mod = num % space;
            modMap.computeIfAbsent(mod, k -> new ArrayList<>()).add(num);
        }

        for (List<Integer> list : modMap.values()) {
            Collections.sort(list);
        }

        int bestCount = -1;
        int bestSeed = Integer.MAX_VALUE;

        for (List<Integer> list : modMap.values()) {
            int size = list.size();
            for (int seed : list) {
                int idx = lowerBound(list, seed);
                int count = size - idx;
                if (count > bestCount || (count == bestCount && seed < bestSeed)) {
                    bestCount = count;
                    bestSeed = seed;
                }
            }
        }

        return bestSeed;
    }

    private int lowerBound(List<Integer> list, int target) {
        int lo = 0, hi = list.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (list.get(mid) < target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }
}

