                maxCount = count;
                bestSeed = seed;
            }
        }

        return bestSeed;
    }

    // Binary search for first index i such that list.get(i) >= target
    private int lowerBound(List<Integer> list, int target) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) >>> 1;
            if (list.get(mid) < target) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return low;
    }
}

