public class Solution {
    public int longestNiceSubarray(int[] nums) {
        int maxLen = 0;
        int mask = 0;
        int left = 0;
        for (int right = 0; right < nums.length; right++) {
            int val = nums[right];
            // If current number shares any bit with the current window, shrink window
            while ((mask & val) != 0) {
                int leftVal = nums[left];
                mask ^= leftVal; // remove bits of leftVal
