public class Solution {
    public int longestNiceSubarray(int[] nums) {
        int n = nums.length;
        int[] bitCount = new int[31];
        int duplicateBits = 0;
        int left = 0;
        int best = 0;

        for (int right = 0; right < n; right++) {
            int val = nums[right];
            for (int b = 0; b < 31; b++) {
                if (((val >> b) & 1) == 1) {
                    bitCount[b]++;
                    if (bitCount[b] == 2) {
                        duplicateBits++;
                    }
                }
            }

            while (duplicateBits > 0) {
                int leftVal = nums[left];
                for (int b = 0; b < 31; b++) {
                    if (((leftVal >> b) & 1) == 1) {
                        bitCount[b]--;
                        if (bitCount[b] == 1) {
                            duplicateBits--;
                        }
                    }
                }
                left++;
            }

            best = Math.max(best, right - left + 1);
        }

        return best;
    }
}

