public class Solution {
    public int longestNiceSubarray(int[] nums) {
        if (nums == null || nums.length == 0) return 0;
        int n = nums.length;
        int[] bitCnt = new int[31];
        int left = 0, best = 0;
        for (int right = 0; right < n; right++) {
            int val = nums[right];
            for (int b = 0; b < 31; b++) {
                if ((val & (1 << b)) != 0) bitCnt[b]++;
            }
            while (left <= right && !hasCommonBit(bitCnt, right - left + 1)) {
                int valL = nums[left];
                for (int b = 0; b < 31; b++) {
                    if ((valL & (1 << b)) != 0) bitCnt[b]--;
                }
                left++;
            }
            if (left <= right && hasCommonBit(bitCnt, right - left + 1)) {
                best = Math.max(best, right - left + 1);
            }
        }
        return best;
    }

    private boolean hasCommonBit(int[] bitCnt, int windowSize) {
        for (int c : bitCnt) {
            if (c == windowSize) return true;
        }
        return false;
    }
}

