public class Solution {
    public int longestNiceSubarray(int[] nums) {
        int n = nums.length;
        int[] bitCount = new int[32];
        int left = 0;
        int maxLen = 0;

        for (int right = 0; right < n; right++) {
            int num = nums[right];
            // update bit counts for the new element
            for (int bit = 0; bit < 32; bit++) {
                if (((num >> bit) & 1) == 1) {
                    bitCount[bit]++;
                }
            }

            // shrink the window while it violates the nice condition
            int windowSize = right - left + 1;
            while (hasBad(bitCount, windowSize)) {
                int leftNum = nums[left];
                for (int bit = 0; bit < 32; bit++) {
                    if (((leftNum >> bit) & 1) == 1) {
                        bitCount[bit]--;
                    }
                }
                left++;
                windowSize = right - left + 1;
            }

            // update maximum length
            if (windowSize > maxLen) {
                maxLen = windowSize;
            }
        }
        return maxLen;
    }

    // Helper method to determine if the current window violates the nice property
    private boolean hasBad(int[] bitCount, int windowSize) {
        for (int count : bitCount) {
            if (count > 1 && count < windowSize) {
                return true;
            }
        }
        return false;
    }
}

