                }
            }
            // shrink window until it becomes nice
            while (true) {
                int windowSize = right - left + 1;
                boolean invalid = false;
                for (int b = 0; b < 31; b++) {
                    if (bitCount[b] > 1 && bitCount[b] < windowSize) {
                        invalid = true;
                        break;
                    }
                }
                if (!invalid) {
                    break;
                }
                // remove bits of nums[left]
                int leftNum = nums[left];
                for (int b = 0; b < 31; b++) {
                    if (((leftNum >> b) & 1) == 1) {
                        bitCount[b]--;
                    }
                }
                left++;
            }
            int currentLen = right - left + 1;
            if (currentLen > maxLen) {
                maxLen = currentLen;
            }
        }
        return maxLen;
    }
