public class Solution {
    public long minimumFuelCost(int[][] roads, int seats) {
        int n = roads.length + 1;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] road : roads) {
            int a = road[0];
            int b = road[1];
            graph[a].add(b);
            graph[b].add(a);
        }

        int[] parent = new int[n];
        int[] order = new int[n];
        int idx = 0;
        Stack<Integer> stack = new Stack<>();
        stack.push(0);
        parent[0] = -1;

        while (!stack.isEmpty()) {
            int u = stack.pop();
            order[idx++] = u;
            for (int v : graph[u]) {
                if (v == parent[u]) continue;
                parent[v] = u;
                stack.push(v);
            }
        }

        long[] sub = new long[n];
        long answer = 0;
        for (int i = n - 1; i >= 0; i--) {
            int u = order[i];
            sub[u] = 1; // the representative of this city
            for (int v : graph[u]) {
                if (v == parent[u]) continue;
                sub[u] += sub[v];
            }
            if (u != 0) {
                long cars = (sub[u] + seats - 1) / seats;
                answer += cars;
            }
        }
        return answer;
    }
}

