        int m = nums2.length;

        int xor1 = 0;
        for (int v : nums1) xor1 ^= v;

        int xor2 = 0;
        for (int v : nums2) xor2 ^= v;

        if ((m & 1) == 0) { // m is even
            if ((n & 1) == 0) {
                return 0;
            } else {
                return xor2;
            }
        } else { // m is odd
            int result = xor1;
            if ((n & 1) == 1) {
                result ^= xor2;
            }
            return result;
        }
    }
}

