import java.util.ArrayList;
import java.util.List;
import java.util.PriorityQueue;

public class Solution {
    public int maxStarSum(int[] nodeValues, int[][] edges, int maxNumberOfEdges) {
        int n = nodeValues.length;
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            adj[u].add(v);
            adj[v].add(u);
        }

        long best = Long.MIN_VALUE;
        for (int i = 0; i < n; i++) {
            PriorityQueue<Integer> pq = new PriorityQueue<>(maxNumberOfEdges);
            long sumNeighbors = 0;
            for (int nb : adj[i]) {
                int val = nodeValues[nb];
                if (val > 0) {
                    pq.offer(val);
                    sumNeighbors += val;
                    if (pq.size() > maxNumberOfEdges) {
                        int removed = pq.poll();
                        sumNeighbors -= removed;
                    }
                }
            }
            long total = nodeValues[i] + sumNeighbors;
            if (total > best) {
                best = total;
            }
        }
        return (int) best;
    }
}

