import com_github_leetcode.TreeNode;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Solution {
    public int minimumOperations(TreeNode root) {
        if (root == null) return 0;
        int totalSwaps = 0;
        ArrayDeque<TreeNode> queue = new ArrayDeque<>();
        queue.offer(root);
        while (!queue.isEmpty()) {
            int levelSize = queue.size();
            List<Integer> values = new ArrayList<>(levelSize);
            for (int i = 0; i < levelSize; i++) {
                TreeNode node = queue.poll();
                values.add(node.val);
                if (node.left != null) queue.offer(node.left);
                if (node.right != null) queue.offer(node.right);
            }
            totalSwaps += minSwapsToSort(values);
        }
        return totalSwaps;
    }

    private int minSwapsToSort(List<Integer> values) {
        int n = values.size();
        if (n <= 1) return 0;
        List<Integer> sorted = new ArrayList<>(values);
        Collections.sort(sorted);
        // Map value to its sorted index
        java.util.Map<Integer, Integer> indexMap = new java.util.HashMap<>();
        for (int i = 0; i < n; i++) {
            indexMap.put(sorted.get(i), i);
        }
        int[] perm = new int[n];
        for (int i = 0; i < n; i++) {
            perm[i] = indexMap.get(values.get(i));
        }
        boolean[] visited = new boolean[n];
        int swaps = 0;
        for (int i = 0; i < n; i++) {
            if (visited[i] || perm[i] == i) continue;
            int cycleSize = 0;
            int j = i;
            while (!visited[j]) {
                visited[j] = true;
                j = perm[j];
                cycleSize++;
            }
            if (cycleSize > 0) swaps += cycleSize - 1;
        }
        return swaps;
    }
}

