public class Solution {
    private static final int MOD = 1_000_000_007;

    public int numberOfPaths(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;

        int[][] prev = new int[n][k];
        int[][] curr = new int[n][k];

        int startMod = mod(grid[0][0], k);
        prev[0][startMod] = 1;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (i == 0 && j == 0) {
                    continue; // already initialized
                }
                int valMod = mod(grid[i][j], k);
                for (int r = 0; r < k; r++) {
                    long count = 0;
                    if (i > 0) {
                        count += prev[j][r];
                    }
                    if (j > 0) {
                        count += curr[j - 1][r];
                    }
                    if (count == 0) continue;
                    int newMod = (r + valMod) % k;
                    curr[j][newMod] = (int) ((curr[j][newMod] + count) % MOD);
                }
            }
            // prepare for next row
            int[][] temp = prev;
            prev = curr;
            curr = temp;
            // reset curr for next use
            for (int j = 0; j < n; j++) {
                java.util.Arrays.fill(curr[j], 0);
            }
        }

        return prev[n - 1][0];
    }

    private int mod(int value, int k) {
        int res = value % k;
        if (res < 0) res += k;
        return res;
    }
}

