public class Solution {
    public int maxJump(int[] stones) {
        int n = stones.length;
        int maxConsecutive = 0;
        for (int i = 0; i < n - 1; i++) {
            int diff = stones[i + 1] - stones[i];
            if (diff > maxConsecutive) {
                maxConsecutive = diff;
            }
        }
        int maxTwoApart = 0;
        for (int i = 0; i < n - 2; i++) {
            int diff = stones[i + 2] - stones[i];
            if (diff > maxTwoApart) {
                maxTwoApart = diff;
            }
        }
        return Math.max(maxConsecutive, maxTwoApart);
    }
