import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int mostProfitablePath(int[][] edges, int bob, int[] amount) {
        int n = amount.length;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }

        int[] parent = new int[n];
        int[] depth = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = -1;
            depth[i] = -1;
        }

        // DFS from root to compute parent and depth
        dfsRoot(0, -1, 0, parent, depth, graph);

        int bobDepth = depth[bob];

        // Mark nodes on Bob's path to root
        boolean[] isBobPath = new boolean[n];
        int cur = bob;
        while (cur != -1) {
            isBobPath[cur] = true;
            cur = parent[cur];
        }

        Result res = new Result();
        dfsAlice(0, -1, 0L, amount, depth, bobDepth, isBobPath, graph, res);
        return (int) res.max;
    }

    private void dfsRoot(int node, int par, int d, int[] parent, int[] depth, List<Integer>[] graph) {
        parent[node] = par;
        depth[node] = d;
        for (int nb : graph[node]) {
            if (nb == par) continue;
            dfsRoot(nb, node, d + 1, parent, depth, graph);
        }
    }

    private void dfsAlice(int node, int par, long curSum, int[] amount, int[] depth,
                          int bobDepth, boolean[] isBobPath, List<Integer>[] graph, Result res) {
        long contrib;
        if (isBobPath[node]) {
            int aliceTime = depth[node];
            int bobTime = bobDepth - depth[node];
            if (aliceTime < bobTime) {
                contrib = amount[node];
            } else if (aliceTime > bobTime) {
                contrib = 0;
            } else {
                contrib = amount[node] / 2L;
            }
        } else {
            contrib = amount[node];
        }
        long newSum = curSum + contrib;

        boolean isLeaf = (node != 0 && graph[node].size() == 1) || (node == 0 && graph[node].size() == 0);
        if (isLeaf) {
            if (newSum > res.max) res.max = newSum;
        }

        for (int nb : graph[node]) {
            if (nb == par) continue;
            dfsAlice(nb, node, newSum, amount, depth, bobDepth, isBobPath, graph, res);
        }
    }

    private static class Result {
        long max = Long.MIN_VALUE;
    }
}

