import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Deque;
import java.util.List;
import java.util.Queue;
import java.util.LinkedList;

public class Solution {
    public int mostProfitablePath(int[][] edges, int bob, int[] amount) {
        int n = amount.length;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; ++i) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }

        int[] distA = bfs(0, graph, n);
        int[] distB = bfs(bob, graph, n);

        int maxIncome = Integer.MIN_VALUE;
        Deque<StackNode> stack = new ArrayDeque<>();
        stack.push(new StackNode(0, -1, 0));

        while (!stack.isEmpty()) {
            StackNode cur = stack.pop();
            int node = cur.node;
            int parent = cur.parent;
            int curProfit = cur.profit;

            int contribution = 0;
            if (distB[node] > distA[node]) {
                contribution = amount[node];
            } else if (distB[node] == distA[node]) {
                contribution = amount[node] / 2;
            } // else contribution stays 0

            curProfit += contribution;

            boolean isLeaf = (node != 0 && graph[node].size() == 1) || (node == 0 && graph[node].isEmpty());
            if (isLeaf) {
                if (curProfit > maxIncome) maxIncome = curProfit;
            }

            for (int nei : graph[node]) {
                if (nei == parent) continue;
                stack.push(new StackNode(nei, node, curProfit));
            }
        }

        return maxIncome;
    }

    private int[] bfs(int start, List<Integer>[] graph, int n) {
        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        Queue<Integer> q = new LinkedList<>();
        dist[start] = 0;
        q.offer(start);
        while (!q.isEmpty()) {
            int v = q.poll();
            for (int to : graph[v]) {
                if (dist[to] == -1) {
                    dist[to] = dist[v] + 1;
                    q.offer(to);
                }
            }
        }
        return dist;
    }

    private static class StackNode {
        int node;
        int parent;
        int profit;

        StackNode(int node, int parent, int profit) {
            this.node = node;
            this.parent = parent;
            this.profit = profit;
        }
    }
}

