public class Solution {
    public int mostProfitablePath(int[][] edges, int bob, int[] amount) {
        int n = amount.length;
        List<List<Integer>> g = new ArrayList<>(n);
        for (int i = 0; i < n; i++) g.add(new ArrayList<>());
        for (int[] e : edges) {
            g.get(e[0]).add(e[1]);
            g.get(e[1]).add(e[0]);
        }

        int[] parent = new int[n];
        Arrays.fill(parent, -1);
        dfsParent(0, -1, g, parent);

        int[] distBob = new int[n];
        Arrays.fill(distBob, -1);
        int dist = 0;
        int node = bob;
        while (node != 0) {
            distBob[node] = dist;
            node = parent[node];
            dist++;
        }
        distBob[0] = dist;

        long maxIncome = Long.MIN_VALUE;
        dfs(0, -1, 0, g, amount, distBob, maxIncomeHolder -> maxIncome = Math.max(maxIncome, maxIncomeHolder));
        return (int) maxIncome;
    }

    private void dfsParent(int u, int p, List<List<Integer>> g, int[] parent) {
        parent[u] = p;
        for (int v : g.get(u)) {
            if (v == p) continue;
            dfsParent(v, u, g, parent);
        }
    }

    private class ResultHolder {
        long value;
    }

    private void dfs(int u, int p, int depth, List<List<Integer>> g, int[] amount, int[] distBob, java.util.function.Consumer<Long> consumer) {
        long contrib = 0;
        if (distBob[u] == -1) {
            contrib = amount[u];
        } else {
            if (depth < distBob[u]) {
                contrib = amount[u];
            } else if (depth == distBob[u]) {
                contrib = amount[u] / 2;
            }
        }
        long sum = contrib;
        boolean isLeaf = (u != 0 && g.get(u).size() == 1);
        if (isLeaf) {
            consumer.accept(sum);
        } else {
            for (int v : g.get(u)) {
                if (v == p) continue;
                dfs(v, u, depth + 1, g, amount, distBob, consumer);
            }
        }
    }
}

