public class Solution {
    public int mostProfitablePath(int[][] edges, int bob, int[] amount) {
        int n = amount.length;
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(e[1]);
            adj[e[1]].add(e[0]);
        }
        int[] parent = new int[n];
        int[] depth = new int[n];
        Arrays.fill(parent, -1);
        dfs(0, -1, 0, adj, parent, depth);
        int[] timeBob = new int[n];
        int node = bob;
        int t = 0;
        while (node != -1) {
            timeBob[node] = t;
            node = parent[node];
            t++;
        }
        long[] best = new long[1];
        best[0] = Long.MIN_VALUE;
        dfsProfit(0, -1, 0, adj, parent, depth, timeBob, amount, best);
        return (int) best[0];
    }

    private void dfs(int cur, int par, int d, List<Integer>[] adj, int[] parent, int[] depth) {
        parent[cur] = par;
        depth[cur] = d;
        for (int nb : adj[cur]) {
            if (nb == par) continue;
            dfs(nb, cur, d + 1, adj, parent, depth);
        }
    }

    private void dfsProfit(int cur, int par, long curSum, List<Integer>[] adj, int[] parent, int[] depth,
                           int[] timeBob, int[] amount, long[] best) {
        if (timeBob[cur] == depth[cur]) {
            curSum += amount[cur] / 2L;
        } else if (timeBob[cur] > depth[cur]) {
            curSum += amount[cur];
        } // else timeBob < depth -> curSum unchanged
        boolean leaf = true;
        for (int nb : adj[cur]) {
            if (nb == par) continue;
            leaf = false;
            dfsProfit(nb, cur, curSum, adj, parent, depth, timeBob, amount, best);
        }
        if (leaf) best[0] = Math.max(best[0], curSum);
    }
}

