import java.util.*;

public class Solution {
    public int countTime(String time) {
        char[] arr = time.toCharArray();
        List<Integer> qPos = new ArrayList<>();
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] == '?') qPos.add(i);
        }
        int[] idx = qPos.stream().mapToInt(Integer::intValue).toArray();
        int n = idx.length;
        int[] digits = new int[n];
        int[] count = new int[1];
        dfs(0, n, idx, arr, digits, count);
        return count[0];
    }

    private void dfs(int pos, int n, int[] idx, char[] arr, int[] digits, int[] count) {
        if (pos == n) {
            if (isValid(arr)) count[0]++;
            return;
        }
        for (int d = 0; d <= 9; d++) {
            arr[idx[pos]] = (char) ('0' + d);
            dfs(pos + 1, n, idx, arr, digits, count);
        }
    }

    private boolean isValid(char[] arr) {
        int hour = (arr[0] - '0') * 10 + (arr[1] - '0');
        int minute = (arr[3] - '0') * 10 + (arr[4] - '0');
        return hour >= 0 && hour <= 23 && minute >= 0 && minute <= 59;
    }
}

