        int count = 0;
        for (int h = 0; h < 24; h++) {
            for (int m = 0; m < 60; m++) {
                String t = String.format("%02d:%02d", h, m);
                if (matches(time, t)) {
                    count++;
                }
            }
        }
        return count;
    }

    private boolean matches(String pattern, String candidate) {
        for (int i = 0; i < pattern.length(); i++) {
            char p = pattern.charAt(i);
            char c = candidate.charAt(i);
            if (p != '?' && p != c) {
                return false;
            }
        }
        return true;
    }
}

