public class Solution {
    public int maxPalindromes(String s, int k) {
        int n = s.length();
        if (n == 0 || k > n) return 0;

        // Precompute palindromic substrings of length >= k
        boolean[][] pal = new boolean[n][n];

        // Odd length palindromes
        for (int center = 0; center < n; center++) {
            int l = center, r = center;
            while (l >= 0 && r < n && s.charAt(l) == s.charAt(r)) {
                if (r - l + 1 >= k) pal[l][r] = true;
                l--;
                r++;
            }
        }

        // Even length palindromes
        for (int center = 0; center < n - 1; center++) {
            int l = center, r = center + 1;
            while (l >= 0 && r < n && s.charAt(l) == s.charAt(r)) {
                if (r - l + 1 >= k) pal[l][r] = true;
                l--;
                r++;
            }
        }

        // DP: dp[i] = max palindromes in prefix s[0..i-1]
        int[] dp = new int[n + 1];
        Arrays.fill(dp, 0);

        for (int end = 0; end < n; end++) {
            // carry over previous value
            dp[end + 1] = Math.max(dp[end + 1], dp[end]);

            // check all palindromes ending at 'end'
            for (int start = 0; start <= end; start++) {
                if (pal[start][end]) {
                    dp[end + 1] = Math.max(dp[end + 1], dp[start] + 1);
                }
            }
        }

        return dp[n];
    }
}

