public class Solution {
    public int maxPalindromes(String s, int k) {
        if (s == null || s.length() == 0 || k <= 0) return 0;
        int n = s.length();
        boolean[][] isPal = new boolean[n][n];
        // Precompute palindrome table
        for (int len = 1; len <= n; len++) {
            for (int i = 0; i + len - 1 < n; i++) {
                int j = i + len - 1;
                if (len == 1) {
                    isPal[i][j] = true;
                } else if (len == 2) {
                    isPal[i][j] = s.charAt(i) == s.charAt(j);
                } else {
                    isPal[i][j] = s.charAt(i) == s.charAt(j) && isPal[i + 1][j - 1];
                }
            }
        }

        int[] dp = new int[n];
        for (int i = 0; i < n; i++) {
            // carry forward previous best
            dp[i] = (i > 0) ? dp[i - 1] : 0;
            // try all palindromes ending at i with length >= k
            for (int start = Math.max(0, i - k + 1); start >= 0; start--) {
                if (isPal[start][i]) {
                    int prev = (start > 0) ? dp[start - 1] : 0;
                    dp[i] = Math.max(dp[i], prev + 1);
                }
            }
        }
        return dp[n - 1];
    }
}

