        if (k > n || k <= 0) return 0;

        int[] dp = new int[n + 1]; // dp[i] = max count using first i chars

        for (int center = 0; center < n; center++) {
            if (center > 0) {
                dp[center] = Math.max(dp[center], dp[center - 1]);
            }

            // Odd length palindromes
            int l = center, r = center;
            while (l >= 0 && r < n && s.charAt(l) == s.charAt(r)) {
                int len = r - l + 1;
                if (len >= k) {
                    dp[r + 1] = Math.max(dp[r + 1], dp[l] + 1);
                }
                l--;
                r++;
            }

            // Even length palindromes
            l = center;
            r = center + 1;
            while (l >= 0 && r < n && s.charAt(l) == s.charAt(r)) {
                int len = r - l + 1;
                if (len >= k) {
                    dp[r + 1] = Math.max(dp[r + 1], dp[l] + 1);
                }
                l--;
                r++;
            }
        }

        // Final propagation to handle positions without a chosen palindrome
        for (int i = 1; i <= n; i++) {
            dp[i] = Math.max(dp[i], dp[i - 1]);
        }

