            long[] primePrefix = new long[n + 1];
            for (int pos = 0; pos < n; pos++) {
                primePrefix[pos + 1] = primePrefix[pos];
                if (isPrimeDigit(s.charAt(pos))) {
                    primePrefix[pos + 1] += dpPrev[pos];
                    if (primePrefix[pos + 1] >= MOD) primePrefix[pos + 1] -= MOD;
