public class Solution {
    public long minCost(int[] nums, int[] cost) {
        int n = nums.length;
        // Pair nums and cost
        int[][] pairs = new int[n][2];
        for (int i = 0; i < n; i++) {
            pairs[i][0] = nums[i];
            pairs[i][1] = cost[i];
        }
        // Sort by nums
        Arrays.sort(pairs, Comparator.comparingInt(a -> a[0]));
        // Compute total cost weight
        long totalWeight = 0;
        for (int i = 0; i < n; i++) {
            totalWeight += pairs[i][1];
        }
        // Find weighted median
        long half = (totalWeight + 1) / 2; // ceil(totalWeight/2)
        long cumulative = 0;
        int median = pairs[0][0];
        for (int i = 0; i < n; i++) {
            cumulative += pairs[i][1];
            if (cumulative >= half) {
                median = pairs[i][0];
                break;
            }
        }
        // Compute total cost to move all to median
        long result = 0;
        for (int i = 0; i < n; i++) {
            result += Math.abs((long)pairs[i][0] - median) * pairs[i][1];
        }
        return result;
    }
}

