        for (int w : cost) totalWeight += w;
        long half = (totalWeight + 1) / 2;
        long cum = 0;
        int median = pairs[0][0];
        for (int[] p : pairs) {
            cum += p[1];
            if (cum >= half) {
                median = p[0];
                break;
            }
        }
        long result = 0;
        for (int[] p : pairs) {
            result += (long) Math.abs(p[0] - median) * p[1];
        }
