import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

public class Solution {

    public long minCost(int[] nums, int[] cost) {
        int n = nums.length;
        // Pair each number with its corresponding cost
        List<Pair> pairs = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            pairs.add(new Pair(nums[i], (long) cost[i]));
        }

        // Sort pairs by the value of nums
        Collections.sort(pairs, Comparator.comparingInt(p -> p.value));

        // Compute the total weight (sum of costs)
        long totalWeight = 0L;
        for (Pair p : pairs) {
            totalWeight += p.weight;
        }

        // Find weighted median
        long threshold = (totalWeight + 1) / 2; // ceil(totalWeight/2)
        long cumulative = 0L;
        int target = 0;
        for (Pair p : pairs) {
            cumulative += p.weight;
            if (cumulative >= threshold) {
                target = p.value;
                break;
            }
        }

        // Compute the minimal total cost to reach the target
        long result = 0L;
        for (Pair p : pairs) {
            result += p.weight * Math.abs((long) p.value - target);
        }

        return result;
    }

    private static class Pair {
        int value;
        long weight;

        Pair(int value, long weight) {
            this.value = value;
            this.weight = weight;
        }
    }
}

