import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int componentValue(int[] nums, int[][] edges) {
        int n = nums.length;
        if (n == 0) return 0;
        long total = 0;
        for (int v : nums) total += v;
        if (total == 0) return n - 1; // all components can be zero-sum

        // Build adjacency list
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(e[1]);
            adj[e[1]].add(e[0]);
        }

        // Find all divisors of total (possible number of components)
        List<Long> divisors = new ArrayList<>();
        for (long i = 1; i * i <= total; i++) {
            if (total % i == 0) {
                divisors.add(i);
                if (i != total / i) divisors.add(total / i);
            }
        }

        // Sort divisors descending to try largest k first
        divisors.sort((a, b) -> Long.compare(b, a));

        for (long kLong : divisors) {
            if (kLong > n) continue; // cannot have more components than nodes
            long target = total / kLong;
            int[] count = new int[1];
            if (dfs(0, -1, adj, nums, target, count)) {
                if (count[0] == kLong) {
                    return (int) (kLong - 1);
                }
            }
        }
        return 0; // fallback, should not happen
    }

    private boolean dfs(int node, int parent, List<Integer>[] adj, int[] nums,
                        long target, int[] count) {
        long sum = nums[node];
        for (int nei : adj[node]) {
            if (nei == parent) continue;
            if (!dfs(nei, node, adj, nums, target, count)) return false;
            sum += sumSubtree[nei];
        }
        if (sum == target) {
            count[0]++;
            sumSubtree[node] = 0; // cut here
        } else if (sum > target) {
            return false; // cannot form target
        } else {
            sumSubtree[node] = sum;
        }
        return true;
    }

    // Temporary array to store subtree sums during DFS
    private long[] sumSubtree;
    private boolean dfs(int node, int parent, List<Integer>[] adj, int[] nums,
                        long target, int[] count, long[] sumSubtree) {
        long sum = nums[node];
        for (int nei : adj[node]) {
            if (nei == parent) continue;
            if (!dfs(nei, node, adj, nums, target, count, sumSubtree)) return false;
            sum += sumSubtree[nei];
        }
        if (sum == target) {
            count[0]++;
            sumSubtree[node] = 0;
        } else if (sum > target) {
            return false;
        } else {
            sumSubtree[node] = sum;
        }
        return true;
    }

    // Wrapper to initialize sumSubtree array
    private boolean dfs(int node, int parent, List<Integer>[] adj, int[] nums,
                        long target, int[] count) {
        sumSubtree = new long[adj.length];
        return dfs(node, parent, adj, nums, target, count, sumSubtree);
    }
}

