import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int componentValue(int[] nums, int[][] edges) {
        int n = nums.length;
        List<Integer>[] g = new ArrayList[n];
        for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
        for (int[] e : edges) {
            g[e[0]].add(e[1]);
            g[e[1]].add(e[0]);
        }

        long total = 0;
        for (int v : nums) total += v;

        if (total == 0) {
            return countCuts(nums, g, 0);
        }

        long absTotal = Math.abs(total);
        List<Long> divisors = new ArrayList<>();
        for (long i = 1; i * i <= absTotal; i++) {
            if (absTotal % i == 0) {
                divisors.add(i);
                if (i != absTotal / i) divisors.add(absTotal / i);
            }
        }

        int maxCuts = 0;
        for (long d : divisors) {
            long target = total / d;
            int cuts = countCuts(nums, g, target);
            if (cuts == d - 1) {
                if (cuts > maxCuts) maxCuts = cuts;
            }
        }
        return maxCuts;
    }

    private int countCuts(int[] nums, List<Integer>[] g, long target) {
        int n = nums.length;
        long[] sum = new long[n];
        int[] stack = new int[n * 2];
        int[] parent = new int[n * 2];
        int[] state = new int[n * 2];
        int top = 0;
        stack[top] = 0;
        parent[top] = -1;
        state[top] = 0;
        top++;

        int cuts = 0;
        while (top > 0) {
            top--;
            int v = stack[top];
            int p = parent[top];
            int st = state[top];
            if (st == 0) {
                stack[top] = v;
                parent[top] = p;
                state[top] = 1;
                top++;
                for (int child : g[v]) {
                    if (child == p) continue;
                    stack[top] = child;
                    parent[top] = v;
                    state[top] = 0;
                    top++;
                }
            } else {
                long s = nums[v];
                for (int child : g[v]) {
                    if (child == p) continue;
                    s += sum[child];
                }
                if (v != 0 && s == target) {
                    cuts++;
                    sum[v] = 0;
                } else {
                    sum[v] = s;
                }
            }
        }
        return cuts;
    }
}

