import java.util.ArrayList;
import java.util.List;

public class Solution {
    private List<Integer>[] graph;
    private long[] values;
    private long componentSum;
    private int count;

    public int componentValue(int[] nums, int[][] edges) {
        int n = nums.length;
        graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            int a = e[0], b = e[1];
            graph[a].add(b);
            graph[b].add(a);
        }
        values = new long[n];
        long totalSum = 0;
        for (int i = 0; i < n; i++) {
            values[i] = nums[i];
            totalSum += values[i];
        }

        int maxDeleted = 0;

        // Candidate component sums
        if (totalSum == 0) {
            // handle S = 0 case
            componentSum = 0;
            count = 0;
            long remaining = dfs(0, -1);
            if (remaining == 0) {
                maxDeleted = Math.max(maxDeleted, count - 1);
            }
        } else {
            long absSum = Math.abs(totalSum);
            for (long d = 1; d * d <= absSum; d++) {
                if (absSum % d == 0) {
                    long[] candidates = new long[]{d, absSum / d};
                    for (long cand : candidates) {
                        componentSum = totalSum >= 0 ? cand : -cand;
                        count = 0;
                        long remaining = dfs(0, -1);
                        if (remaining == 0) {
                            long k = totalSum / componentSum; // number of components
                            if (count == k) {
                                maxDeleted = Math.max(maxDeleted, (int) (count - 1));
                            }
                        }
                    }
                }
            }
        }
        return maxDeleted;
    }

    private long dfs(int node, int parent) {
        long sum = values[node];
        for (int nb : graph[node]) {
            if (nb == parent) continue;
            long childSum = dfs(nb, node);
            if (childSum == componentSum) {
                count++;
                childSum = 0; // cut this subtree
            }
            sum += childSum;
        }
        if (sum == componentSum) {
            count++;
            return 0; // cut this subtree
        }
        return sum;
    }
}

