            // Check divisor d
            if (d <= n && total % d == 0) {
                long target = total / d;
                int components = 0;
                boolean valid = true;
                for (int i = n - 1; i >= 0; i--) {
                    int u = order[i];
                    long s = numsLong[u];
                    for (int v : adj[u]) {
                        if (v == parent[u]) continue;
                        s += sum[v];
                    }
                    if (s == target) {
                        components++;
                        sum[u] = 0;
                    } else {
                        sum[u] = s;
                    }
                }
                if (sum[0] != 0) valid = false;
                if (valid && components > maxComponents) maxComponents = components;
            }

            long other = absTotal / d;
            if (other != d && other <= n && total % other == 0) {
                long target = total / other;
                int components = 0;
                boolean valid = true;
                for (int i = n - 1; i >= 0; i--) {
