import java.util.*;

public class Solution {
    public int componentValue(int[] nums, int[][] edges) {
        int n = nums.length;
        if (n == 0) return 0;

        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            int a = e[0], b = e[1];
            graph[a].add(b);
            graph[b].add(a);
        }

        long[] sub = new long[n];
        int[] parent = new int[n];
        Arrays.fill(parent, -2);
        parent[0] = -1;

        int[] order = new int[n];
        int idx = 0;
        int[] stack = new int[n];
        int top = 0;
        stack[top++] = 0;

        while (top > 0) {
            int u = stack[--top];
            order[idx++] = u;
            for (int v : graph[u]) {
                if (parent[v] == -2) {
                    parent[v] = u;
                    stack[top++] = v;
                }
            }
        }

        for (int i = n - 1; i >= 0; i--) {
            int u = order[i];
            long sum = nums[u];
            for (int v : graph[u]) {
                if (parent[v] == u) {
                    sum += sub[v];
                }
            }
            sub[u] = sum;
        }

        long total = sub[0];
        if (total == 0) return n - 1;

        long absTotal = Math.abs(total);
        int maxCuts = 0;

        for (long d = 1; d * d <= absTotal; d++) {
            if (absTotal % d != 0) continue;

            long target = total > 0 ? d : -d;
            if (isFeasible(target, total, sub, n)) {
                int cuts = (int) (total / target - 1);
                if (cuts > maxCuts) maxCuts = cuts;
            }

            if (d * d != absTotal) {
                long d2 = absTotal / d;
                target = total > 0 ? d2 : -d2;
                if (isFeasible(target, total, sub, n)) {
                    int cuts = (int) (total / target - 1);
                    if (cuts > maxCuts) maxCuts = cuts;
                }
            }
        }

        return maxCuts;
    }

    private boolean isFeasible(long target, long total, long[] sub, int n) {
        int count = 0;
        for (int i = 1; i < n; i++) { // exclude root
            if (sub[i] == target) count++;
        }
        int components = (int) (total / target);
        return count == components - 1;
    }
}

