public class Solution {
    public long makeIntegerBeautiful(long n, int target) {
        long original = n;
        long sum = sumDigits(n);
        long pow = 1;
        while (sum > target) {
            long digit = (n / pow) % 10;
            long add = (10 - digit) * pow;
            n += add;
            pow *= 10;
            sum = sumDigits(n);
        }
        return n - original;
    }

    private long sumDigits(long num) {
        long sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        return sum;
    }
}

