public class Solution {
    public long makeIntegerBeautiful(long n, int target) {
        if (sumDigits(n) <= target) {
            return 0L;
        }

        long add = 0L;
        long power = 1L;

        while (sumDigits(n) > target) {
            int digit = (int) ((n / power) % 10);
            if (digit == 0) {
                power *= 10;
                continue;
            }
            long inc = power * (10 - digit);
            n += inc;
            add += inc;
            power *= 10;
        }

        return add;
    }

    private long sumDigits(long num) {
        long sum = 0L;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        return sum;
    }
}

