        while (tmp > 0) {
            sum += tmp % 10;
            tmp /= 10;
        }
        if (sum <= target) return 0;

        String s = Long.toString(n);
        int len = s.length();
        long lowerSum = 0;
        long pow10 = 1;

        for (int pos = 0; pos < len; pos++) {
            int digit = s.charAt(len - 1 - pos) - '0';
            if (digit != 9) {
                long newSum = sum - lowerSum + 1; // after incrementing this digit and zeroing lower ones
                if (newSum <= target) {
                    long newPrefix = (n / pow10) + 1;
                    long newNumber = newPrefix * pow10;
                    return newNumber - n;
                }
            }
            lowerSum += digit;
            pow10 *= 10;
        }

        // If no position was suitable, we need to go to the next power of 10
        return pow10 - n;
    }
}

