import java.util.*;

public class Solution {
    private static long[] pow10 = new long[20];
    static {
        pow10[0] = 1L;
        for (int i = 1; i < pow10.length; i++) {
            pow10[i] = pow10[i - 1] * 10L;
        }
    }

    private static int digitSum(long x) {
        int sum = 0;
        while (x > 0) {
            sum += (int)(x % 10);
            x /= 10;
        }
        return sum;
    }

    public long makeIntegerBeautiful(long n, int target) {
        if (digitSum(n) <= target) return 0L;
        long best = Long.MAX_VALUE;

        for (int i = 0; i < 18; i++) { // i from 0 to 17 inclusive
            long div = pow10[i + 1];
            if (div == 0) break; // overflow guard
            long inc = ((n / div) + 1) * div;
            if (inc < 0) break; // overflow guard
            if (digitSum(inc) <= target) {
                best = Math.min(best, inc - n);
            }
        }
        if (best == Long.MAX_VALUE) best = 0L; // fallback, should not happen
        return best;
    }
}

