import java.util.*;

public class Solution {
    public int minimizeArrayValue(int[] nums) {
        long total = 0;
        int maxVal = 0;
        for (int v : nums) {
            total += v;
            if (v > maxVal) maxVal = v;
        }
        long low = maxVal, high = total;
        while (low < high) {
            long mid = (low + high) / 2;
            if (can(mid, nums)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return (int) low;
    }

    private boolean can(long limit, int[] nums) {
        long sum = 0;
        for (int i = 0; i < nums.length; i++) {
            sum += nums[i];
            long capacity = limit * (i + 1);
            if (sum > capacity) return false;
        }
        return true;
    }
}

