import java.util.Map;

public class Solution {

    // Segment Tree for range maximum query and point update
    static class SegTree {
        private final int size;
        private final int[] tree;

        SegTree(int n) {
            size = 1;
            while (size < n) size <<= 1;
            tree = new int[size << 1];
        }

        // point update: set position pos to max(current, val)
        void update(int pos, int val) {
            pos += size;
            if (tree[pos] >= val) return;
            tree[pos] = val;
            for (pos >>= 1; pos > 0; pos >>= 1) {
                int newVal = Math.max(tree[pos << 1], tree[(pos << 1) | 1]);
                if (tree[pos] == newVal) break;
                tree[pos] = newVal;
            }
        }

        // range maximum query on inclusive [l, r]
        int query(int l, int r) {
            if (l > r) return 0;
            l += size;
            r += size;
            int res = 0;
            while (l <= r) {
                if ((l & 1) == 1) res = Math.max(res, tree[l++]);
                if ((r & 1) == 0) res = Math.max(res, tree[r--]);
                l >>= 1;
                r >>= 1;
            }
            return res;
        }
    }

    public int longestSubsequence(int[] nums, int k) {
        int n = nums.length;
        if (n == 0) return 0;

        // coordinate compression
        int[] sorted = nums.clone();
        Arrays.sort(sorted);
        int m = 0;
        for (int i = 0; i < n; i++) {
            if (i == 0 || sorted[i] != sorted[i - 1]) {
                sorted[m++] = sorted[i];
            }
        }
        sorted = Arrays.copyOf(sorted, m);
        Map<Integer, Integer> indexMap = new HashMap<>(m * 2);
        for (int i = 0; i < m; i++) {
            indexMap.put(sorted[i], i);
        }

        SegTree seg = new SegTree(m);
        int best = 0;

        for (int value : nums) {
            // Find left bound: first index with value >= value - k
            int leftVal = value - k;
            int left = lowerBound(sorted, leftVal);
            // Find right bound: last index with value <= value - 1
            int rightVal = value - 1;
            int right = upperBound(sorted, rightVal) - 1;

            int curr = 1;
            if (left <= right) {
                curr = 1 + seg.query(left, right);
            }
            int idx = indexMap.get(value);
            seg.update(idx, curr);
            if (curr > best) best = curr;
        }

        return best;
    }

    // Helper: first index >= target
    private int lowerBound(int[] arr, int target) {
        int l = 0, r = arr.length;
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (arr[mid] < target) l = mid + 1;
            else r = mid;
        }
        return l;
    }

    // Helper: first index > target
    private int upperBound(int[] arr, int target) {
        int l = 0, r = arr.length;
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (arr[mid] <= target) l = mid + 1;
            else r = mid;
        }
        return l;
    }
}

