import java.util.*;

public class Solution {
    public int numberOfGoodPaths(int[] vals, int[][] edges) {
        int n = vals.length;
        // Build adjacency list
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(e[1]);
            adj[e[1]].add(e[0]);
        }

        // Sort nodes by value
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, Comparator.comparingInt(i -> vals[i]));

        DSU dsu = new DSU(n);
        long ans = 0;
        int idx = 0;
        while (idx < n) {
            int val = vals[order[idx]];
            int start = idx;
            // Union edges where both ends have value <= val
            while (idx < n && vals[order[idx]] == val) {
                int u = order[idx];
                for (int v : adj[u]) {
                    if (vals[v] <= val) {
                        dsu.union(u, v);
                    }
                }
                idx++;
            }
            // Count nodes with current value in each component
            Map<Integer, Integer> compCount = new HashMap<>();
            for (int i = start; i < idx; i++) {
                int u = order[i];
                int root = dsu.find(u);
                compCount.put(root, compCount.getOrDefault(root, 0) + 1);
            }
            for (int cnt : compCount.values()) {
                ans += (long) cnt * (cnt + 1) / 2;
            }
        }
        return (int) ans;
    }

    // Disjoint Set Union (Union-Find)
    private static class DSU {
        int[] parent;
        int[] size;

        DSU(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int x) {
            if (parent[x] != x) parent[x] = find(parent[x]);
            return parent[x];
        }

        void union(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return;
            if (size[ra] < size[rb]) {
                int tmp = ra;
                ra = rb;
                rb = tmp;
            }
            parent[rb] = ra;
            size[ra] += size[rb];
        }
    }
}

