import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Collections;
import java.util.Comparator;
import java.util.Map;

public class Solution {
    public int numberOfGoodPaths(int[] vals, int[][] edges) {
        int n = vals.length;
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0], v = e[1];
            adj[u].add(v);
            adj[v].add(u);
        }

        int[] order = new int[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, Comparator.comparingInt(i -> vals[i]));

        int[] parent = new int[n];
        int[] size = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            size[i] = 1;
        }

        boolean[] processed = new boolean[n];
        long result = 0;
        HashMap<Integer, Integer> counter = new HashMap<>();

        int idx = 0;
        while (idx < n) {
            int currentVal = vals[order[idx]];
            int j = idx;
            // process all nodes with the same value
            while (j < n && vals[order[j]] == currentVal) {
                int node = order[j];
                // union with already processed neighbors
                for (int nei : adj[node]) {
                    if (processed[nei]) union(node, nei, parent, size);
                }
                processed[node] = true;
                j++;
            }
            // after unions, count occurrences per component
            for (int k = idx; k < j; k++) {
                int node = order[k];
                int root = find(node, parent);
                counter.put(root, counter.getOrDefault(root, 0) + 1);
            }
            // compute paths for this value
            for (int cnt : counter.values()) {
                result += (long) cnt * (cnt + 1) / 2;
            }
            counter.clear();
            idx = j;
        }
        return (int) result;
    }

    private int find(int x, int[] parent) {
        if (parent[x] != x) parent[x] = find(parent[x], parent);
        return parent[x];
    }

    private void union(int a, int b, int[] parent, int[] size) {
        int ra = find(a, parent);
        int rb = find(b, parent);
        if (ra == rb) return;
        if (size[ra] < size[rb]) {
            int tmp = ra; ra = rb; rb = tmp;
        }
        parent[rb] = ra;
        size[ra] += size[rb];
    }
}

