            adj[e[1]].add(e[0]);
        }

        // Nodes sorted by value
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, Comparator.comparingInt(i -> vals[i]));

        DSU dsu = new DSU(n);
        long ans = n; // single node paths

        int i = 0;
        while (i < n) {
            int val = vals[idx[i]];
            int j = i;
            while (j < n && vals[idx[j]] == val) j++;

            // Union edges where both ends <= val
            for (int k = i; k < j; k++) {
                int node = idx[k];
                for (int nb : adj[node]) {
                    if (vals[nb] <= val) {
                        dsu.union(node, nb);
                    }
                }
            }

            // Count nodes with current value per component
            Map<Integer,Integer> countMap = new HashMap<>();
            for (int k = i; k < j; k++) {
                int root = dsu.find(idx[k]);
                countMap.put(root, countMap.getOrDefault(root, 0) + 1);
            }

            // Add pairs within each component
            for (int cnt : countMap.values()) {
                ans += (long)cnt * (cnt - 1) / 2;
            }

            i = j;
        }
        return (int)ans;
    }

    private static class DSU {
        int[] parent;
        int[] size;

        DSU(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
