public class Solution {
    public int minimizeXor(int num1, int num2) {
        int k = Integer.bitCount(num2);
        int result = 0;
        int remaining = k;

        // First, try to set bits where num1 has 1, starting from the highest bit
        for (int i = 31; i >= 0 && remaining > 0; i--) {
            int mask = 1 << i;
            if ((num1 & mask) != 0) {
                result |= mask;
                remaining--;
            }
        }

        // If we still need more bits, set bits where num1 has 0, starting from the lowest bit
        for (int i = 0; i <= 31 && remaining > 0; i++) {
            int mask = 1 << i;
            if ((num1 & mask) == 0) {
                result |= mask;
                remaining--;
            }
        }

        return result;
    }
}

