                int[] dist = new int[n + 1];
                Arrays.fill(dist, -1);
                dist[start] = 0;
                dq.clear();
                dq.add(start);

                while (!dq.isEmpty()) {
                    int u = dq.pollFirst();
                    for (int v : adj[u]) {
                        if (dist[v] == -1) {
                            dist[v] = dist[u] + 1;
                            if (dist[v] > maxDist) {
                                maxDist = dist[v];
                                farthest = v;
                            }
                            dq.addLast(v);
                        }
                    }
                }

                Arrays.fill(dist, -1);
                dist[farthest] = 0;
                maxDist = 0;
                dq.clear();
                dq.add(farthest);

                while (!dq.isEmpty()) {
                    int u = dq.pollFirst();
                    for (int v : adj[u]) {
                        if (dist[v] == -1) {
                            dist[v] = dist[u] + 1;
                            if (dist[v] > maxDist) {
                                maxDist = dist[v];
                            }
                            dq.addLast(v);
                        }
                    }
                }

                totalGroups += maxDist + 1;
            }
        }

        return totalGroups;
    }
}

