            int start = meetings[i][0];
            int end = meetings[i][1];
            arr[i] = new Meeting(start, end);
        }
        Arrays.sort(arr, Comparator.comparingInt(m -> m.start));

        // Room counts
        int[] count = new int[n];

        // Available rooms (by room number)
        PriorityQueue<Integer> available = new PriorityQueue<>();
        for (int i = 0; i < n; i++) {
            available.offer(i);
        }

        // Busy rooms (by earliest end time)
        PriorityQueue<Room> busy = new PriorityQueue<>(Comparator.comparingLong(r -> r.end));

        for (Meeting m : arr) {
            // Free rooms that have finished by current start
            while (!busy.isEmpty() && busy.peek().end <= m.start) {
                Room finished = busy.poll();
                available.offer(finished.room);
            }

            if (!available.isEmpty()) {
                // Use the lowest-numbered available room
                int room = available.poll();
                long newEnd = m.start + m.duration;
                busy.offer(new Room(room, newEnd));
                count[room]++;
            } else {
                // All rooms busy; wait for the earliest finishing room
                Room earliest = busy.poll();
                long newStart = earliest.end;
                long newEnd = newStart + m.duration;
                busy.offer(new Room(earliest.room, newEnd));
                count[earliest.room]++;
