public class Solution {
    public int mostBooked(int n, int[][] meetings) {
        Arrays.sort(meetings, Comparator.comparingInt(a -> a[0]));
        int[] count = new int[n];

        PriorityQueue<Integer> free = new PriorityQueue<>();
        for (int i = 0; i < n; i++) {
            free.offer(i);
        }

        PriorityQueue<long[]> busy = new PriorityQueue<>(new Comparator<long[]>() {
            @Override
            public int compare(long[] a, long[] b) {
                int cmp = Long.compare(a[0], b[0]);
                if (cmp != 0) return cmp;
                return Long.compare(a[1], b[1]);
            }
        });

        for (int[] meet : meetings) {
            long start = meet[0];
            long end = meet[1];
            long duration = end - start;

            // Release rooms that became free before this meeting starts
            while (!busy.isEmpty() && busy.peek()[0] <= start) {
                int room = (int) busy.poll()[1];
                free.offer(room);
            }

            if (free.isEmpty()) {
                // Need to delay: wait until the earliest finishing room becomes free
                long earliestEnd = busy.peek()[0];
                while (!busy.isEmpty() && busy.peek()[0] <= earliestEnd) {
                    int room = (int) busy.poll()[1];
                    free.offer(room);
                }
                int chosenRoom = free.poll();
                long newStart = earliestEnd;
                long newEnd = newStart + duration;
                count[chosenRoom]++;
                busy.offer(new long[]{newEnd, chosenRoom});
            } else {
                int chosenRoom = free.poll();
                long newEnd = end; // same as original end
                count[chosenRoom]++;
                busy.offer(new long[]{newEnd, chosenRoom});
            }
        }

        int maxIdx = 0;
        for (int i = 1; i < n; i++) {
            if (count[i] > count[maxIdx]) {
                maxIdx = i;
            }
        }
        return maxIdx;
    }
}

