                if (val == minK) lastMin = i;
                if (val == maxK) lastMax = i;
                int validStart = Math.max(lastInvalid + 1, Math.min(lastMin, lastMax) + 1);
                if (lastMin > lastInvalid && lastMax > lastInvalid) {
                    result += Math.min(lastMin, lastMax) - lastInvalid;
                }
            }
        }
        return result;
    }
}

