public class Solution {
    private static final long MOD = 1_000_000_007L;

    public int[] productQueries(int n, int[][] queries) {
        // Build the powers array from the binary representation of n
        List<Long> powersList = new ArrayList<>();
        int pos = 0;
        int temp = n;
        while (temp > 0) {
            if ((temp & 1) == 1) {
                powersList.add(1L << pos);
            }
            temp >>= 1;
            pos++;
        }

        int m = powersList.size();
        long[] prefix = new long[m];
        if (m > 0) {
            prefix[0] = powersList.get(0) % MOD;
            for (int i = 1; i < m; i++) {
                prefix[i] = (prefix[i - 1] * (powersList.get(i) % MOD)) % MOD;
            }
        }

        int q = queries.length;
        int[] answers = new int[q];
        for (int i = 0; i < q; i++) {
            int left = queries[i][0];
            int right = queries[i][1];
            long prod;
            if (left == 0) {
                prod = prefix[right];
            } else {
                long inv = modInverse(prefix[left - 1], MOD);
                prod = (prefix[right] * inv) % MOD;
            }
            answers[i] = (int) prod;
        }
        return answers;
    }

    private long modInverse(long a, long mod) {
        return modPow(a, mod - 2, mod);
    }

    private long modPow(long base, long exp, long mod) {
        long result = 1L;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
}

