public class Solution {
    private static final int MOD = 1_000_000_007;

    public int[] productQueries(int n, int[][] queries) {
        // Convert n to list of exponents of set bits (powers of 2)
        List<Integer> exponents = new ArrayList<>();
        int idx = 0;
        int temp = n;
        while (temp > 0) {
            if ((temp & 1) == 1) {
                exponents.add(idx);
            }
            temp >>= 1;
            idx++;
        }

        int m = exponents.size();
        long[] prefix = new long[m + 1];
        prefix[0] = 0; // sum of exponents up to before first element
        for (int i = 0; i < m; i++) {
            prefix[i + 1] = prefix[i] + exponents.get(i);
        }

        int[] answers = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int left = queries[i][0];
            int right = queries[i][1];
            long sumExp = prefix[right + 1] - prefix[left];
            answers[i] = modPow(2, sumExp, MOD);
        }
        return answers;
    }

    private int modPow(long base, long exp, int mod) {
        long result = 1;
        long b = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * b) % mod;
            }
            b = (b * b) % mod;
            exp >>= 1;
        }
        return (int) result;
    }
}

