public class Solution {
    public long minimumMoney(int[][] transactions) {
        int n = transactions.length;
        long[] dp = new long[n];
        for (int i = 0; i < n; i++) dp[i] = Long.MAX_VALUE;
        dp[0] = 0;

        Arrays.sort(transactions, new Comparator<int[]>() {
            public int compare(int[] a, int[] b) {
                return Integer.compare(b[1] - a[1], b[1] - a[1]); // sort by (cashback - cost) descending
            }
        });

        long current = 0;
        long maxDeficit = 0;
        for (int i = 0; i < n; i++) {
            int cost = transactions[i][0];
            int cashback = transactions[i][1];
            current += cashback;
            long deficit = (long) cost - current;
            if (deficit > maxDeficit) maxDeficit = deficit;
            dp[i] = Math.max(dp[i], dp[i - 1] + 1);
        }
        return Math.max(maxDeficit, 0);
    }
}

