public class Solution {
    public int[] secondGreaterElement(int[] nums) {
        int n = nums.length;
        int[] next = new int[n];
        Arrays.fill(next, -1);
        Deque<Integer> stack = new ArrayDeque<>();

        // Compute nearest greater element to the right for each index
        for (int i = n - 1; i >= 0; i--) {
            while (!stack.isEmpty() && nums[stack.peek()] <= nums[i]) {
                stack.pop();
            }
            if (!stack.isEmpty()) {
                next[i] = stack.peek();
            }
            stack.push(i);
        }

        // Determine the second greater element using the precomputed next array
        int[] result = new int[n];
        for (int i = 0; i < n; i++) {
            int firstGreaterIdx = next[i];
            if (firstGreaterIdx != -1 && next[firstGreaterIdx] != -1) {
                result[i] = nums[next[firstGreaterIdx]];
            } else {
                result[i] = -1;
            }
        }
        return result;
    }
}

