import java.util.ArrayDeque;
import java.util.Deque;

public class Solution {
    public int[] secondGreaterElement(int[] nums) {
        int n = nums.length;
        int[] answer = new int[n];
        // initialize all answers to -1
        for (int i = 0; i < n; i++) {
            answer[i] = -1;
        }

        Deque<Integer> firstGreaterStack = new ArrayDeque<>();
        Deque<Integer> waitingForSecondStack = new ArrayDeque<>();

        for (int i = 0; i < n; i++) {
            int currentVal = nums[i];

            // Assign current element as second greater for all waiting indices
            while (!waitingForSecondStack.isEmpty() && nums[waitingForSecondStack.peek()] < currentVal) {
                int idx = waitingForSecondStack.pop();
                answer[idx] = currentVal;
            }

            // Find first greater for indices in firstGreaterStack
            while (!firstGreaterStack.isEmpty() && nums[firstGreaterStack.peek()] < currentVal) {
                int idx = firstGreaterStack.pop();
                waitingForSecondStack.push(idx);
            }

            // Current index is now waiting for its first greater
            firstGreaterStack.push(i);
        }

        return answer;
    }
}

