        Arrays.fill(ans, -1);

        Deque<Integer> first = new ArrayDeque<>();   // indices waiting for their first greater element
        Deque<Integer> second = new ArrayDeque<>();  // indices waiting for their second greater element

        for (int i = 0; i < n; i++) {
            // Resolve second greater elements first
            while (!second.isEmpty() && nums[i] > nums[second.peek()]) {
                int idx = second.pop();
                ans[idx] = nums[i];
