            // Move indices from first stack to second stack when we find their first greater
            while (!first.isEmpty() && nums[i] > nums[first.peek()]) {
                second.push(first.pop());
            }

            // Current index is waiting for its first greater
            first.push(i);
        }

        return ans;
    }
}

