    private boolean matchesAny(String word, String[] dictionary) {
        for (String dictWord : dictionary) {
            if (hammingDistance(word, dictWord) <= 2) {
                return true;
            }
        }
        return false;
    }

    /**
     * Computes the Hamming distance between two strings of equal length.
     * Assumes both strings are non-null and of the same length.
     */
    private int hammingDistance(String a, String b) {
        int dist = 0;
        for (int i = 0; i < a.length(); i++) {
            if (a.charAt(i) != b.charAt(i)) {
                dist++;
                if (dist > 2) { // early exit
                    return dist;
                }
            }
        }
        return dist;
    }
