public class Solution {
    public boolean sumOfNumberAndReverse(int num) {
        final int MAX_DIGITS = 10; // int max has 10 digits
        for (int len = 1; len <= MAX_DIGITS; len++) {
            int half = (len + 1) / 2;
            int combos = 1;
            for (int i = 0; i < half; i++) combos *= 10;

            for (int mask = 0; mask < combos; mask++) {
                int[] halfDigits = new int[half];
                int tmp = mask;
                for (int i = 0; i < half; i++) {
                    halfDigits[i] = tmp % 10;
                    tmp /= 10;
                }

                int[] digits = new int[len];
                for (int i = 0; i < half; i++) {
                    digits[i] = halfDigits[i];
                    digits[len - 1 - i] = halfDigits[i];
                }

                long carry = 0;
                long sum = 0;
                long pow = 1;
                for (int pos = 0; pos < len; pos++) {
                    long cur = digits[pos] + digits[len - 1 - pos] + carry;
                    sum += (cur % 10) * pow;
                    carry = cur / 10;
                    pow *= 10;
                }
                if (carry > 0) {
                    sum += carry * pow;
                }

                if (sum == num) {
                    return true;
                }
            }
        }
        return false;
    }
}

