            int f = freqMap.keySet().iterator().next();
            int count = freqMap.get(f);
            if (count == 1 && f == 1) {
                // only one letter occurring once
                return false;
            }
            if (f == 1) {
                // multiple letters each occurring once
                return true;
            }
            if (count == 1) {
                // only one type of letter, any frequency > 1
                return true;
            }
            return false;
        } else if (freqMap.size() == 2) {
            int[] keys = new int[2];
            int[] values = new int[2];
            int idx = 0;
            for (Map.Entry<Integer, Integer> e : freqMap.entrySet()) {
                keys[idx] = e.getKey();
                values[idx] = e.getValue();
                idx++;
            }

            // Check if there is a frequency of 1 that appears only once
            if ((keys[0] == 1 && values[0] == 1) || (keys[1] == 1 && values[1] == 1)) {
                return true;
            }

            int lowF = Math.min(keys[0], keys[1]);
            int highF = Math.max(keys[0], keys[1]);
            int lowC = (keys[0] == lowF) ? values[0] : values[1];
            int highC = (keys[0] == highF) ? values[0] : values[1];

            if (highF - lowF == 1 && highC == 1) {
                return true;
            }
            return false;
        } else {
            return false;
        }
    }
}

