import java.util.*;

public class Solution {
    public int countPalindromes(String s) {
        final long MOD = 1_000_000_007L;
        int n = s.length();
        if (n == 0) return 0;

        // next occurrence of the same digit after position i
        int[] nextPos = new int[n];
        int[] lastNext = new int[10];
        Arrays.fill(lastNext, -1);
        for (int i = n - 1; i >= 0; i--) {
            int d = s.charAt(i) - '0';
            nextPos[i] = lastNext[d];
            lastNext[d] = i;
        }

        // previous occurrence of the same digit before position j
        int[] prevPos = new int[n];
        int[] lastPrev = new int[10];
        Arrays.fill(lastPrev, -1);
        for (int i = 0; i < n; i++) {
            int d = s.charAt(i) - '0';
            prevPos[i] = lastPrev[d];
            lastPrev[d] = i;
        }

        long[][] dp = new long[n][n];
        for (int i = 0; i < n; i++) {
            dp[i][i] = 1; // single character
        }

        for (int len = 2; len <= n; len++) {
            for (int i = 0; i + len - 1 < n; i++) {
                int j = i + len - 1;
                if (s.charAt(i) != s.charAt(j)) {
                    long val = (dp[i + 1][j] + dp[i][j - 1] - dp[i + 1][j - 1]) % MOD;
                    if (val < 0) val += MOD;
                    dp[i][j] = val;
                } else {
                    int nextI = nextPos[i];
                    int prevJ = prevPos[j];
                    long inside = 0;
                    if (i + 1 <= j - 1) inside = dp[i + 1][j - 1];

                    if (nextI == -1 || nextI > j) {
                        // no same digit inside
                        dp[i][j] = (inside * 2 + 2) % MOD;
                    } else if (nextI == prevJ) {
                        // exactly one same digit inside
                        dp[i][j] = (inside * 2 + 1) % MOD;
                    } else {
                        // multiple same digits inside
                        long sub = 0;
                        if (nextI + 1 <= prevJ - 1) sub = dp[nextI + 1][prevJ - 1];
                        long val = (inside * 2 - sub) % MOD;
                        if (val < 0) val += MOD;
                        dp[i][j] = val;
                    }
                }
            }
        }

        return (int) (dp[0][n - 1] % MOD);
    }
}

