import java.util.*;

public class Solution {
    public int countPalindromes(String s) {
        final int MOD = 1_000_000_007;
        int n = s.length();
        if (n == 0) return 0;

        int[] next = new int[n];
        int[] prev = new int[n];
        Map<Character, Integer> last = new HashMap<>();

        // next occurrence
        for (int i = n - 1; i >= 0; i--) {
            char c = s.charAt(i);
            next[i] = last.getOrDefault(c, n);
            last.put(c, i);
        }

        // previous occurrence
        last.clear();
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            prev[i] = last.getOrDefault(c, -1);
            last.put(c, i);
        }

        long[][] dp = new long[n][n];

        for (int len = 1; len <= n; len++) {
            for (int i = 0; i + len - 1 < n; i++) {
                int j = i + len - 1;
                if (i == j) {
                    dp[i][j] = 1;
                    continue;
                }
                if (s.charAt(i) != s.charAt(j)) {
                    long val = dp[i + 1][j] + dp[i][j - 1] - dp[i + 1][j - 1];
                    val %= MOD;
                    if (val < 0) val += MOD;
                    dp[i][j] = val;
                } else {
                    int ni = next[i];
                    int pj = prev[j];
                    if (ni > pj) { // no same char inside
                        long val = (dp[i + 1][j - 1] * 2 + 2) % MOD;
                        dp[i][j] = val;
                    } else if (ni == pj) { // only one same char inside
                        long val = (dp[i + 1][j - 1] * 2 + 1) % MOD;
                        dp[i][j] = val;
                    } else { // at least two same chars inside
                        long inner = 0;
                        if (ni + 1 <= pj - 1) {
                            inner = dp[ni + 1][pj - 1];
                        }
                        long val = (dp[i + 1][j - 1] * 2 - inner) % MOD;
                        if (val < 0) val += MOD;
                        dp[i][j] = val;
                    }
                }
            }
        }
        return (int) dp[0][n - 1];
    }
}

