public class Solution {
    public String[] splitMessage(String message, int limit) {
        int n = message.length();
        int max = n + 1;
        int[] digits = new int[max + 1];
        for (int i = 1; i <= max; i++) {
            digits[i] = Integer.toString(i).length();
        }

        for (int b = 1; b <= n + 1; b++) {
            int suffixLenLast = 2 + digits[b] + digits[b];
            int contentLenLast = limit - suffixLenLast;
            if (contentLenLast < 0) continue;

            long sumFirst = 0;
            boolean ok = true;
            for (int i = 1; i < b; i++) {
                int suffixLen = 2 + digits[i] + digits[b];
                int contentLen = limit - suffixLen;
                if (contentLen < 0) {
                    ok = false;
                    break;
                }
                sumFirst += contentLen;
            }
            if (!ok) continue;

            long remaining = n - sumFirst;
            if (remaining < 0) continue;
            if (remaining <= contentLenLast) {
                String[] parts = new String[b];
                int pos = 0;
                for (int i = 1; i < b; i++) {
                    int suffixLen = 2 + digits[i] + digits[b];
                    int contentLen = limit - suffixLen;
                    String content = message.substring(pos, pos + contentLen);
                    pos += contentLen;
                    parts[i - 1] = content + "<" + i + "/" + b + ">";
                }
                int contentLen = (int) remaining;
                String content = message.substring(pos, pos + contentLen);
                parts[b - 1] = content + "<" + b + "/" + b + ">";
