public class Solution {
    public String[] splitMessage(String message, int limit) {
        int n = message.length();
        if (n == 0) return new String[0];
        int maxK = n + 1; // upper bound for number of parts
        // Precompute digits count and prefix sums up to maxK
        int[] digits = new int[maxK + 1];
        long[] prefixDigits = new long[maxK + 1];
        for (int i = 1; i <= maxK; i++) {
            int d = 0;
            int x = i;
            while (x > 0) { d++; x /= 10; }
            digits[i] = d;
            prefixDigits[i] = prefixDigits[i - 1] + d;
        }

        int minK = (n + limit - 1) / limit; // lower bound
        int bestK = -1;
        for (int k = minK; k <= maxK; k++) {
            int dK = digits[k];
            int maxDPrev = digits[k - 1];
            // Check if any suffix exceeds limit
            if (3 + maxDPrev + dK > limit) continue;
            if (3 + 2 * dK > limit) continue; // last part suffix too long

            long sumFirst = (long) (k - 1) * (limit - 3 - dK) - prefixDigits[k - 1];
            if (sumFirst < 0) continue;

            long lastContent = (long) n - sumFirst;
            long lastLenAllowed = limit - (3 + dK + dK);
            if (lastContent < 0 || lastContent > lastLenAllowed) continue;

            bestK = k;
            break;
        }

        if (bestK == -1) return new String[0];

        String[] result = new String[bestK];
        int dK = digits[bestK];
        int pos = 0;
        for (int i = 1; i <= bestK; i++) {
            int suffixLen = 3 + digits[i] + dK;
            int contentLen;
            if (i < bestK) {
                contentLen = limit - suffixLen;
            } else {
                contentLen = (int) ((long) n - 
                        ((long) (bestK - 1) * (limit - 3 - dK) - prefixDigits[bestK - 1]));
            }
            String partContent = message.substring(pos, pos + contentLen);
            String suffix = "<" + i + "/" + bestK + ">";
            result[i - 1] = partContent + suffix;
            pos += contentLen;
        }
        return result;
    }
}

