            int[] suffixLen = new int[k + 1]; // 1-indexed
            for (int i = 1; i <= k; i++) {
                suffixLen[i] = 2 + digits(i) + digits(k);
            }

            boolean ok = true;
            long sumBefore = 0;
            for (int i = 1; i <= k - 1; i++) {
                int contentLen = limit - suffixLen[i];
                if (contentLen < 1) { ok = false; break; }
                sumBefore += contentLen;
                if (sumBefore > n) { ok = false; break; }
            }
            if (!ok) continue;
            long lastContent = n - sumBefore;
            if (lastContent < 1) continue;
            if (lastContent > limit - suffixLen[k]) continue;
            // feasible
            List<String> parts = new ArrayList<>();
            int idx = 0;
            for (int i = 1; i <= k - 1; i++) {
