            String content = message.substring(idx, idx + contentLen);
            idx += contentLen;
            parts.add(content + "<" + i + "/" + b + ">");
        }

        // Last part
        int remaining = n - idx;
        int suffixLenLast = digitsB + digitsB + 3;
        String contentLast = message.substring(idx);
        parts.add(contentLast + "<" + b + "/" + b + ">");

        return parts.toArray(new String[0]);
