import java.util.*;

public class Solution {
    private static int digits(int x) {
        return String.valueOf(x).length();
    }

    private static int suffixLen(int i, int b) {
        return digits(i) + digits(b) + 3; // "<i/b>"
    }

    private static boolean feasible(String msg, int limit, int b) {
        int n = msg.length();
        long sumCap = 0;
        for (int i = 1; i <= b; i++) {
            int sl = suffixLen(i, b);
            if (limit < sl) return false;
            sumCap += (long)limit - sl;
        }
        return n <= sumCap;
    }

    private static String[] build(String msg, int limit, int b) {
        int n = msg.length();
        int[] maxContent = new int[b + 1];
        for (int i = 1; i <= b; i++) {
            maxContent[i] = limit - suffixLen(i, b);
        }
        int lastCap = maxContent[b];
        int minBeforeLast = Math.max(0, n - lastCap);

        int[] content = new int[b + 1];
        int remaining = minBeforeLast;
        for (int i = 1; i <= b - 1; i++) {
            int take = Math.min(maxContent[i], remaining);
            content[i] = take;
            remaining -= take;
        }
        // any remaining needed capacity must be distributed among first b-1 parts
        if (remaining > 0) {
            for (int i = 1; i <= b - 1 && remaining > 0; i++) {
                int can = maxContent[i] - content[i];
                int add = Math.min(can, remaining);
                content[i] += add;
                remaining -= add;
            }
        }
        int sumAssigned = 0;
        for (int i = 1; i <= b - 1; i++) sumAssigned += content[i];
        content[b] = n - sumAssigned;

        String[] res = new String[b];
        int pos = 0;
        for (int i = 1; i <= b; i++) {
            int len = content[i];
            String part = (len > 0 ? msg.substring(pos, pos + len) : "") + "<" + i + "/" + b + ">";
            res[i - 1] = part;
            pos += len;
        }
        return res;
    }

    public String[] splitMessage(String message, int limit) {
        int n = message.length();
        if (n == 0) {
            // Special case: empty message
            if (limit < suffixLen(1, 1)) return new String[0];
            return new String[]{"<1/1>"};
        }

        int low = 1, high = n;
        int best = -1;
        while (low <= high) {
            int mid = (low + high) >>> 1;
            if (feasible(message, limit, mid)) {
                best = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        if (best == -1) return new String[0];
        return build(message, limit, best);
    }
}

