        int[][] counts = new int[numPrimes][];
        for (int idx = 0; idx < numPrimes; idx++) {
            counts[idx] = new int[targetExp.get(idx) + 1];
        }
        int[] currentMaxExp = new int[numPrimes];
        int satisfiedCount = 0;
        long ans = 0;
        int l = 0;

        for (int r = 0; r < n; r++) {
            if (!valid[r]) {
                // reset window
                l = r + 1;
                Arrays.fill(currentMaxExp, 0);
                satisfiedCount = 0;
                for (int idx = 0; idx < numPrimes; idx++) {
                    Arrays.fill(counts[idx], 0);
                }
                continue;
            }

            // add element at r
            for (int idx = 0; idx < numPrimes; idx++) {
                int e = exps[r][idx];
                counts[idx][e]++;
                if (e > currentMaxExp[idx]) {
                    int old = currentMaxExp[idx];
                    currentMaxExp[idx] = e;
                    if (e == targetExp.get(idx) && old < targetExp.get(idx)) {
                        satisfiedCount++;
                    }
                }
            }

            // count subarrays ending at r
            while (satisfiedCount == numPrimes) {
                ans++;
                // remove leftmost element
                for (int idx = 0; idx < numPrimes; idx++) {
                    int e = exps[l][idx];
                    counts[idx][e]--;
                    if (e == currentMaxExp[idx] && counts[idx][e] == 0) {
                        int newMax = 0;
                        for (int exp = targetExp.get(idx); exp >= 0; exp--) {
                            if (counts[idx][exp] > 0) {
                                newMax = exp;
                                break;
                            }
                        }
                        if (currentMaxExp[idx] == targetExp.get(idx) && newMax < targetExp.get(idx)) {
                            satisfiedCount--;
                        }
                        currentMaxExp[idx] = newMax;
                    }
                }
                l++;
            }
        }

        return (int) ans;
    }
}

