import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int subarrayLCM(int[] nums, int k) {
        long result = 0;
        Map<Long, Long> prev = new HashMap<>();
        for (int num : nums) {
            if (k % num != 0) {
                prev.clear();
                continue;
            }
            Map<Long, Long> cur = new HashMap<>();
            long val = num;
            cur.put(val, cur.getOrDefault(val, 0L) + 1);
            if (val == k) result++;
            for (Map.Entry<Long, Long> e : prev.entrySet()) {
                long l = e.getKey();
                long cnt = e.getValue();
                long newL = lcm(l, val);
                if (newL == k) {
                    result += cnt;
                }
                if (newL <= k) {
                    cur.put(newL, cur.getOrDefault(newL, 0L) + cnt);
                }
            }
            prev = cur;
        }
        return (int) result;
    }

    private long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    private long lcm(long a, long b) {
        return a / gcd(a, b) * b;
    }
}

