            for (int j = i; j < n; j++) {
                long g = gcd(lcm, nums[j]);
                long div = lcm / g;
                // Check for overflow and whether lcm will exceed K
                if (div > K / nums[j]) {
                    lcm = K + 1; // mark as exceeding K
                } else {
                    lcm = div * nums[j];
