        Set<Integer> window = new HashSet<>();
        long sum = 0;
        long maxSum = -1;
        int left = 0;

        for (int right = 0; right < nums.length; right++) {
            // Remove elements until duplicate is resolved
            while (window.contains(nums[right])) {
                window.remove(nums[left]);
                sum -= nums[left];
                left++;
            }

            // Add current element
            window.add(nums[right]);
            sum += nums[right];

            // If window size exceeds k, shrink from left
            if (right - left + 1 > k) {
                window.remove(nums[left]);
                sum -= nums[left];
                left++;
            }

            // Record max sum when window size equals k
            if (right - left + 1 == k) {
                maxSum = Math.max(maxSum, sum);
            }
        }

        return maxSum;
    }
}

