public class Solution {
    public String robotWithString(String s) {
        if (s == null || s.isEmpty()) {
            return "";
        }
        int n = s.length();
        char[] chars = s.toCharArray();
        char[] minRem = new char[n + 1];
        minRem[n] = Character.MAX_VALUE;
        for (int i = n - 1; i >= 0; i--) {
            minRem[i] = (char) Math.min(chars[i], minRem[i + 1]);
        }

        Deque<Character> stack = new ArrayDeque<>();
        StringBuilder result = new StringBuilder();

        for (int i = 0; i < n; i++) {
            stack.push(chars[i]);
            while (!stack.isEmpty() && stack.peek() <= minRem[i + 1]) {
                result.append(stack.pop());
            }
        }

        while (!stack.isEmpty()) {
            result.append(stack.pop());
        }

        return result.toString();
    }
}

