public class Solution {
    public String robotWithString(String s) {
        int n = s.length();
        int[] freq = new int[26];
        for (int i = 0; i < n; i++) {
            freq[s.charAt(i) - 'a']++;
        }

        StringBuilder t = new StringBuilder();
        StringBuilder out = new StringBuilder();

        int pos = 0; // next index to take from s
        int minIdx = 0;
        while (pos < n || t.length() > 0) {
            // update minIdx to smallest remaining character in s
            while (minIdx < 26 && freq[minIdx] == 0) {
                minIdx++;
            }

            char minRemaining = minIdx < 26 ? (char) ('a' + minIdx) : 0;

            if (t.length() == 0) {
                // must push
                char c = s.charAt(pos);
                freq[c - 'a']--;
                t.append(c);
                pos++;
            } else {
                char top = t.charAt(t.length() - 1);
                if (minIdx == 26 || top <= minRemaining) {
                    // pop to output
                    t.setLength(t.length() - 1);
                    out.append(top);
                } else {
                    // push next from s
                    if (pos < n) {
                        char c = s.charAt(pos);
                        freq[c - 'a']--;
                        t.append(c);
                        pos++;
                    } else {
                        // no more to push, must pop
                        t.setLength(t.length() - 1);
                        out.append(top);
                    }
                }
            }
        }

        return out.toString();
    }
}

