            prev.next = null;
        }

        // Reverse the list again to restore original order
        curr = newHead;
        rev = null;
        while (curr != null) {
            ListNode next = curr.next;
            curr.next = rev;
            rev = curr;
            curr = next;
        }

        return rev;
    }
}

