import com_github_leetcode.ListNode;

public class Solution {
    public ListNode removeNodes(ListNode head) {
        if (head == null) return null;

        // Reverse the list
        ListNode prev = null;
        ListNode curr = head;
        while (curr != null) {
            ListNode next = curr.next;
            curr.next = prev;
            prev = curr;
            curr = next;
        }
        ListNode reversed = prev;

        // Build new list keeping nodes that are >= max so far
        ListNode newHead = null;
        ListNode newTail = null;
        int max = Integer.MIN_VALUE;
        curr = reversed;
        while (curr != null) {
            if (curr.val >= max) {
                max = curr.val;
                ListNode newNode = new ListNode(curr.val);
                if (newHead == null) {
                    newHead = newNode;
                    newTail = newNode;
                } else {
                    newTail.next = newNode;
                    newTail = newNode;
                }
            }
            curr = curr.next;
        }

        // Reverse again to restore original order
        prev = null;
        curr = newHead;
        while (curr != null) {
            ListNode next = curr.next;
            curr.next = prev;
            prev = curr;
            curr = next;
        }
        return prev;
    }
}

