import com_github_leetcode.ListNode;
import java.util.ArrayDeque;
import java.util.Deque;

public class Solution {
    public ListNode removeNodes(ListNode head) {
        if (head == null) return null;

        // Push all nodes onto a stack to process from the end
        Deque<ListNode> stack = new ArrayDeque<>();
        ListNode cur = head;
        while (cur != null) {
            stack.push(cur);
            cur = cur.next;
        }

        // Build the result list by keeping nodes that are not smaller than any node to their right
        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;
        int maxVal = Integer.MIN_VALUE;

        while (!stack.isEmpty()) {
            ListNode node = stack.pop();
            if (node.val >= maxVal) {
                maxVal = node.val;
                node.next = null; // detach from original list
                tail.next = node;
                tail = node;
            }
        }

        return dummy.next;
    }
}

