public class Solution {
    public int minimumDeviation(int[] nums) {
        PriorityQueue<Long> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
        long min = Long.MAX_VALUE;
        // Convert all numbers to their maximum possible even value
        for (int num : nums) {
            long val = num;
            while (val % 2 == 1) {
                val *= 3;
            }
            maxHeap.add(val);
            if (val < min) {
                min = val;
            }
        }

        long best = Long.MAX_VALUE;
        while (true) {
            long curMax = maxHeap.poll();
            if (curMax - min < best) {
                best = curMax - min;
            }
            // If current maximum is odd, we cannot reduce it
            if (curMax % 2 == 1) {
                break;
            }
            long reduced = curMax / 2;
            if (reduced < min) {
                min = reduced;
            }
            maxHeap.add(reduced);
        }
        return (int) best;
    }
}

