public class Solution {
    public long minimumTotalCost(int[] nums1, int[] nums2) {
        int n = nums1.length;
        boolean[] bad = new boolean[n];
        int badCount = 0;
        for (int i = 0; i < n; i++) {
            if (nums1[i] == nums2[i]) {
                bad[i] = true;
                badCount++;
            }
        }
        long totalCost = 0;
        while (badCount > 0) {
            int i = -1;
            for (int k = 0; k < n; k++) {
                if (bad[k]) {
                    i = k;
                    break;
                }
            }
            if (i == -1) break; // should not happen
            int bestJ = -1;
            int bestSum = Integer.MAX_VALUE;
            for (int j = 0; j < n; j++) {
                if (j == i) continue;
                // after swap, values at i and j
                int valI = nums1[i];
                int valJ = nums1[j];
                if (valJ != nums2[i] && valI != nums2[j]) {
                    int sum = i + j;
                    if (sum < bestSum) {
                        bestSum = sum;
                        bestJ = j;
                    }
                }
            }
            if (bestJ == -1) {
                return -1;
            }
            // perform swap
            int temp = nums1[i];
            nums1[i] = nums1[bestJ];
            nums1[bestJ] = temp;
            totalCost += bestSum;
            // update bad flags
            boolean badI = nums1[i] == nums2[i];
            boolean badJ = nums1[bestJ] == nums2[bestJ];
            if (bad[i] != badI) {
                if (badI) badCount++; else badCount--;
                bad[i] = badI;
            }
            if (bad[bestJ] != badJ) {
                if (badJ) badCount++; else badCount--;
                bad[bestJ] = badJ;
            }
        }
        return totalCost;
    }
}

