import java.util.ArrayList;
import java.util.List;

public class Solution {
    public long minimumTotalCost(int[] nums1, int[] nums2) {
        int n = nums1.length;
        List<Integer> conflictIndices = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (nums1[i] == nums2[i]) conflictIndices.add(i);
        }
        int k = conflictIndices.size();
        if (k == 0) return 0L;

        long best = Long.MAX_VALUE;
        int[] indices = new int[k];
        for (int i = 0; i < k; i++) indices[i] = conflictIndices.get(i);

        // Generate all permutations of indices array
        permute(indices, 0, nums1, nums2, n, best);
        return best == Long.MAX_VALUE ? -1L : best;
    }

    private void permute(int[] indices, int start, int[] nums1, int[] nums2, int n, long best) {
        if (start == indices.length) {
            if (checkAndCompute(indices, nums1, nums2, n, best)) {
                // Update best inside checkAndCompute
            }
            return;
        }
        for (int i = start; i < indices.length; i++) {
            swap(indices, start, i);
            permute(indices, start + 1, nums1, nums2, n, best);
            swap(indices, start, i);
        }
    }

    private boolean checkAndCompute(int[] perm, int[] nums1, int[] nums2, int n, long best) {
        int k = perm.length;
        // perm[i] is the original index whose value will go to position perm[i] ??? No, perm is permutation of conflict indices
        // We interpret perm as mapping from position list to source indices
        // Build targetPos map: for each j in conflict, its element will go to position perm[i], if perm[i] is source j? Need mapping
        // Actually perm array is a permutation of conflict indices. For position at indices[i], we take value from indices[perm[i]].
        // So source index = indices[perm[i]] goes to destination index = indices[i].
        int[] targetPos = new int[n];
        for (int i = 0; i < n; i++) targetPos[i] = i; // default unchanged
        for (int i = 0; i < k; i++) {
            int dest = indices[i];
            int src = indices[perm[i]];
            // value from src will be placed at dest
            targetPos[src] = dest;
        }
        // Validate that after permutation, no conflict
        for (int i = 0; i < k; i++) {
            int dest = indices[i];
            int src = indices[perm[i]];
            if (nums1[src] == nums2[dest]) return false;
            if (src == dest) return false; // no fixed point
        }
        // Compute minimal cost to realize permutation via swaps
        boolean[] visited = new boolean[n];
        long totalCost = 0;
        int globalMinIdx = 0; // index 0 is minimal
        for (int i = 0; i < n; i++) {
            if (visited[i] || targetPos[i] == i) continue;
            int cur = i;
            int len = 0;
            long sumIdx = 0;
            int minIdx = Integer.MAX_VALUE;
            while (!visited[cur]) {
                visited[cur] = true;
                sumIdx += cur;
                if (cur < minIdx) minIdx = cur;
                len++;
                cur = targetPos[cur];
            }
            if (len > 1) {
                long cost1 = sumIdx + (len - 2L) * minIdx;
                long cost2 = sumIdx + minIdx + (len + 1L) * globalMinIdx;
                totalCost += Math.min(cost1, cost2);
            }
        }
        if (totalCost < best) {
            // Since best is passed by value, we need to capture via a mutable holder or return.
            // Here we rely on outer best variable by reference? Not possible. Use a global field instead.
        }
        return false;
    }

    private void swap(int[] a, int i, int j) {
        int tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
    }
}

