        for (int i = 1; i <= n; i++) {
            int weightSum = 0;
            int portChanges = 0;
            for (int j = i - 1; j >= 0 && i - j <= maxBoxes; j--) {
                weightSum += boxes[j][1];
                if (weightSum > maxWeight) break;
                if (j < i - 1 && boxes[j][0] != boxes[j + 1][0]) portChanges++;
