import java.util.Arrays;

public class Solution {
    public int boxDelivering(int[][] boxes, int portsCount, int maxBoxes, int maxWeight) {
        int n = boxes.length;
        int[] dp = new int[n + 1];
        Arrays.fill(dp, Integer.MAX_VALUE / 4); // large value
        dp[0] = 0;

        // Pre‑compute number of port changes up to each index
        int[] portChanges = new int[n];
        for (int i = 1; i < n; i++) {
            portChanges[i] = portChanges[i - 1] + (boxes[i][0] == boxes[i - 1][0] ? 0 : 1);
        }

        for (int i = 0; i < n; i++) {
            if (dp[i] >= Integer.MAX_VALUE / 4) continue; // unreachable state
            int weightSum = 0;
            for (int j = i; j < n && j - i < maxBoxes; j++) {
                weightSum += boxes[j][1];
                if (weightSum > maxWeight) break;

                // Number of port changes inside segment [i, j] inclusive
                int changes = portChanges[j] - (i == 0 ? 0 : portChanges[i]);

                // Trips for this segment: load to first port (1), each internal port change (changes),
                // and return to storage (1) => 2 + changes
                int cost = dp[i] + 2 + changes;

                dp[j + 1] = Math.min(dp[j + 1], cost);
            }
        }
        return dp[n];
    }
}

