public class Solution {
    public int boxDelivering(int[][] boxes, int portsCount, int maxBoxes, int maxWeight) {
        int n = boxes.length;
        // prefix sum of weight changes for port transitions
        int[] port = new int[n];
        for (int i = 0; i < n; i++) {
            port[i] = boxes[i][0];
        }
        int[] diff = new int[n];
        for (int i = 1; i < n; i++) {
            diff[i] = (port[i] == port[i - 1]) ? 0 : 1;
        }
        int[] pref = new int[n];
        for (int i = 1; i < n; i++) {
            pref[i] = pref[i - 1] + diff[i];
        }

        // compute next[i] = farthest index exclusive that we can load starting at i
        int[] next = new int[n];
        int r = 0;
        long sumWeight = 0;
        int countBoxes = 0;
        for (int l = 0; l < n; l++) {
            while (r < n && countBoxes < maxBoxes && sumWeight + boxes[r][1] <= maxWeight) {
                sumWeight += boxes[r][1];
                countBoxes++;
                r++;
            }
            next[l] = r; // segment [l, r-1]
            // move left edge forward
            sumWeight -= boxes[l][1];
            countBoxes--;
        }

        int[] dp = new int[n + 1];
        final int INF = Integer.MAX_VALUE / 4;
        dp[n] = 0;
        for (int i = n - 1; i >= 0; i--) {
            int best = INF;
            for (int j = i + 1; j <= next[i]; j++) {
                int changes = pref[j - 1] - pref[i];
                int cost = 2 + changes;
                int val = dp[j] + cost;
                if (val < best) best = val;
            }
            dp[i] = best;
        }
        return dp[0];
    }
}

