            // It also must leave enough sum (at least 1 for every remaining
            // character before this position) for the earlier characters.
            int maxForCurrent = k - i;          // maximum value that can be used now
            int val = Math.min(26, maxForCurrent);
            result[i] = (char) ('a' + val - 1);
            k -= val;
        }
        return new String(result);
    }
}

