import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;

public class Solution {
    public List<Boolean> checkArithmeticSubarrays(int[] nums, int[] l, int[] r) {
        int m = l.length;
        List<Boolean> ans = new ArrayList<>(m);
        for (int i = 0; i < m; i++) {
            int left = l[i];
            int right = r[i];
            int len = right - left + 1;
            if (len <= 1) {
                ans.add(false);
                continue;
            }
            int minVal = Integer.MAX_VALUE;
            int maxVal = Integer.MIN_VALUE;
            HashSet<Integer> set = new HashSet<>(len);
            for (int j = left; j <= right; j++) {
                int val = nums[j];
                if (val < minVal) minVal = val;
                if (val > maxVal) maxVal = val;
                set.add(val);
            }
            if (set.size() != len) {
                ans.add(false);
                continue;
            }
            int diffNum = maxVal - minVal;
            if (diffNum % (len - 1) != 0) {
                ans.add(false);
                continue;
            }
            int diff = diffNum / (len - 1);
            if (diff == 0) {
                ans.add(true);
                continue;
            }
            boolean valid = true;
            for (int val : set) {
                if ((val - minVal) % diff != 0) {
                    valid = false;
                    break;
                }
            }
            ans.add(valid);
        }
        return ans;
    }
}

