import java.util.*;

public class Solution {
    public int getMaxGridHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
        // Precompute all possible masks for a row
        List<RowMask> masks = generateRowMasks(n);

        // DP: map key -> max happiness
        // key = (mask) | (iUsed << 16) | (eUsed << 20)
        Map<Integer, Integer> prevDP = new HashMap<>();
        prevDP.put(0, 0); // mask=0, i=0, e=0

        for (int row = 0; row < m; row++) {
            Map<Integer, Integer> currDP = new HashMap<>();
            for (Map.Entry<Integer, Integer> entry : prevDP.entrySet()) {
                int key = entry.getKey();
                int prevMask = key & 0xFFFF;
                int iUsed = (key >> 16) & 0x1F;
                int eUsed = (key >> 20) & 0x1F;
                int baseVal = entry.getValue();

                for (RowMask rm : masks) {
                    int newI = iUsed + rm.introCount;
                    int newE = eUsed + rm.extroCount;
                    if (newI > introvertsCount || newE > extrovertsCount) continue;

                    int interaction = computeInteraction(prevMask, rm.mask, n);
                    int newVal = baseVal + rm.baseHappiness + interaction;

                    int newKey = (rm.mask & 0xFFFF) | (newI << 16) | (newE << 20);
                    currDP.merge(newKey, newVal, Math::max);
                }
            }
            prevDP = currDP;
        }

        int ans = 0;
        for (int val : prevDP.values()) {
            if (val > ans) ans = val;
        }
        return ans;
    }

    private static int computeInteraction(int prevMask, int currMask, int n) {
        int delta = 0;
        for (int col = 0; col < n; col++) {
            int upState = (prevMask >> (col * 2)) & 3;
            int currState = (currMask >> (col * 2)) & 3;
            if (upState != 0 && currState != 0) {
                delta += neighborEffect(currState) + neighborEffect(upState);
            }
        }
        return delta;
    }

    private static int neighborEffect(int state) {
        if (state == 1) return -30; // introvert
        if (state == 2) return 20;  // extrovert
        return 0;
    }

    private static List<RowMask> generateRowMasks(int n) {
        List<RowMask> list = new ArrayList<>();
        int total = (int) Math.pow(3, n);
        for (int mask = 0; mask < total; mask++) {
            int temp = mask;
            int currMask = 0;
            int introCount = 0;
            int extroCount = 0;
            int base = 0;
            int[] states = new int[n];
            for (int col = 0; col < n; col++) {
                int state = temp % 3; // 0 none, 1 intro, 2 extro
                temp /= 3;
                states[col] = state;
                currMask |= (state << (col * 2));
                if (state == 1) {
                    introCount++;
                    base += 120;
                } else if (state == 2) {
                    extroCount++;
                    base += 40;
                }
            }
            // add pair contributions within the row
            for (int col = 0; col < n - 1; col++) {
                int s1 = states[col];
                int s2 = states[col + 1];
                if (s1 != 0 && s2 != 0) {
                    base += neighborEffect(s1) + neighborEffect(s2);
                }
            }
            list.add(new RowMask(currMask, introCount, extroCount, base));
        }
        return list;
    }

    private static class RowMask {
        int mask;
        int introCount;
        int extroCount;
        int baseHappiness;

        RowMask(int mask, int introCount, int extroCount, int baseHappiness) {
            this.mask = mask;
            this.introCount = introCount;
            this.extroCount = extroCount;
            this.baseHappiness = baseHappiness;
        }
    }
}

package referenz;


public class Solution {
    public int getMaxGridHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
        int maskSize = 1;
        for (int i = 0; i < n; i++) maskSize *= 3; // 3^n

        // Precompute digits, base happiness, intro/extro counts for each mask
        int[][] digits = new int[maskSize][n];
        int[] baseMask = new int[maskSize];
        int[] countIntroMask = new int[maskSize];
        int[] countExtroMask = new int[maskSize];

        for (int mask = 0; mask < maskSize; mask++) {
            int temp = mask;
            int base = 0;
            int cntIntro = 0;
            int cntExtro = 0;
            for (int col = 0; col < n; col++) {
                int val = temp % 3; // 0 none, 1 intro, 2 extro
                digits[mask][col] = val;
                if (val == 1) {
                    base += 120;
                    cntIntro++;
                } else if (val == 2) {
                    base += 40;
                    cntExtro++;
                }
                temp /= 3;
            }
            baseMask[mask] = base;
            countIntroMask[mask] = cntIntro;
            countExtroMask[mask] = cntExtro;
        }

        // Pair contribution between two people
        int[][] pairContrib = new int[3][3];
        pairContrib[1][1] = -60; // intro-intro
        pairContrib[1][2] = -10; // intro-extro
        pairContrib[2][1] = -10; // extro-intro
        pairContrib[2][2] = 40;  // extro-extro

        int INF = -1_000_000_000;
        int[][][] dpPrev = new int[maskSize][introvertsCount + 1][extrovertsCount + 1];
        int[][][] dpCurr = new int[maskSize][introvertsCount + 1][extrovertsCount + 1];
        for (int mask = 0; mask < maskSize; mask++) {
            for (int i = 0; i <= introvertsCount; i++) {
                for (int j = 0; j <= extrovertsCount; j++) {
                    dpPrev[mask][i][j] = INF;
                }
            }
        }
        dpPrev[0][0][0] = 0;

        for (int row = 0; row < m; row++) {
            // reset dpCurr
            for (int mask = 0; mask < maskSize; mask++) {
                for (int i = 0; i <= introvertsCount; i++) {
                    for (int j = 0; j <= extrovertsCount; j++) {
                        dpCurr[mask][i][j] = INF;
                    }
                }
            }

            for (int prevMask = 0; prevMask < maskSize; prevMask++) {
                for (int usedIntro = 0; usedIntro <= introvertsCount; usedIntro++) {
                    for (int usedExtro = 0; usedExtro <= extrovertsCount; usedExtro++) {
                        int curVal = dpPrev[prevMask][usedIntro][usedExtro];
                        if (curVal <= INF / 2) continue; // unreachable
                        for (int curMask = 0; curMask < maskSize; curMask++) {
                            int newIntro = usedIntro + countIntroMask[curMask];
                            int newExtro = usedExtro + countExtroMask[curMask];
                            if (newIntro > introvertsCount || newExtro > extrovertsCount) continue;

                            int total = curVal + baseMask[curMask];

                            // Contribution with previous row (up neighbor)
                            for (int col = 0; col < n; col++) {
                                int typeCur = digits[curMask][col];
                                int typeUp = digits[prevMask][col];
                                if (typeCur > 0 && typeUp > 0) {
                                    total += pairContrib[typeCur][typeUp];
                                }
                            }

                            // Contribution within current row (left neighbor)
                            for (int col = 1; col < n; col++) {
                                int typeCur = digits[curMask][col];
                                int typeLeft = digits[curMask][col - 1];
                                if (typeCur > 0 && typeLeft > 0) {
                                    total += pairContrib[typeCur][typeLeft];
                                }
                            }

                            if (total > dpCurr[curMask][newIntro][newExtro]) {
                                dpCurr[curMask][newIntro][newExtro] = total;
                            }
                        }
                    }
                }
            }
            // swap dpPrev and dpCurr
            int[][][] temp = dpPrev;
            dpPrev = dpCurr;
            dpCurr = temp;
        }

        int answer = 0;
        for (int mask = 0; mask < maskSize; mask++) {
            for (int i = 0; i <= introvertsCount; i++) {
                for (int j = 0; j <= extrovertsCount; j++) {
                    answer = Math.max(answer, dpPrev[mask][i][j]);
                }
            }
        }
        return answer;
    }
}

package referenz;


import java.util.HashMap;
import java.util.Map;

public class Solution {
    private int m, n, maxIntro, maxExtro;
    private int pow3;
    private int[][] maskTypes;
    private int[] introCnt;
    private int[] extroCnt;
    private int[][] pairDeltaTable;
    private Map<Long, Integer> memo;

    public int getMaxGridHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
        this.m = m;
        this.n = n;
        this.maxIntro = introvertsCount;
        this.maxExtro = extrovertsCount;

        pow3 = 1;
        for (int i = 0; i < n; i++) pow3 *= 3;

        maskTypes = new int[pow3][n];
        introCnt = new int[pow3];
        extroCnt = new int[pow3];
        precomputeMasks();

        pairDeltaTable = new int[3][3];
        for (int a = 0; a < 3; a++) {
            for (int b = 0; b < 3; b++) {
                if (a == 0 || b == 0) {
                    pairDeltaTable[a][b] = 0;
                } else if (a == 1 && b == 1) {
                    pairDeltaTable[a][b] = -60; // both introverts
                } else if (a == 1 && b == 2) {
                    pairDeltaTable[a][b] = -10; // intro & extro
                } else if (a == 2 && b == 1) {
                    pairDeltaTable[a][b] = -10;
                } else { // 2 & 2
                    pairDeltaTable[a][b] = 40;
                }
            }
        }

        memo = new HashMap<>();
        return dfs(0, 0, maxIntro, maxExtro);
    }

    private int dfs(int row, int prevMask, int introLeft, int extroLeft) {
        if (row == m) return 0;
        long key = ((long) row << 48) | ((long) prevMask << 32) | ((long) introLeft << 16) | extroLeft;
        Integer cached = memo.get(key);
        if (cached != null) return cached;

        int best = 0;
        for (int curMask = 0; curMask < pow3; curMask++) {
            int usedIntro = introCnt[curMask];
            int usedExtro = extroCnt[curMask];
            if (usedIntro > introLeft || usedExtro > extroLeft) continue;

            int addition = 0;
            for (int col = 0; col < n; col++) {
                int curType = maskTypes[curMask][col];
                if (curType == 0) continue;

                addition += (curType == 1) ? 120 : 40; // base happiness

                // left neighbor
                if (col > 0) {
                    int leftType = maskTypes[curMask][col - 1];
                    if (leftType != 0) {
                        addition += pairDeltaTable[curType][leftType];
                    }
                }
                // top neighbor
                int topType = maskTypes[prevMask][col];
                if (topType != 0) {
                    addition += pairDeltaTable[curType][topType];
                }
            }

            int candidate = addition + dfs(row + 1, curMask, introLeft - usedIntro, extroLeft - usedExtro);
            if (candidate > best) best = candidate;
        }

        memo.put(key, best);
        return best;
    }

    private void precomputeMasks() {
        for (int mask = 0; mask < pow3; mask++) {
            int temp = mask;
            int intro = 0;
            int extro = 0;
            for (int col = 0; col < n; col++) {
                int val = temp % 3;
                temp /= 3;
                maskTypes[mask][col] = val;
                if (val == 1) intro++;
                else if (val == 2) extro++;
            }
            introCnt[mask] = intro;
            extroCnt[mask] = extro;
        }
    }
}

package referenz;


import java.util.Arrays;

public class Solution {
    public int getMaxGridHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
        int maxMask = 1;
        for (int i = 0; i < n; i++) maxMask *= 3;
        int[] pow3 = new int[n];
        pow3[0] = 1;
        for (int i = 1; i < n; i++) pow3[i] = pow3[i - 1] * 3;

        int[] introInMask = new int[maxMask];
        int[] extroInMask = new int[maxMask];
        int[] baseScore = new int[maxMask];
        int[] internalScore = new int[maxMask];

        for (int mask = 0; mask < maxMask; mask++) {
            int temp = mask;
            int rowScore = 0;
            int rowBase = 0;
            int[] types = new int[n];
            for (int j = 0; j < n; j++) {
                int type = temp % 3;
                temp /= 3;
                types[j] = type;
                if (type == 1) {
                    introInMask[mask]++;
                    rowBase += 120;
                } else if (type == 2) {
                    extroInMask[mask]++;
                    rowBase += 40;
                }
            }
            // horizontal pairs
            int rowInternal = 0;
            for (int j = 0; j < n - 1; j++) {
                int t1 = types[j];
                int t2 = types[j + 1];
                if (t1 != 0 && t2 != 0) {
                    rowInternal += (t1 == 1 ? -30 : 20) + (t2 == 1 ? -30 : 20);
                }
            }
            baseScore[mask] = rowBase;
            internalScore[mask] = rowInternal;
        }

        int[][][] verticalScore = new int[maxMask][maxMask];
        for (int pm = 0; pm < maxMask; pm++) {
            int[] pTypes = new int[n];
            int tmp = pm;
            for (int j = 0; j < n; j++) {
                pTypes[j] = tmp % 3;
                tmp /= 3;
            }
            for (int cm = 0; cm < maxMask; cm++) {
                int[] cTypes = new int[n];
                tmp = cm;
                for (int j = 0; j < n; j++) {
                    cTypes[j] = tmp % 3;
                    tmp /= 3;
                }
                int sum = 0;
                for (int j = 0; j < n; j++) {
                    int t1 = pTypes[j];
                    int t2 = cTypes[j];
                    if (t1 != 0 && t2 != 0) {
                        sum += (t1 == 1 ? -30 : 20) + (t2 == 1 ? -30 : 20);
                    }
                }
                verticalScore[pm][cm] = sum;
            }
        }

        int INF_NEG = -1_000_000_000;
        int[][][] dp = new int[maxMask][introvertsCount + 1][extrovertsCount + 1];
        for (int i = 0; i < maxMask; i++) {
            for (int a = 0; a <= introvertsCount; a++) {
                Arrays.fill(dp[i][a], INF_NEG);
            }
        }
        dp[0][0][0] = 0;

        for (int row = 0; row < m; row++) {
            int[][][] newDp = new int[maxMask][introvertsCount + 1][extrovertsCount + 1];
            for (int i = 0; i < maxMask; i++) {
                for (int a = 0; a <= introvertsCount; a++) {
                    Arrays.fill(newDp[i][a], INF_NEG);
                }
            }
            for (int prevMask = 0; prevMask < maxMask; prevMask++) {
                for (int a = 0; a <= introvertsCount; a++) {
                    for (int b = 0; b <= extrovertsCount; b++) {
                        int curVal = dp[prevMask][a][b];
                        if (curVal == INF_NEG) continue;
                        for (int curMask = 0; curMask < maxMask; curMask++) {
                            int ca = introInMask[curMask];
                            int ce = extroInMask[curMask];
                            int na = a + ca;
                            int nb = b + ce;
                            if (na > introvertsCount || nb > extrovertsCount) continue;
                            int score = curVal + baseScore[curMask] + internalScore[curMask] + verticalScore[prevMask][curMask];
                            int prev = newDp[curMask][na][nb];
                            if (score > prev) newDp[curMask][na][nb] = score;
                        }
                    }
                }
            }
            dp = newDp;
        }

        int ans = 0;
        for (int mask = 0; mask < maxMask; mask++) {
            for (int a = 0; a <= introvertsCount; a++) {
                for (int b = 0; b <= extrovertsCount; b++) {
                    ans = Math.max(ans, dp[mask][a][b]);
                }
            }
        }
        return ans;
    }
}

