import java.util.*;

public class Solution {
    public boolean canDistribute(int[] nums, int[] quantity) {
        // Count frequencies of each unique number
        Map<Integer, Integer> freqMap = new HashMap<>();
        for (int num : nums) {
            freqMap.put(num, freqMap.getOrDefault(num, 0) + 1);
        }
        int[] counts = new int[freqMap.size()];
        int idx = 0;
        for (int val : freqMap.values()) {
            counts[idx++] = val;
        }

        int m = quantity.length;
        int fullMask = (1 << m) - 1;

        // Quick feasibility checks
        int totalQty = 0;
        for (int q : quantity) totalQty += q;
        int totalCount = 0;
        for (int c : counts) totalCount += c;
        if (totalQty > totalCount) return false;

        for (int q : quantity) {
            boolean ok = false;
            for (int c : counts) {
                if (c >= q) {
                    ok = true;
                    break;
                }
            }
            if (!ok) return false;
        }

        // Precompute sum of quantities for each subset mask
        int[] sum = new int[1 << m];
        for (int mask = 1; mask <= fullMask; mask++) {
            int lsb = mask & -mask;
            int pos = Integer.numberOfTrailingZeros(lsb);
            sum[mask] = sum[mask ^ lsb] + quantity[pos];
        }

        // Memoization arrays
        int nValues = counts.length;
        boolean[][] visited = new boolean[nValues + 1][1 << m];
        boolean[][] memo = new boolean[nValues + 1][1 << m];

        return dfs(0, 0, counts, fullMask, sum, visited, memo);
    }

    private boolean dfs(int idx, int mask, int[] counts, int fullMask, int[] sum,
                        boolean[][] visited, boolean[][] memo) {
        if (mask == fullMask) return true;
        if (idx == counts.length) return false;
        if (visited[idx][mask]) return memo[idx][mask];
        visited[idx][mask] = true;

        // Option 1: skip this value
        if (dfs(idx + 1, mask, counts, fullMask, sum, visited, memo)) {
            memo[idx][mask] = true;
            return true;
        }

        int remaining = fullMask ^ mask;
        // Iterate over all non-empty submasks of remaining customers
        for (int sub = remaining; sub > 0; sub = (sub - 1) & remaining) {
            if (sum[sub] <= counts[idx]) {
                if (dfs(idx + 1, mask | sub, counts, fullMask, sum, visited, memo)) {
                    memo[idx][mask] = true;
                    return true;
                }
            }
        }

        memo[idx][mask] = false;
        return false;
    }
}

