    public boolean canDistribute(int[] nums, int[] quantity) {
        // Count frequency of each unique number
        Map<Integer, Integer> freq = new HashMap<>();
        for (int num : nums) {
            freq.put(num, freq.getOrDefault(num, 0) + 1);
        }

        int[] counts = new int[freq.size()];
        int idx = 0;
        for (int val : freq.values()) {
            counts[idx++] = val;
        }

        int m = quantity.length;
        // Sort quantities in descending order for better pruning
        Arrays.sort(quantity);
        for (int i = 0; i < m / 2; i++) {
            int tmp = quantity[i];
            quantity[i] = quantity[m - 1 - i];
            quantity[m - 1 - i] = tmp;
        }

        // Quick checks
        int totalNum = nums.length;
        int totalQty = 0;
        for (int q : quantity) totalQty += q;
        if (totalQty > totalNum) return false;

        int maxCnt = 0;
        for (int c : counts) maxCnt = Math.max(maxCnt, c);
        int maxQty = quantity[0];
        if (maxQty > maxCnt) return false;

        // Precompute sum of quantities for all subsets of customers
        int subsetCount = 1 << m;
        int[] subsetSum = new int[subsetCount];
        for (int mask = 1; mask < subsetCount; mask++) {
            int lsb = mask & -mask;
            int bit = Integer.numberOfTrailingZeros(lsb);
            subsetSum[mask] = subsetSum[mask ^ lsb] + quantity[bit];
        }

        // Memoization for dp[mask] = possible or not
        Map<Integer, Boolean> memo = new HashMap<>();

        return dfs(0, subsetCount - 1, counts, subsetSum, memo);
    }

    private boolean dfs(int idx, int mask, int[] counts, int[] subsetSum, Map<Integer, Boolean> memo) {
        if (mask == 0) return true; // all customers satisfied
        if (idx >= counts.length) return false; // no more numbers

        Boolean memoVal = memo.get((idx << 8) | mask);
        if (memoVal != null) return memoVal;

        // Option 1: skip current number
        if (dfs(idx + 1, mask, counts, subsetSum, memo)) {
            memo.put((idx << 8) | mask, true);
            return true;
        }

        // Try all non-empty subsets of remaining customers
        for (int sub = mask; sub > 0; sub = (sub - 1) & mask) {
            if (subsetSum[sub] <= counts[idx]) {
                if (dfs(idx + 1, mask ^ sub, counts, subsetSum, memo)) {
                    memo.put((idx << 8) | mask, true);
                    return true;
                }
            }
        }

        memo.put((idx << 8) | mask, false);
        return false;
    }
}

