public class Solution {
    public boolean canDistribute(int[] nums, int[] quantity) {
        if (nums == null || quantity == null) return false;
        int totalNums = nums.length;
        int totalQty = 0;
        for (int q : quantity) totalQty += q;
        if (totalNums != totalQty) return false;

        // Count frequency of each unique number
        Map<Integer, Integer> freqMap = new HashMap<>();
        for (int num : nums) {
            freqMap.put(num, freqMap.getOrDefault(num, 0) + 1);
        }

        int[] counts = new int[freqMap.size()];
        int idx = 0;
        for (int val : freqMap.values()) counts[idx++] = val;

        // Sort quantities descending to reduce branching
        Arrays.sort(quantity);
        int m = quantity.length;
        int[] qtyDesc = new int[m];
        for (int i = 0; i < m; i++) qtyDesc[i] = quantity[m - 1 - i];

        Map<String, Boolean> memo = new HashMap<>();
        return dfs(0, qtyDesc, counts, memo);
    }

    private boolean dfs(int i, int[] quantity, int[] counts, Map<String, Boolean> memo) {
        if (i == quantity.length) return true;
        String key = buildKey(i, counts);
        if (memo.containsKey(key)) return memo.get(key);

        int q = quantity[i];
        for (int j = 0; j < counts.length; j++) {
            if (counts[j] >= q) {
                counts[j] -= q;
                if (dfs(i + 1, quantity, counts, memo)) {
                    counts[j] += q; // backtrack before returning
                    memo.put(key, true);
                    return true;
                }
                counts[j] += q; // backtrack
            }
        }
        memo.put(key, false);
        return false;
    }

    private String buildKey(int i, int[] counts) {
        int[] sorted = counts.clone();
        Arrays.sort(sorted);
        StringBuilder sb = new StringBuilder();
        sb.append(i).append('|');
        for (int v : sorted) {
            sb.append(v).append(',');
        }
        return sb.toString();
    }
}

