public class Solution {
    public boolean canDistribute(int[] nums, int[] quantity) {
        // Count frequency of each distinct number
        Map<Integer, Integer> freqMap = new HashMap<>();
        for (int num : nums) {
            freqMap.put(num, freqMap.getOrDefault(num, 0) + 1);
        }
        int unique = freqMap.size();
        int[] freq = new int[unique];
        int idx = 0;
        for (int val : freqMap.values()) {
            freq[idx++] = val;
        }

        int m = quantity.length;
        if (m == 0) return true;  // No customers to satisfy

        // Precompute all subset sums of quantity
        int totalMasks = 1 << m;
        int[] sumMask = new int[totalMasks];
        Map<Integer, List<Integer>> sumToMasks = new HashMap<>();
        for (int mask = 1; mask < totalMasks; mask++) {
            int lsb = Integer.numberOfTrailingZeros(mask);
            int prev = mask & (mask - 1);
            sumMask[mask] = sumMask[prev] + quantity[lsb];
            int s = sumMask[mask];
            sumToMasks.computeIfAbsent(s, k -> new ArrayList<>()).add(mask);
        }

        // For each unique frequency, get list of masks that sum up to it
        List<Integer> indices = new ArrayList<>();
        for (int i = 0; i < unique; i++) indices.add(i);
        // Sort indices by decreasing frequency to speed up pruning
        indices.sort((a, b) -> Integer.compare(freq[b], freq[a]));

        int sortedLen = indices.size();
        int[] freqSorted = new int[sortedLen];
        List<Integer>[] masksSorted = new List[sortedLen];
        for (int i = 0; i < sortedLen; i++) {
            int origIdx = indices.get(i);
            freqSorted[i] = freq[origIdx];
            masksSorted[i] = sumToMasks.getOrDefault(freqSorted[i], null);
        }

        boolean[][] memo = new boolean[sortedLen][totalMasks];
        boolean[][] vis = new boolean[sortedLen][totalMasks];

        return dfs(0, totalMasks - 1, freqSorted, masksSorted, vis, memo);
    }

    private boolean dfs(int idx, int mask,
                        int[] freqSorted,
                        List<Integer>[] masksSorted,
                        boolean[][] vis,
                        boolean[][] memo) {
        if (mask == 0) return true;
        if (idx == freqSorted.length) return false;
        if (vis[idx][mask]) return memo[idx][mask];
        vis[idx][mask] = true;

        // Option 1: skip this number
        if (dfs(idx + 1, mask, freqSorted, masksSorted, vis, memo)) {
            memo[idx][mask] = true;
            return true;
        }

        // Option 2: try to satisfy a subset of remaining customers with this number
        List<Integer> candidates = masksSorted[idx];
        if (candidates != null) {
            for (int sub : candidates) {
                if ((mask & sub) == sub) {
                    if (dfs(idx + 1, mask ^ sub, freqSorted, masksSorted, vis, memo)) {
                        memo[idx][mask] = true;
                        return true;
                    }
                }
            }
        }

        memo[idx][mask] = false;
        return false;
    }
}

