public class Solution {
    public boolean canDistribute(int[] nums, int[] quantity) {
        // Count frequency of each unique number
        Map<Integer, Integer> freqMap = new HashMap<>();
        for (int num : nums) {
            freqMap.put(num, freqMap.getOrDefault(num, 0) + 1);
        }
        int[] freq = new int[freqMap.size()];
        int idx = 0;
        for (int val : freqMap.values()) {
            freq[idx++] = val;
        }

        int m = quantity.length;
        int fullMask = (1 << m) - 1;

        // Precompute sum of quantities for each subset
        int[] sumQty = new int[1 << m];
        for (int mask = 1; mask <= fullMask; mask++) {
            int lsb = mask & -mask;
            int bit = Integer.numberOfTrailingZeros(lsb);
            sumQty[mask] = sumQty[mask ^ lsb] + quantity[bit];
        }

        // For each unique number, precompute subsets that this number can satisfy
        List<int[]> subsetLists = new ArrayList<>();
        for (int count : freq) {
            List<Integer> subsets = new ArrayList<>();
            for (int sub = 1; sub <= fullMask; sub++) {
                if (sumQty[sub] <= count) {
                    subsets.add(sub);
                }
            }
            // Convert to int array for faster iteration
            int[] arr = new int[subsets.size()];
            for (int i = 0; i < subsets.size(); i++) {
                arr[i] = subsets.get(i);
            }
            subsetLists.add(arr);
        }

        boolean[] dp = new boolean[1 << m];
        dp[0] = true;

        for (int[] subList : subsetLists) {
            boolean[] next = dp.clone();
            for (int mask = 0; mask <= fullMask; mask++) {
                if (!dp[mask]) continue;
                for (int sub : subList) {
                    if ((mask & sub) == 0) {
                        next[mask | sub] = true;
                    }
                }
            }
            dp = next;
        }

        return dp[fullMask];
    }
}

