public class Solution {
    private static final int MOD = 1_000_000_007;

    public int createSortedArray(int[] instructions) {
        int n = instructions.length;
        int[] sorted = instructions.clone();
        Arrays.sort(sorted);
        int m = 0;
        int prev = Integer.MIN_VALUE;
        for (int v : sorted) {
            if (v != prev) {
                sorted[m++] = v;
                prev = v;
            }
        }
        int[] uniq = Arrays.copyOf(sorted, m);
        Map<Integer, Integer> idxMap = new HashMap<>(m * 2);
        for (int i = 0; i < m; i++) {
            idxMap.put(uniq[i], i + 1); // 1-based index for BIT
        }

        BIT bit = new BIT(m + 2);
        long totalInserted = 0;
        long cost = 0;

        for (int val : instructions) {
            int idx = idxMap.get(val);
            long less = bit.query(idx - 1);
            long greater = totalInserted - bit.query(idx);
            cost += Math.min(less, greater);
            cost %= MOD;
            bit.update(idx, 1);
            totalInserted++;
        }

        return (int) cost;
    }

    // Binary Indexed Tree (Fenwick Tree) for prefix sums
    private static class BIT {
        private final long[] tree;
        private final int size;

        BIT(int size) {
            this.size = size;
            this.tree = new long[size + 2];
        }

        void update(int idx, long delta) {
            while (idx <= size) {
                tree[idx] += delta;
                idx += idx & -idx;
            }
        }

        long query(int idx) {
            long sum = 0;
            while (idx > 0) {
                sum += tree[idx];
                idx -= idx & -idx;
            }
            return sum;
        }
    }
}

