public class Solution {
    public int minimumIncompatibility(int[] nums, int k) {
        int n = nums.length;
        if (n % k != 0) return -1;
        int subsetSize = n / k;

        // Check if any number appears more than k times
        int[] freq = new int[101];
        for (int num : nums) {
            if (++freq[num] > k) return -1;
        }

        int totalMasks = 1 << n;
        int[] incompat = new int[totalMasks];
        Arrays.fill(incompat, -1);

        // Precompute incompatibility for all subsets of size subsetSize with no duplicates
        for (int mask = 0; mask < totalMasks; mask++) {
            if (Integer.bitCount(mask) != subsetSize) continue;
            boolean[] seen = new boolean[101];
            int min = Integer.MAX_VALUE;
            int max = Integer.MIN_VALUE;
            boolean valid = true;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    int val = nums[i];
                    if (seen[val]) {
                        valid = false;
                        break;
                    }
                    seen[val] = true;
                    if (val < min) min = val;
                    if (val > max) max = val;
                }
            }
            if (valid) incompat[mask] = max - min;
        }

        int[] dp = new int[totalMasks];
        Arrays.fill(dp, Integer.MAX_VALUE / 2);
        dp[0] = 0;

        for (int mask = 1; mask < totalMasks; mask++) {
            // iterate over submasks of mask
            for (int sub = mask; sub > 0; sub = (sub - 1) & mask) {
                if (incompat[sub] == -1) continue;
                int prev = mask ^ sub;
                dp[mask] = Math.min(dp[mask], dp[prev] + incompat[sub]);
            }
        }

        int ans = dp[totalMasks - 1];
        return ans >= Integer.MAX_VALUE / 2 ? -1 : ans;
    }
}

