public class Solution {
    public int minimumIncompatibility(int[] nums, int k) {
        int n = nums.length;
        if (n % k != 0) return -1;
        int subsetSize = n / k;

        // Check if any element appears more than k times
        Map<Integer, Integer> countMap = new HashMap<>();
        for (int v : nums) {
            countMap.put(v, countMap.getOrDefault(v, 0) + 1);
            if (countMap.get(v) > k) return -1;
        }

        int fullMask = (1 << n) - 1;
        int[] incompat = new int[1 << n];
        Arrays.fill(incompat, Integer.MAX_VALUE / 2);
        List<Integer> validMasks = new ArrayList<>();

        // Precompute all valid subsets of size subsetSize with unique elements
        for (int mask = 0; mask <= fullMask; mask++) {
            if (Integer.bitCount(mask) != subsetSize) continue;
            int minVal = Integer.MAX_VALUE, maxVal = Integer.MIN_VALUE;
            Set<Integer> seen = new HashSet<>();
            boolean dup = false;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    int val = nums[i];
                    if (!seen.add(val)) {
                        dup = true;
                        break;
                    }
                    minVal = Math.min(minVal, val);
                    maxVal = Math.max(maxVal, val);
                }
            }
            if (!dup) {
                incompat[mask] = maxVal - minVal;
                validMasks.add(mask);
            }
        }

        int[] memo = new int[1 << n];
        Arrays.fill(memo, Integer.MAX_VALUE / 2);
        memo[fullMask] = 0;

        int result = dfs(0, fullMask, k, subsetSize, validMasks, incompat, memo);
        return result == Integer.MAX_VALUE / 2 ? -1 : result;
    }

    private int dfs(int mask, int fullMask, int k, int subsetSize,
                    List<Integer> validMasks, int[] incompat, int[] memo) {
        if (mask == fullMask) return 0;
        if (memo[mask] != Integer.MAX_VALUE / 2) return memo[mask];

        int best = Integer.MAX_VALUE / 2;
        for (int sub : validMasks) {
            if ((sub & mask) != 0) continue; // subset intersects with already used elements
            // Ensure that the subset fits into remaining elements
            int newMask = mask | sub;
            int added = incompat[sub];
            int rest = dfs(newMask, fullMask, k, subsetSize, validMasks, incompat, memo);
            if (rest < Integer.MAX_VALUE / 2) {
                best = Math.min(best, added + rest);
            }
        }
        memo[mask] = best;
        return best;
    }
}

