            if (++count[v] > k) return -1;
        }

        int fullMask = (1 << n) - 1;
        int[] inc = new int[1 << n];
        Arrays.fill(inc, -1);

        // Precompute incompatibility for all valid subsets of size subsetSize
        for (int mask = 0; mask <= fullMask; mask++) {
            if (Integer.bitCount(mask) != subsetSize) continue;
            int[] freq = new int[21];
            int min = Integer.MAX_VALUE;
            int max = Integer.MIN_VALUE;
            boolean ok = true;
            for (int i = 0; i < n; i++) {
                if ((mask >> i & 1) == 1) {
                    int v = nums[i];
                    if (++freq[v] > 1) {
                        ok = false;
                        break;
                    }
                    if (v < min) min = v;
                    if (v > max) max = v;
                }
            }
            if (ok) inc[mask] = max - min;
        }

        int INF = Integer.MAX_VALUE / 2;
        int[] dp = new int[1 << n];
        Arrays.fill(dp, INF);
        dp[0] = 0;

        // DP over masks
        for (int mask = 0; mask <= fullMask; mask++) {
            if (dp[mask] == INF) continue;
            int remaining = fullMask ^ mask;

            // Collect indices of bits that are still available
            int[] positions = new int[Integer.bitCount(remaining)];
            int idx = 0;
            for (int i = 0; i < n; i++) {
                if ((remaining >> i & 1) == 1) {
                    positions[idx++] = i;
                }
            }

            // Generate all subsets of size subsetSize from remaining positions
            dfs(positions, 0, 0, 0, subsetSize, mask, inc, dp);
        }

        return dp[fullMask] == INF ? -1 : dp[fullMask];
    }

    // Recursive helper to generate subsets of size 'need' from 'positions'
    private void dfs(int[] positions, int posIdx, int chosenMask, int chosenCount,
                     int need, int currentMask, int[] inc, int[] dp) {
        if (chosenCount == need) {
            int newMask = currentMask | chosenMask;
            dp[newMask] = Math.min(dp[newMask], dp[currentMask] + inc[chosenMask]);
            return;
        }
        if (posIdx == positions.length) return;

        // Include current position
        dfs(positions, posIdx + 1, chosenMask | (1 << positions[posIdx]),
            chosenCount + 1, need, currentMask, inc, dp);

        // Skip current position
        dfs(positions, posIdx + 1, chosenMask, chosenCount, need, currentMask, inc, dp);
    }
}

