import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Solution {
    public int minimumIncompatibility(int[] nums, int k) {
        int n = nums.length;
        if (n % k != 0) return -1;
        int subsetSize = n / k;

        // Check frequency of each number
        int[] freq = new int[101];
        for (int v : nums) freq[v]++;
        for (int f : freq) if (f > k) return -1;

        int totalMask = 1 << n;
        int[] incompat = new int[totalMask];
        Arrays.fill(incompat, -1);
        List<Integer> validMasks = new ArrayList<>();

        // Precompute valid subsets and their incompatibility
        for (int mask = 0; mask < totalMask; mask++) {
            if (Integer.bitCount(mask) != subsetSize) continue;

            int min = Integer.MAX_VALUE;
            int max = Integer.MIN_VALUE;
            boolean dup = false;
            boolean[] seen = new boolean[101];

            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    int val = nums[i];
                    if (seen[val]) { dup = true; break; }
                    seen[val] = true;
                    if (val < min) min = val;
                    if (val > max) max = val;
                }
            }
            if (!dup) {
                incompat[mask] = max - min;
                validMasks.add(mask);
            }
        }

        int INF = Integer.MAX_VALUE / 2;
        int[] dp = new int[totalMask];
        Arrays.fill(dp, INF);
        dp[0] = 0;

        for (int mask = 0; mask < totalMask; mask++) {
            if (dp[mask] == INF) continue;
            for (int sub : validMasks) {
                if ((mask & sub) == 0) {
                    int newMask = mask | sub;
                    int newVal = dp[mask] + incompat[sub];
                    if (newVal < dp[newMask]) dp[newMask] = newVal;
                }
            }
        }

        int finalMask = totalMask - 1;
        return dp[finalMask] == INF ? -1 : dp[finalMask];
    }
}

