public class Solution {
    public boolean checkPalindromeFormation(String a, String b) {
        int n = a.length();
        for (int k = 0; k <= n; k++) {
            if (isPalindromeWithSplit(a, b, k)) return true;
            if (isPalindromeWithSplit(b, a, k)) return true;
        }
        return false;
    }

    private boolean isPalindromeWithSplit(String first, String second, int split) {
        int n = first.length();
        int left = 0, right = n - 1;
        while (left < right) {
            char leftChar = (left < split) ? first.charAt(left) : second.charAt(left);
            char rightChar = (right < split) ? first.charAt(right) : second.charAt(right);
            if (leftChar != rightChar) return false;
            left++;
            right--;
        }
        return true;
    }
}

