public class Solution {
    public boolean checkPalindromeFormation(String a, String b) {
        int n = a.length();
        return checkCase(a, b, n) || checkCase(b, a, n);
    }

    private boolean checkCase(String s1, String s2, int n) {
        for (int i = 0; i <= n; i++) {
            int l = 0, r = n - 1;
            while (l < r) {
                char cl = l < i ? s1.charAt(l) : s2.charAt(l);
                char cr = r < i ? s1.charAt(r) : s2.charAt(r);
                if (cl != cr) break;
                l++;
                r--;
            }
            if (l >= r) return true;
        }
        return false;
    }
}

