import java.util.ArrayDeque;
import java.util.Deque;

public class Solution {
    public int[] mostCompetitive(int[] nums, int k) {
        Deque<Integer> stack = new ArrayDeque<>();
        int n = nums.length;
        for (int i = 0; i < n; i++) {
            int remaining = n - i;
            while (!stack.isEmpty() && stack.peekLast() > nums[i] && stack.size() - 1 + remaining >= k) {
                stack.pollLast();
            }
            if (stack.size() < k) {
                stack.offerLast(nums[i]);
            }
        }
        int[] result = new int[k];
        int idx = 0;
        for (int val : stack) {
            result[idx++] = val;
        }
        return result;
    }
}

