public class Solution {
    public int[] mostCompetitive(int[] nums, int k) {
        int[] stack = new int[nums.length];
        int top = 0;

        for (int i = 0; i < nums.length; i++) {
            int current = nums[i];
            // Pop greater elements if we can still fill the stack with k elements
            while (top > 0 && stack[top - 1] > current &&
                   (top - 1 + (nums.length - i) >= k)) {
                top--;
            }
            // Push current if we still need more elements for the result
            if (top < k) {
                stack[top++] = current;
            }
        }

        // The stack now contains the most competitive subsequence of size k
        int[] result = new int[k];
        System.arraycopy(stack, 0, result, 0, k);
        return result;
    }
}

