public class Solution {
    public double trimMean(int[] arr) {
        int n = arr.length;
        int trim = n / 20; // 5% of n, rounded down
        Arrays.sort(arr);
        double sum = 0.0;
        for (int i = trim; i < n - trim; i++) {
            sum += arr[i];
        }
        int remaining = n - 2 * trim;
        return sum / remaining;
    }
}

