import java.math.BigInteger;

public class Solution {
    public String kthSmallestPath(int[] destination, int k) {
        int r = destination[0];
        int c = destination[1];
        StringBuilder sb = new StringBuilder();
        BigInteger K = BigInteger.valueOf(k);

        while (r > 0 || c > 0) {
            if (c == 0) {
                sb.append('V');
                r--;
            } else if (r == 0) {
                sb.append('H');
                c--;
            } else {
                BigInteger count = binomial(r + c - 1, r); // strings starting with 'H'
                if (K.compareTo(count) <= 0) {
                    sb.append('H');
                    c--;
                } else {
                    sb.append('V');
                    K = K.subtract(count);
                    r--;
                }
            }
        }
        return sb.toString();
    }

    private BigInteger binomial(int n, int k) {
        if (k < 0 || k > n) return BigInteger.ZERO;
        if (k > n - k) k = n - k;
        BigInteger res = BigInteger.ONE;
        for (int i = 1; i <= k; i++) {
            res = res.multiply(BigInteger.valueOf(n - k + i));
            res = res.divide(BigInteger.valueOf(i));
        }
        return res;
    }
}

