import java.math.BigInteger;

public class Solution {
    public String kthSmallestPath(int[] destination, int k) {
        int rows = destination[0];
        int cols = destination[1];
        int totalV = rows; // number of 'V' moves (down)
        int totalH = cols; // number of 'H' moves (right)
        long K = k; // 1-indexed
        StringBuilder sb = new StringBuilder();

        while (totalV > 0 || totalH > 0) {
            if (totalH == 0) {
                sb.append('V');
                totalV--;
                continue;
            }
            if (totalV == 0) {
                sb.append('H');
                totalH--;
                continue;
            }

            long countHFirst = nCrCap(totalH - 1 + totalV, totalH - 1, Long.MAX_VALUE);
            if (K <= countHFirst) {
                sb.append('H');
                totalH--;
            } else {
                sb.append('V');
                K -= countHFirst;
                totalV--;
            }
        }
        return sb.toString();
    }

    private long nCrCap(int n, int r, long cap) {
        if (r < 0 || r > n) return 0;
        r = Math.min(r, n - r);
        BigInteger res = BigInteger.ONE;
        for (int i = 1; i <= r; i++) {
            res = res.multiply(BigInteger.valueOf(n - r + i));
            res = res.divide(BigInteger.valueOf(i));
            if (res.compareTo(BigInteger.valueOf(cap)) > 0) {
                return cap;
            }
        }
        return res.longValue();
    }
}

