import java.math.BigInteger;

public class Solution {
    public String kthSmallestPath(int[] destination, int k) {
        int rights = destination[1]; // number of 'H'
        int downs = destination[0];  // number of 'V'
        long target = k; // 1-indexed
        StringBuilder sb = new StringBuilder();

        while (rights > 0 || downs > 0) {
            if (rights == 0) {
                sb.append('V');
                downs--;
                continue;
            }
            if (downs == 0) {
                sb.append('H');
                rights--;
                continue;
            }
            long countH = countComb(rights - 1 + downs, rights - 1, target);
            if (target <= countH) {
                sb.append('H');
                rights--;
            } else {
                sb.append('V');
                target -= countH;
                downs--;
            }
        }
        return sb.toString();
    }

    private long countComb(int n, int r, long limit) {
        if (r < 0 || r > n) return 0L;
        r = Math.min(r, n - r);
        BigInteger res = BigInteger.ONE;
        for (int i = 1; i <= r; i++) {
            res = res.multiply(BigInteger.valueOf(n - r + i)).divide(BigInteger.valueOf(i));
            if (res.compareTo(BigInteger.valueOf(limit)) > 0) {
                return limit + 1;
            }
        }
        return res.longValue();
    }
}

