public class Solution {
    public String kthSmallestPath(int[] destination, int k) {
        int totalRows = destination[0];
        int totalCols = destination[1];
        int n = totalRows + totalCols;
        long[][] comb = new long[n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            comb[i][0] = comb[i][i] = 1;
            for (int j = 1; j < i; j++) {
                long val = comb[i - 1][j - 1] + comb[i - 1][j];
                if (val < 0 || val > Long.MAX_VALUE / 2) val = Long.MAX_VALUE / 2;
                comb[i][j] = val;
            }
        }

        StringBuilder sb = new StringBuilder();
        int remainingRows = totalRows; // V
        int remainingCols = totalCols; // H
        long kth = k;

        while (remainingRows > 0 || remainingCols > 0) {
            if (remainingCols == 0) {
                sb.append('V');
                remainingRows--;
                continue;
            }
            if (remainingRows == 0) {
                sb.append('H');
                remainingCols--;
                continue;
            }
            long countH = comb[remainingCols - 1 + remainingRows][remainingCols - 1];
            if (kth <= countH) {
                sb.append('H');
                remainingCols--;
            } else {
                kth -= countH;
                sb.append('V');
                remainingRows--;
            }
        }
        return sb.toString();
    }
}

