import java.util.*;

public class Solution {
    private static final long INF = Long.MAX_VALUE / 2;

    private static long[][] comb = new long[61][61];

    static {
        for (int n = 0; n <= 60; n++) {
            comb[n][0] = comb[n][n] = 1;
            for (int k = 1; k < n; k++) {
                long val = comb[n - 1][k - 1] + comb[n - 1][k];
                comb[n][k] = val > INF ? INF : val;
            }
        }
    }

    public String kthSmallestPath(int[] destination, int k) {
        int rows = destination[0];
        int cols = destination[1];

        StringBuilder sb = new StringBuilder(rows + cols);
        long remainingK = k; // 1-indexed

        while (rows > 0 || cols > 0) {
            if (cols == 0) {
                sb.append('V');
                rows--;
                continue;
            }
            if (rows == 0) {
                sb.append('H');
                cols--;
                continue;
            }

            long countWithH = comb[rows + cols - 1][rows]; // fix H, remaining rows
            if (remainingK <= countWithH) {
                sb.append('H');
                cols--;
            } else {
                sb.append('V');
                remainingK -= countWithH;
                rows--;
            }
        }
        return sb.toString();
    }
}

