import java.util.*;

public class Solution {
    public int[][] matrixRankTransform(int[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;
        int[][] ans = new int[m][n];

        // Map value to list of positions
        Map<Integer, List<int[]>> valueMap = new TreeMap<>();
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                valueMap.computeIfAbsent(matrix[i][j], k -> new ArrayList<>()).add(new int[]{i, j});
            }
        }

        int[] rowMax = new int[m];
        int[] colMax = new int[n];

        for (Map.Entry<Integer, List<int[]>> entry : valueMap.entrySet()) {
            List<int[]> cells = entry.getValue();
            int size = cells.size();

            // DSU structures
            int[] parent = new int[size];
            int[] rank = new int[size];
            for (int i = 0; i < size; i++) parent[i] = i;

            // Map cell to index
            Map<Integer, Integer> posToIdx = new HashMap<>();
            for (int i = 0; i < size; i++) {
                int[] cell = cells.get(i);
                int key = cell[0] * n + cell[1];
                posToIdx.put(key, i);
            }

            // Build row and column groups
            Map<Integer, List<Integer>> rowGroups = new HashMap<>();
            Map<Integer, List<Integer>> colGroups = new HashMap<>();
            for (int i = 0; i < size; i++) {
                int[] cell = cells.get(i);
                int r = cell[0], c = cell[1];
                rowGroups.computeIfAbsent(r, k -> new ArrayList<>()).add(i);
                colGroups.computeIfAbsent(c, k -> new ArrayList<>()).add(i);
            }

            // Union indices in same row
            for (List<Integer> list : rowGroups.values()) {
                for (int i = 1; i < list.size(); i++) {
                    union(list.get(i - 1), list.get(i), parent, rank);
                }
            }
            // Union indices in same column
            for (List<Integer> list : colGroups.values()) {
                for (int i = 1; i < list.size(); i++) {
                    union(list.get(i - 1), list.get(i), parent, rank);
                }
            }

            // Group indices by component
            Map<Integer, List<Integer>> compMap = new HashMap<>();
            for (int i = 0; i < size; i++) {
                int root = find(i, parent);
                compMap.computeIfAbsent(root, k -> new ArrayList<>()).add(i);
            }

            // Assign ranks for each component
            for (List<Integer> comp : compMap.values()) {
                int maxPrev = 0;
                for (int idx : comp) {
                    int[] cell = cells.get(idx);
                    int r = cell[0], c = cell[1];
                    maxPrev = Math.max(maxPrev, Math.max(rowMax[r], colMax[c]));
                }
                int rankVal = maxPrev + 1;
                for (int idx : comp) {
                    int[] cell = cells.get(idx);
                    int r = cell[0], c = cell[1];
                    ans[r][c] = rankVal;
                    rowMax[r] = rankVal;
                    colMax[c] = rankVal;
                }
            }
        }

        return ans;
    }

    private int find(int x, int[] parent) {
        if (parent[x] != x) parent[x] = find(parent[x], parent);
        return parent[x];
    }

    private void union(int a, int b, int[] parent, int[] rank) {
        int ra = find(a, parent);
        int rb = find(b, parent);
        if (ra == rb) return;
        if (rank[ra] < rank[rb]) {
            parent[ra] = rb;
        } else if (rank[ra] > rank[rb]) {
            parent[rb] = ra;
        } else {
            parent[rb] = ra;
            rank[ra]++;
        }
    }
}

