import java.util.*;

public class Solution {
    public int[][] matrixRankTransform(int[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;
        int[][] ans = new int[m][n];
        int total = m * n;

        // Build list of cells with their values
        int[][] cells = new int[total][3]; // {value, row, col}
        int idx = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                cells[idx][0] = matrix[i][j];
                cells[idx][1] = i;
                cells[idx][2] = j;
                idx++;
            }
        }
        Arrays.sort(cells, Comparator.comparingInt(a -> a[0]));

        // DSU for cells
        DSU dsu = new DSU(total);
        int[] rowRank = new int[m];
        int[] colRank = new int[n];

        int i = 0;
        while (i < total) {
            int val = cells[i][0];
            int j = i;
            // Collect all cells with current value
            while (j < total && cells[j][0] == val) j++;

            // Union cells that share same row or column
            HashMap<Integer, List<Integer>> rowMap = new HashMap<>();
            HashMap<Integer, List<Integer>> colMap = new HashMap<>();
            for (int k = i; k < j; k++) {
                int r = cells[k][1];
                int c = cells[k][2];
                int cellIdx = r * n + c;
                rowMap.computeIfAbsent(r, x -> new ArrayList<>()).add(cellIdx);
                colMap.computeIfAbsent(c, x -> new ArrayList<>()).add(cellIdx);
            }
            for (List<Integer> list : rowMap.values()) {
                for (int t = 1; t < list.size(); t++) {
                    dsu.union(list.get(0), list.get(t));
                }
            }
            for (List<Integer> list : colMap.values()) {
                for (int t = 1; t < list.size(); t++) {
                    dsu.union(list.get(0), list.get(t));
                }
            }

            // Determine rank for each component
            HashMap<Integer, Integer> compMax = new HashMap<>();
            for (int k = i; k < j; k++) {
                int r = cells[k][1];
                int c = cells[k][2];
                int cellIdx = r * n + c;
                int root = dsu.find(cellIdx);
                int curMax = Math.max(rowRank[r], colRank[c]);
                compMax.merge(root, curMax, Math::max);
            }
            // Assign ranks
            for (int k = i; k < j; k++) {
                int r = cells[k][1];
                int c = cells[k][2];
                int cellIdx = r * n + c;
                int root = dsu.find(cellIdx);
                int rank = compMax.get(root) + 1;
                ans[r][c] = rank;
                rowRank[r] = rank;
                colRank[c] = rank;
            }

            i = j;
        }

        return ans;
    }

    // Disjoint Set Union (Union-Find)
    private static class DSU {
        int[] parent;
        int[] rank;
        DSU(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) parent[i] = i;
        }
        int find(int x) {
            if (parent[x] != x) parent[x] = find(parent[x]);
            return parent[x];
        }
        void union(int x, int y) {
            int rx = find(x);
            int ry = find(y);
            if (rx == ry) return;
            if (rank[rx] < rank[ry]) {
                parent[rx] = ry;
            } else if (rank[rx] > rank[ry]) {
                parent[ry] = rx;
            } else {
                parent[ry] = rx;
                rank[rx]++;
            }
        }
    }
}

