import java.util.*;

public class Solution {
    public int[][] matrixRankTransform(int[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;
        int[][] ans = new int[m][n];
        int total = m * n;

        // Prepare cells array: [value, row, col]
        int[][] cells = new int[total][3];
        int idx = 0;
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                cells[idx][0] = matrix[r][c];
                cells[idx][1] = r;
                cells[idx][2] = c;
                idx++;
            }
        }

        // Sort cells by value
        Arrays.sort(cells, Comparator.comparingInt(a -> a[0]));

        // DSU structures
        int[] parent = new int[total];
        int[] rank = new int[total]; // not used for union by rank, but placeholder
        for (int i = 0; i < total; i++) parent[i] = i;

        int[] rowRank = new int[m];
        int[] colRank = new int[n];
        int[] rootRank = new int[total];

        int i = 0;
        while (i < total) {
            int val = cells[i][0];
            int start = i;
            while (i < total && cells[i][0] == val) i++;
            int end = i;

            // Union cells with same value in same row or column
            int[] rowLast = new int[m];
            int[] colLast = new int[n];
            Arrays.fill(rowLast, -1);
            Arrays.fill(colLast, -1);

            for (int k = start; k < end; k++) {
                int r = cells[k][1];
                int c = cells[k][2];
                int id = r * n + c;
                if (rowLast[r] != -1) union(parent, rowLast[r], id);
                rowLast[r] = id;
                if (colLast[c] != -1) union(parent, colLast[c], id);
                colLast[c] = id;
            }

            // Compute max previous rank for each root
            for (int k = start; k < end; k++) {
                int r = cells[k][1];
                int c = cells[k][2];
                int id = r * n + c;
                int root = find(parent, id);
                int maxPrev = Math.max(rowRank[r], colRank[c]);
                rootRank[root] = Math.max(rootRank[root], maxPrev + 1);
            }

            // Assign ranks to cells
            for (int k = start; k < end; k++) {
                int r = cells[k][1];
                int c = cells[k][2];
                int id = r * n + c;
                int root = find(parent, id);
                int rankVal = rootRank[root];
                ans[r][c] = rankVal;
                rowRank[r] = rankVal;
                colRank[c] = rankVal;
            }
        }

        return ans;
    }

    private int find(int[] parent, int x) {
        if (parent[x] != x) parent[x] = find(parent, parent[x]);
        return parent[x];
    }

    private void union(int[] parent, int a, int b) {
        int ra = find(parent, a);
        int rb = find(parent, b);
        if (ra != rb) parent[ra] = rb;
    }
}

