import java.util.*;

public class Solution {
    // Union Find (Disjoint Set Union)
    private static class DSU {
        int[] parent;
        int[] size;
        DSU(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }
        int find(int x) {
            if (parent[x] != x) parent[x] = find(parent[x]);
            return parent[x];
        }
        void union(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return;
            if (size[ra] < size[rb]) {
                parent[ra] = rb;
                size[rb] += size[ra];
            } else {
                parent[rb] = ra;
                size[ra] += size[rb];
            }
        }
    }

    private static class Cell {
        int val;
        int row;
        int col;
        int idx;
        Cell(int val, int row, int col, int idx) {
            this.val = val;
            this.row = row;
            this.col = col;
            this.idx = idx;
        }
    }

    public int[][] matrixRankTransform(int[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;
        int total = m * n;
        Cell[] cells = new Cell[total];
        int k = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                cells[k++] = new Cell(matrix[i][j], i, j, i * n + j);
            }
        }
        Arrays.sort(cells, Comparator.comparingInt(c -> c.val));

        int[][] answer = new int[m][n];
        int[] rowRank = new int[m];
        int[] colRank = new int[n];
        DSU dsu = new DSU(total);

        int ptr = 0;
        while (ptr < total) {
            int val = cells[ptr].val;
            int start = ptr;
            while (ptr < total && cells[ptr].val == val) ptr++;
            int end = ptr; // [start, end)

            // Union equal values in same row/column
            Map<Integer, Integer> rowMap = new HashMap<>();
            Map<Integer, Integer> colMap = new HashMap<>();
            for (int i = start; i < end; i++) {
                Cell c = cells[i];
                if (rowMap.containsKey(c.row)) {
                    dsu.union(c.idx, rowMap.get(c.row));
                } else {
                    rowMap.put(c.row, c.idx);
                }
                if (colMap.containsKey(c.col)) {
                    dsu.union(c.idx, colMap.get(c.col));
                } else {
                    colMap.put(c.col, c.idx);
                }
            }

            // Compute rank for each root
            Map<Integer, Integer> rootToRank = new HashMap<>();
            for (int i = start; i < end; i++) {
                Cell c = cells[i];
                int root = dsu.find(c.idx);
                int rank = Math.max(rowRank[c.row], colRank[c.col]) + 1;
                rootToRank.merge(root, rank, Math::max);
            }

            // Assign ranks and update row/col ranks
            for (int i = start; i < end; i++) {
                Cell c = cells[i];
                int root = dsu.find(c.idx);
                int rank = rootToRank.get(root);
                answer[c.row][c.col] = rank;
                rowRank[c.row] = rank;
                colRank[c.col] = rank;
            }
        }

        return answer;
    }
}

