import java.util.*;

public class Solution {
    public int[][] matrixRankTransform(int[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;
        int total = m * n;
        int[][] ans = new int[m][n];

        // DSU for rows and columns
        int size = m + n;
        int[] parent = new int[size];
        int[] rank = new int[size];
        for (int i = 0; i < size; i++) parent[i] = i;

        // Helper functions for DSU
        int find(int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        }
        void union(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return;
            if (rank[ra] < rank[rb]) {
                parent[ra] = rb;
            } else if (rank[ra] > rank[rb]) {
                parent[rb] = ra;
            } else {
                parent[rb] = ra;
                rank[ra]++;
            }
        }

        // Cell representation
        class Cell {
            int r, c, v;
            Cell(int r, int c, int v) { this.r = r; this.c = c; this.v = v; }
        }

        Cell[] cells = new Cell[total];
        int idx = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                cells[idx++] = new Cell(i, j, matrix[i][j]);
            }
        }
        Arrays.sort(cells, Comparator.comparingInt(c -> c.v));

        int[] rowRank = new int[m];
        int[] colRank = new int[n];
        int[] rootMax = new int[size];
        boolean[] used = new boolean[size];
        ArrayList<Integer> roots = new ArrayList<>();

        int i = 0;
        while (i < total) {
            int val = cells[i].v;
            int start = i;
            while (i < total && cells[i].v == val) i++;
            // union rows and columns for this group
            for (int k = start; k < i; k++) {
                union(cells[k].r, cells[k].c + m);
            }
            // compute max rank for each component
            for (int k = start; k < i; k++) {
                int root = find(cells[k].r);
                if (!used[root]) {
                    used[root] = true;
                    roots.add(root);
                }
                int curMax = Math.max(rowRank[cells[k].r], colRank[cells[k].c]);
                if (curMax > rootMax[root]) rootMax[root] = curMax;
            }
            // assign ranks
            for (int root : roots) {
                int newRank = rootMax[root] + 1;
                for (int k = start; k < i; k++) {
                    if (find(cells[k].r) == root) {
                        ans[cells[k].r][cells[k].c] = newRank;
                        rowRank[cells[k].r] = newRank;
                        colRank[cells[k].c] = newRank;
                    }
                }
                rootMax[root] = 0; // reset for next use
                used[root] = false;
            }
            roots.clear();
        }

        return ans;
    }
}

