public class Solution {
    public int countSubstrings(String s, String t) {
        int n = s.length();
        int m = t.length();
        if (n == 0 || m == 0) return 0;

        int[][] lcp = new int[n + 1][m + 1];
        for (int i = n - 1; i >= 0; i--) {
            for (int j = m - 1; j >= 0; j--) {
                if (s.charAt(i) == t.charAt(j)) {
                    lcp[i][j] = lcp[i + 1][j + 1] + 1;
                } else {
                    lcp[i][j] = 0;
                }
            }
        }

        int[][] lcs = new int[n + 1][m + 1];
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (s.charAt(i - 1) == t.charAt(j - 1)) {
                    lcs[i][j] = lcs[i - 1][j - 1] + 1;
                } else {
                    lcs[i][j] = 0;
                }
            }
        }

        boolean[][] visited = new boolean[n][n + 1];
        int count = 0;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int maxLen = Math.min(n - i, m - j);
                int k = lcp[i][j];
                if (k == maxLen) continue; // identical, no mismatch
                int maxSuffixLen = lcs[i + maxLen][j + maxLen];
                int Lmax = Math.min(maxLen, k + 1 + maxSuffixLen);
                for (int L = k + 1; L <= Lmax; L++) {
                    if (!visited[i][L]) {
                        visited[i][L] = true;
                        count++;
                    }
                }
            }
        }

        return count;
    }
}

