public class Solution {
    public int countSubstrings(String s, String t) {
        int n = s.length();
        int m = t.length();
        char[] cs = s.toCharArray();
        char[] ct = t.toCharArray();
        long count = 0L;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int k = 0;
                // Find first mismatch
                while (i + k < n && j + k < m && cs[i + k] == ct[j + k]) {
                    k++;
                }
                if (i + k >= n || j + k >= m) {
                    continue; // no mismatch
                }
                // Now k is first mismatch position
                // Extend beyond mismatch as long as remaining characters match
                int l = k + 1;
                while (i + l < n && j + l < m && cs[i + l] == ct[j + l]) {
                    count++;
                    l++;
                }
            }
        }
        return (int) count;
    }
}

