public class Solution {
    public int countSubstrings(String s, String t) {
        int n = s.length();
        int m = t.length();

        // Build LCP table
        int[][] lcp = new int[n + 1][m + 1];
        for (int i = n - 1; i >= 0; i--) {
            for (int j = m - 1; j >= 0; j--) {
                if (s.charAt(i) == t.charAt(j)) {
                    lcp[i][j] = lcp[i + 1][j + 1] + 1;
                } else {
                    lcp[i][j] = 0;
                }
            }
        }

        int ans = 0;
        for (int i = 0; i < n; i++) {
            int lenS = n - i;
            int[] diff = new int[lenS + 2]; // difference array

            for (int j = 0; j < m; j++) {
                int maxLenPossible = Math.min(lenS, m - j);
                int match = lcp[i][j];

                if (match >= maxLenPossible) {
                    // All characters match up to the end; no mismatch possible
                    continue;
                }

                int suffix = 0;
                int nextI = i + match + 1;
                int nextJ = j + match + 1;
                if (nextI < n && nextJ < m) {
                    suffix = lcp[nextI][nextJ];
                }

                int startLen = match + 1; // first length that includes the mismatch
                int endLen = Math.min(match + 1 + suffix, maxLenPossible);

                if (startLen <= endLen) {
                    diff[startLen]++;          // inclusive start
                    diff[endLen + 1]--;        // exclusive end
                }
            }

            int cur = 0;
            for (int l = 1; l <= lenS; l++) {
                cur += diff[l];
                if (cur > 0) {
                    ans++;
                }
            }
        }

        return ans;
    }
}

