public class Solution {
    public int maxOperations(int[] nums, int k) {
        Map<Integer, Integer> counts = new HashMap<>();
        for (int num : nums) {
            counts.put(num, counts.getOrDefault(num, 0) + 1);
        }
        int operations = 0;
        for (int num : nums) {
            int comp = k - num;
            Integer cntNum = counts.get(num);
            Integer cntComp = counts.get(comp);
            if (cntNum == null || cntComp == null || cntNum == 0 || cntComp == 0) {
                continue;
            }
            if (num == comp) {
                int pairs = cntNum / 2;
                if (pairs > 0) {
                    counts.put(num, cntNum - 2 * pairs);
                    operations += pairs;
                }
            } else {
                int pairs = Math.min(cntNum, cntComp);
                if (pairs > 0) {
                    counts.put(num, cntNum - pairs);
                    counts.put(comp, cntComp - pairs);
                    operations += pairs;
                }
            }
        }
        return operations;
    }
}

