public class Solution {
    // Union-Find (Disjoint Set Union) implementation
    private static class DSU {
        private final int[] parent;
        private final int[] size;

        DSU(int n) {
            parent = new int[n + 1];
            size = new int[n + 1];
            for (int i = 1; i <= n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union(int a, int b) {
            int pa = find(a);
            int pb = find(b);
            if (pa == pb) return;
            if (size[pa] < size[pb]) {
                int tmp = pa;
                pa = pb;
                pb = tmp;
            }
            parent[pb] = pa;
            size[pa] += size[pb];
        }
    }

    public List<Boolean> areConnected(int n, int threshold, int[][] queries) {
        DSU dsu = new DSU(n);

        // For each divisor z greater than threshold, union all its multiples
        for (int z = threshold + 1; z <= n; z++) {
            int firstMultiple = z;
            // Union firstMultiple with all other multiples of z
            for (int multiple = z * 2; multiple <= n; multiple += z) {
                dsu.union(firstMultiple, multiple);
            }
        }

        List<Boolean> answer = new ArrayList<>(queries.length);
        for (int[] q : queries) {
            int a = q[0];
            int b = q[1];
            answer.add(dsu.find(a) == dsu.find(b));
        }
        return answer;
    }
}

