public class Solution {
    private static final int MOD = 1_000_000_007;

    public int numWays(String[] words, String target) {
        int n = words[0].length();
        int m = target.length();
        if (n < m) return 0;

        long[][] count = new long[26][n];
        for (String w : words) {
            for (int i = 0; i < n; i++) {
                char c = w.charAt(i);
                count[c - 'a'][i]++;
            }
        }

        long[] pow2 = new long[n + 1];
        pow2[0] = 1;
        for (int i = 1; i <= n; i++) {
            pow2[i] = (pow2[i - 1] * 2) % MOD;
        }

        long[] dp = new long[m + 1];
        dp[0] = 1;
        for (int i = 0; i < m; i++) {
            int idx = target.charAt(i) - 'a';
            for (int pos = i; pos < n; pos++) {
                long ways = dp[i] * count[idx][pos] % MOD * pow2[n - pos - 1] % MOD;
                dp[i + 1] = (dp[i + 1] + ways) % MOD;
            }
        }
        return (int) dp[m];
    }
}

