            // Operation 1: add a to all odd indices
            char[] chars = cur.toCharArray();
            for (int i = 1; i < n; i += 2) {
                int digit = chars[i] - '0';
                digit = (digit + a) % 10;
                chars[i] = (char) ('0' + digit);
            }
            String op1 = new String(chars);
            if (visited.add(op1)) {
