import java.util.HashSet;
import java.util.ArrayDeque;
import java.util.Queue;

public class Solution {

    public String getSmallestString(String s, int a, int b) {
        int n = s.length();
        int shift = b % n;                // effective rotation shift
        Queue<String> queue = new ArrayDeque<>();
        HashSet<String> visited = new HashSet<>();

        queue.offer(s);
        visited.add(s);

        String best = s;                  // current lexicographically smallest

        while (!queue.isEmpty()) {
            String cur = queue.poll();

            // Update best if current string is smaller
            if (cur.compareTo(best) < 0) {
                best = cur;
            }

            // Operation 1: add a to all odd indices
            String added = addOddIndices(cur, a);
            if (!visited.contains(added)) {
                visited.add(added);
                queue.offer(added);
            }

            // Operation 2: rotate right by shift positions
            String rotated = rotateRight(cur, shift);
            if (!visited.contains(rotated)) {
                visited.add(rotated);
                queue.offer(rotated);
            }
        }

        return best;
    }

    // Helper to add 'a' to digits at odd indices, modulo 10
    private String addOddIndices(String s, int a) {
        char[] arr = s.toCharArray();
        for (int i = 1; i < arr.length; i += 2) {
            int d = arr[i] - '0';
            d = (d + a) % 10;
            arr[i] = (char) (d + '0');
        }
        return new String(arr);
    }

    // Helper to rotate string right by 'shift' positions
    private String rotateRight(String s, int shift) {
        if (shift == 0) return s;
        int n = s.length();
        int idx = n - shift;
        return s.substring(idx) + s.substring(0, idx);
    }
}

