public class Solution {
    public int visiblePoints(List<List<Integer>> points, int angle, List<Integer> location) {
        int sameLocation = 0;
        List<Double> angles = new ArrayList<>();

        int px = location.get(0);
        int py = location.get(1);

        for (List<Integer> p : points) {
            int x = p.get(0);
            int y = p.get(1);
            if (x == px && y == py) {
                sameLocation++;
            } else {
                double ang = Math.toDegrees(Math.atan2(y - py, x - px));
                if (ang < 0) ang += 360.0;
                angles.add(ang);
            }
        }

        if (angles.isEmpty()) {
            return sameLocation;
        }

        Collections.sort(angles);
        int n = angles.size();
        // duplicate angles with +360 to handle wrap-around
        for (int i = 0; i < n; i++) {
            angles.add(angles.get(i) + 360.0);
        }

        double angLimit = angle;
        int maxVisible = 0;
        int j = 0;
        int total = angles.size();
        for (int i = 0; i < n; i++) {
            while (j < total && angles.get(j) - angles.get(i) <= angLimit + 1e-9) {
                j++;
            }
            maxVisible = Math.max(maxVisible, j - i);
        }

        return maxVisible + sameLocation;
    }
}

