            all[i + n] = angleList.get(i) + 360.0;
        }

        int maxVisible = 0;
        int j = 0;
        double eps = 1e-9;
        for (int i = 0; i < n; i++) {
            if (j < i) j = i;
            double limit = angleList.get(i) + angle + eps;
            while (j < i + n && all[j] <= limit) {
                j++;
            }
            maxVisible = Math.max(maxVisible, j - i);
        }

        return maxVisible + sameCount;
    }
