        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) dist[i][j] = Integer.MAX_VALUE / 2;
            dist[i][i] = 0;
            Queue<Integer> q = new ArrayDeque<>();
            q.add(i);
            while (!q.isEmpty()) {
                int cur = q.poll();
                for (int nxt : adj[cur]) {
                    if (dist[i][nxt] > dist[i][cur] + 1) {
                        dist[i][nxt] = dist[i][cur] + 1;
                        q.add(nxt);
                    }
                }
            }
        }

        int totalMasks = 1 << n;
        int[] result = new int[n - 1];

        for (int mask = 1; mask < totalMasks; mask++) {
            int cnt = Integer.bitCount(mask);
            if (cnt < 2) continue; // diameter zero, skip

            // Check connectivity
            int first = Integer.numberOfTrailingZeros(mask);
            boolean[] visited = new boolean[n];
            Queue<Integer> q = new ArrayDeque<>();
            q.add(first);
            visited[first] = true;
            int visitedCnt = 1;
            while (!q.isEmpty()) {
                int cur = q.poll();
                for (int nxt : adj[cur]) {
                    if (((mask >> nxt) & 1) == 1 && !visited[nxt]) {
                        visited[nxt] = true;
                        q.add(nxt);
                        visitedCnt++;
                    }
                }
            }
            if (visitedCnt != cnt) continue; // not connected

            // Compute diameter
            int diameter = 0;
            for (int i = 0; i < n; i++) {
                if (((mask >> i) & 1) == 0) continue;
                for (int j = i + 1; j < n; j++) {
                    if (((mask >> j) & 1) == 0) continue;
                    if (dist[i][j] > diameter) diameter = dist[i][j];
                }
            }
            if (diameter > 0 && diameter <= n - 1) {
                result[diameter - 1]++;
            }
        }
        return result;
    }
}

