public class Solution {
    public int[] countSubgraphsForEachDiameter(int n, int[][] edges) {
        // Build adjacency list
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0] - 1;
            int v = e[1] - 1;
            adj[u].add(v);
            adj[v].add(u);
        }

        int totalMasks = 1 << n;
        int[] result = new int[n]; // result[diameter] count, ignore index 0

        // For each subset
        for (int mask = 1; mask < totalMasks; mask++) {
            // skip single node subsets: diameter 0 not needed
            if ((mask & (mask - 1)) == 0) continue; // only one bit set

            // Find first node in subset
            int start = Integer.numberOfTrailingZeros(mask);

            // First BFS to check connectivity and get farthest node from start
            int[] dist = new int[n];
            Arrays.fill(dist, -1);
            Queue<Integer> q = new ArrayDeque<>();
            q.add(start);
            dist[start] = 0;
            int visitedCount = 0;
            int farNode = start;

            while (!q.isEmpty()) {
                int u = q.poll();
                visitedCount++;
                if (dist[u] > dist[farNode]) farNode = u;
                for (int v : adj[u]) {
                    if (((mask >> v) & 1) == 1 && dist[v] == -1) {
                        dist[v] = dist[u] + 1;
                        q.add(v);
                    }
                }
            }

            if (visitedCount != Integer.bitCount(mask)) continue; // not connected

            // Second BFS from farNode to find diameter
            Arrays.fill(dist, -1);
            q.clear();
            q.add(farNode);
            dist[farNode] = 0;
            int diameter = 0;
            while (!q.isEmpty()) {
                int u = q.poll();
                diameter = Math.max(diameter, dist[u]);
                for (int v : adj[u]) {
                    if (((mask >> v) & 1) == 1 && dist[v] == -1) {
                        dist[v] = dist[u] + 1;
                        q.add(v);
                    }
                }
            }

            if (diameter >= 1 && diameter <= n - 1) {
                result[diameter]++;
            }
        }

        // Prepare output array (1-indexed d)
        int[] ans = new int[n - 1];
        for (int d = 1; d <= n - 1; d++) ans[d - 1] = result[d];
        return ans;
    }
}

