import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;

public class Solution {
    public int[] countSubgraphsForEachDiameter(int n, int[][] edges) {
        // Build adjacency list
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0] - 1;
            int v = e[1] - 1;
            adj[u].add(v);
            adj[v].add(u);
        }

        int totalMasks = 1 << n;
        int[] res = new int[n - 1];

        for (int mask = 1; mask < totalMasks; mask++) {
            int size = Integer.bitCount(mask);
            if (size <= 1) continue; // diameter 0, ignore

            // Check connectivity
            int first = Integer.numberOfTrailingZeros(mask);
            boolean[] visited = new boolean[n];
            Queue<Integer> q = new ArrayDeque<>();
            q.add(first);
            visited[first] = true;
            int visitedCnt = 1;

            while (!q.isEmpty()) {
                int u = q.poll();
                for (int v : adj[u]) {
                    if (((mask >> v) & 1) == 1 && !visited[v]) {
                        visited[v] = true;
                        q.add(v);
                        visitedCnt++;
                    }
                }
            }
            if (visitedCnt != size) continue; // not connected

            // First BFS to find farthest node
            int[] far1 = bfs(first, mask, adj);
            int[] far2 = bfs(far1[0], mask, adj);
            int diameter = far2[1];
            res[diameter - 1]++;
        }

        return res;
    }

    // Returns {farthestNode, maxDistance}
    private int[] bfs(int src, int mask, List<Integer>[] adj) {
        boolean[] seen = new boolean[adj.length];
        Queue<Integer> q = new ArrayDeque<>();
        int[] dist = new int[adj.length];
        q.add(src);
        seen[src] = true;
        dist[src] = 0;
        int farNode = src;
        int maxDist = 0;

        while (!q.isEmpty()) {
            int u = q.poll();
            if (dist[u] > maxDist) {
                maxDist = dist[u];
                farNode = u;
            }
            for (int v : adj[u]) {
                if (((mask >> v) & 1) == 1 && !seen[v]) {
                    seen[v] = true;
                    dist[v] = dist[u] + 1;
                    q.add(v);
                }
            }
        }
        return new int[]{farNode, maxDist};
    }
}

