public class Solution {
    public int[] decrypt(int[] code, int k) {
        int n = code.length;
        int[] result = new int[n];
        if (k == 0) {
            return code.clone();
        }
        int m = Math.abs(k);
        long sum = 0;
        if (k > 0) {
            // initial sum of next k elements for index 0
            for (int i = 1; i <= m; i++) {
                sum += code[i % n];
            }
            for (int i = 0; i < n; i++) {
                result[i] = (int) sum;
                // slide window: remove code[(i+1)%n], add code[(i+m+1)%n]
                sum -= code[(i + 1) % n];
                sum += code[(i + m + 1) % n];
            }
        } else { // k < 0
            // initial sum of previous m elements for index 0
            for (int i = 1; i <= m; i++) {
                sum += code[(n - i) % n];
            }
            for (int i = 0; i < n; i++) {
                result[i] = (int) sum;
                // slide window: remove code[(i - m + n) % n], add code[i % n]
                sum -= code[(i - m + n) % n];
                sum += code[i % n];
            }
        }
        return result;
    }
}

