    public int[] decrypt(int[] code, int k) {
        int n = code.length;
        int[] res = new int[n];
        if (k == 0) {
            System.arraycopy(code, 0, res, 0, n);
            return res;
        }
        for (int i = 0; i < n; i++) {
            int sum = 0;
            if (k > 0) {
                int idx = i + 1;
                for (int j = 0; j < k; j++) {
                    sum += code[(idx + n) % n];
                    idx++;
                }
            } else {
                int idx = i - 1;
                for (int j = 0; j < -k; j++) {
                    sum += code[(idx + n) % n];
                    idx--;
                }
            }
            res[i] = sum;
        }
        return res;
    }
}

