public class Solution {
    public int[] decrypt(int[] code, int k) {
        int n = code.length;
        if (n == 0) return new int[0];
        int[] res = new int[n];

        if (k == 0) {
            return res; // all zeros
        }

        int kAbs = Math.abs(k);
        // Build extended array to avoid modular arithmetic in prefix sums
        int[] extended = new int[2 * n];
        System.arraycopy(code, 0, extended, 0, n);
        System.arraycopy(code, 0, extended, n, n);

        int[] prefix = new int[2 * n + 1];
        for (int i = 0; i < 2 * n; i++) {
            prefix[i + 1] = prefix[i] + extended[i];
        }

        if (k > 0) {
            for (int i = 0; i < n; i++) {
                int start = i + 1;
                int end = i + k;
                res[i] = prefix[end + 1] - prefix[start];
            }
        } else { // k < 0
            for (int i = 0; i < n; i++) {
                res[i] = prefix[i + n] - prefix[i + n - kAbs];
            }
        }

        return res;
    }
}

