public class Solution {
    private static class Pair {
        int pos;
        boolean back;
        Pair(int pos, boolean back) {
            this.pos = pos;
            this.back = back;
        }
        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Pair)) return false;
            Pair p = (Pair) o;
            return pos == p.pos && back == p.back;
        }
        @Override
        public int hashCode() {
            return 31 * pos + (back ? 1 : 0);
        }
    }

    public int minimumJumps(int[] forbidden, int a, int b, int x) {
        if (x == 0) return 0;

        Set<Integer> forbiddenSet = new HashSet<>();
        int maxForbidden = 0;
        for (int f : forbidden) {
            forbiddenSet.add(f);
            if (f > maxForbidden) maxForbidden = f;
        }

        int limit = Math.max(maxForbidden + a + b, x + a + b);

        Queue<Pair> queue = new LinkedList<>();
        Set<Pair> visited = new HashSet<>();
        Pair start = new Pair(0, false);
        queue.offer(start);
        visited.add(start);

        int steps = 0;
        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                Pair cur = queue.poll();
                int pos = cur.pos;
                boolean back = cur.back;

                // Forward jump
                int nextPos = pos + a;
                if (nextPos == x) return steps + 1;
                if (nextPos <= limit && !forbiddenSet.contains(nextPos)) {
                    Pair next = new Pair(nextPos, false);
                    if (!visited.contains(next)) {
                        visited.add(next);
                        queue.offer(next);
                    }
                }

                // Backward jump (only if previous move was not backward)
                if (!back) {
                    int nextPosB = pos - b;
                    if (nextPosB == x) return steps + 1;
                    if (nextPosB >= 0 && !forbiddenSet.contains(nextPosB)) {
                        Pair next = new Pair(nextPosB, true);
                        if (!visited.contains(next)) {
                            visited.add(next);
                            queue.offer(next);
                        }
                    }
                }
            }
            steps++;
        }
        return -1;
    }
}

