import java.util.HashSet;
import java.util.LinkedList;
import java.util.Queue;
import java.util.Set;

public class Solution {

    // Helper class to represent a state in BFS
    private static class State {
        int pos;
        boolean lastWasBackward;
        int steps;

        State(int pos, boolean lastWasBackward, int steps) {
            this.pos = pos;
            this.lastWasBackward = lastWasBackward;
            this.steps = steps;
        }
    }

    public int minimumJumps(int[] forbidden, int a, int b, int x) {
        if (x == 0) {
            return 0;
        }

        Set<Integer> forbiddenSet = new HashSet<>();
        for (int f : forbidden) {
            forbiddenSet.add(f);
        }

        int maxForbidden = 0;
        for (int f : forbidden) {
            if (f > maxForbidden) {
                maxForbidden = f;
            }
        }

        // Define an upper bound for positions to consider
        int limit = Math.max(x, maxForbidden) + a + b + 5;

        Set<String> visited = new HashSet<>();
        Queue<State> queue = new LinkedList<>();
        queue.offer(new State(0, false, 0));
        visited.add(encode(0, false));

        while (!queue.isEmpty()) {
            State cur = queue.poll();

            // Forward jump
            int nextPos = cur.pos + a;
            if (nextPos == x) {
                return cur.steps + 1;
            }
            if (nextPos >= 0 && nextPos <= limit && !forbiddenSet.contains(nextPos) && !visited.contains(encode(nextPos, false))) {
                visited.add(encode(nextPos, false));
                queue.offer(new State(nextPos, false, cur.steps + 1));
            }

            // Backward jump (only if last move was not backward)
            if (!cur.lastWasBackward) {
                int backPos = cur.pos - b;
                if (backPos == x) {
                    return cur.steps + 1;
                }
                if (backPos >= 0 && backPos <= limit && !forbiddenSet.contains(backPos) && !visited.contains(encode(backPos, true))) {
                    visited.add(encode(backPos, true));
                    queue.offer(new State(backPos, true, cur.steps + 1));
                }
            }
        }

        return -1;
    }

    // Helper to encode state into a string for visited set
    private String encode(int pos, boolean lastWasBackward) {
        return pos + "#" + lastWasBackward;
    }
