public class Solution {
    public int waysToMakeFair(int[] nums) {
        int n = nums.length;
        if (n == 0) return 0;

        int[] prefixEven = new int[n];
        int[] prefixOdd = new int[n];
        int[] suffixEven = new int[n];
        int[] suffixOdd = new int[n];

        // Build prefix sums
        for (int i = 0; i < n; i++) {
            if (i == 0) {
                prefixEven[i] = (i % 2 == 0) ? nums[i] : 0;
                prefixOdd[i] = (i % 2 == 1) ? nums[i] : 0;
            } else {
                prefixEven[i] = prefixEven[i - 1] + ((i % 2 == 0) ? nums[i] : 0);
                prefixOdd[i] = prefixOdd[i - 1] + ((i % 2 == 1) ? nums[i] : 0);
            }
        }

        // Build suffix sums
        for (int i = n - 1; i >= 0; i--) {
            if (i == n - 1) {
                suffixEven[i] = (i % 2 == 0) ? nums[i] : 0;
                suffixOdd[i] = (i % 2 == 1) ? nums[i] : 0;
            } else {
                suffixEven[i] = suffixEven[i + 1] + ((i % 2 == 0) ? nums[i] : 0);
                suffixOdd[i] = suffixOdd[i + 1] + ((i % 2 == 1) ? nums[i] : 0);
            }
        }

        int count = 0;
        for (int i = 0; i < n; i++) {
            int evenSum = (i > 0 ? prefixEven[i - 1] : 0) + (i < n - 1 ? suffixOdd[i + 1] : 0);
            int oddSum = (i > 0 ? prefixOdd[i - 1] : 0) + (i < n - 1 ? suffixEven[i + 1] : 0);
            if (evenSum == oddSum) {
                count++;
            }
        }
        return count;
    }
}

