import java.util.LinkedList;
import java.util.Queue;

public class Solution {
    public int countStudents(int[] students, int[] sandwiches) {
        Queue<Integer> queue = new LinkedList<>();
        for (int s : students) queue.offer(s);

        int stackIndex = 0; // index of current top sandwich
        int attempts = 0;   // consecutive students that didn't take the sandwich

        while (!queue.isEmpty() && attempts < queue.size() && stackIndex < sandwiches.length) {
            int student = queue.poll();
            int sandwich = sandwiches[stackIndex];
            if (student == sandwich) {
                // student takes the sandwich
                stackIndex++;
                attempts = 0; // reset attempts because a sandwich was taken
            } else {
                // student goes to the back of the queue
                queue.offer(student);
                attempts++;
            }
        }
        return queue.size();
    }
}

