public class Solution {
    public int minimumMountainRemovals(int[] nums) {
        int n = nums.length;
        if (n < 3) {
            return n;
        }
        // Longest increasing subsequence ending at each position
        int[] lis = new int[n];
        int[] tails = new int[n];
        int size = 0;
        for (int i = 0; i < n; i++) {
            int pos = Arrays.binarySearch(tails, 0, size, nums[i]);
            if (pos < 0) pos = -pos - 1;
            tails[pos] = nums[i];
            lis[i] = pos + 1;
            if (pos == size) size++;
        }

        // Longest decreasing subsequence starting at each position
        int[] rev = new int[n];
        for (int i = 0; i < n; i++) {
            rev[i] = -nums[n - 1 - i];
        }
        int[] ldsRev = new int[n];
        Arrays.fill(tails, 0);
        size = 0;
        for (int i = 0; i < n; i++) {
            int pos = Arrays.binarySearch(tails, 0, size, rev[i]);
            if (pos < 0) pos = -pos - 1;
            tails[pos] = rev[i];
            ldsRev[i] = pos + 1;
            if (pos == size) size++;
        }
        int[] lds = new int[n];
        for (int i = 0; i < n; i++) {
            lds[i] = ldsRev[n - 1 - i];
        }

        int maxLen = 0;
        for (int i = 0; i < n; i++) {
            if (lis[i] > 1 && lds[i] > 1) {
                int len = lis[i] + lds[i] - 1;
                if (len >= 3 && len > maxLen) {
                    maxLen = len;
                }
            }
        }

        if (maxLen == 0) {
            return n;
        }
        return n - maxLen;
    }
