public class Solution {
    private static class Node implements Comparable<Node> {
        int r, c, effort;
        Node(int r, int c, int effort) {
            this.r = r;
            this.c = c;
            this.effort = effort;
        }
        @Override
        public int compareTo(Node other) {
            return Integer.compare(this.effort, other.effort);
        }
    }

    public int minimumEffortPath(int[][] heights) {
        int rows = heights.length;
        int cols = heights[0].length;
        boolean[][] visited = new boolean[rows][cols];
        int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
        PriorityQueue<Node> pq = new PriorityQueue<>();
        pq.offer(new Node(0, 0, 0));

        while (!pq.isEmpty()) {
            Node cur = pq.poll();
            int r = cur.r;
            int c = cur.c;
            int effort = cur.effort;
            if (visited[r][c]) continue;
            visited[r][c] = true;
            if (r == rows - 1 && c == cols - 1) return effort;

            for (int[] d : dirs) {
                int nr = r + d[0];
                int nc = c + d[1];
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
                if (visited[nr][nc]) continue;
                int nextEffort = Math.max(effort, Math.abs(heights[nr][nc] - heights[r][c]));
                pq.offer(new Node(nr, nc, nextEffort));
            }
        }
        return 0; // unreachable, but per problem statement this won't happen
    }
}

