public class Solution {
    public int stoneGameVII(int[] stones) {
        int n = stones.length;
        if (n == 0) return 0;
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + stones[i];
        }
        long[][] dp = new long[n][n];
        for (int len = 2; len <= n; len++) {
            for (int l = 0; l + len <= n; l++) {
                int r = l + len - 1;
                long leftPoints = prefix[r + 1] - prefix[l + 1];
                long rightPoints = prefix[r] - prefix[l];
                dp[l][r] = Math.max(leftPoints - dp[l + 1][r], rightPoints - dp[l][r - 1]);
            }
        }
        return (int) dp[0][n - 1];
    }
}

