public class Solution {

    // Helper class to represent a busy server
    public static class Server {
        int id;
        int busyTime; // time when the server will become free

        public Server(int id, int busyTime) {
            this.id = id;
            this.busyTime = busyTime;
        }
    }

    public List<Integer> busiestServers(int k, int[] arrival, int[] load) {
        // Count of handled requests per server
        int[] count = new int[k];

        // Set of currently available servers
        TreeSet<Integer> available = new TreeSet<>();
        for (int i = 0; i < k; i++) {
            available.add(i);
        }

        // Priority queue of busy servers ordered by finish time
        PriorityQueue<Server> busy = new PriorityQueue<>(Comparator.comparingInt(s -> s.busyTime));

        for (int i = 0; i < arrival.length; i++) {
            int currentTime = arrival[i];

            // Release servers that have finished before or at current time
            while (!busy.isEmpty() && busy.peek().busyTime <= currentTime) {
                Server finished = busy.poll();
                available.add(finished.id);
            }

            if (available.isEmpty()) {
                // All servers busy, drop request
                continue;
            }

            // Find the server to assign
            int startIdx = i % k;
            Integer serverId = available.ceiling(startIdx);
            if (serverId == null) {
                serverId = available.first();
            }

            // Assign request
            available.remove(serverId);
            busy.offer(new Server(serverId, currentTime + load[i]));
            count[serverId]++;
        }

        // Find maximum handled requests
        int max = 0;
        for (int c : count) {
            if (c > max) {
                max = c;
            }
        }

        // Collect all servers with maximum count
        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            if (count[i] == max) {
                result.add(i);
            }
        }

        return result;
    }
}

