import java.util.List;
import java.util.PriorityQueue;
import java.util.TreeSet;

public class Solution {

    /** A helper class to represent a server and when it will finish the current job. */
    static class Server {
        int id;          // server id
        int busyUntil;   // time until which the server is busy

        Server(int id, int busyUntil) {
            this.id = id;
            this.busyUntil = busyUntil;
        }
    }

    /**
     * Returns the list of busiest servers.
     *
     * @param k      number of servers
     * @param arrival arrival times of the requests
     * @param load    processing time required for each request
     * @return list of server ids that handled the most requests
     */
    public List<Integer> busiestServers(int k, int[] arrival, int[] load) {
        int n = arrival.length;
        int[] count = new int[k];                    // number of requests handled by each server
        TreeSet<Integer> idle = new TreeSet<>();     // ids of idle servers (ordered)
        for (int i = 0; i < k; ++i) idle.add(i);

        PriorityQueue<Server> busy = new PriorityQueue<>(Comparator.comparingInt(s -> s.busyUntil));

        for (int i = 0; i < n; ++i) {
            int curTime = arrival[i];

            // Release servers that have finished before the current request arrives
            while (!busy.isEmpty() && busy.peek().busyUntil <= curTime) {
                idle.add(busy.poll().id);
            }

            if (idle.isEmpty()) {
                // all servers are busy, request is dropped
                continue;
            }

            // Determine the server to try first
            int target = i % k;
            Integer serverId = idle.ceiling(target);
            if (serverId == null) {
                serverId = idle.first(); // wrap around
            }

            // Assign the request to the chosen server
            idle.remove(serverId);
            count[serverId]++;

            int finishTime = curTime + load[i];
            busy.offer(new Server(serverId, finishTime));
        }

        // Find the maximum number of requests handled by any server
        int max = 0;
        for (int c : count) {
            if (c > max) max = c;
        }

        // Collect all server ids that achieved the maximum
        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < k; ++i) {
            if (count[i] == max) {
                result.add(i);
            }
        }

        return result;
    }

    /** Provided constructor in the template – not used directly in the algorithm. */
    public Server(int id, int busyTime) {
        // This method is intentionally left to satisfy the template requirement.
        // It returns a new Server instance with the specified id and busyUntil time.
        return new Server(id, busyTime);
    }
}

