import java.util.*;

public class Solution {
    private static final int MOD = 1_000_000_007;

    /**
     * Returns the number of ways to choose k disjoint pairs from 1..n.
     *
     * @param n number of points (1 ≤ n)
     * @param k number of pairs (k ≥ 0)
     * @return number of valid selections modulo 1 000 000 007
     */
    public int numberOfWays(int n, int k) {
        long a = (long) n + k - 1;       // A = n + k - 1
        long b = 2L * k;                // B = 2k

        if (b > a) return 0;            // impossible, answer is 0

        int maxI = (int) b;             // 0 ≤ maxI = 2k
        long[] inv = new long[maxI + 1];
        if (maxI >= 1) inv[1] = 1;
        for (int i = 2; i <= maxI; i++) {
            inv[i] = MOD - (MOD / i) * inv[MOD % i] % MOD;
        }

        long res = 1;
        for (int i = 1; i <= maxI; i++) {
            long term = (long) n - k - 1 + i;   // = n - k - 1 + i
            term %= MOD;
            if (term < 0) term += MOD;
            res = res * term % MOD;
            res = res * inv[i] % MOD;
        }
        return (int) res;
    }

    // ---------- for quick testing ----------
    public static void main(String[] args) {
        PairwiseDisjointPairs solver = new PairwiseDisjointPairs();
        System.out.println(solver.numberOfWays(4, 1)); // 6
        System.out.println(solver.numberOfWays(2, 1)); // 0
        System.out.println(solver.numberOfWays(1, 0)); // 1
        System.out.println(solver.numberOfWays(5, 3)); // 7
    }
}

