        res = res * invFact[twoK] % MOD;
        res = res * invFact[mInt] % MOD;
        return (int) res;
    }

    private long modPow(long base, long exp) {
        long result = 1L;
        long b = base % MOD;
        long e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                result = result * b % MOD;
            }
            b = b * b % MOD;
            e >>= 1;
        }
        return result;
