public class Solution {
    private static final int MOD = 1_000_000_007;

    public int numberSets(int n, int k) {
        if (k == 0) return 1;
        if (n == 0) return 0;

        int size = n + 1;
        long[] prev = new long[size];
        // dp[i][0] = 1 for all i
        for (int i = 0; i < size; i++) {
            prev[i] = 1;
        }

        for (int interval = 1; interval <= k; interval++) {
            long[] pref = new long[size];
            pref[0] = prev[0];
            for (int i = 1; i < size; i++) {
                pref[i] = (pref[i - 1] + prev[i]) % MOD;
            }

            long[] cur = new long[size];
            long curVal = 0;
            for (int i = 1; i < size; i++) {
                long add = pref[i - 1] - pref[0];
                if (add < 0) add += MOD;
                curVal += add;
                if (curVal >= MOD) curVal -= MOD;
                cur[i] = curVal;
            }
            prev = cur;
        }
        return (int) prev[n];
    }
}

