public class Solution {
    public int stoneGame(int[] aliceValues, int[] bobValues) {
        int n = aliceValues.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, new Comparator<Integer>() {
            @Override
            public int compare(Integer a, Integer b) {
                int sumA = aliceValues[a] + bobValues[a];
                int sumB = aliceValues[b] + bobValues[b];
                return Integer.compare(sumB, sumA); // descending
            }
        });

        long aliceScore = 0;
        long bobScore = 0;
        for (int turn = 0; turn < n; turn++) {
            int i = idx[turn];
            if (turn % 2 == 0) { // Alice's turn
                aliceScore += aliceValues[i];
            } else { // Bob's turn
                bobScore += bobValues[i];
            }
        }

        if (aliceScore > bobScore) return 1;
        if (aliceScore < bobScore) return -1;
        return 0;
    }
}

