public class Solution {
    /**
     * Determines the winner of the stone picking game.
     *
     * @param aliceValues array of points Alice receives for each stone
     * @param bobValues   array of points Bob receives for each stone
     * @return 1 if Alice wins, -1 if Bob wins, 0 if it's a draw
     */
    public int stoneGame(int[] aliceValues, int[] bobValues) {
        int n = aliceValues.length;
        if (n == 0) return 0;

        // Create a list of indices sorted by (alice + bob) descending
        Integer[] indices = new Integer[n];
        for (int i = 0; i < n; i++) indices[i] = i;
        Arrays.sort(indices, (i, j) -> {
            long sumI = (long) aliceValues[i] + bobValues[i];
            long sumJ = (long) aliceValues[j] + bobValues[j];
            return Long.compare(sumJ, sumI); // descending
        });

        long diff = 0; // Alice's points minus Bob's points
        for (int turn = 0; turn < n; turn++) {
            int idx = indices[turn];
            if ((turn & 1) == 0) { // Alice's turn
                diff += aliceValues[idx];
            } else { // Bob's turn
                diff -= bobValues[idx];
            }
        }

        if (diff > 0) return 1;
        if (diff < 0) return -1;
        return 0;
    }
}

