public class Solution {
    public int stoneGame(int[] aliceValues, int[] bobValues) {
        int n = aliceValues.length;
        int[][] stones = new int[n][3]; // [alice, bob, total]
        for (int i = 0; i < n; i++) {
            stones[i][0] = aliceValues[i];
            stones[i][1] = bobValues[i];
            stones[i][2] = aliceValues[i] + bobValues[i];
        }

        Arrays.sort(stones, (a, b) -> Integer.compare(b[2], a[2]));

        long aliceScore = 0;
        long bobScore = 0;
        for (int i = 0; i < n; i++) {
            if (i % 2 == 0) {
                aliceScore += stones[i][0];
            } else {
                bobScore += stones[i][1];
            }
        }

        if (aliceScore > bobScore) return 1;
        if (bobScore > aliceScore) return -1;
        return 0;
    }
}

