import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    public int minimumEffort(int[][] tasks) {
        if (tasks == null || tasks.length == 0) return 0;

        // Sort by (minimum - actual) in descending order
        Arrays.sort(tasks, new Comparator<int[]>() {
            @Override
            public int compare(int[] a, int[] b) {
                int diffA = a[1] - a[0];
                int diffB = b[1] - b[0];
                return Integer.compare(diffB, diffA);
            }
        });

        long cumulativeActual = 0;
        long requiredEnergy = 0;

        for (int[] task : tasks) {
            int actual = task[0];
            int minimum = task[1];
            long need = (long) minimum + cumulativeActual;
            if (need > requiredEnergy) {
                requiredEnergy = need;
            }
            cumulativeActual += actual;
        }

        return (int) requiredEnergy;
    }
}

