import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    public int minimumEffort(int[][] tasks) {
        if (tasks == null || tasks.length == 0) {
            return 0;
        }

        Arrays.sort(tasks, new Comparator<int[]>() {
            @Override
            public int compare(int[] t1, int[] t2) {
                long a1 = t1[0];
                long m1 = t1[1];
                long a2 = t2[0];
                long m2 = t2[1];

                long left = Math.max(m1, m2 + a1);
                long right = Math.max(m2, m1 + a2);

                return Long.compare(left, right);
            }
        });

        long sumActual = 0;
        long required = 0;

        for (int[] task : tasks) {
            long actual = task[0];
            long minimum = task[1];

            long candidate = minimum + sumActual;
            if (candidate > required) {
                required = candidate;
            }
            sumActual += actual;
        }

        return (int) required;
    }
}

