import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    // Disjoint Set Union (Union-Find) implementation
    private static class DSU {
        private final int[] parent;
        private final int[] rank;

        DSU(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]); // path compression
            }
            return parent[x];
        }

        void union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);
            if (rootA == rootB) return;
            if (rank[rootA] < rank[rootB]) {
                parent[rootA] = rootB;
            } else if (rank[rootA] > rank[rootB]) {
                parent[rootB] = rootA;
            } else {
                parent[rootB] = rootA;
                rank[rootA]++;
            }
        }
    }

    public boolean[] distanceLimitedPathsExist(int[][] edgeList, int[][] queries) {
        // Determine number of nodes
        int maxNode = -1;
        for (int[] e : edgeList) {
            maxNode = Math.max(maxNode, Math.max(e[0], e[1]));
        }
        for (int[] q : queries) {
            maxNode = Math.max(maxNode, Math.max(q[0], q[1]));
        }
        int n = maxNode + 1;

        // Sort edges by weight (distance)
        Arrays.sort(edgeList, Comparator.comparingInt(a -> a[2]));

        // Prepare queries with original indices
        int m = queries.length;
        int[][] queryInfo = new int[m][4]; // p, q, limit, originalIndex
        for (int i = 0; i < m; i++) {
            queryInfo[i][0] = queries[i][0];
            queryInfo[i][1] = queries[i][1];
            queryInfo[i][2] = queries[i][2];
            queryInfo[i][3] = i;
        }
        Arrays.sort(queryInfo, Comparator.comparingInt(a -> a[2]));

        boolean[] answer = new boolean[m];
        DSU dsu = new DSU(n);
        int eIdx = 0;
        for (int[] q : queryInfo) {
            int p = q[0], r = q[1], limit = q[2], idx = q[3];
            // Add all edges with weight < limit
            while (eIdx < edgeList.length && edgeList[eIdx][2] < limit) {
                dsu.union(edgeList[eIdx][0], edgeList[eIdx][1]);
                eIdx++;
            }
            answer[idx] = dsu.find(p) == dsu.find(r);
        }
        return answer;
    }
}

