public class Solution {
    // Disjoint Set Union (Union-Find) data structure
    private static class DSU {
        private final int[] parent;
        private final int[] rank;

        DSU(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]); // Path compression
            }
            return parent[x];
        }

        void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX == rootY) {
                return;
            }
            // Union by rank
            if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }

    public boolean[] distanceLimitedPathsExist(int n, int[][] edgeList, int[][] queries) {
        // Sort edges by distance ascending
        Arrays.sort(edgeList, (a, b) -> Integer.compare(a[2], b[2]));

        // Augment queries with original index
        int m = queries.length;
        int[][] qWithIndex = new int[m][4];
        for (int i = 0; i < m; i++) {
            qWithIndex[i][0] = queries[i][0];
            qWithIndex[i][1] = queries[i][1];
            qWithIndex[i][2] = queries[i][2];
            qWithIndex[i][3] = i;
        }

        // Sort queries by limit ascending
        Arrays.sort(qWithIndex, (a, b) -> Integer.compare(a[2], b[2]));

        boolean[] answer = new boolean[m];
        DSU dsu = new DSU(n);
        int edgeIdx = 0;

        for (int[] q : qWithIndex) {
            int p = q[0];
            int qNode = q[1];
            int limit = q[2];
            int origIdx = q[3];

            // Add all edges with distance < limit
            while (edgeIdx < edgeList.length && edgeList[edgeIdx][2] < limit) {
                dsu.union(edgeList[edgeIdx][0], edgeList[edgeIdx][1]);
                edgeIdx++;
            }

            answer[origIdx] = dsu.find(p) == dsu.find(qNode);
        }

        return answer;
    }
}

