public class Solution {

    private static class Dsu {
        private final int[] parent;
        private final int[] size;

        Dsu(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        }

        void union(int a, int b) {
            int pa = find(a);
            int pb = find(b);
            if (pa == pb) return;
            if (size[pa] < size[pb]) {
                parent[pa] = pb;
                size[pb] += size[pa];
            } else {
                parent[pb] = pa;
                size[pa] += size[pb];
            }
        }
    }

    public boolean[] distanceLimitedPathsExist(int n, int[][] edgeList, int[][] queries) {
        int qCount = queries.length;
        boolean[] answer = new boolean[qCount];

        // Attach original index to each query
        int[][] queriesWithIndex = new int[qCount][4];
        for (int i = 0; i < qCount; i++) {
            queriesWithIndex[i][0] = queries[i][0];
            queriesWithIndex[i][1] = queries[i][1];
            queriesWithIndex[i][2] = queries[i][2];
            queriesWithIndex[i][3] = i;
        }

        Arrays.sort(queriesWithIndex, (a, b) -> Integer.compare(a[2], b[2]));
        Arrays.sort(edgeList, (a, b) -> Integer.compare(a[2], b[2]));

        Dsu dsu = new Dsu(n);
        int eIdx = 0;

        for (int[] q : queriesWithIndex) {
            while (eIdx < edgeList.length && edgeList[eIdx][2] < q[2]) {
                dsu.union(edgeList[eIdx][0], edgeList[eIdx][1]);
                eIdx++;
            }
            answer[q[3]] = dsu.find(q[0]) == dsu.find(q[1]);
        }

        return answer;
    }
