public class Solution {
    private int n;
    private int[][] requests;
    private int best;
    private int m;
    private int[] diff;

    public int maximumRequests(int n, int[][] requests) {
        this.n = n;
        this.requests = requests;
        this.m = requests.length;
        this.diff = new int[n];
        this.best = 0;
        dfs(0, 0);
        return best;
    }

    private void dfs(int idx, int count) {
        if (idx == m) {
            if (isBalanced()) {
                if (count > best) best = count;
            }
            return;
        }

        // Prune if even taking all remaining cannot beat current best
        if (count + (m - idx) <= best) return;

        // Option 1: include current request
        int from = requests[idx][0];
        int to = requests[idx][1];
        diff[from]--;
        diff[to]++;
        dfs(idx + 1, count + 1);
        diff[from]++; // backtrack
        diff[to]--;

        // Option 2: exclude current request
        dfs(idx + 1, count);
    }

    private boolean isBalanced() {
        for (int d : diff) {
            if (d != 0) return false;
        }
        return true;
    }
}

