public class Solution {
    public int maximumRequests(int n, int[][] requests) {
        int m = requests.length;
        int max = 0;
        int totalSubsets = 1 << m;
        for (int mask = 0; mask < totalSubsets; mask++) {
            int[] diff = new int[n];
            int count = 0;
            boolean ok = true;
            for (int i = 0; i < m; i++) {
                if ((mask & (1 << i)) != 0) {
                    int from = requests[i][0];
                    int to = requests[i][1];
                    diff[from]--;
                    diff[to]++;
                    count++;
                }
            }
            for (int val : diff) {
                if (val != 0) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                max = Math.max(max, count);
            }
        }
        return max;
    }
}

