public class Solution {
    public int maximumRequests(int n, int[][] requests) {
        int m = requests.length;
        int max = 0;
        int[] diff = new int[n];

        int totalMasks = 1 << m;
        for (int mask = 0; mask < totalMasks; mask++) {
            Arrays.fill(diff, 0);
            int count = Integer.bitCount(mask);
            if (count <= max) continue; // skip if cannot improve

            int tempMask = mask;
            int idx = 0;
            while (tempMask != 0) {
                if ((tempMask & 1) == 1) {
                    int from = requests[idx][0];
                    int to = requests[idx][1];
                    diff[from]--;
                    diff[to]++;
                }
                idx++;
                tempMask >>= 1;
            }

            boolean ok = true;
            for (int v : diff) {
                if (v != 0) {
                    ok = false;
                    break;
                }
            }

            if (ok) {
                max = count;
            }
        }

        return max;
    }
}

