public class Solution {
    public int maxWidthOfVerticalArea(int[][] points) {
        if (points == null || points.length < 2) {
            return 0;
        }
        int n = points.length;
        int[] xs = new int[n];
        for (int i = 0; i < n; i++) {
            xs[i] = points[i][0];
        }
        Arrays.sort(xs);
        int maxGap = 0;
        for (int i = 1; i < n; i++) {
            int gap = xs[i] - xs[i - 1];
            if (gap > maxGap) {
                maxGap = gap;
            }
        }
        return maxGap;
    }
}

