public class Solution {
    public int maxLengthBetweenEqualCharacters(String s) {
        int[] firstIndex = new int[26];
        for (int i = 0; i < 26; i++) {
            firstIndex[i] = -1;
        }
        int maxLen = -1;
        for (int i = 0; i < s.length(); i++) {
            int idx = s.charAt(i) - 'a';
            if (firstIndex[idx] == -1) {
                firstIndex[idx] = i;
            } else {
                int len = i - firstIndex[idx] - 1;
                if (len > maxLen) {
                    maxLen = len;
                }
            }
        }
        return maxLen;
    }
}

