public class Solution {
    public int maxLengthBetweenEqualCharacters(String s) {
        HashMap<Character, Integer> firstIndex = new HashMap<>();
        int maxLen = -1;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (!firstIndex.containsKey(c)) {
                firstIndex.put(c, i);
            } else {
                int len = i - firstIndex.get(c) - 1;
                if (len > maxLen) {
                    maxLen = len;
                }
            }
        }
        return maxLen;
    }
}

