import java.util.HashMap;
import java.util.Map;

public class Solution {

    public int minOperations(int[] nums, int x) {
        int n = nums.length;
        long total = 0;
        for (int v : nums) total += v;

        // If we need to remove all elements
        if (total == x) return n;
        // If we need to remove nothing
        if (x == 0) return 0;

        long target = total - x;          // we need a subarray with this sum
        if (target < 0) return -1;        // impossible

        int maxLen = -1;                  // length of the longest subarray with sum = target
        long sum = 0;
        int left = 0;
        Map<Long, Integer> map = new HashMap<>();
        map.put(0L, -1);                  // prefix sum before start

        for (int right = 0; right < n; right++) {
            sum += nums[right];
            long need = sum - target;     // prefix sum that would give desired subarray
            if (map.containsKey(need)) {
                int len = right - map.get(need);
                if (len > maxLen) maxLen = len;
            }
            // store earliest occurrence of this prefix sum
            map.putIfAbsent(sum, right);
        }

        return maxLen == -1 ? -1 : n - maxLen;
    }
}

