import java.util.Arrays;

public class Solution {
    public int countVowelStrings(int n) {
        // There are 5 vowels: a, e, i, o, u.
        // A lexicographically sorted string over these vowels is equivalent to
        // choosing a multiset of size `n` from 5 types, where each type can be
        // used any number of times (including zero) and ordering is non‑decreasing.
        // The number of such strings is C(n+5‑1, 5‑1) = C(n+4, 4).
        long result = 1;
        // Compute C(n+4, 4) iteratively to avoid overflow in intermediate values.
        for (int i = 1; i <= 4; i++) {
            result = result * (n + 4 - (4 - i)) / i;
        }
        return (int) result;
    }
}

