import java.util.Arrays;

public class Solution {
    public int specialArray(int[] nums) {
        int n = nums.length;
        if (n == 0) {
            // For an empty array, 0 numbers are >= 0, so x = 0 satisfies the condition.
            return 0;
        }

        Arrays.sort(nums); // ascending order

        // Check for x from n down to 1
        for (int x = n; x >= 1; x--) {
            int idx = lowerBound(nums, x); // first index with value >= x
            int count = n - idx;           // number of elements >= x
            if (count == x) {
                return x;
            }
        }

        // No valid x found
        return -1;
    }

    // Returns the first index where nums[idx] >= target
    private int lowerBound(int[] nums, int target) {
        int l = 0, r = nums.length;
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (nums[mid] >= target) {
                r = mid;
            } else {
                l = mid + 1;
            }
        }
        return l;
    }
}

