public class Solution {
    public int specialArray(int[] nums) {
        int n = nums.length;
        // Case of an empty array – x = 0 is the only possible answer
        if (n == 0) {
            return 0;
        }

        // 1. Sort ascending
        int[] a = nums.clone();
        Arrays.sort(a);

        // 2. Build the descending order array
        int[] desc = new int[n];
        for (int i = 0; i < n; i++) {
            desc[i] = a[n - 1 - i];
        }

        // 3. Scan for a valid x
        for (int i = 0; i < n; i++) {
            int x = i + 1;               // candidate x
            if (desc[i] >= x) {
                // exactly x elements are >= x ?
                if (i + 1 == n || desc[i + 1] < x) {
                    return x;
                }
            }
        }

        // No suitable x found
        return -1;
    }
}

