        int n = s.length();
        int[] suffixA = new int[n + 1];
        for (int i = n - 1; i >= 0; i--) {
            suffixA[i] = suffixA[i + 1] + (s.charAt(i) == 'a' ? 1 : 0);
        }

        int prefixB = 0;
        int minDel = Integer.MAX_VALUE;
        for (int i = 0; i <= n; i++) {
