public class Solution {
    public int minimumDeletions(String s) {
        int n = s.length();
        // prefixA[i] = number of 'a's in s[0..i-1]
        int[] prefixA = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefixA[i + 1] = prefixA[i] + (s.charAt(i) == 'a' ? 1 : 0);
        }
        // suffixB[i] = number of 'b's in s[i..n-1]
        int[] suffixB = new int[n + 1];
        suffixB[n] = 0;
        for (int i = n - 1; i >= 0; i--) {
            suffixB[i] = suffixB[i + 1] + (s.charAt(i) == 'b' ? 1 : 0);
        }
        int maxSubseq = 0;
        for (int split = 0; split <= n; split++) {
            maxSubseq = Math.max(maxSubseq, prefixA[split] + suffixB[split]);
        }
        return n - maxSubseq;
    }
}

