import java.util.*;

public class Solution {
    public int bestTeamScore(int[] scores, int[] ages) {
        int n = scores.length;
        if (n == 0) return 0;
        Pair[] players = new Pair[n];
        for (int i = 0; i < n; i++) {
            players[i] = new Pair(ages[i], scores[i]);
        }
        Arrays.sort(players, Comparator.comparingInt(p -> p.age));
        Map<Integer, Integer> rank = new HashMap<>();
        int idx = 0;
        for (Pair p : players) {
            rank.putIfAbsent(p.score, idx++);
        }
        int maxRank = rank.size();
        Fenwick bit = new Fenwick(maxRank);
        int ans = 0;
        for (Pair p : players) {
            int r = rank.get(p.score);
            int best = bit.query(r - 1);
            int val = best + p.score;
            bit.update(r, val);
            ans = Math.max(ans, val);
        }
        return ans;
    }

    private static final class Pair {
        int age, score;
        Pair(int age, int score) { this.age = age; this.score = score; }
    }

    private static final class Fenwick {
        private final int n;
        private final int[] tree;
        Fenwick(int n) { this.n = n; this.tree = new int[n + 1]; }
        void update(int idx, int val) { for (; idx <= n; idx += idx & -idx) tree[idx] = Math.max(tree[idx], val); }
        int query(int idx) { int res = 0; for (; idx > 0; idx -= idx & -idx) res = Math.max(res, tree[idx]); return res; }
    }
}

