public class Solution {
    public int maxProfit(int[] inventory, int orders) {
        final long MOD = 1_000_000_007L;
        Arrays.sort(inventory);
        int n = inventory.length;
        long result = 0;
        int idx = n - 1;
        while (orders > 0 && idx >= 0) {
            int current = inventory[idx];
            int next = (idx > 0) ? inventory[idx - 1] : 0;
            long diff = current - next;
            long count = idx + 1; // number of colors at this level or higher
            long sellable = diff * count;
            if (sellable <= orders) {
                // sell all from current down to next+1
                long sum = (current + next + 1) * diff / 2; // sum of integers from next+1 to current
                result = (result + sum % MOD * count % MOD) % MOD;
                orders -= sellable;
                idx--; // move to next level
            } else {
                // sell only part of this level
                long fullLevels = orders / count;
                long remaining = orders % count;
                long high = current;
                long low = current - fullLevels;
                long sum = (high + low + 1) * fullLevels / 2; // sum of fullLevels numbers
                result = (result + sum % MOD * count % MOD) % MOD;
                result = (result + remaining * (high - fullLevels) % MOD) % MOD;
                orders = 0;
            }
        }
        return (int) result;
    }
}

