public class Solution {
    public int maxProfit(int[] inventory, int orders) {
        final long MOD = 1_000_000_007L;
        int n = inventory.length;
        long[] arr = new long[n + 1];
        for (int i = 0; i < n; i++) {
            arr[i] = inventory[i];
        }
        arr[n] = 0; // sentinel
        Arrays.sort(arr);
        long totalProfit = 0;
        int remaining = orders;
        // process from highest to lowest
        for (int i = n; i > 0; i--) {
            long current = arr[i];
            long next = arr[i - 1];
            long diff = current - next;
            if (diff == 0) continue;
            long colors = i; // number of colors with at least 'current' balls
            long maxSell = diff * colors;
            if (remaining >= maxSell) {
                // sell all in this segment
                long sumLevels = (current + next + 1) * diff / 2; // sum of levels from current down to next+1
                totalProfit = (totalProfit + sumLevels % MOD * (colors % MOD)) % MOD;
                remaining -= maxSell;
            } else {
                long fullLevels = remaining / colors;
                long rem = remaining % colors;
                long high = current;
                long low = current - fullLevels + 1;
                long sumFull = (high + low) * fullLevels / 2;
                totalProfit = (totalProfit + sumFull % MOD * (colors % MOD)) % MOD;
                totalProfit = (totalProfit + (current - fullLevels) % MOD * (rem % MOD)) % MOD;
                remaining = 0;
                break;
            }
        }
        return (int)totalProfit;
    }
}

