public class Solution {
    public int maxProfit(int[] inventory, int orders) {
        int n = inventory.length;
        int[] arr = inventory.clone();
        Arrays.sort(arr); // ascending
        final long MOD = 1_000_000_007L;
        final long INV2 = 500_000_004L; // modular inverse of 2 modulo MOD
        long result = 0L;
        int i = n - 1; // start from the largest value

        while (orders > 0 && i >= 0) {
            long cur = arr[i];
            long next = (i > 0 ? arr[i - 1] : 0);
            long diff = cur - next;            // number of levels we can sell at this value
            long count = diff * (long) (i + 1); // total balls we can sell from these levels

            if (orders <= count) {
                // We sell only a part of these levels
                long fullLevels = orders / (long)(i + 1);   // complete levels to sell
                long remainder = orders % (long)(i + 1);   // remaining balls after full levels

                long high = cur;
                long low = cur - fullLevels + 1;          // inclusive
                long sumFull = ((fullLevels % MOD) *
                        ((high % MOD + low % MOD) % MOD) % MOD *
                        INV2 % MOD) % MOD;

                long valueAfterFull = (cur - fullLevels) % MOD;
                long sumRem = (remainder % MOD) * valueAfterFull % MOD;

                result = (result + sumFull + sumRem) % MOD;
                break; // all orders processed
            } else {
                // We take all the levels from cur down to next + 1
                long levelCount = i + 1L;
                long high = cur;
                long low = next + 1; // inclusive lower bound
                long terms = diff;   // number of terms in the arithmetic series

                long sumSeries = ((terms % MOD) *
                        ((high % MOD + low % MOD) % MOD) % MOD *
                        INV2 % MOD) % MOD;

                result = (result + sumSeries * levelCount) % MOD;
                orders -= count;
                i--; // move to the next lower level
            }
        }
        return (int) result;
    }
}

