public class Solution {
    private static final long MOD = 1_000_000_007L;

    public int maxProfit(int[] inventory, int orders) {
        Arrays.sort(inventory);
        int n = inventory.length;
        long profit = 0;
        int idx = n - 1;                     // index of current maximum count
        while (orders > 0 && idx >= 0) {
            int current = inventory[idx];
            int next = (idx > 0) ? inventory[idx - 1] : 0;
            int diff = current - next;       // difference between current level and next level
            long countColors = idx + 1L;     // number of colors that have at least 'current' balls
            long totalBalls = diff * countColors; // total balls that can be sold to reach 'next' level

            if (orders >= totalBalls) {
                // sell all balls from current level down to next+1 for these colors
                long sumLevels = (long)(current + next + 1) * diff / 2; // sum of arithmetic series per color
                profit = (profit + sumLevels % MOD * countColors % MOD) % MOD;
                orders -= totalBalls;
                idx--;                         // move to next level
            } else {
                // we cannot reduce all the way to 'next', we only need 'orders' balls
                long fullLayers = orders / countColors;   // full layers we can sell
                long rem = orders % countColors;          // remaining balls after full layers

                if (fullLayers > 0) {
                    long start = current;
                    long end = current - fullLayers + 1; // inclusive
                    long sumLevels = (start + end) * fullLayers / 2; // per color
                    profit = (profit + sumLevels % MOD * countColors % MOD) % MOD;
                }

                // sell the remaining 'rem' balls at the next value after full layers
                if (rem > 0) {
                    long value = current - fullLayers;
                    profit = (profit + (value % MOD) * (rem % MOD)) % MOD;
                }

                orders = 0; // all orders satisfied
            }
        }
        return (int) profit;
    }
}

