public class Solution {
    // Preprocess stickers into character counts
    private int[][] stickerCounts;
    private Map<String, Integer> memo;

    public int minStickers(String[] stickers, String target) {
        int n = stickers.length;
        stickerCounts = new int[n][26];
        for (int i = 0; i < n; i++) {
            for (char c : stickers[i].toCharArray()) {
                stickerCounts[i][c - 'a']++;
            }
        }
        memo = new HashMap<>();
        int ans = dfs(target);
        return ans == Integer.MAX_VALUE ? -1 : ans;
    }

    private int dfs(String target) {
        if (target.isEmpty()) return 0;
        if (memo.containsKey(target)) return memo.get(target);

        // Convert target to sorted string to have canonical form
        char[] arr = target.toCharArray();
        java.util.Arrays.sort(arr);
        target = new String(arr);

        int targetCount[] = new int[26];
        for (char c : target.toCharArray()) targetCount[c - 'a']++;

        int ans = Integer.MAX_VALUE;
        // Choose first character in target to reduce branching
        int firstCharIdx = -1;
        for (int i = 0; i < 26; i++) {
            if (targetCount[i] > 0) {
                firstCharIdx = i;
                break;
            }
        }

        for (int i = 0; i < stickerCounts.length; i++) {
            if (stickerCounts[i][firstCharIdx] == 0) continue; // skip useless stickers

            // Apply sticker i to current target
            String nextTarget = applySticker(targetCount, stickerCounts[i]);
            int sub = dfs(nextTarget);
            if (sub != Integer.MAX_VALUE) {
                ans = Math.min(ans, 1 + sub);
            }
        }

        memo.put(target, ans);
        return ans;
    }

    private String applySticker(int[] targetCount, int[] sticker) {
        int[] remaining = targetCount.clone();
        for (int i = 0; i < 26; i++) {
            remaining[i] = Math.max(0, remaining[i] - sticker[i]);
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 26; i++) {
            for (int j = 0; j < remaining[i]; j++) {
                sb.append((char) ('a' + i));
            }
        }
        return sb.toString();
    }
}

