    private int dfs(String target, int[][] stickers, HashMap<String, Integer> memo) {
        if (target.isEmpty()) return 0;
        if (memo.containsKey(target)) return memo.get(target);

        int[] targetCnt = new int[26];
        for (char ch : target.toCharArray()) {
            targetCnt[ch - 'a']++;
        }

        int ans = Integer.MAX_VALUE;
        for (int[] sticker : stickers) {
            // skip stickers that don't reduce anything
            boolean used = false;
            int[] newCnt = new int[26];
            System.arraycopy(targetCnt, 0, newCnt, 0, 26);
            for (int c = 0; c < 26; c++) {
                if (sticker[c] > 0 && newCnt[c] > 0) {
                    int use = Math.min(newCnt[c], sticker[c]);
                    newCnt[c] -= use;
                    used = true;
                }
            }
            if (!used) continue;

            StringBuilder sb = new StringBuilder();
            for (int c = 0; c < 26; c++) {
                for (int k = 0; k < newCnt[c]; k++) {
                    sb.append((char) (c + 'a'));
                }
            }
            String newTarget = sb.toString();
            int sub = dfs(newTarget, stickers, memo);
            if (sub != -1) {
                ans = Math.min(ans, 1 + sub);
            }
        }

        memo.put(target, ans == Integer.MAX_VALUE ? -1 : ans);
        return ans == Integer.MAX_VALUE ? -1 : ans;
    }
}

