        Collections.sort(trees, Comparator.comparingInt(a -> a[0]));
        int totalSteps = 0;
        int curR = 0, curC = 0;
        for (int[] tree : trees) {
            int targetR = tree[1];
            int targetC = tree[2];
            int steps = bfs(grid, curR, curC, targetR, targetC);
            if (steps == -1) return -1;
            totalSteps += steps;
            curR = targetR;
            curC = targetC;
        }
        return totalSteps;
    }

    private int bfs(int[][] grid, int sr, int sc, int tr, int tc) {
        int m = grid.length;
        int n = grid[0].length;
        if (sr == tr && sc == tc) return 0;
        boolean[][] visited = new boolean[m][n];
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{sr, sc, 0});
        visited[sr][sc] = true;
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};
