                if (visited[nr][nc] || grid[nr][nc] == 0) continue;
                if (nr == tr && nc == tc) return d + 1;
                visited[nr][nc] = true;
                q.offer(new int[]{nr, nc, d + 1});
            }
        }
        return -1;
    }
}

