        Collections.sort(trees, Comparator.comparingInt(t -> t.height));

        int steps = 0;
        int curX = 0, curY = 0;

        if (grid[0][0] == 0) return -1;

        for (Tree tree : trees) {
            int d = bfs(grid, curX, curY, tree.x, tree.y);
            if (d == -1) return -1;
            steps += d;
            curX = tree.x;
            curY = tree.y;
        }

        return steps;
    }

    private int bfs(int[][] grid, int sx, int sy, int tx, int ty) {
        int m = grid.length;
        int n = grid[0].length;
        if (sx == tx && sy == ty) return 0;

        boolean[][] vis = new boolean[m][n];
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{sx, sy, 0});
        vis[sx][sy] = true;
        int[] dx = {1, -1, 0, 0};
        int[] dy = {0, 0, 1, -1};

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int x = cur[0], y = cur[1], d = cur[2];
            for (int dir = 0; dir < 4; dir++) {
                int nx = x + dx[dir];
                int ny = y + dy[dir];
                if (nx < 0 || nx >= m || ny < 0 || ny >= n) continue;
                if (vis[nx][ny]) continue;
                if (grid[nx][ny] == 0) continue;
                if (nx == tx && ny == ty) return d + 1;
                vis[nx][ny] = true;
                q.offer(new int[]{nx, ny, d + 1});
            }
        }
        return -1;
    }

