                // '*' can represent 1-9
                dp[i + 1] = (dp[i + 1] + 9 * dp[i]) % MOD;
            }

            // Two-digit decoding (10-26)
            if (i > 0) {
                char prev = s.charAt(i - 1);
                if (prev == '1') {
                    // "10" to "19"
                    if (c == '*') {
                        dp[i + 1] = (dp[i + 1] + dp[i - 1]) % MOD; // 1-9 => 9 possibilities
                    } else {
                        dp[i + 1] = (dp[i + 1] + dp[i - 1]) % MOD;
                    }
                } else if (prev == '2') {
                    // "20" to "26"
                    if (c == '*') {
                        dp[i + 1] = (dp[i + 1] + dp[i - 1]) % MOD; // 2-6 => 5 possibilities
                    } else if (c >= '0' && c <= '6') {
                        dp[i + 1] = (dp[i + 1] + dp[i - 1]) % MOD;
                    }
                } else if (prev == '*') {
                    // prev can be 1 or 2
                    if (c == '*') {
                        // "11" to "26" (9 + 5 = 14 possibilities)
                        dp[i + 1] = (dp[i + 1] + 14 * dp[i - 1]) % MOD;
                    } else {
                        // '*' treated as 1-9
                        // valid pairs are 10-26 => we need to check c
                        if (c >= '0' && c <= '6') {
                            dp[i + 1] = (dp[i + 1] + dp[i - 1]) % MOD; // 2c (20-26)
                        }
                        if (c >= '7' && c <= '9') {
                            dp[i + 1] = (dp[i + 1] + dp[i - 1]) % MOD; // 1c (17-19)
                        }
                    }
                }
            }
        }

