public class Solution {
    private static final double TARGET = 24.0;
    private static final double EPS = 1e-6;

    public boolean judge24(int[] cards) {
        List<Double> nums = new ArrayList<>();
        for (int c : cards) {
            nums.add((double) c);
        }
        return dfs(nums);
    }

    private boolean dfs(List<Double> nums) {
        int n = nums.size();
        if (n == 1) {
            return Math.abs(nums.get(0) - TARGET) < EPS;
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                List<Double> next = new ArrayList<>();
                for (int k = 0; k < n; k++) {
                    if (k != i && k != j) {
                        next.add(nums.get(k));
                    }
                }

                double a = nums.get(i);
                double b = nums.get(j);

                // Addition
                if (i < j) { // avoid duplicate commutative operations
                    next.add(a + b);
                    if (dfs(next)) return true;
                    next.remove(next.size() - 1);
                }

                // Subtraction
                next.add(a - b);
                if (dfs(next)) return true;
                next.remove(next.size() - 1);

                // Multiplication
                if (i < j) {
                    next.add(a * b);
                    if (dfs(next)) return true;
                    next.remove(next.size() - 1);
                }

                // Division
                if (Math.abs(b) > EPS) {
                    next.add(a / b);
                    if (dfs(next)) return true;
                    next.remove(next.size() - 1);
                }
            }
        }
        return false;
    }
}

