public class Solution {
    public List<Integer> fallingSquares(int[][] positions) {
        // Coordinate compression
        TreeSet<Integer> set = new TreeSet<>();
        for (int[] pos : positions) {
            int left = pos[0];
            int right = pos[0] + pos[1];
            set.add(left);
            set.add(right);
        }
        List<Integer> coords = new ArrayList<>(set);
        int n = coords.size() - 1; // number of intervals

        // Segment tree arrays
        int[] tree = new int[4 * n];
        int[] lazy = new int[4 * n];
        for (int i = 0; i < lazy.length; i++) {
            lazy[i] = -1; // -1 indicates no pending assignment
        }

        List<Integer> ans = new ArrayList<>();
        int globalMax = 0;

        for (int[] pos : positions) {
            int left = pos[0];
            int right = pos[0] + pos[1];
            int l = Collections.binarySearch(coords, left);
            int r = Collections.binarySearch(coords, right);
            // Query current max height in [l, r-1]
            int curMax = query(tree, lazy, 1, 0, n - 1, l, r - 1);
            int newHeight = curMax + pos[1];
            // Update the interval with new height
            update(tree, lazy, 1, 0, n - 1, l, r - 1, newHeight);
            globalMax = Math.max(globalMax, newHeight);
            ans.add(globalMax);
        }

        return ans;
    }

    private int query(int[] tree, int[] lazy, int node, int start, int end, int l, int r) {
        if (l > end || r < start) {
            return 0;
        }
        if (l <= start && end <= r) {
            return tree[node];
        }
        push(tree, lazy, node);
        int mid = (start + end) >> 1;
        int leftMax = query(tree, lazy, node << 1, start, mid, l, r);
        int rightMax = query(tree, lazy, node << 1 | 1, mid + 1, end, l, r);
        return Math.max(leftMax, rightMax);
    }

    private void update(int[] tree, int[] lazy, int node, int start, int end, int l, int r, int val) {
        if (l > end || r < start) {
            return;
        }
        if (l <= start && end <= r) {
            tree[node] = val;
            lazy[node] = val;
            return;
        }
        push(tree, lazy, node);
        int mid = (start + end) >> 1;
        update(tree, lazy, node << 1, start, mid, l, r, val);
        update(tree, lazy, node << 1 | 1, mid + 1, end, l, r, val);
        tree[node] = Math.max(tree[node << 1], tree[node << 1 | 1]);
    }

    private void push(int[] tree, int[] lazy, int node) {
        if (lazy[node] != -1) {
            int val = lazy[node];
            tree[node << 1] = val;
            tree[node << 1 | 1] = val;
            lazy[node << 1] = val;
            lazy[node << 1 | 1] = val;
            lazy[node] = -1;
        }
    }
}

