        if (l <= start && end <= r) return tree[node];
        int mid = (start + end) >>> 1;
        int leftMax = query(tree, node * 2 + 1, start, mid, l, r);
        int rightMax = query(tree, node * 2 + 2, mid + 1, end, l, r);
        return Math.max(leftMax, rightMax);
    }

    // Helper: update interval [l, r] with value val
    private void update(int[] tree, int node, int start, int end, int l, int r, int val) {
        if (l > end || r < start) return;
        if (l <= start && end <= r) {
            tree[node] = val;
            return;
        }
        int mid = (start + end) >>> 1;
        update(tree, node * 2 + 1, start, mid, l, r, val);
        update(tree, node * 2 + 2, mid + 1, end, l, r, val);
        tree[node] = Math.max(tree[node * 2 + 1], tree[node * 2 + 2]);
    }
}

