    private TrieNode buildTrie(List<String> dictionary) {
        TrieNode root = new TrieNode();
        for (String dictWord : dictionary) {
            TrieNode node = root;
            for (char ch : dictWord.toCharArray()) {
                node = node.children.computeIfAbsent(ch, k -> new TrieNode());
