            node = node.children.get(ch);
            if (node == null) {
                break;
            }
            if (node.isEnd) {
                candidate = node.word;  // first terminal along the path → shortest root
                break;
            }
        }
        return candidate;
    }

    public String replaceWords(List<String> dictionary, String sentence) {
        // Edge cases: null or empty inputs
        if (dictionary == null || dictionary.isEmpty() || sentence == null) {
