    private final TrieNode root = new TrieNode();

    // Insert a root into the trie
    private void insert(String word) {
        TrieNode node = root;
        for (char ch : word.toCharArray()) {
            node = node.children.computeIfAbsent(ch, k -> new TrieNode());
        }
        node.isWord = true;
        node.root = word;   // store the root at the terminal node
    }

    // Find the shortest root that matches the prefix of 'word'
    private String searchShortestRoot(String word) {
        TrieNode node = root;
        String best = null;
        for (char ch : word.toCharArray()) {
            node = node.children.get(ch);
            if (node == null) {
                break;
            }
            if (node.isWord) {
                // Found a root; store the shortest found so far
                if (best == null || node.root.length() < best.length()) {
                    best = node.root;
                }
            }
        }
