import java.util.*;

public class Solution {
    public int strangePrinter(String s) {
        int n = s.length();
        // Edge case: empty string
        if (n == 0) return 0;

        // Remove consecutive duplicates
        StringBuilder sb = new StringBuilder();
        char prev = 0;
        for (char c : s.toCharArray()) {
            if (c != prev) {
                sb.append(c);
                prev = c;
            }
        }
        char[] chars = sb.toString().toCharArray();
        n = chars.length;

        int[][] dp = new int[n][n];
        for (int[] row : dp) Arrays.fill(row, -1);

        // Recursive helper with memoization
        return solve(chars, 0, n - 1, dp);
    }

    private int solve(char[] c, int i, int j, int[][] dp) {
        if (i > j) return 0;

        if (dp[i][j] != -1) return dp[i][j];

        // If the characters at the ends are the same, we can keep them together
        if (c[i] == c[j]) {
            dp[i][j] = solve(c, i, j - 1, dp);
        } else {
            int best = Integer.MAX_VALUE;
            for (int k = i; k < j; k++) {
                int left = solve(c, i, k, dp);
                int right = solve(c, k + 1, j, dp);
                best = Math.min(best, left + right - 1);
            }
            dp[i][j] = best;
        }
        return dp[i][j];
    }
}

