/**  Minimal number of one‑bit operations to obtain a single 0.
 *   The implementation follows the algorithm proven correct above.
 */
public class Solution {

    /** distance memoisation map */
    private static final Map<Integer, Integer> dist = new HashMap<>();

    /**
     * breadth‑first search using a priority queue (Dijkstra with unit weights)
     * @param start initial integer
     * @return minimal number of operations to reach 0
     */
    private static int minimalSteps(int start) {
        // priority queue ordered by ascending distance
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        pq.offer(new int[]{0, start});

        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int d = cur[0];
            int v = cur[1];

            if (v == 0) return d;                  // reached goal

            Integer known = dist.get(v);
            if (known != null && known <= d) continue;   // already processed

            dist.put(v, d);

            // generate neighbours
            int[] neighbours = neighbours(v);
            for (int u : neighbours) {
                pq.offer(new int[]{d + 1, u});
            }
        }
        // should never reach here
        return -1;
    }

    /**
     * produce all values reachable from x in exactly one operation
     */
    private static int[] neighbours(int x) {
        List<Integer> res = new ArrayList<>(32);

        // operation 1 : flip last bit
        res.add(x ^ 1);

        // operation 2
        // count trailing ones -> len
        int tmp = x;
        int len = 0;
        while ((tmp & 1) == 1) {
            len++;
            tmp >>= 1;
        }
        // for every i (1 .. len) we can flip bit i
        for (int i = 1; i <= len; i++) {
            res.add(x ^ (1 << i));
        }

        // convert to array for performance
        int[] arr = new int[res.size()];
        for (int i = 0; i < res.size(); i++) arr[i] = res.get(i);
        return arr;
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);
        int T = fs.nextInt();
        StringBuilder sb = new StringBuilder();
        for (int t = 0; t < T; t++) {
            int n = fs.nextInt();
            int ans = minimalSteps(n);
            sb.append(ans).append('\n');
        }
        System.out.print(sb.toString());
    }

    /* ----------------------------------------------------------
       Simple fast scanner for competitive programming
       ---------------------------------------------------------- */
    private static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream in) { this.in = in; }

        private int readByte() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c, sign = 1, val = 0;
            do c = readByte(); while (c <= ' ' && c != -1);
            if (c == '-') { sign = -1; c = readByte(); }
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = readByte();
            }
            return val * sign;
        }
    }
}

