#include <bits/stdc++.h>
using namespace std;

/*  -------------------------------------------------------------
    BFS over all integers reachable from n
    ------------------------------------------------------------- */
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    if (!(cin >> n)) return 0;          // no input
    if (n == 0) { cout << 0 << '\n'; return 0; }

    unordered_set<long long> vis;       // already visited
    queue<pair<long long,int>> q;       // (current value , distance)

    vis.reserve(2 * (n+1));
    q.emplace(n, 0);
    vis.insert(n);

    while (!q.empty()) {
        auto [x, d] = q.front(); q.pop();
        if (x == 0) { cout << d << '\n'; break; }

        /* ----- 1. toggle the 0‑th bit ----- */
        long long y = x ^ 1LL;          // flip bit 0
        if (vis.insert(y).second)       // not visited yet
            q.emplace(y, d+1);

        /* ----- 2. toggle a higher bit ----- */
        /* admissible only when the whole number is 2^(i-1) or
           2^(i-1)+2^i  ->  the binary representation has
           exactly one set bit at position i-1.                */
        if ((x & (x-1)) == 0) {         // only one bit set
            // find its position
            int pos = 0;
            long long tmp = x;
            while (tmp > 1) { tmp >>= 1; ++pos; }

            // toggle bit (pos+1)
            long long z = x ^ (1LL << (pos+1));
            if (vis.insert(z).second)
                q.emplace(z, d+1);
        }
    }
    return 0;
}

