                prefix[j] = (prefix[j - 1] + dp[i - 1][j]) % MOD;
            }
            for (int j = 0; j <= k; j++) {
                long val = prefix[j];
                if (j >= i) {
                    val = (val - prefix[j - i] + MOD) % MOD;
                }
                dp[i][j] = val;
            }
        }
        return (int) dp[n][k];
    }
}

