public class Solution {
    private static final int MOD = 1_000_000_007;

    public int kInversePairs(int n, int k) {
        // Maximum possible inverse pairs for n numbers is n*(n-1)/2
        if (k > n * (n - 1) / 2) {
            return 0;
        }

        int[][] dp = new int[n + 1][k + 1];
        dp[0][0] = 1;

        for (int i = 1; i <= n; i++) {
            // prefix sum optimization to compute dp[i][j] efficiently
            int maxJ = Math.min(k, i * (i - 1) / 2);
            for (int j = 0; j <= maxJ; j++) {
                long val = dp[i - 1][j];
                if (j > 0) {
                    val += dp[i][j - 1];
                }
                if (j >= i) {
                    val -= dp[i - 1][j - i];
                }
                val %= MOD;
                if (val < 0) val += MOD;
                dp[i][j] = (int) val;
            }
        }
        return dp[n][k];
    }
}

