// #2022_03_21_Time_3_ms_(84.36%)_Space_54.4_MB_(17.04%)

import com_github_leetcode.TreeNode;

public class Solution {
    public TreeNode constructMaximumBinaryTree(int[] nums) {
        if (nums == null || nums.length == 0) {
            return null;
        }

        TreeNode[] stack = new TreeNode[nums.length];
        int top = -1;

        for (int val : nums) {
            TreeNode node = new TreeNode(val);

            // Pop smaller values and set them as left child
            while (top >= 0 && stack[top].val < val) {
                node.left = stack[top];
                top--;
            }

            // If there is still an element on stack, set current node as its right child
            if (top >= 0) {
                stack[top].right = node;
            }

            stack[++top] = node;
        }

        // The root is the first element in the stack
        return stack[0];
    }
}

