import java.util.HashSet;
import java.util.Set;

public class Solution {
    public int flipLights(int n, int m) {
        int evenCount = n / 2;
        int oddCount = n - evenCount;
        int odd3k1Count = (n + 5) / 6; // numbers i (1 ≤ i ≤ n) where i%3==1
        int oddNot3k1Count = oddCount - odd3k1Count;

        Set<String> configs = new HashSet<>();

        for (int p1 = 0; p1 < 2; p1++) {
            for (int p2 = 0; p2 < 2; p2++) {
                for (int p3 = 0; p3 < 2; p3++) {
                    for (int p4 = 0; p4 < 2; p4++) {
                        int sumP = p1 + p2 + p3 + p4;
                        if (sumP <= m && ((m - sumP) % 2 == 0)) {
                            int valEven = 1 ^ p1 ^ p2;           // even bulbs
                            int valOdd3k1 = 1 ^ p1 ^ p3 ^ p4;    // odd bulbs with i%3==1
                            int valOddNot = 1 ^ p1 ^ p3;         // odd bulbs with i%3!=1

                            StringBuilder sb = new StringBuilder();
                            if (evenCount > 0) sb.append(valEven).append(',');
                            if (odd3k1Count > 0) sb.append(valOdd3k1).append(',');
                            if (oddNot3k1Count > 0) sb.append(valOddNot).append(',');

                            configs.add(sb.toString());
                        }
                    }
                }
            }
        }

        return configs.size();
    }
}

