import java.util.*;

public class Solution {
    public int flipLights(int n, int m) {
        Set<BitSet> states = new HashSet<>();

        // Precompute patterns for each button
        BitSet evens = new BitSet(n);
        for (int i = 2; i <= n; i += 2) evens.set(i - 1);

        BitSet odds = new BitSet(n);
        for (int i = 1; i <= n; i += 2) odds.set(i - 1);

        BitSet mod3 = new BitSet(n);
        for (int i = 1; i <= n; i += 3) mod3.set(i - 1);

        // Enumerate all 16 combinations of button presses (parity only)
        for (int a = 0; a <= 1; a++) {
            for (int b = 0; b <= 1; b++) {
                for (int c = 0; c <= 1; c++) {
                    for (int d = 0; d <= 1; d++) {
                        int presses = a + b + c + d;
                        if (m < presses || ((m - presses) & 1) != 0) {
                            continue; // not achievable with exactly m presses
                        }

                        int x = a ^ b; // toggle even bulbs
                        int y = a ^ c; // toggle odd bulbs
                        int z = d;     // toggle bulbs with label 1 mod 3

                        BitSet w = new BitSet(n);
                        if (x == 1) w.xor(evens);
                        if (y == 1) w.xor(odds);
                        if (z == 1) w.xor(mod3);

                        states.add(w); // BitSet equality gives distinct states
                    }
                }
            }
        }

        return states.size();
    }
}

