import com_github_leetcode.Employee;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.ArrayDeque;
import java.util.Deque;

/**
 * Definition for Employee.
 * public class Solution {
 *     public int id;
 *     public int importance;
 *     public List<Integer> subordinates;
 * }
 */
public class Solution {
    public int getImportance(List<Employee> employees, int id) {
        if (employees == null || employees.isEmpty()) {
            return 0;
        }

        // Build a map from employee ID to Employee object for O(1) lookup.
        Map<Integer, Employee> idToEmployee = new HashMap<>();
        for (Employee e : employees) {
            idToEmployee.put(e.id, e);
        }

        int totalImportance = 0;
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(id);

        while (!stack.isEmpty()) {
            int currentId = stack.pop();
            Employee current = idToEmployee.get(currentId);
            if (current == null) {
                continue;
            }
            totalImportance += current.importance;
            for (int subId : current.subordinates) {
                stack.push(subId);
            }
        }

        return totalImportance;
    }
}

