public class Solution {
    public int minSteps(int n) {
        if (n <= 1) return 0;
        int[] dp = new int[n + 1];
        dp[1] = 0;
        for (int i = 2; i <= n; i++) {
            int min = i; // worst case: copy 1, paste i times
            for (int j = 1; j * j <= i; j++) {
                if (i % j == 0) {
                    int d1 = j;
                    int d2 = i / j;
                    // use d1 as the base
                    if (d1 < i) {
                        int candidate = dp[d1] + d2;
                        if (candidate < min) min = candidate;
                    }
                    // use d2 as the base (if different)
                    if (d2 != d1 && d2 < i) {
                        int candidate = dp[d2] + d1;
                        if (candidate < min) min = candidate;
                    }
                }
            }
            dp[i] = min;
        }
        return dp[n];
    }
}

