public class Solution {
    public int[] findErrorNums(int[] nums) {
        int n = nums.length;
        long sum = 0;
        long sumSq = 0;
        for (int num : nums) {
            sum += num;
            sumSq += (long) num * num;
        }
        long targetSum = (long) n * (n + 1) / 2;
        long targetSqSum = (long) n * (n + 1) * (2L * n + 1) / 6;
        long diff = sum - targetSum;          // duplicated - missing
        long sqDiff = sumSq - targetSqSum;    // duplicated^2 - missing^2
        long sumDupMissing = sqDiff / diff;   // duplicated + missing
        int duplicate = (int) ((diff + sumDupMissing) / 2);
        int missing = (int) (sumDupMissing - duplicate);
        return new int[]{duplicate, missing};
    }
}

