public class Solution {
    public int[] findRedundantDirectedConnection(int[][] edges) {
        int n = edges.length;
        int[] parent = new int[n + 1];
        int[] candidate1 = null;
        int[] candidate2 = null;

        // Detect node with two parents
        for (int[] edge : edges) {
            int u = edge[0], v = edge[1];
            if (parent[v] != 0) {
                candidate1 = new int[]{parent[v], v};
                candidate2 = new int[]{u, v};
                // Mark this edge as invalid by skipping union later
            } else {
                parent[v] = u;
            }
        }

        // Union-Find initialization
        int[] ufParent = new int[n + 1];
        int[] rank = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            ufParent[i] = i;
        }

        // Helper functions
        java.util.function.IntUnaryOperator find = new java.util.function.IntUnaryOperator() {
            @Override
            public int applyAsInt(int x) {
                if (ufParent[x] != x) {
                    ufParent[x] = applyAsInt(ufParent[x]);
                }
                return ufParent[x];
            }
        };

        java.util.function.BiConsumer<Integer, Integer> union = new java.util.function.BiConsumer<Integer, Integer>() {
            @Override
            public void accept(Integer a, Integer b) {
                int pa = find.applyAsInt(a);
                int pb = find.applyAsInt(b);
                if (pa == pb) return;
                if (rank[pa] < rank[pb]) {
                    ufParent[pa] = pb;
                } else if (rank[pa] > rank[pb]) {
                    ufParent[pb] = pa;
                } else {
                    ufParent[pb] = pa;
                    rank[pa]++;
                }
            }
        };

        // Process edges, skipping candidate2 if it exists
        for (int[] edge : edges) {
            int u = edge[0], v = edge[1];
            if (candidate2 != null && u == candidate2[0] && v == candidate2[1]) {
                continue; // skip the second edge causing two parents
            }
            if (find.applyAsInt(u) == find.applyAsInt(v)) {
                // Cycle detected
                if (candidate1 != null) {
                    return candidate1;
                } else {
                    return edge;
                }
            }
            union.accept(u, v);
        }

        // No cycle found; return the second edge causing two parents
        return candidate2;
    }
}

