public class Solution {
    public int[] findRedundantDirectedConnection(int[][] edges) {
        int n = edges.length;
        int[] parent = new int[n + 1];
        int[] candidate1 = null; // first edge causing double parent
        int[] candidate2 = null; // second edge causing double parent

        // Step 1: Detect node with two parents
        for (int[] edge : edges) {
            int u = edge[0], v = edge[1];
            if (parent[v] == 0) {
                parent[v] = u;
            } else {
                candidate1 = new int[]{parent[v], v};
                candidate2 = new int[]{u, v};
                // Mark this edge as invalid by skipping it later
                edge[0] = -1; // invalidate
            }
        }

        // Union-Find initialization
        int[] root = new int[n + 1];
        for (int i = 0; i <= n; i++) root[i] = i;

        // Helper to find root with path compression
        java.util.function.IntUnaryOperator find = new java.util.function.IntUnaryOperator() {
            public int applyAsInt(int x) {
                while (root[x] != x) {
                    root[x] = root[root[x]];
                    x = root[x];
                }
                return x;
            }
        };

        // Step 2: Run Union-Find while skipping candidate2 if present
        for (int[] edge : edges) {
            if (edge[0] == -1) continue; // skip the invalidated edge
            int u = edge[0], v = edge[1];
            int pu = find.applyAsInt(u);
            int pv = find.applyAsInt(v);
            if (pu == pv) {
                // Cycle detected
                if (candidate2 == null) {
                    // No node has two parents, so this edge is the answer
                    return new int[]{u, v};
                } else {
                    // Node has two parents and we removed the later edge earlier;
                    // So the earlier edge is the answer
