                cand1Idx = i;
                cand2 = new int[]{u, v};
                cand2Idx = i;
                // Keep parent[v] as u (the later one) for later tests
                parent[v] = u;
            }
        }

        // Helper to detect cycle with optional skipped edge
        UnionFind uf = new UnionFind(n);
        boolean cycleFound = false;
        for (int i = 0; i < edges.length; i++) {
            if (cand2Idx != -1 && i == cand2Idx) continue; // skip cand2
            int u = edges[i][0];
            int v = edges[i][1];
            if (!uf.union(u, v)) {
                cycleFound = true;
                break;
            }
        }

        if (cand1 != null) {
            if (!cycleFound) {
                return cand2;
            } else {
                return cand1;
            }
        } else {
            // No node with two parents, cycle must exist
            uf = new UnionFind(n);
            for (int i = 0; i < edges.length; i++) {
                int u = edges[i][0];
                int v = edges[i][1];
                if (!uf.union(u, v)) {
                    return edges[i];
                }
            }
        }
        // Should never reach here
        return new int[]{-1, -1};
    }

    private static class UnionFind {
        private int[] parent, rank;

        public UnionFind(int n) {
            parent = new int[n + 1];
            rank = new int[n + 1];
            for (int i = 1; i <= n; i++) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        public int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        public boolean union(int x, int y) {
            int xr = find(x);
            int yr = find(y);
            if (xr == yr) return false;
            if (rank[xr] < rank[yr]) {
                parent[xr] = yr;
            } else if (rank[xr] > rank[yr]) {
                parent[yr] = xr;
            } else {
                parent[yr] = xr;
                rank[xr]++;
            }
            return true;
        }
    }
}

