        for (int i = 1; i <= n; i++) {
            uf[i] = i;
        }

        if (cand1 != null) {
            // Try removing cand2
            for (int[] edge : edges) {
                if (edge[0] == cand2[0] && edge[1] == cand2[1]) {
                    continue; // skip cand2
                }
                int u = edge[0], v = edge[1];
                if (!union(uf, u, v)) {
                    // Adding this edge creates a cycle, so cand1 is the answer
                    return cand1;
                }
            }
            // No cycle when cand2 removed, so cand2 is the answer
            return cand2;
        } else {
            // No node has two parents, find the edge that creates a cycle
            for (int[] edge : edges) {
                int u = edge[0], v = edge[1];
                if (!union(uf, u, v)) {
                    return edge;
                }
            }
        }
        // Should never reach here
        return new int[0];
    }

    private boolean union(int[] uf, int u, int v) {
        int pu = find(uf, u);
        int pv = find(uf, v);
        if (pu == pv) {
            return false;
        }
        uf[pu] = pv;
        return true;
    }

    private int find(int[] uf, int x) {
        if (uf[x] != x) {
            uf[x] = find(uf, uf[x]);
        }
        return uf[x];
    }
