public class Solution {
    public int[] findRedundantDirectedConnection(int[][] edges) {
        int n = edges.length;
        int[] parent = new int[n + 1];
        int[] indegree = new int[n + 1];
        int[] firstEdge = null;
        int[] secondEdge = null;

        for (int i = 0; i < n; i++) {
            int u = edges[i][0];
            int v = edges[i][1];
            if (indegree[v] == 1) { // node v has two parents
                firstEdge = new int[]{parent[v], v};
                secondEdge = edges[i];
            } else {
                indegree[v] = 1;
                parent[v] = u;
            }
        }

        // Union-Find structure
        int[] root = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            root[i] = i;
        }

        // Helper to find root
        java.util.function.IntUnaryOperator find = new java.util.function.IntUnaryOperator() {
            @Override
            public int applyAsInt(int x) {
                if (root[x] != x) {
                    root[x] = this.applyAsInt(root[x]);
                }
                return root[x];
            }
        };

        // If there is a node with two parents
        if (firstEdge != null) {
            // Try removing the second edge
            for (int i = 0; i < n; i++) {
                if (i == Arrays.asList(secondEdge).hashCode()) { // skip secondEdge
                    continue;
                }
                int u = edges[i][0];
                int v = edges[i][1];
                int ru = find.applyAsInt(u);
                int rv = find.applyAsInt(v);
                if (ru == rv) { // cycle detected
                    return firstEdge;
                }
                root[rv] = ru;
            }
            return secondEdge;
        } else {
            // No node has two parents, so there must be a cycle
            for (int i = 0; i < n; i++) {
                int u = edges[i][0];
                int v = edges[i][1];
                int ru = find.applyAsInt(u);
                int rv = find.applyAsInt(v);
                if (ru == rv) {
                    return edges[i];
                }
                root[rv] = ru;
            }
        }
        return new int[]{-1, -1}; // Should not reach here
    }
