        {-2, -1}, {-1, -2}, {1, -2}, {2, -1}
    };

    public double knightProbability(int n, int k, int row, int column) {
        double[][][] dp = new double[k + 1][n][n];
        dp[0][row][column] = 1.0;

        for (int step = 1; step <= k; step++) {
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < n; c++) {
                    double currProb = dp[step - 1][r][c];
                    if (currProb == 0) continue;
                    for (int[] move : MOVES) {
                        int nr = r + move[0];
                        int nc = c + move[1];
                        if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                            dp[step][nr][nc] += currProb / 8.0;
                        }
                    }
                }
            }
        }

        double result = 0.0;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                result += dp[k][r][c];
            }
        }
        return result;
    }
}

