    public boolean checkValidString(String s) {
        int minOpen = 0; // minimum possible number of open '('
        int maxOpen = 0; // maximum possible number of open '('

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(') {
                minOpen++;
                maxOpen++;
            } else if (c == ')') {
                minOpen = Math.max(0, minOpen - 1);
                maxOpen--;
            } else { // '*'
                // '*' can be treated as ')', so decrease minOpen if possible
                minOpen = Math.max(0, minOpen - 1);
                // '*' can be treated as '(' or empty, so increase maxOpen
                maxOpen++;
            }

            // If at any point maxOpen becomes negative, there are more ')' than
            // possible '(' to match, so the string cannot be valid.
            if (maxOpen < 0) {
                return false;
            }
        }

        // If minOpen is zero, we can match all remaining '(' with ')' or '*'
        return minOpen == 0;
    }
}

