        int minOpen = 0; // minimum possible number of unmatched '('
        int maxOpen = 0; // maximum possible number of unmatched '('
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(') {
                minOpen++;
                maxOpen++;
            } else if (c == ')') {
                minOpen--;
                maxOpen--;
            } else { // '*'
                minOpen--;   // treat '*' as ')'
                maxOpen++;   // treat '*' as '('
            }
            if (maxOpen < 0) { // too many ')'
                return false;
            }
            if (minOpen < 0) {
                minOpen = 0; // treat '*' as empty string
            }
        }
        return minOpen == 0;
    }
}

