import java.util.List;
import java.util.Objects;
import java.util.PriorityQueue;

public class Solution {
    public int[] smallestRange(List<List<Integer>> nums) {
        if (nums == null || nums.isEmpty()) {
            return new int[0];
        }

        int k = nums.size();
        PriorityQueue<Node> pq = new PriorityQueue<>((a, b) -> Integer.compare(a.val, b.val));
        int currentMax = Integer.MIN_VALUE;

        // Initialize the heap with the first element from each list
        for (int i = 0; i < k; i++) {
            List<Integer> list = nums.get(i);
            if (list == null || list.isEmpty()) {
                return new int[0];
            }
            int val = list.get(0);
            pq.offer(new Node(val, i, 0));
            currentMax = Math.max(currentMax, val);
        }

        int bestStart = 0, bestEnd = Integer.MAX_VALUE;
        int bestLen = Integer.MAX_VALUE;

        while (pq.size() == k) {
            Node minNode = pq.poll();
            int minVal = minNode.val;

            // Update the best range
            int len = currentMax - minVal;
            if (len < bestLen || (len == bestLen && minVal < bestStart)) {
                bestLen = len;
                bestStart = minVal;
                bestEnd = currentMax;
            }

            // Move to the next element in the same list
            int nextIdx = minNode.elemIndex + 1;
            List<Integer> list = nums.get(minNode.listIndex);
            if (nextIdx < list.size()) {
                int nextVal = list.get(nextIdx);
                pq.offer(new Node(nextVal, minNode.listIndex, nextIdx));
                if (nextVal > currentMax) {
                    currentMax = nextVal;
                }
            } else {
                // One list has been exhausted; cannot find better range
                break;
            }
        }

        return new int[] { bestStart, bestEnd };
    }

    private static class Node {
        int val;
        int listIndex;
        int elemIndex;

        Node(int val, int listIndex, int elemIndex) {
            this.val = val;
            this.listIndex = listIndex;
            this.elemIndex = elemIndex;
        }
    }
}

