public class Solution {

    public int[] findSmallestRange(List<List<Integer>> nums) {
        int k = nums.size();
        // Priority queue to keep track of the minimum current element
        PriorityQueue<Node> minHeap = new PriorityQueue<>(Comparator.comparingInt(n -> n.val));
        int currentMax = Integer.MIN_VALUE;

        // Initialize heap with first element from each list
        for (int i = 0; i < k; i++) {
            int val = nums.get(i).get(0);
            minHeap.offer(new Node(val, i, 0));
            if (val > currentMax) currentMax = val;
        }

        int bestStart = minHeap.peek().val;
        int bestEnd   = currentMax;
        int bestLen   = bestEnd - bestStart;

        while (true) {
            Node cur = minHeap.poll();
            int minVal = cur.val;
            int listIdx = cur.listIdx;
            int elemIdx = cur.elemIdx;

            // If this list has no more elements, we cannot extend the range further
            if (elemIdx + 1 == nums.get(listIdx).size()) {
                break;
            }

            // Move to next element in the same list
            int nextVal = nums.get(listIdx).get(elemIdx + 1);
            minHeap.offer(new Node(nextVal, listIdx, elemIdx + 1));
