        // Min-heap based on the current element value
        PriorityQueue<Element> minHeap = new PriorityQueue<>(Comparator.comparingInt(e -> e.value));

        int currentMax = Integer.MIN_VALUE;
        // Initialize heap with the first element from each list
        for (int i = 0; i < k; i++) {
            List<Integer> list = nums.get(i);
            if (list == null || list.isEmpty()) {
                // If any list is empty, no range can include an element from it
                return new int[]{0, 0};
            }
            int val = list.get(0);
            minHeap.offer(new Element(i, 0, val));
            currentMax = Math.max(currentMax, val);
        }

        int bestStart = Integer.MIN_VALUE;
        int bestEnd = Integer.MAX_VALUE;
        int bestLen = Integer.MAX_VALUE;

        while (true) {
            Element minElem = minHeap.poll();
            int currentMin = minElem.value;

            // Update best range if needed
            if (currentMax - currentMin < bestLen ||
                (currentMax - currentMin == bestLen && currentMin < bestStart)) {
                bestLen = currentMax - currentMin;
                bestStart = currentMin;
                bestEnd = currentMax;
