import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    private Map<String, Integer> memo = new HashMap<>();

    public int shoppingOffers(List<Integer> price, List<List<Integer>> special, List<Integer> needs) {
        return dfs(price, special, needs);
    }

    private int dfs(List<Integer> price, List<List<Integer>> special, List<Integer> needs) {
        String key = needsToString(needs);
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        // Base cost without any special offers
        int minCost = 0;
        for (int i = 0; i < needs.size(); i++) {
            minCost += needs.get(i) * price.get(i);
        }

        // Try each special offer
        for (List<Integer> offer : special) {
            if (canApply(offer, needs)) {
                List<Integer> newNeeds = new ArrayList<>(needs);
                for (int i = 0; i < newNeeds.size(); i++) {
                    newNeeds.set(i, newNeeds.get(i) - offer.get(i));
                }
                int offerCost = offer.get(offer.size() - 1);
                int totalCost = offerCost + dfs(price, special, newNeeds);
                if (totalCost < minCost) {
                    minCost = totalCost;
                }
            }
        }

        memo.put(key, minCost);
        return minCost;
    }

    private boolean canApply(List<Integer> offer, List<Integer> needs) {
        for (int i = 0; i < needs.size(); i++) {
            if (offer.get(i) > needs.get(i)) {
                return false;
            }
        }
        return true;
    }

    private String needsToString(List<Integer> needs) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < needs.size(); i++) {
            if (i > 0) sb.append('#');
            sb.append(needs.get(i));
        }
        return sb.toString();
    }
}

