                    newNeeds.set(i, newNeeds.get(i) - offer.get(i));
                }
                int offerCost = offer.get(n); // last element is price
                cost = Math.min(cost, offerCost + dfs(price, newNeeds, special));
            }
        }

        memo.put(key, cost);
        return cost;
    }

    private boolean canApply(List<Integer> offer, List<Integer> needs) {
        int n = needs.size();
        for (int i = 0; i < n; i++) {
            if (offer.get(i) > needs.get(i)) {
                return false;
            }
        }
        return true;
    }

    private String getKey(List<Integer> needs) {
        StringBuilder sb = new StringBuilder();
        for (int num : needs) {
            sb.append(num).append(',');
        }
        return sb.toString();
    }
}

