import java.util.List;
import java.util.Map;

public class Solution {
    private List<Integer> price;
    private List<List<Integer>> special;
    private Map<String, Integer> memo;

    public int shoppingOffers(List<Integer> price, List<List<Integer>> special, List<Integer> needs) {
        this.price = price;
        this.special = special;
        this.memo = new HashMap<>();
        return dfs(needs);
    }

    private int dfs(List<Integer> needs) {
        String key = buildKey(needs);
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        // base cost without any special offers
        int minCost = 0;
        for (int i = 0; i < needs.size(); i++) {
            minCost += needs.get(i) * price.get(i);
        }

        // try every special offer
        for (List<Integer> offer : special) {
            boolean canUse = true;
            for (int i = 0; i < needs.size(); i++) {
                if (offer.get(i) > needs.get(i)) {
                    canUse = false;
                    break;
                }
            }
            if (!canUse) continue;

            // apply offer
            List<Integer> newNeeds = new ArrayList<>(needs.size());
            for (int i = 0; i < needs.size(); i++) {
                newNeeds.add(needs.get(i) - offer.get(i));
            }
            int offerCost = offer.get(offer.size() - 1);
            int totalCost = offerCost + dfs(newNeeds);
            if (totalCost < minCost) {
                minCost = totalCost;
            }
        }

        memo.put(key, minCost);
        return minCost;
    }

    private String buildKey(List<Integer> needs) {
        StringBuilder sb = new StringBuilder();
        for (int n : needs) {
            sb.append(n).append(',');
        }
        return sb.toString();
    }
}

