import java.util.*;

public class Solution {
    public int shoppingOffers(int[] price, int[] needs, List<int[]> special) {
        int n = price.length;
        int[] pow = new int[n + 1];
        pow[0] = 1;
        for (int i = 1; i <= n; i++) {
            pow[i] = pow[i - 1] * 11; // needs[i] <= 10
        }
        Map<Integer, Integer> memo = new HashMap<>();
        return dfs(price, needs, special, pow, memo);
    }

    private int dfs(int[] price, int[] needs, List<int[]> special, int[] pow, Map<Integer, Integer> memo) {
        int key = encode(needs, pow);
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        // cost without any special offer
        int cost = 0;
        for (int i = 0; i < price.length; i++) {
            cost += price[i] * needs[i];
        }

        // try each special offer
        for (int[] offer : special) {
            int[] newNeeds = new int[needs.length];
            boolean ok = true;
            for (int i = 0; i < needs.length; i++) {
                if (offer[i] > needs[i]) {
                    ok = false;
                    break;
                }
                newNeeds[i] = needs[i] - offer[i];
            }
            if (!ok) continue;
            int offerCost = offer[needs.length] + dfs(price, newNeeds, special, pow, memo);
            if (offerCost < cost) {
                cost = offerCost;
            }
        }

        memo.put(key, cost);
        return cost;
    }

    private int encode(int[] needs, int[] pow) {
        int key = 0;
        for (int i = 0; i < needs.length; i++) {
            key += needs[i] * pow[i];
        }
        return key;
    }
}

