import java.util.*;

public class Solution {
    // Cache the minimal cost for a particular needs state
    private final Map<String, Integer> memo = new HashMap<>();

    public int shoppingOffers(List<Integer> price, List<List<Integer>> special, List<Integer> needs) {
        int n = price.size();
        int[] p = new int[n];
        for (int i = 0; i < n; i++) p[i] = price.get(i);
        int[] need = new int[n];
        for (int i = 0; i < n; i++) need[i] = needs.get(i);
        return dfs(need, p, special);
    }

    private int dfs(int[] need, int[] price, List<List<Integer>> special) {
        String key = Arrays.toString(need);
        if (memo.containsKey(key)) return memo.get(key);

        // Base cost: buy all remaining items at regular price
        int minCost = 0;
        for (int i = 0; i < need.length; i++) {
            minCost += need[i] * price[i];
        }

        // Try each special offer
        for (List<Integer> offer : special) {
            boolean canUse = true;
            int[] newNeed = new int[need.length];
            for (int i = 0; i < need.length; i++) {
                int qty = offer.get(i);
                if (qty > need[i]) {
                    canUse = false;
                    break;
                }
                newNeed[i] = need[i] - qty;
            }
            if (!canUse) continue;
            int offerPrice = offer.get(offer.size() - 1);
            int totalCost = offerPrice + dfs(newNeed, price, special);
            if (totalCost < minCost) minCost = totalCost;
        }

        memo.put(key, minCost);
        return minCost;
    }
}

