import java.util.Arrays;

public class Solution {
    public boolean canPartitionKSubsets(int[] nums, int k) {
        if (k <= 0) return false;
        int n = nums.length;
        if (k == 1) return true;
        int total = 0;
        for (int num : nums) total += num;
        if (total % k != 0) return false;
        int target = total / k;
        Arrays.sort(nums);
        // reverse sort for better pruning
        for (int i = 0; i < n / 2; i++) {
            int tmp = nums[i];
            nums[i] = nums[n - 1 - i];
            nums[n - 1 - i] = tmp;
        }
        if (nums[0] > target) return false;

        int allMask = (1 << n) - 1;
        int[] memo = new int[1 << n];
        Arrays.fill(memo, -1);
        return dfs(nums, target, 0, 0, 0, allMask, memo);
    }

    private boolean dfs(int[] nums, int target, int mask, int currentSum, int startIndex, int allMask, int[] memo) {
        if (mask == allMask) return true;
        if (memo[mask] != -1) return memo[mask] == 1;
        if (currentSum == target) {
            // start filling next subset
            boolean res = dfs(nums, target, mask, 0, 0, allMask, memo);
            memo[mask] = res ? 1 : 0;
            return res;
        }
        for (int i = startIndex; i < nums.length; i++) {
            if ((mask & (1 << i)) != 0) continue; // already used
            if (currentSum + nums[i] > target) continue;
            int newMask = mask | (1 << i);
            if (dfs(nums, target, newMask, currentSum + nums[i], i + 1, allMask, memo)) {
                memo[mask] = 1;
                return true;
            }
        }
        memo[mask] = 0;
        return false;
    }
}

