public class Solution {
    public boolean canPartitionKSubsets(int[] nums, int k) {
        if (k <= 0) return false;
        int n = nums.length;
        if (n < k) return false;

        int total = 0;
        for (int num : nums) total += num;
        if (total % k != 0) return false;

        int target = total / k;
        Arrays.sort(nums);

        if (nums[n - 1] > target) return false;

        int fullMask = (1 << n) - 1;
        int[] memo = new int[1 << n];
        Arrays.fill(memo, -1);

        return dfs(0, 0, nums, target, fullMask, memo);
    }

    private boolean dfs(int mask, int currentSum, int[] nums, int target, int fullMask, int[] memo) {
        if (mask == fullMask) return true;
        if (memo[mask] != -1) return memo[mask] == 1;

        for (int i = 0; i < nums.length; i++) {
            // skip already used numbers
            if ((mask & (1 << i)) != 0) continue;

            // skip duplicates to reduce states
            if (i > 0 && nums[i] == nums[i - 1] && (mask & (1 << (i - 1))) == 0)
                continue;

            if (currentSum + nums[i] <= target) {
                int newMask = mask | (1 << i);
                int newSum = currentSum + nums[i];
                if (dfs(newMask, newSum == target ? 0 : newSum, nums, target, fullMask, memo)) {
                    memo[mask] = 1;
                    return true;
                }
            }
        }

        memo[mask] = 0;
        return false;
    }
}

