public class Solution {
    public boolean canPartitionKSubsets(int[] nums, int k) {
        int n = nums.length;
        int total = 0;
        for (int num : nums) {
            total += num;
        }
        if (total % k != 0) {
            return false;
        }
        int target = total / k;
        Arrays.sort(nums);
        // If the largest number is greater than the target, impossible
        if (nums[n - 1] > target) {
            return false;
        }
        // Sort in descending order to speed up pruning
        for (int i = 0; i < n / 2; i++) {
            int temp = nums[i];
            nums[i] = nums[n - 1 - i];
            nums[n - 1 - i] = temp;
        }

        int fullMask = (1 << n) - 1;
        int[] memo = new int[1 << n]; // 0: unknown, 1: false, 2: true
        return dfs(0, 0, nums, k, target, memo, fullMask);
    }

    private boolean dfs(int mask, int currSum, int[] nums, int k, int target,
                        int[] memo, int fullMask) {
        if (mask == fullMask) {
            return true;
        }
        if (memo[mask] != 0) {
            return memo[mask] == 2;
        }

        for (int i = 0; i < nums.length; i++) {
            if ((mask & (1 << i)) == 0) {
                int newSum = currSum + nums[i];
                if (newSum > target) {
                    continue;
                }
                if (dfs(mask | (1 << i), newSum % target, nums, k, target, memo, fullMask)) {
                    memo[mask] = 2; // true
                    return true;
                }
            }
        }
        memo[mask] = 1; // false
        return false;
    }
}

