public class Solution {
    public boolean canPartitionKSubsets(int[] nums, int k) {
        int n = nums.length;
        int total = Arrays.stream(nums).sum();
        if (total % k != 0) return false;
        int target = total / k;
        Arrays.sort(nums);
        if (nums[n - 1] > target) return false;

        boolean[] memo = new boolean[1 << n];
        return backtrack(0, 0, 0, target, nums, memo);
    }

    private boolean backtrack(int usedMask, int currentSum, int startIndex,
                              int target, int[] nums, boolean[] memo) {
        if (usedMask == (1 << nums.length) - 1) return true;
        if (memo[usedMask]) return false;
        if (currentSum == target) {
            return backtrack(usedMask, 0, 0, target, nums, memo);
        }

        int prev = -1;
        for (int i = startIndex; i < nums.length; i++) {
            if ((usedMask & (1 << i)) != 0) continue;
            if (currentSum + nums[i] > target) continue;
            if (prev == nums[i]) continue; // skip duplicates
            if (backtrack(usedMask | (1 << i), currentSum + nums[i], i + 1, target, nums, memo))
                return true;
            prev = nums[i];
        }

        memo[usedMask] = true;
        return false;
    }
}

