public class Solution {
    public boolean canPartitionKSubsets(int[] nums, int k) {
        int n = nums.length;
        if (k > n) return false;

        int total = 0;
        for (int num : nums) total += num;

        if (total % k != 0) return false;
        int target = total / k;

        // Sort numbers in descending order to improve pruning
        Arrays.sort(nums);
        for (int i = 0; i < n / 2; i++) {
            int tmp = nums[i];
            nums[i] = nums[n - 1 - i];
            nums[n - 1 - i] = tmp;
        }

        if (nums[0] > target) return false;

        boolean[] visited = new boolean[1 << n];
        return dfs(0, 0, k, nums, target, visited);
    }

    private boolean dfs(int mask, int curSum, int kLeft, int[] nums,
                        int target, boolean[] visited) {
        if (kLeft == 1) return true;          // remaining numbers form the last subset
        if (visited[mask]) return false;      // this state has already been proven impossible

        for (int i = 0; i < nums.length; i++) {
            if ((mask & (1 << i)) != 0) continue;          // already used
            if (curSum + nums[i] > target) continue;       // would exceed target

            int newMask = mask | (1 << i);
            int newSum = curSum + nums[i];

            if (newSum == target) {
                if (dfs(newMask, 0, kLeft - 1, nums, target, visited)) return true;
            } else {
                if (dfs(newMask, newSum, kLeft, nums, target, visited)) return true;
            }
        }

        visited[mask] = true;   // mark this state as impossible
        return false;
    }
}

