import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<Integer> findClosestElements(int[] arr, int k, int x) {
        int n = arr.length;
        if (k >= n) {
            List<Integer> res = new ArrayList<>(n);
            for (int v : arr) res.add(v);
            return res;
        }

        // Binary search for the first element >= x
        int left = 0, right = n - 1;
        while (left < right) {
            int mid = (left + right) >>> 1;
            if (arr[mid] < x) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }

        // Define initial window boundaries
        int l = Math.max(0, left - k);
        int r = Math.min(n - 1, left + k - 1);

        // Shrink window to exactly k elements
        while (r - l + 1 > k) {
            int leftDiff = Math.abs(arr[l] - x);
            int rightDiff = Math.abs(arr[r] - x);
            if (leftDiff <= rightDiff) {
                r--;
            } else {
                l++;
            }
        }

        List<Integer> result = new ArrayList<>(k);
        for (int i = l; i <= r; i++) {
            result.add(arr[i]);
        }
        return result;
    }
}

