        int left, right;
        if (idx >= 0) {
            left = idx - 1;
            right = idx + 1;
        } else {
            int insertPos = -idx - 1;
            left = insertPos - 1;
            right = insertPos;
        }

        while (k > 0) {
            if (left < 0) {
                right++;
            } else if (right >= n) {
                left--;
            } else {
                int leftDiff = Math.abs(arr[left] - x);
                int rightDiff = Math.abs(arr[right] - x);
                if (leftDiff <= rightDiff) {
                    left--;
                } else {
                    right++;
                }
            }
            k--;
        }

        List<Integer> result = new ArrayList<>(right - left - 1);
        for (int i = left + 1; i < right; i++) {
            result.add(arr[i]);
        }
        return result;
    }
}

