import com_github_leetcode.TreeNode;
import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<List<String>> printTree(TreeNode root) {
        if (root == null) {
            return new ArrayList<>();
        }
        int height = getHeight(root);
        int rows = height + 1;
        int cols = (int) Math.pow(2, height + 1) - 1;
        String[][] res = new String[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                res[i][j] = "";
            }
        }
        fill(res, root, 0, (cols - 1) / 2, height);
        List<List<String>> result = new ArrayList<>();
        for (int i = 0; i < rows; i++) {
            List<String> rowList = new ArrayList<>();
            for (int j = 0; j < cols; j++) {
                rowList.add(res[i][j]);
            }
            result.add(rowList);
        }
        return result;
    }

    private int getHeight(TreeNode node) {
        if (node == null) {
            return -1; // height of empty tree is -1 so that leaf has height 0
        }
        return 1 + Math.max(getHeight(node.left), getHeight(node.right));
    }

    private void fill(String[][] res, TreeNode node, int row, int col, int height) {
        if (node == null) {
            return;
        }
        res[row][col] = String.valueOf(node.val);
        int offset = (int) Math.pow(2, height - row - 1);
        if (node.left != null) {
            fill(res, node.left, row + 1, col - offset, height);
        }
        if (node.right != null) {
            fill(res, node.right, row + 1, col + offset, height);
        }
    }
}

