public class Solution {
    public int[] findRedundantConnection(int[][] edges) {
        int n = edges.length;
        DSU dsu = new DSU(n + 1); // nodes are 1-indexed
        int[] redundant = null;
        for (int[] edge : edges) {
            int u = edge[0], v = edge[1];
            if (!dsu.union(u, v)) {
                redundant = edge; // record the last edge that creates a cycle
            }
        }
        return redundant;
    }

    private static class DSU {
        private final int[] parent;
        private final int[] rank;

        DSU(int size) {
            parent = new int[size];
            rank = new int[size];
            for (int i = 0; i < size; i++) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]); // path compression
            }
            return parent[x];
        }

        boolean union(int x, int y) {
            int px = find(x);
            int py = find(y);
            if (px == py) {
                return false; // already connected, would form a cycle
            }
            // union by rank
            if (rank[px] < rank[py]) {
                parent[px] = py;
            } else if (rank[px] > rank[py]) {
                parent[py] = px;
            } else {
                parent[py] = px;
                rank[px]++;
            }
            return true;
        }
    }
}

