        for (String w : words) {
            freqMap.put(w, freqMap.getOrDefault(w, 0) + 1);
        }

        // Priority queue: higher frequency first, then lexicographically smaller
        PriorityQueue<String> pq = new PriorityQueue<>(new Comparator<String>() {
