                int freqB = freqMap.get(b);
                if (freqA != freqB) {
                    return freqB - freqA; // descending frequency
                }
                return a.compareTo(b); // ascending lexicographical
            }
        });

        // Add all words to the priority queue
        for (String w : freqMap.keySet()) {
            pq.offer(w);
        }

        // Extract top k
        List<String> result = new ArrayList<>();
        for (int i = 0; i < k && !pq.isEmpty(); i++) {
            result.add(pq.poll());
        }

