                int freqCompare = e1.getValue().compareTo(e2.getValue());
                if (freqCompare != 0) {
                    return freqCompare;
                }
                // Secondary: lexicographical descending to make min-heap remove lexicographically larger
                return e2.getKey().compareTo(e1.getKey());
            }
        });

        // Build heap of size k
        for (Map.Entry<String, Integer> entry : freqMap.entrySet()) {
            minHeap.offer(entry);
            if (minHeap.size() > k) {
                minHeap.poll();
            }
        }

        // Extract elements from heap to list
        ArrayList<String> result = new ArrayList<>();
        while (!minHeap.isEmpty()) {
            result.add(minHeap.poll().getKey());
        }

        // Reverse list to get descending frequency order
        java.util.Collections.reverse(result);
        return result;
    }
