                // Sort in descending order based on concatenation
                return (b + a).compareTo(a + b);
            }
        });

        // If the highest number is "0", the result is "0"
        if (strs[0].equals("0")) {
            return "0";
        }

        StringBuilder sb = new StringBuilder();
        for (String s : strs) {
            sb.append(s);
        }
        return sb.toString();
    }
}

