public class Solution {
    public int maxProfit(int k, int[] prices) {
        int n = prices.length;
        if (n == 0) return 0;
        if (k >= n / 2) {
            int total = 0;
            for (int i = 1; i < n; i++) {
                if (prices[i] > prices[i - 1]) total += prices[i] - prices[i - 1];
            }
            return total;
        }
        int[] prev = new int[k + 1];
        int[] curr = new int[k + 1];
        for (int day = 1; day < n; day++) {
            for (int t = k; t >= 1; t--) {
                int best = curr[t];
                int diff = prices[day] - prices[day - 1];
                if (diff > 0) {
                    int cand = prev[t] + diff;
                    if (cand > best) best = cand;
                }
                for (int j = 1; j < t; j++) {
                    int cand = prev[j] + curr[t - j];
                    if (cand > best) best = cand;
                }
                curr[t] = best;
            }
            int[] tmp = prev;
            prev = curr;
            curr = tmp;
        }
        return prev[k];
    }
}

