public class Solution {
    public int maxProfit(int k, int[] prices) {
        if (prices == null || prices.length == 0 || k == 0) {
            return 0;
        }
        int n = prices.length;
        // If k is large enough to allow unlimited transactions
        if (k >= n / 2) {
            int profit = 0;
            for (int i = 1; i < n; i++) {
                if (prices[i] > prices[i - 1]) {
                    profit += prices[i] - prices[i - 1];
                }
            }
            return profit;
        }

        int[] buy = new int[k + 1];
        int[] sell = new int[k + 1];
        for (int t = 0; t <= k; t++) {
            buy[t] = Integer.MIN_VALUE; // cannot hold stock at start
            sell[t] = 0;
        }
        buy[0] = -prices[0]; // with 0 transactions, buying on day 0

        for (int i = 1; i < n; i++) {
            int price = prices[i];
            // iterate transactions in reverse to avoid overwriting needed values
            for (int t = k; t >= 1; t--) {
                // Update buy: either keep previous buy or buy today after sell[t-1]
                buy[t] = Math.max(buy[t], sell[t - 1] - price);
                // Update sell: either keep previous sell or sell today after buy[t]
                sell[t] = Math.max(sell[t], buy[t] + price);
            }
            // handle case t=0 separately: we can only buy
            buy[0] = Math.max(buy[0], -price);
        }
        return sell[k];
    }
}

