public class Solution {
    public int calculateMinimumHP(int[][] dungeon) {
        if (dungeon == null || dungeon.length == 0 || dungeon[0].length == 0) {
            return 1;
        }
        int m = dungeon.length;
        int n = dungeon[0].length;
        int[][] dp = new int[m][n];

        // Base case: bottom-right corner (princess's room)
        dp[m - 1][n - 1] = Math.max(1, 1 - dungeon[m - 1][n - 1]);

        // Fill last row (can only move right)
        for (int j = n - 2; j >= 0; j--) {
            int need = dp[m - 1][j + 1] - dungeon[m - 1][j];
            dp[m - 1][j] = Math.max(1, need);
        }

        // Fill last column (can only move down)
        for (int i = m - 2; i >= 0; i--) {
            int need = dp[i + 1][n - 1] - dungeon[i][n - 1];
            dp[i][n - 1] = Math.max(1, need);
        }

        // Fill the rest
        for (int i = m - 2; i >= 0; i--) {
            for (int j = n - 2; j >= 0; j--) {
                int needFromRight = dp[i][j + 1] - dungeon[i][j];
                int needFromDown = dp[i + 1][j] - dungeon[i][j];
                int need = Math.min(needFromRight, needFromDown);
                dp[i][j] = Math.max(1, need);
            }
        }

        return dp[0][0];
    }
}

