public class Solution {
    private int maxSum = Integer.MIN_VALUE;

    public int maxPathSum(TreeNode root) {
        maxPathSumHelper(root);
        return maxSum;
    }

    private int maxPathSumHelper(TreeNode node) {
        if (node == null) {
            return 0;
        }

        // Recursively get the maximum sum of the left and right subtree.
        // If the sum is negative, we ignore it by treating as 0.
        int leftMax = Math.max(0, maxPathSumHelper(node.left));
        int rightMax = Math.max(0, maxPathSumHelper(node.right));

        // Current path sum passing through the current node.
        int currentMax = node.val + leftMax + rightMax;
        maxSum = Math.max(maxSum, currentMax);

        // Return the maximum sum of a path extending from current node to one side
        // (used by its parent).
        return node.val + Math.max(leftMax, rightMax);
    }
}

