public class Solution {
    public int singleNumber(int[] nums) {
        int ones = 0, twos = 0;
        for (int num : nums) {
            // Update twos with bits that have appeared twice
            twos |= ones & num;
            // Update ones with bits that have appeared once
            ones ^= num;
            // Bits that have appeared three times are cleared from both ones and twos
            int commonMask = ~(ones & twos);
            ones &= commonMask;
            twos &= commonMask;
        }
        return ones;
    }
}

