public class Solution {
    public ListNode insertionSortList(ListNode head) {
        if (head == null || head.next == null) {
            return head;
        }

        ListNode dummy = new ListNode(0);
        dummy.next = head;
        ListNode curr = head;
        ListNode prev = dummy;

        while (curr != null) {
            if (curr.next != null && curr.val > curr.next.val) {
                // Find the correct position to insert curr.next
                ListNode toInsert = curr.next;
                curr.next = toInsert.next; // remove toInsert from current position

                // Find insertion point
                ListNode search = dummy;
                while (search.next != null && search.next.val < toInsert.val) {
                    search = search.next;
                }

                // Insert toInsert after search
                toInsert.next = search.next;
                search.next = toInsert;
            } else {
                // Move forward if no insertion needed
                curr = curr.next;
            }
        }

        return dummy.next;
    }
}

