public class Solution {
    public int compareVersion(String version1, String version2) {
        String[] parts1 = version1.split("\\.");
        String[] parts2 = version2.split("\\.");
        int i = 0;
        while (i < parts1.length || i < parts2.length) {
            String rev1 = i < parts1.length ? parts1[i] : "0";
            String rev2 = i < parts2.length ? parts2[i] : "0";

            rev1 = trimLeadingZeros(rev1);
            rev2 = trimLeadingZeros(rev2);

            int cmp = compareNumericStrings(rev1, rev2);
            if (cmp != 0) {
                return cmp;
            }
            i++;
        }
        return 0;
    }

    private String trimLeadingZeros(String s) {
        int idx = 0;
        while (idx < s.length() && s.charAt(idx) == '0') {
            idx++;
        }
        return idx == s.length() ? "0" : s.substring(idx);
    }

    private int compareNumericStrings(String a, String b) {
        if (a.length() > b.length()) return 1;
        if (a.length() < b.length()) return -1;
        int cmp = a.compareTo(b);
        if (cmp > 0) return 1;
        if (cmp < 0) return -1;
        return 0;
    }
}

