            String b = i < len2 ? revs2[i] : "0";

            a = trimLeadingZeros(a);
            b = trimLeadingZeros(b);

            int cmp = compareNumericStrings(a, b);
            if (cmp != 0) {
                return cmp;
            }
        }
        return 0;
    }

    private String trimLeadingZeros(String s) {
        int i = 0;
        while (i < s.length() && s.charAt(i) == '0') {
            i++;
        }
        if (i == s.length()) {
            return "0";
        }
        return s.substring(i);
    }

    private int compareNumericStrings(String a, String b) {
        if (a.length() > b.length()) {
            return 1;
        }
        if (a.length() < b.length()) {
            return -1;
        }
        for (int i = 0; i < a.length(); i++) {
            char ca = a.charAt(i);
            char cb = b.charAt(i);
            if (ca > cb) {
                return 1;
            }
            if (ca < cb) {
                return -1;
            }
        }
        return 0;
    }
}

