public class Solution {
    public int minimumTotal(List<List<Integer>> triangle) {
        if (triangle == null || triangle.isEmpty()) {
            return 0;
        }

        int n = triangle.size();
        int[] dp = new int[triangle.get(n - 1).size()];

        // Initialize dp with the last row of the triangle
        for (int i = 0; i < dp.length; i++) {
            dp[i] = triangle.get(n - 1).get(i);
        }

        // Build the solution from bottom to top
        for (int row = n - 2; row >= 0; row--) {
            List<Integer> currentRow = triangle.get(row);
            for (int i = 0; i < currentRow.size(); i++) {
                dp[i] = currentRow.get(i) + Math.min(dp[i], dp[i + 1]);
            }
        }

        return dp[0];
    }
}

