import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int maxPoints(int[][] points) {
        if (points == null) return 0;
        int n = points.length;
        if (n <= 1) return n;

        int result = 0;
        for (int i = 0; i < n; i++) {
            Map<Long, Integer> map = new HashMap<>();
            int duplicates = 0;
            int localMax = 0;

            for (int j = i + 1; j < n; j++) {
                int dx = points[j][0] - points[i][0];
                int dy = points[j][1] - points[i][1];

                if (dx == 0 && dy == 0) {
                    duplicates++;
                    continue;
                }

                int g = gcd(dx, dy);
                dx /= g;
                dy /= g;

                // Normalize sign to ensure unique representation
                if (dx < 0) {
                    dx = -dx;
                    dy = -dy;
                } else if (dx == 0 && dy < 0) {
                    dy = -dy;
                }

                long key = ((long) dx << 32) ^ (dy & 0xffffffffL);
                int count = map.getOrDefault(key, 0) + 1;
                map.put(key, count);
                localMax = Math.max(localMax, count);
            }

            result = Math.max(result, localMax + duplicates + 1);
        }

        return result;
    }

    private int gcd(int a, int b) {
        a = Math.abs(a);
        b = Math.abs(b);
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

