            return;
        }
        int m = board.length;
        int n = board[0].length;
        // Directions: up, down, left, right
        int[][] dirs = {{-1,0},{1,0},{0,-1},{0,1}};
        Queue<int[]> queue = new ArrayDeque<>();

        // Helper to add border O's to queue
        for (int i = 0; i < m; i++) {
            if (board[i][0] == 'O') {
                queue.offer(new int[]{i,0});
                board[i][0] = '#';
            }
            if (board[i][n-1] == 'O') {
                queue.offer(new int[]{i,n-1});
                board[i][n-1] = '#';
            }
        }
        for (int j = 0; j < n; j++) {
            if (board[0][j] == 'O') {
                queue.offer(new int[]{0,j});
                board[0][j] = '#';
            }
            if (board[m-1][j] == 'O') {
                queue.offer(new int[]{m-1,j});
                board[m-1][j] = '#';
            }
        }

        // BFS to mark all connected O's from borders
        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            int r = cell[0], c = cell[1];
            for (int[] d : dirs) {
                int nr = r + d[0];
                int nc = c + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && board[nr][nc] == 'O') {
