public class Solution {
    public int minCut(String s) {
        int n = s.length();
        if (n == 0) return 0;
        int[] dp = new int[n];
        for (int i = 0; i < n; i++) dp[i] = i; // maximum cuts

        for (int center = 0; center < n; center++) {
            // odd length palindromes
            expandAndCut(s, center, center, dp);
            // even length palindromes
            expandAndCut(s, center, center + 1, dp);
        }
        return dp[n - 1];
    }

    private void expandAndCut(String s, int left, int right, int[] dp) {
        int n = s.length();
        while (left >= 0 && right < n && s.charAt(left) == s.charAt(right)) {
            int cut = (left == 0) ? 0 : dp[left - 1] + 1;
            dp[right] = Math.min(dp[right], cut);
            left--;
            right++;
        }
    }
}

