import com_github_leetcode.TreeNode;
import java.util.HashMap;
import java.util.Map;

public class Solution {
    public TreeNode buildTree(int[] inorder, int[] postorder) {
        if (inorder == null || postorder == null || inorder.length == 0 || postorder.length == 0) {
            return null;
        }
        Map<Integer, Integer> inorderIndexMap = new HashMap<>();
        for (int i = 0; i < inorder.length; i++) {
            inorderIndexMap.put(inorder[i], i);
        }
        int[] postIndex = {postorder.length - 1};
        return build(inorder, postorder, 0, inorder.length - 1, inorderIndexMap, postIndex);
    }

    private TreeNode build(int[] inorder, int[] postorder, int inStart, int inEnd,
                           Map<Integer, Integer> inorderIndexMap, int[] postIndex) {
        if (inStart > inEnd) {
            return null;
        }

        int rootVal = postorder[postIndex[0]--];
        TreeNode root = new TreeNode(rootVal);

        int inRootIndex = inorderIndexMap.get(rootVal);

        // Build right subtree first because postorder processes left subtree before right subtree
        root.right = build(inorder, postorder, inRootIndex + 1, inEnd, inorderIndexMap, postIndex);
        root.left = build(inorder, postorder, inStart, inRootIndex - 1, inorderIndexMap, postIndex);

        return root;
    }
}

