import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;

public class Solution {
    public List<String> findRepeatedDnaSequences(String s) {
        List<String> result = new ArrayList<>();
        if (s == null || s.length() < 10) {
            return result;
        }

        int mask = 0;
        int maskBits = 20; // 10 letters * 2 bits each
        int maskAll = (1 << maskBits) - 1;

        HashSet<Integer> seen = new HashSet<>();
        HashSet<String> added = new HashSet<>();

        for (int i = 0; i < s.length(); i++) {
            int val = 0;
            char c = s.charAt(i);
            switch (c) {
                case 'A': val = 0; break;
                case 'C': val = 1; break;
                case 'G': val = 2; break;
                case 'T': val = 3; break;
            }
            mask = ((mask << 2) | val) & maskAll;

            if (i >= 9) { // window size reached 10
                if (seen.contains(mask)) {
                    String sub = s.substring(i - 9, i + 1);
                    if (added.add(sub)) {
                        result.add(sub);
                    }
                } else {
                    seen.add(mask);
                }
            }
        }

        return result;
    }
}

