public class Solution {
    public List<String> findRepeatedDnaSequences(String s) {
        List<String> result = new ArrayList<>();
        if (s == null || s.length() < 10) {
            return result;
        }

        int n = s.length();
        int mask = (1 << 20) - 1; // 20 bits for 10 nucleotides
        int value = 0;

        // Map nucleotides to 2-bit values
        int[] map = new int[128];
        map['A'] = 0;
        map['C'] = 1;
        map['G'] = 2;
        map['T'] = 3;

        HashSet<Integer> seen = new HashSet<>();
        HashSet<String> repeated = new HashSet<>();

        for (int i = 0; i < n; i++) {
            value = ((value << 2) | map[s.charAt(i)]) & mask;
            if (i >= 9) { // we have a 10-letter sequence
                if (!seen.add(value)) { // value already seen
                    repeated.add(s.substring(i - 9, i + 1));
                }
            }
        }

        result.addAll(repeated);
        return result;
    }
}

