        int[] freq = new int[1 << 20];

        // Build the code for the first 10 characters
        int code = 0;
        for (int i = 0; i < 10; i++) {
            code = (code << 2) | map[s.charAt(i)];
        }
        freq[code]++;

        // Slide over the string
        for (int i = 10; i < s.length(); i++) {
            code = ((code << 2) | map[s.charAt(i)]) & mask;
            freq[code]++;
            if (freq[code] == 2) {
                result.add(s.substring(i - 9, i + 1));
            }
        }

