import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class Solution {
    public List<String> findRepeatedDnaSequences(String s) {
        List<String> result = new ArrayList<>();
        if (s == null || s.length() < 10) {
            return result;
        }

        int n = s.length();
        int mask = (1 << 20) - 1; // 20 bits for 10 letters (2 bits each)
        int code = 0;

        Set<Integer> seen = new HashSet<>();
        Set<Integer> repeated = new HashSet<>();

        for (int i = 0; i < n; i++) {
            code = ((code << 2) | charToBits(s.charAt(i))) & mask;
            if (i >= 9) {
                if (seen.contains(code)) {
                    repeated.add(code);
                } else {
                    seen.add(code);
                }
            }
        }

        for (int c : repeated) {
            result.add(bitsToString(c));
        }

        return result;
    }

    private int charToBits(char ch) {
        switch (ch) {
            case 'A':
                return 0;
            case 'C':
                return 1;
            case 'G':
                return 2;
            case 'T':
                return 3;
            default:
                return 0;
        }
    }

    private String bitsToString(int code) {
        char[] chars = new char[10];
        for (int i = 9; i >= 0; i--) {
            int bits = (code >> (2 * i)) & 3;
            chars[9 - i] = bitsToChar(bits);
        }
        return new String(chars);
    }

    private char bitsToChar(int bits) {
        switch (bits) {
            case 0:
                return 'A';
            case 1:
                return 'C';
            case 2:
                return 'G';
            case 3:
                return 'T';
            default:
                return 'A';
        }
    }
}

