import com_github_leetcode.ListNode;

public class Solution {
    public ListNode getIntersectionNode(ListNode headA, ListNode headB) {
        if (headA == null || headB == null) {
            return null;
        }

        // Calculate lengths of both lists
        int lenA = 0, lenB = 0;
        ListNode curA = headA, curB = headB;
        while (curA != null) {
            lenA++;
            curA = curA.next;
        }
        while (curB != null) {
            lenB++;
            curB = curB.next;
        }

        // Reset pointers to heads
        curA = headA;
        curB = headB;

        // Advance the pointer of the longer list by the difference in lengths
        if (lenA > lenB) {
            int diff = lenA - lenB;
            while (diff-- > 0) {
                curA = curA.next;
            }
        } else if (lenB > lenA) {
            int diff = lenB - lenA;
            while (diff-- > 0) {
                curB = curB.next;
            }
        }

        // Traverse both lists together until the nodes are the same
        while (curA != null && curB != null) {
            if (curA == curB) {
                return curA; // Intersection found
            }
            curA = curA.next;
            curB = curB.next;
        }

        return null; // No intersection
    }
}

