import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;
import java.util.Queue;
import java.util.Set;

public class Solution {
    public List<List<String>> findLadders(String beginWord, String endWord, List<String> wordList) {
        List<List<String>> result = new ArrayList<>();
        if (beginWord == null || endWord == null || wordList == null) {
            return result;
        }

        Set<String> wordSet = new HashSet<>(wordList);
        if (!wordSet.contains(endWord)) {
            return result;
        }

        if (beginWord.equals(endWord)) {
            List<String> single = new ArrayList<>();
            single.add(beginWord);
            result.add(single);
            return result;
        }

        Map<String, List<String>> graph = new HashMap<>();
        Queue<String> queue = new LinkedList<>();
        Set<String> visited = new HashSet<>();
        queue.offer(beginWord);
        visited.add(beginWord);
        boolean found = false;

        while (!queue.isEmpty() && !found) {
            int size = queue.size();
            Set<String> localVisited = new HashSet<>();

            for (int i = 0; i < size; i++) {
                String word = queue.poll();
                char[] chars = word.toCharArray();

                for (int j = 0; j < chars.length; j++) {
                    char old = chars[j];
                    for (char c = 'a'; c <= 'z'; c++) {
                        if (c == old) continue;
                        chars[j] = c;
                        String newWord = new String(chars);
                        if (wordSet.contains(newWord)) {
                            if (!visited.contains(newWord)) {
                                localVisited.add(newWord);
                                queue.offer(newWord);
                                graph.computeIfAbsent(newWord, k -> new ArrayList<>()).add(word);
                            }
                        }
                    }
                    chars[j] = old;
                }
            }

            visited.addAll(localVisited);
            if (localVisited.contains(endWord)) {
                found = true;
            }
        }

        if (!found) {
            return result;
        }

        List<String> path = new ArrayList<>();
        dfs(endWord, beginWord, graph, path, result);
        return result;
    }

    private void dfs(String current, String target, Map<String, List<String>> graph,
                     List<String> path, List<List<String>> result) {
        path.add(current);
        if (current.equals(target)) {
            List<String> temp = new ArrayList<>(path);
            Collections.reverse(temp);
            result.add(temp);
        } else {
            List<String> preds = graph.get(current);
            if (preds != null) {
                for (String pred : preds) {
                    dfs(pred, target, graph, path, result);
                }
            }
        }
        path.remove(path.size() - 1);
    }
}

