import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;
import java.util.Queue;
import java.util.Set;

public class Solution {
    public List<List<String>> findLadders(String beginWord, String endWord, List<String> wordList) {
        List<List<String>> result = new ArrayList<>();
        if (beginWord == null || endWord == null || wordList == null) {
            return result;
        }

        Set<String> wordSet = new HashSet<>(wordList);
        if (!wordSet.contains(endWord)) {
            return result;
        }

        // Special case: beginWord equals endWord
        if (beginWord.equals(endWord)) {
            List<String> single = new ArrayList<>();
            single.add(beginWord);
            result.add(single);
            return result;
        }

        // Map to store the parents of each word in the shortest paths
        Map<String, Set<String>> parents = new HashMap<>();

        // BFS variables
        Set<String> visited = new HashSet<>();
        Queue<String> queue = new LinkedList<>();
        queue.offer(beginWord);
        visited.add(beginWord);

        boolean foundEnd = false;

        while (!queue.isEmpty() && !foundEnd) {
            int levelSize = queue.size();
            Set<String> currentLevelVisited = new HashSet<>();

            for (int i = 0; i < levelSize; i++) {
                String word = queue.poll();
                char[] chars = word.toCharArray();

                for (int pos = 0; pos < chars.length; pos++) {
                    char original = chars[pos];
                    for (char c = 'a'; c <= 'z'; c++) {
                        if (c == original) continue;
                        chars[pos] = c;
                        String nextWord = new String(chars);

                        if (wordSet.contains(nextWord)) {
                            if (!visited.contains(nextWord)) {
                                // First time we see this word at this level
                                currentLevelVisited.add(nextWord);
                                queue.offer(nextWord);
                                parents.computeIfAbsent(nextWord, k -> new HashSet<>()).add(word);
                            } else if (currentLevelVisited.contains(nextWord)) {
                                // Word already discovered in this level, add another parent
                                parents.computeIfAbsent(nextWord, k -> new HashSet<>()).add(word);
                            }
                        }
                    }
                    chars[pos] = original;
                }
            }

            visited.addAll(currentLevelVisited);
            if (currentLevelVisited.contains(endWord)) {
                foundEnd = true;
            }
        }

        if (!foundEnd) {
            return result;
        }

        // Backtracking from endWord to beginWord to build all paths
        LinkedList<String> path = new LinkedList<>();
        path.offerLast(endWord);
        backtrack(endWord, beginWord, parents, path, result);

        return result;
    }

    private void backtrack(String current, String begin,
                           Map<String, Set<String>> parents,
                           LinkedList<String> path,
                           List<List<String>> result) {
        if (current.equals(begin)) {
            List<String> temp = new ArrayList<>(path);
            Collections.reverse(temp);
            result.add(temp);
            return;
        }

        Set<String> prevWords = parents.getOrDefault(current, Collections.emptySet());
        for (String prev : prevWords) {
            path.offerLast(prev);
            backtrack(prev, begin, parents, path, result);
            path.removeLast();
        }
    }
}

