        // Start with the first node of each level
        Node currentLevelStart = root;

        while (currentLevelStart != null) {
            // Dummy node that will help build the next level's linked list
            Node dummyHead = new Node(0);
            Node tail = dummyHead;

            // Iterate over nodes in the current level using the next pointers
            for (Node node = currentLevelStart; node != null; node = node.next) {
                if (node.left != null) {
                    tail.next = node.left;
