public class Solution {
    public int makeArrayIncreasing(int[] arr1, int[] arr2) {
        // Sort and deduplicate arr2
        int[] sortedArr2 = arr2.clone();
        Arrays.sort(sortedArr2);
        int m = 0;
        for (int i = 0; i < sortedArr2.length; i++) {
            if (i == 0 || sortedArr2[i] != sortedArr2[i - 1]) {
                sortedArr2[m++] = sortedArr2[i];
            }
        }
        sortedArr2 = Arrays.copyOf(sortedArr2, m);

        final int INF = Integer.MAX_VALUE / 2;
        // Map: last value -> minimal operations to achieve that last value
        TreeMap<Integer, Integer> map = new TreeMap<>();
        map.put(Integer.MIN_VALUE, 0); // sentinel

        for (int val : arr1) {
            TreeMap<Integer, Integer> newMap = new TreeMap<>();

            for (Map.Entry<Integer, Integer> entry : map.entrySet()) {
                int last = entry.getKey();
                int opsPrev = entry.getValue();

                // Option 1: keep current value
                if (val > last) {
                    newMap.merge(val, opsPrev, Math::min);
                }

                // Option 2: replace with smallest arr2 element > last
                int idx = upperBound(sortedArr2, last);
                if (idx < m) {
                    int newVal = sortedArr2[idx];
                    newMap.merge(newVal, opsPrev + 1, Math::min);
                }
            }

            map = newMap;
            if (map.isEmpty()) {
                return -1; // impossible to continue
            }
        }

        int answer = INF;
        for (int ops : map.values()) {
            if (ops < answer) answer = ops;
        }
        return answer >= INF ? -1 : answer;
    }

    // Returns the first index in arr where arr[idx] > key
    private int upperBound(int[] arr, int key) {
        int l = 0, r = arr.length;
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (arr[mid] <= key) {
                l = mid + 1;
            } else {
                r = mid;
            }
        }
        return l;
    }
}

