public class Solution {
    public int makeArrayIncreasing(int[] arr1, int[] arr2) {
        int n = arr1.length;
        if (n == 0) return 0;

        // Sort and deduplicate arr2
        int[] sorted2 = arr2.clone();
        Arrays.sort(sorted2);
        int uniq = 0;
        for (int i = 0; i < sorted2.length; i++) {
            if (uniq == 0 || sorted2[i] != sorted2[uniq - 1]) {
                sorted2[uniq++] = sorted2[i];
            }
        }
        int[] arr2u = Arrays.copyOf(sorted2, uniq);

        HashMap<Integer, Integer> dp = new HashMap<>();
        dp.put(arr1[0], 0);

        // Replace first element with the largest arr2 value smaller than arr1[0]
        int idx = Arrays.binarySearch(arr2u, arr1[0]);
        int insertPoint = idx >= 0 ? idx : -idx - 1;
        if (insertPoint > 0) {
            int val = arr2u[insertPoint - 1];
            dp.put(val, 1);
        }

        final int INF = Integer.MAX_VALUE / 2;

        for (int i = 1; i < n; i++) {
            HashMap<Integer, Integer> next = new HashMap<>();
            for (Map.Entry<Integer, Integer> e : dp.entrySet()) {
                int last = e.getKey();
                int ops = e.getValue();

                // Keep arr1[i] if possible
                if (arr1[i] > last) {
                    int cur = next.getOrDefault(arr1[i], INF);
                    if (ops < cur) next.put(arr1[i], ops);
                }

                // Replace arr1[i] with the smallest arr2 value greater than last
                int pos = upperBound(arr2u, last);
                if (pos < arr2u.length) {
                    int val = arr2u[pos];
                    int cur = next.getOrDefault(val, INF);
                    if (ops + 1 < cur) next.put(val, ops + 1);
                }
            }
            dp = next;
            if (dp.isEmpty()) return -1;
        }

        int ans = INF;
        for (int ops : dp.values()) {
            if (ops < ans) ans = ops;
        }
        return ans == INF ? -1 : ans;
    }

    // Return index of first element > key
    private int upperBound(int[] arr, int key) {
        int l = 0, r = arr.length;
        while (l < r) {
            int m = (l + r) >>> 1;
            if (arr[m] <= key) l = m + 1;
            else r = m;
        }
        return l;
    }
}

