import java.util.Arrays;

public class Solution {
    public int makeArrayIncreasing(int[] arr1, int[] arr2) {
        int n = arr1.length;
        int m = arr2.length;
        // Sort and deduplicate arr2
        Arrays.sort(arr2);
        int uniqueCount = 0;
        for (int i = 0; i < m; i++) {
            if (uniqueCount == 0 || arr2[i] != arr2[uniqueCount - 1]) {
                arr2[uniqueCount++] = arr2[i];
            }
        }
        int[] sorted = Arrays.copyOf(arr2, uniqueCount);
        m = uniqueCount;

        final int INF = Integer.MAX_VALUE / 2;

        // dp[j] - minimal operations to make arr1[0..i] strictly increasing
        // with arr1[i] replaced by sorted[j]
        int[] dp = new int[m];
        Arrays.fill(dp, INF);

        // Initial step for i = 0
        for (int j = 0; j < m; j++) {
            if (sorted[j] < arr1[0]) {
                dp[j] = 1;
            }
        }
        int bestOps = 0; // keep arr1[0] unchanged

        // Iterate over remaining positions
        for (int i = 1; i < n; i++) {
            // prefix minima of dp
            int[] prefixMin = new int[m];
            int min = INF;
            for (int j = 0; j < m; j++) {
                if (dp[j] < min) min = dp[j];
                prefixMin[j] = min;
            }

            // position for arr1[i] in sorted
            int pos = lowerBound(sorted, arr1[i]);

            // Compute new bestOps (keeping arr1[i] unchanged)
            int newBestOps = INF;
            if (arr1[i] > arr1[i - 1]) {
                newBestOps = bestOps;
            }
            if (pos > 0 && prefixMin[pos - 1] < newBestOps) {
                newBestOps = prefixMin[pos - 1];
            }

            // Compute new dp
            int[] newDp = new int[m];
            Arrays.fill(newDp, INF);
            for (int j = 0; j < m; j++) {
                int candidate = INF;
                if (bestOps < INF && arr1[i - 1] < sorted[j]) {
                    candidate = bestOps + 1;
                }
                if (j > 0 && prefixMin[j - 1] < candidate) {
                    candidate = prefixMin[j - 1] + 1;
                }
                newDp[j] = candidate;
            }

            dp = newDp;
            bestOps = newBestOps;
        }

        int answer = bestOps;
        for (int v : dp) {
            if (v < answer) answer = v;
        }
        return answer >= INF ? -1 : answer;
    }

    // Helper: lower bound for sorted array
    private int lowerBound(int[] arr, int key) {
        int idx = Arrays.binarySearch(arr, key);
        if (idx < 0) {
            return -idx - 1;
        }
        return idx;
    }
}

