import java.util.*;

public class Solution {
    public int makeArrayIncreasing(int[] arr1, int[] arr2) {
        // sort and deduplicate arr2
        Arrays.sort(arr2);
        int m = 0;
        for (int i = 0; i < arr2.length; i++) {
            if (i == 0 || arr2[i] != arr2[i - 1]) {
                arr2[m++] = arr2[i];
            }
        }
        arr2 = Arrays.copyOf(arr2, m);

        int n = arr1.length;
        // memoization maps for each index
        @SuppressWarnings("unchecked")
        Map<Long, Integer>[] memo = new HashMap[n];
        for (int i = 0; i < n; i++) {
            memo[i] = new HashMap<>();
        }

        final int INF = Integer.MAX_VALUE / 2;

        class Solver {
            int solve(int i, long prev) {
                if (i == n) return 0;
                Integer cached = memo[i].get(prev);
                if (cached != null) return cached;

                int best = INF;

                // Option 1: keep arr1[i] if possible
                if (arr1[i] > prev) {
                    best = Math.min(best, solve(i + 1, arr1[i]));
                }

                // Option 2: replace with smallest arr2 element greater than prev
                int idx = findNext(arr2, prev);
                if (idx != -1) {
                    int replaced = 1 + solve(i + 1, arr2[idx]);
                    best = Math.min(best, replaced);
                }

                memo[i].put(prev, best);
                return best;
            }

            // binary search for first element > prev
            int findNext(int[] sortedArr, long prev) {
                int l = 0, r = sortedArr.length - 1, res = -1;
                while (l <= r) {
                    int mid = l + (r - l) / 2;
                    if ((long) sortedArr[mid] > prev) {
                        res = mid;
                        r = mid - 1;
                    } else {
                        l = mid + 1;
                    }
                }
                return res;
            }
        }

        int result = new Solver().solve(0, Long.MIN_VALUE);
        return result >= INF ? -1 : result;
    }
}

