public class Solution {
    public int maximumSum(int[] arr) {
        if (arr == null || arr.length == 0) return 0;
        int n = arr.length;
        int keep = arr[0];          // max subarray sum ending at current index without deletion
        int delete = Integer.MIN_VALUE; // max subarray sum ending at current index with one deletion
        int result = arr[0];
        for (int i = 1; i < n; i++) {
            int newDelete = Math.max(delete + arr[i], keep); // delete current or keep previous deletion
            int newKeep = Math.max(keep + arr[i], arr[i]);   // start new subarray or extend
            keep = newKeep;
            delete = newDelete;
            result = Math.max(result, Math.max(keep, delete));
        }
        return result;
    }
}

