        }

        int ans = arr[0];
        for (int i = 0; i < n; i++) {
            ans = Math.max(ans, forward[i]);          // no deletion
            if (i > 0 && i < n - 1) {                 // delete arr[i]
                ans = Math.max(ans, forward[i - 1] + backward[i + 1]);
            }
        }

