public class Solution {
    public int maximumSum(int[] arr) {
        if (arr == null || arr.length == 0) return 0; // edge case, though problem guarantees non-empty
        int n = arr.length;
        if (n == 1) return arr[0];

        int keep = arr[0];      // max sum ending at current index without deletion
        int del = Integer.MIN_VALUE; // max sum ending at current index with one deletion
        int best = arr[0];

        for (int i = 1; i < n; i++) {
            int newDel = Math.max(del + arr[i], keep);           // delete current element or extend previous deletion
            int newKeep = Math.max(keep + arr[i], arr[i]);        // no deletion
            keep = newKeep;
            del = newDel;
            best = Math.max(best, Math.max(keep, del));
        }
        return best;
    }
}

