public class Solution {

    private static class Pair {
        char c;
        int count;

        Pair(char c, int count) {
            this.c = c;
            this.count = count;
        }
    }

    public int longestSubstring(String text) {
        if (text == null || text.length() == 0) {
            return 0;
        }

        int n = text.length();
        // Count total occurrences of each character
        int[] total = new int[26];
        for (int i = 0; i < n; i++) {
            total[text.charAt(i) - 'a']++;
        }

        // Build list of consecutive blocks
        List<Pair> blocks = new ArrayList<>();
        char prev = text.charAt(0);
        int cnt = 1;
        for (int i = 1; i < n; i++) {
            char cur = text.charAt(i);
            if (cur == prev) {
                cnt++;
            } else {
                blocks.add(new Pair(prev, cnt));
                prev = cur;
                cnt = 1;
            }
        }
        blocks.add(new Pair(prev, cnt));

        int maxLen = 0;
        int m = blocks.size();

        for (int i = 0; i < m; i++) {
            Pair block = blocks.get(i);
            int charIdx = block.c - 'a';

            // Case 1: swap one occurrence of the same character from elsewhere
            if (total[charIdx] > block.count) {
                maxLen = Math.max(maxLen, block.count + 1);
            } else {
                maxLen = Math.max(maxLen, block.count);
            }

            // Case 2: merge with next block if middle block is different
            if (i + 2 < m) {
                Pair next = blocks.get(i + 1);
                Pair nextNext = blocks.get(i + 2);
                if (block.c == nextNext.c && block.c != next.c) {
                    int merged = block.count + next.count + nextNext.count;
                    if (total[charIdx] > merged) {
                        merged++; // we can bring one more from elsewhere
                    }
                    maxLen = Math.max(maxLen, merged);
                }
            }
        }

        return maxLen;
    }
}

