    /**
     * Returns the length of the longest substring that can be made of repeated
     * characters after performing at most one swap of any two characters in the string.
     *
     * @param text the input string
     * @return maximum length of a repeated-character substring after one swap
     */
    public int longestSubstring(String text) {
        if (text == null || text.isEmpty()) return 0;

        int n = text.length();
        int[] total = new int[26];
        for (int i = 0; i < n; i++) {
            total[text.charAt(i) - 'a']++;
        }

        int best = 0;

        for (int cIdx = 0; cIdx < 26; cIdx++) {
            if (total[cIdx] == 0) continue; // character not present
            char c = (char) ('a' + cIdx);
            int maxForC = 0;
            int i = 0;
            while (i < n) {
                if (text.charAt(i) != c) {
                    i++;
                    continue;
                }

                // start of a block of character c
                int j = i;
                while (j < n && text.charAt(j) == c) j++;
                int len1 = j - i;

                // consider extending this block by one swap if available
                maxForC = Math.max(maxForC, Math.min(total[cIdx], len1 + 1));

                // consider merging two blocks separated by a single different character
                int k = j + 1; // skip one character between blocks
                if (k < n && text.charAt(k) == c) {
                    int l = k;
                    while (l < n && text.charAt(l) == c) l++;
                    int len2 = l - k;
                    maxForC = Math.max(maxForC,
                            Math.min(total[cIdx], len1 + len2 + 1));
                }

                i = j; // move to the end of the current block
            }

            best = Math.max(best, maxForC);
        }

        return best;
    }
}

