import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    // Helper class for character runs
    private static class Run {
        char c;
        int len;
        Run(char c, int len) {
            this.c = c;
            this.len = len;
        }
    }

    // Pair class used by the template (not required for the solution)
    public static class Pair {
        char c;
        int count;
        public Pair(char c, int count) {
            this.c = c;
            this.count = count;
        }
    }

    public int longestRepeatingCharacterSwap(String text) {
        if (text == null || text.length() == 0) {
            return 0;
        }
        int n = text.length();

        // Count total occurrences of each character
        Map<Character, Integer> totalCount = new HashMap<>();
        for (int i = 0; i < n; i++) {
            char ch = text.charAt(i);
            totalCount.put(ch, totalCount.getOrDefault(ch, 0) + 1);
        }

        // Build list of consecutive runs
        List<Run> runs = new ArrayList<>();
        int idx = 0;
        while (idx < n) {
            char ch = text.charAt(idx);
            int start = idx;
            while (idx < n && text.charAt(idx) == ch) {
                idx++;
            }
            int len = idx - start;
            runs.add(new Run(ch, len));
        }

        int best = 0;

        // Evaluate single-run extensions
        for (Run r : runs) {
            int total = totalCount.get(r.c);
            int cand = Math.min(r.len + 1, total);
            if (cand > best) {
                best = cand;
            }
        }

        // Evaluate two-run merges separated by one different character
        for (int i = 0; i + 2 < runs.size(); i++) {
            Run r1 = runs.get(i);
            Run r2 = runs.get(i + 1);
            Run r3 = runs.get(i + 2);
            if (r1.c == r3.c && r1.c != r2.c) {
                int total = totalCount.get(r1.c);
                int cand = Math.min(r1.len + r3.len + 1, total);
                if (cand > best) {
                    best = cand;
                }
            }
        }

        return best;
    }
}

