public class Solution {
    public List<TreeNode> delNodes(TreeNode root, int[] to_delete) {
        Set<Integer> deleteSet = new HashSet<>();
        for (int val : to_delete) {
            deleteSet.add(val);
        }
        List<TreeNode> result = new ArrayList<>();
        if (root != null && !deleteSet.contains(root.val)) {
            result.add(root);
        }
        deleteHelper(root, deleteSet, result);
        return result;
    }

    private TreeNode deleteHelper(TreeNode node, Set<Integer> deleteSet, List<TreeNode> result) {
        if (node == null) {
            return null;
        }

        node.left = deleteHelper(node.left, deleteSet, result);
        node.right = deleteHelper(node.right, deleteSet, result);

        if (deleteSet.contains(node.val)) {
            if (node.left != null && !deleteSet.contains(node.left.val)) {
                result.add(node.left);
            }
            if (node.right != null && !deleteSet.contains(node.right.val)) {
                result.add(node.right);
            }
            return null;
        }

        return node;
    }
}

