public class Solution {
    public int maxDistance(int[][] grid) {
        int n = grid.length;
        if (n == 0) return -1;

        boolean[][] visited = new boolean[n][n];
        Queue<int[]> queue = new LinkedList<>();

        // Initialize queue with all land cells
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    visited[i][j] = true;
                    queue.offer(new int[]{i, j});
                }
            }
        }

        // If there is no land or no water, return -1
        if (queue.isEmpty() || queue.size() == n * n) {
            return -1;
        }

        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        int distance = 0;
        boolean foundWater = false;

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int s = 0; s < size; s++) {
                int[] cur = queue.poll();
                for (int[] d : dirs) {
                    int ni = cur[0] + d[0];
                    int nj = cur[1] + d[1];
                    if (ni >= 0 && ni < n && nj >= 0 && nj < n && !visited[ni][nj] && grid[ni][nj] == 0) {
                        visited[ni][nj] = true;
                        queue.offer(new int[]{ni, nj});
                        foundWater = true;
                    }
                }
            }
            distance++;
        }

        return foundWater ? distance - 1 : -1;
    }
}

