        while (!q.isEmpty()) {
            int[] cell = q.poll();
            int x = cell[0], y = cell[1];
            for (int[] d : dirs) {
                int nx = x + d[0];
                int ny = y + d[1];
                if (nx >= 0 && nx < n && ny >= 0 && ny < n && grid[nx][ny] == 0) {
                    grid[nx][ny] = grid[x][y] + 1;
                    maxDist = Math.max(maxDist, grid[nx][ny]);
                    q.offer(new int[]{nx, ny});
                }
            }
        }
        // maxDist is distance from land including the initial land cells at value 1
        return maxDist - 1;
    }
}

