import java.util.ArrayDeque;
import java.util.Deque;

public class Solution {
    public int mctFromLeafValues(int[] arr) {
        // Use a monotonic decreasing stack to compute the minimal sum
        Deque<Integer> stack = new ArrayDeque<>();
        long sum = 0;
        for (int val : arr) {
            // While current value is greater than the top of the stack,
            // we can form a product with the popped element and the
            // smaller of the current value and the new stack top
            while (!stack.isEmpty() && val > stack.peek()) {
                int mid = stack.pop();
                int left = stack.peek();
                sum += (long) mid * Math.min(left, val);
            }
            stack.push(val);
        }
        // Process remaining elements in the stack
        while (stack.size() > 1) {
            int mid = stack.pop();
            sum += (long) mid * stack.peek();
        }
        return (int) sum;
    }
}

