    private int dfs(int index, int m, int[] suffix, int[][] memo) {
        int n = suffix.length - 1;
        if (index == n) return 0;
        if (memo[index][m] != -1) return memo[index][m];

        int maxTake = Math.min(2 * m, n - index);
        int best = 0;
        for (int x = 1; x <= maxTake; x++) {
            int nextM = Math.max(m, x);
            int opponent = dfs(index + x, nextM, suffix, memo);
            int current = suffix[index] - opponent;
            if (current > best) best = current;
        }
        memo[index][m] = best;
        return best;
    }
}

