import java.util.Map;

public class Solution {
    public int[] smallestSufficientTeam(String[] skills, List<List<String>> people) {
        int nSkills = skills.length;
        if (nSkills == 0) {
            return new int[0];
        }

        // Map each skill to a unique bit position
        Map<String, Integer> skillIndex = new HashMap<>();
        for (int i = 0; i < nSkills; i++) {
            skillIndex.put(skills[i], i);
        }

        int m = people.size();
        int[] personMask = new int[m];
        for (int i = 0; i < m; i++) {
            int mask = 0;
            for (String skill : people.get(i)) {
                Integer idx = skillIndex.get(skill);
                if (idx != null) {
                    mask |= 1 << idx;
                }
            }
            personMask[i] = mask;
        }

        int fullMask = (1 << nSkills) - 1;
        int[][] dp = new int[1 << nSkills][];
        dp[0] = new int[0];

        for (int mask = 0; mask <= fullMask; mask++) {
            if (dp[mask] == null) continue;
            for (int i = 0; i < m; i++) {
                int newMask = mask | personMask[i];
                if (dp[newMask] == null || dp[newMask].length > dp[mask].length + 1) {
                    int[] newTeam = new int[dp[mask].length + 1];
                    System.arraycopy(dp[mask], 0, newTeam, 0, dp[mask].length);
                    newTeam[newTeam.length - 1] = i;
                    dp[newMask] = newTeam;
                }
            }
        }

        return dp[fullMask] == null ? new int[0] : dp[fullMask];
    }
}

