                if (bit != null) {
                    mask |= 1 << bit;
                }
            }
            personMask[i] = mask;
        }

        final int INF = Integer.MAX_VALUE;
        int[] bestSize = new int[1 << nSkills];
        int[] prevMask = new int[1 << nSkills];
        int[] lastPerson = new int[1 << nSkills];
        Arrays.fill(bestSize, INF);
        Arrays.fill(prevMask, -1);
        Arrays.fill(lastPerson, -1);
        bestSize[0] = 0; // empty team

        for (int i = 0; i < m; i++) {
