public class Solution {
    private int pos;
    private char[] expr;

    public boolean parseBoolExpr(String expression) {
        expr = expression.toCharArray();
        pos = 0;
        return parse();
    }

    private boolean parse() {
        char c = expr[pos];
        if (c == 't') {
            pos++;
            return true;
        }
        if (c == 'f') {
            pos++;
            return false;
        }
        // operator
        pos++; // skip operator
        // skip '('
        pos++;
        boolean result;
        if (c == '!') {
            result = !parse();
        } else if (c == '&') {
            result = true;
            while (true) {
                result &= parse();
                if (expr[pos] == ',') {
                    pos++;
                } else {
                    break;
                }
            }
        } else { // '|'
            result = false;
            while (true) {
                result |= parse();
                if (expr[pos] == ',') {
                    pos++;
                } else {
                    break;
                }
            }
        }
        // skip ')'
        pos++;
        return result;
    }
}

