public class Solution {
    public boolean parseBoolExpr(String expression) {
        int[] idx = new int[]{0};
        return parse(expression, idx);
    }

    private boolean parse(String s, int[] idx) {
        char c = s.charAt(idx[0]);

        if (c == 't') {
            idx[0]++;
            return true;
        }
        if (c == 'f') {
            idx[0]++;
            return false;
        }
        if (c == '!') {
            idx[0]++; // skip '!'
            if (s.charAt(idx[0]) == '(') idx[0]++; // skip '('
            boolean val = parse(s, idx);
            if (s.charAt(idx[0]) == ')') idx[0]++; // skip ')'
            return !val;
        }
        if (c == '&' || c == '|') {
            boolean result = (c == '&'); // true for AND, false for OR
            idx[0]++; // skip operator
            if (s.charAt(idx[0]) == '(') idx[0]++; // skip '('
            while (true) {
                boolean inner = parse(s, idx);
                if (c == '&') result = result && inner;
                else result = result || inner;

                if (s.charAt(idx[0]) == ',') {
                    idx[0]++; // skip comma
                } else if (s.charAt(idx[0]) == ')') {
                    idx[0]++; // skip ')'
                    break;
                }
            }
            return result;
        }
        // Should never reach here for a valid expression
        return false;
    }
}

