            boolean val = parse(s, idx);
            idx[0]++; // skip ')'
            return !val;
        }

        // '&' or '|'
        char op = c; // '&' or '|'
        idx[0]++; // skip operator
        idx[0]++; // skip '('

        boolean result = (op == '&') ? true : false;

        while (true) {
            boolean val = parse(s, idx);
            if (op == '&') {
                result = result && val;
            } else {
                result = result || val;
            }

            if (s.charAt(idx[0]) == ')') {
                idx[0]++; // skip ')'
                break;
            } else {
                idx[0]++; // skip ','
            }
        }

        return result;
    }
}

