public class Solution {
    public String lastSubstring(String s) {
        int n = s.length();
        if (n == 0) return "";
        int i = 0, j = 1, k = 0;
        while (i < n && j < n && k < n) {
            char a = s.charAt(i + k);
            char b = s.charAt(j + k);
            if (a == b) {
                k++;
                continue;
            }
            if (a < b) {
                i = i + k + 1;
                if (i <= j) i = j + 1;
            } else {
                j = j + k + 1;
                if (j <= i) j = i + 1;
            }
            k = 0;
        }
        int start = Math.min(i, j);
        return s.substring(start);
    }
}

