import java.util.LinkedList;
import java.util.List;

public class Solution {
    public List<Integer> pathInZigZagTree(int label) {
        LinkedList<Integer> path = new LinkedList<>();
        while (label > 0) {
            path.addFirst(label);
            int level = 32 - Integer.numberOfLeadingZeros(label);
            int maxVal = (1 << level) - 1;
            int actual = (level % 2 == 1) ? label : maxVal - label;
            int parentActual = actual / 2;
            if (parentActual == 0) {
                break;
            }
            int parentLevel = level - 1;
            int parentMax = (1 << parentLevel) - 1;
            int parentLabel = (parentLevel % 2 == 1) ? parentActual : parentMax - parentActual;
            label = parentLabel;
        }
        return path;
    }
}

