        LinkedList<Integer> path = new LinkedList<>();
        while (label > 0) {
            int level = 32 - Integer.numberOfLeadingZeros(label); // level of current node
            path.addFirst(label);
            // Compute actual node label in normal binary tree
            int actual = (level % 2 == 1) ? label : ((1 << level) - 1 - label);
            int parentActual = actual >> 1; // parent in normal binary tree
            if (parentActual == 0) {
                break; // reached the root
            }
            int parentLevel = level - 1;
            // Convert parent back to zigzag labeling
            int parentLabel = (parentLevel % 2 == 1)
                    ? parentActual
                    : ((1 << parentLevel) - 1 - parentActual);
            label = parentLabel;
        }
        return path;
    }
}

