import java.util.LinkedList;
import java.util.List;
import java.util.Collections;

public class Solution {
    public List<Integer> pathInZigZagTree(int label) {
        List<Integer> path = new LinkedList<>();
        int current = label;
        int level = 32 - Integer.numberOfLeadingZeros(current);

        while (current > 0) {
            path.add(current);
            if (current == 1) break;

            long pow2 = 1L << level;          // 2^level
            long pow2Minus1 = pow2 - 1;
            long normal;

            if (level % 2 == 0) {
                normal = (1L << (level - 1)) + (pow2Minus1 - current);
            } else {
                normal = current;
            }

            long parentNormal = normal / 2;
            int parentLevel = level - 1;

            long parentZigzag;
            if (parentLevel % 2 == 0) {
                parentZigzag = (1L << parentLevel) - 1 -
                               (parentNormal - (1L << (parentLevel - 1)));
            } else {
                parentZigzag = parentNormal;
            }

            current = (int) parentZigzag;
            level = parentLevel;
        }

        Collections.reverse(path);
        return path;
    }
}

