import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Solution {
    public List<Integer> pathInZigZagTree(int label) {
        List<Integer> path = new ArrayList<>();
        int current = label;
        while (current >= 1) {
            path.add(current);
            if (current == 1) break;
            int level = getLevel(current);
            long start = 1L << (level - 1);
            long end = (1L << level) - 1;
            long actual = start + (end - current);
            long parentActual = actual / 2;
            int parentLevel = level - 1;
            long parentStart = 1L << (parentLevel - 1);
            long parentEnd = (1L << parentLevel) - 1;
            current = (int)(parentEnd - (parentActual - parentStart));
        }
        Collections.reverse(path);
        return path;
    }

    private int getLevel(int n) {
        int level = 1;
        int val = n;
        while (val > 1) {
            val >>= 1;
            level++;
        }
        return level;
    }
}

