import java.util.List;
import java.util.Map;

public class Solution {
    public List<Integer> findNumOfValidWords(String[] words, String[] puzzles) {
        Map<Integer, Integer> wordMaskCount = new HashMap<>();
        for (String word : words) {
            int mask = 0;
            for (char c : word.toCharArray()) {
                mask |= 1 << (c - 'a');
            }
            wordMaskCount.merge(mask, 1, Integer::sum);
        }

        List<Integer> result = new ArrayList<>(puzzles.length);
        for (String puzzle : puzzles) {
            int firstBit = 1 << (puzzle.charAt(0) - 'a');
            int restMask = 0;
            for (int i = 1; i < puzzle.length(); i++) {
                restMask |= 1 << (puzzle.charAt(i) - 'a');
            }

            int count = 0;
            // include subset that is only the first letter
            count += wordMaskCount.getOrDefault(firstBit, 0);

            // iterate over all subsets of restMask
            for (int subset = restMask; subset > 0; subset = (subset - 1) & restMask) {
                int combined = subset | firstBit;
                count += wordMaskCount.getOrDefault(combined, 0);
            }

            result.add(count);
        }
        return result;
    }
}

