            }
            int firstLetterMask = 1 << (puzzle.charAt(0) - 'a');

            int count = 0;
            // Enumerate all non-empty subsets of puzzleMask
            int submask = puzzleMask;
            while (true) {
                if ((submask & firstLetterMask) != 0) {
                    count += wordMaskCount.getOrDefault(submask, 0);
                }
                if (submask == 0) {
                    break;
                }
                submask = (submask - 1) & puzzleMask;
            }

            result.add(count);
        }

        return result;
    }
