public class Solution {
    public int largest1BorderedSquare(int[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return 0;
        }
        int m = grid.length;
        int n = grid[0].length;
        int[][] right = new int[m][n];
        int[][] down = new int[m][n];

        // Precompute consecutive 1s to the right
        for (int i = 0; i < m; i++) {
            int count = 0;
            for (int j = n - 1; j >= 0; j--) {
                if (grid[i][j] == 1) {
                    count++;
                } else {
                    count = 0;
                }
                right[i][j] = count;
            }
        }

        // Precompute consecutive 1s downwards
        for (int j = 0; j < n; j++) {
            int count = 0;
            for (int i = m - 1; i >= 0; i--) {
                if (grid[i][j] == 1) {
                    count++;
                } else {
                    count = 0;
                }
                down[i][j] = count;
            }
        }

        int maxSide = 0;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 0) continue;
                int maxPossible = Math.min(right[i][j], down[i][j]);
                for (int side = maxPossible; side > maxSide; side--) {
                    if (i + side - 1 >= m || j + side - 1 >= n) continue;
                    if (down[i][j + side - 1] >= side && right[i + side - 1][j] >= side) {
                        maxSide = side;
                        break; // no need to check smaller sides for this top-left
                    }
                }
            }
        }

        return maxSide * maxSide;
    }
}

