public class Solution {
    public int largest1BorderedSquare(int[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return 0;
        }
        int m = grid.length;
        int n = grid[0].length;

        // Prefix sums for each row and each column
        int[][] rowPrefix = new int[m][n + 1];
        int[][] colPrefix = new int[m + 1][n];

        for (int i = 0; i < m; i++) {
            rowPrefix[i][0] = 0;
            for (int j = 0; j < n; j++) {
                rowPrefix[i][j + 1] = rowPrefix[i][j] + (grid[i][j] == 1 ? 1 : 0);
            }
        }

        for (int j = 0; j < n; j++) {
            colPrefix[0][j] = 0;
            for (int i = 0; i < m; i++) {
                colPrefix[i + 1][j] = colPrefix[i][j] + (grid[i][j] == 1 ? 1 : 0);
            }
        }

        int maxSize = Math.min(m, n);
        for (int size = maxSize; size >= 1; size--) {
            for (int i = 0; i <= m - size; i++) {
                for (int j = 0; j <= n - size; j++) {
                    int top = rowPrefix[i][j + size] - rowPrefix[i][j];
                    if (top != size) continue;

                    int bottom = rowPrefix[i + size - 1][j + size] - rowPrefix[i + size - 1][j];
                    if (bottom != size) continue;

                    int left = colPrefix[i + size][j] - colPrefix[i][j];
                    if (left != size) continue;

                    int right = colPrefix[i + size][j + size - 1] - colPrefix[i][j + size - 1];
                    if (right != size) continue;

                    return size * size;
                }
            }
        }
        return 0;
    }
}

