public class Solution {
    public int largest1BorderedSquare(int[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return 0;
        }
        int m = grid.length;
        int n = grid[0].length;
        int[][] right = new int[m][n];
        int[][] down = new int[m][n];

        // compute right counts
        for (int i = 0; i < m; i++) {
            for (int j = n - 1; j >= 0; j--) {
                if (grid[i][j] == 1) {
                    right[i][j] = (j + 1 < n ? right[i][j + 1] : 0) + 1;
                } else {
                    right[i][j] = 0;
                }
            }
        }

        // compute down counts
        for (int j = 0; j < n; j++) {
            for (int i = m - 1; i >= 0; i--) {
                if (grid[i][j] == 1) {
                    down[i][j] = (i + 1 < m ? down[i + 1][j] : 0) + 1;
                } else {
                    down[i][j] = 0;
                }
            }
        }

        int maxSide = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    int possible = Math.min(right[i][j], down[i][j]);
                    for (int side = possible; side > maxSide; side--) {
                        if (right[i + side - 1][j] >= side && down[i][j + side - 1] >= side) {
                            maxSide = side;
                            break;
                        }
                    }
                }
            }
        }

        return maxSide * maxSide;
    }
}

