public class Solution {
    public int largest1BorderedSquare(int[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) return 0;
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] right = new int[rows][cols];
        int[][] down = new int[rows][cols];

        // Precompute consecutive ones to the right
        for (int i = rows - 1; i >= 0; i--) {
            for (int j = cols - 1; j >= 0; j--) {
                if (grid[i][j] == 1) {
                    right[i][j] = 1 + (j + 1 < cols ? right[i][j + 1] : 0);
                    down[i][j] = 1 + (i + 1 < rows ? down[i + 1][j] : 0);
                } else {
                    right[i][j] = 0;
                    down[i][j] = 0;
                }
            }
        }

        int maxSide = 0;
        // Iterate over all possible top-left corners
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 0) continue;
                int maxLen = Math.min(rows - i, cols - j);
                if (maxLen <= maxSide) continue; // cannot improve
                for (int len = maxLen; len > maxSide; len--) {
                    if (right[i][j] >= len && down[i][j] >= len
                            && down[i][j + len - 1] >= len
                            && right[i + len - 1][j] >= len) {
                        maxSide = len;
                        break;
                    }
                }
            }
        }
        return maxSide * maxSide;
    }
}

