            blueAdj.get(e[0]).add(e[1]);
        }

        // dist[node][color], color 0=red, 1=blue
        int[][] dist = new int[n][2];
        for (int i = 0; i < n; i++) {
            Arrays.fill(dist[i], -1);
        }

        Queue<int[]> q = new LinkedList<>();
        // start from node 0 with both colors as 0 distance
        dist[0][0] = 0;
        dist[0][1] = 0;
        q.offer(new int[]{0, 0}); // color 0 means next edge can be red
        q.offer(new int[]{0, 1}); // color 1 means next edge can be blue

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int node = cur[0];
            int color = cur[1];
            int nextColor = 1 - color; // alternate color
            ArrayList<ArrayList<Integer>> nextAdj = (nextColor == 0) ? redAdj : blueAdj;

            for (int next : nextAdj.get(node)) {
                if (dist[next][nextColor] == -1) {
                    dist[next][nextColor] = dist[node][color] + 1;
                    q.offer(new int[]{next, nextColor});
                }
            }
        }

