                ans[i] = -1;
            } else if (d0 == -1) {
                ans[i] = d1;
            } else if (d1 == -1) {
                ans[i] = d0;
            } else {
                ans[i] = Math.min(d0, d1);
            }
        }
        return ans;
    }
