public class Solution {
    public int longestDecomposition(String text) {
        int n = text.length();
        int i = 0, j = n - 1;
        int count = 0;
        while (i < j) {
            int l = 0;
            while (i + l < j - l + 1 && text.charAt(i + l) == text.charAt(j - l)) {
                l++;
            }
            if (l == 0) {
                // No matching prefix-suffix, break
                break;
            }
            count += 2;
            i += l;
            j -= l;
        }
        if (i == j) {
            count += 1;
        }
        return count;
    }
}

