            if (!matched) {
                // This situation should never happen because at least the whole remaining substring matches itself.
                // However, to be safe, we treat the remaining as a single part.
                count += 1;
                break;
            }
        }

        if (left == right) {
            count += 1;
        }

        return count;
    }
}

