public class Solution {
    public ListNode removeZeroSumSublists(ListNode head) {
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        Map<Long, ListNode> map = new HashMap<>();
        long sum = 0;
        for (ListNode node = dummy; node != null; node = node.next) {
            sum += node.val;
            if (map.containsKey(sum)) {
                ListNode prev = map.get(sum);
                // Remove intermediate sums from the map
                ListNode temp = prev.next;
                long tempSum = sum;
                while (temp != node) {
                    tempSum += temp.val;
                    map.remove(tempSum);
                    temp = temp.next;
                }
                prev.next = node.next;
            } else {
                map.put(sum, node);
            }
        }
        return dummy.next;
    }
}

