public class Solution {
    public String alphabetBoardPath(String target) {
        StringBuilder sb = new StringBuilder();
        int curRow = 0, curCol = 0;
        for (char ch : target.toCharArray()) {
            int targetRow = (ch - 'a') / 5;
            int targetCol = (ch - 'a') % 5;
            if (ch == 'z') {
                targetRow = 5;
                targetCol = 0;
            }
            int dr = targetRow - curRow;
            int dc = targetCol - curCol;

            if (ch == 'z') {
                // move horizontally first to avoid invalid positions
                if (dc < 0) sb.append("L".repeat(-dc));
                else if (dc > 0) sb.append("R".repeat(dc));
                if (dr > 0) sb.append("D".repeat(dr));
                else if (dr < 0) sb.append("U".repeat(-dr));
            } else if (curRow == 5 && curCol == 0) { // current is 'z'
                // move vertically first
                if (dr < 0) sb.append("U".repeat(-dr));
                else if (dr > 0) sb.append("D".repeat(dr));
                if (dc < 0) sb.append("L".repeat(-dc));
                else if (dc > 0) sb.append("R".repeat(dc));
            } else {
                // normal order: vertical then horizontal
                if (dr < 0) sb.append("U".repeat(-dr));
                else if (dr > 0) sb.append("D".repeat(dr));
                if (dc < 0) sb.append("L".repeat(-dc));
                else if (dc > 0) sb.append("R".repeat(dc));
            }

            sb.append('!');
            curRow = targetRow;
            curCol = targetCol;
        }
        return sb.toString();
    }
