        int n = arr1.length;
        if (n == 0) return 0;
        long ans = 0;
        for (int s1 = -1; s1 <= 1; s1 += 2) {
            for (int s2 = -1; s2 <= 1; s2 += 2) {
                for (int s3 = -1; s3 <= 1; s3 += 2) {
                    long max = Long.MIN_VALUE;
                    long min = Long.MAX_VALUE;
                    for (int i = 0; i < n; i++) {
                        long val = s1 * (long)arr1[i] + s2 * (long)arr2[i] + s3 * (long)i;
                        if (val > max) max = val;
                        if (val < min) min = val;
                    }
                    long diff = max - min;
                    if (diff > ans) ans = diff;
                }
            }
        }
        return (int) ans;
    }
