public class Solution {
    public int[] distributeCandies(int candies, int numPeople) {
        int[] result = new int[numPeople];
        if (candies <= 0 || numPeople <= 0) return result;

        long totalCandies = candies;
        long n = numPeople;

        // Find maximum m such that m*(m+1)/2 <= totalCandies
        long m = (long) ((Math.sqrt(1 + 8.0 * totalCandies) - 1) / 2);
        long rounds = m / n; // number of complete rounds

        long candiesUsed = rounds * n * (rounds * n + 1) / 2;
        long remaining = totalCandies - candiesUsed;

        // Distribute candies for complete rounds
        for (int i = 0; i < numPeople; i++) {
            result[i] = (int) (rounds * n + i + 1);
        }

        // Distribute remaining candies
        for (int i = 0; i < numPeople && remaining > 0; i++) {
            long give = Math.min(remaining, rounds * n + i + 1);
            result[i] += (int) give;
            remaining -= give;
        }

        return result;
    }
}

