import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Solution {
    public List<List<Integer>> criticalConnections(int n, List<List<Integer>> connections) {
        // Build adjacency list
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }
        for (List<Integer> edge : connections) {
            int u = edge.get(0);
            int v = edge.get(1);
            graph.get(u).add(v);
            graph.get(v).add(u);
        }

        boolean[] visited = new boolean[n];
        int[] disc = new int[n];
        int[] low = new int[n];
        int[] time = {0};
        List<List<Integer>> result = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                dfs(i, -1, graph, visited, disc, low, time, result);
            }
        }

        return result;
    }

    private void dfs(int u, int parent, List<List<Integer>> graph,
                     boolean[] visited, int[] disc, int[] low,
                     int[] time, List<List<Integer>> result) {
        visited[u] = true;
        disc[u] = low[u] = time[0]++;
        for (int v : graph.get(u)) {
            if (v == parent) {
                continue;
            }
            if (!visited[v]) {
                dfs(v, u, graph, visited, disc, low, time, result);
                low[u] = Math.min(low[u], low[v]);
                if (low[v] > disc[u]) {
                    result.add(Arrays.asList(u, v));
                }
            } else {
                low[u] = Math.min(low[u], disc[v]);
            }
        }
    }
}

