import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Solution {
    private List<List<Integer>> result;
    private int time;

    public List<List<Integer>> criticalConnections(int n, List<List<Integer>> connections) {
        result = new ArrayList<>();
        time = 0;

        @SuppressWarnings("unchecked")
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        for (List<Integer> edge : connections) {
            int a = edge.get(0);
            int b = edge.get(1);
            graph[a].add(b);
            graph[b].add(a);
        }

        int[] low = new int[n];
        Arrays.fill(low, -1);

        // In case the graph is not fully connected, iterate over all nodes
        for (int i = 0; i < n; i++) {
            if (low[i] == -1) {
                dfs(i, -1, graph, low);
            }
        }

        return result;
    }

    private void dfs(int node, int parent, List<Integer>[] graph, int[] low) {
        low[node] = time++;
        for (int nei : graph[node]) {
            if (nei == parent) {
                continue;
            }
            if (low[nei] == -1) { // not visited
                dfs(nei, node, graph, low);
                if (low[nei] > low[node]) {
                    result.add(Arrays.asList(node, nei));
                }
                low[node] = Math.min(low[node], low[nei]);
            } else {
                // already visited
                low[node] = Math.min(low[node], low[nei]);
            }
        }
    }
}

