public class Solution {
    private int time;
    private int[] ids;
    private int[] low;
    private boolean[] visited;
    private List<List<Integer>> result;
    private List<Integer>[] graph;

    public List<List<Integer>> criticalConnections(int n, List<List<Integer>> connections) {
        // Build graph
        graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (List<Integer> edge : connections) {
            int a = edge.get(0);
            int b = edge.get(1);
            graph[a].add(b);
            graph[b].add(a);
        }

        // Initialize helpers
        ids = new int[n];
        low = new int[n];
        visited = new boolean[n];
        result = new ArrayList<>();
        time = 0;

        // Run DFS from each node (graph is connected but safe)
        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                dfs(i, -1);
            }
        }

        return result;
    }

    private void dfs(int node, int parent) {
        visited[node] = true;
        ids[node] = low[node] = time++;

        for (int nei : graph[node]) {
            if (nei == parent) {
                continue;
            }
            if (!visited[nei]) {
                dfs(nei, node);
                low[node] = Math.min(low[node], low[nei]);

                if (low[nei] > ids[node]) {
                    List<Integer> bridge = new ArrayList<>(2);
                    bridge.add(node);
                    bridge.add(nei);
                    result.add(bridge);
                }
            } else {
                low[node] = Math.min(low[node], ids[nei]);
            }
        }
    }
}

