import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Finds all critical connections (bridges) in an undirected connected graph.
 */
public class Solution {
    private int time;
    private int[] rank;
    private List<List<Integer>> bridges;

    public List<List<Integer>> criticalConnections(int n, List<List<Integer>> connections) {
        // Build adjacency list
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; ++i) {
            graph[i] = new ArrayList<>();
        }
        for (List<Integer> conn : connections) {
            int u = conn.get(0);
            int v = conn.get(1);
            graph[u].add(v);
            graph[v].add(u);
        }

        rank = new int[n];
        for (int i = 0; i < n; ++i) {
            rank[i] = -1;
        }
        bridges = new ArrayList<>();
        time = 0;

        // Run DFS from node 0 (graph is guaranteed to be connected)
        dfs(0, -1, graph);

        return bridges;
    }

    private void dfs(int node, int parent, List<Integer>[] graph) {
        rank[node] = time++;
        for (int nei : graph[node]) {
            if (nei == parent) {
                continue;
            }
            if (rank[nei] == -1) { // unvisited
                dfs(nei, node, graph);
                // After returning, check if edge is a bridge
                if (rank[nei] > rank[node]) {
                    // bridge found
                    bridges.add(List.of(node, nei));
                }
                // Update rank[node] with the lowest reachable rank from its subtree
                rank[node] = Math.min(rank[node], rank[nei]);
            } else { // visited neighbor (back edge)
                rank[node] = Math.min(rank[node], rank[nei]);
            }
        }
    }
}

