public class Solution {
    private int getFreq(String s) {
        char min = 'z' + 1;
        int count = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < min) {
                min = c;
                count = 1;
            } else if (c == min) {
                count++;
            }
        }
        return count;
    }

    private int upperBound(int[] arr, int target) {
        int low = 0, high = arr.length;
        while (low < high) {
            int mid = (low + high) >>> 1;
            if (arr[mid] <= target) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return low;
    }

    public int[] numSmallerByFrequency(String[] queries, String[] words) {
        int wCount = words.length;
        int[] wordFreq = new int[wCount];
        for (int i = 0; i < wCount; i++) {
            wordFreq[i] = getFreq(words[i]);
        }
        Arrays.sort(wordFreq);

        int qCount = queries.length;
        int[] result = new int[qCount];
        for (int i = 0; i < qCount; i++) {
            int fq = getFreq(queries[i]);
            int idx = upperBound(wordFreq, fq);
            result[i] = wCount - idx;
        }
        return result;
    }
}

