public class Solution {
    // Computes frequency of the lexicographically smallest character in a string
    private int smallestCharFrequency(String s) {
        char min = 'z' + 1;
        int count = 0;
        for (char ch : s.toCharArray()) {
            if (ch < min) {
                min = ch;
                count = 1;
            } else if (ch == min) {
                count++;
            }
        }
        return count;
    }

    public int[] numSmallerByFrequency(String[] queries, String[] words) {
        int n = words.length;
        int[] wordFreqs = new int[n];
        for (int i = 0; i < n; i++) {
            wordFreqs[i] = smallestCharFrequency(words[i]);
        }
        Arrays.sort(wordFreqs);

        int m = queries.length;
        int[] answer = new int[m];
        for (int i = 0; i < m; i++) {
            int qFreq = smallestCharFrequency(queries[i]);
            int target = qFreq + 1; // smallest frequency greater than qFreq
            int idx = Arrays.binarySearch(wordFreqs, target);
            if (idx < 0) {
                idx = -idx - 1; // insertion point where target would be inserted
            }
            answer[i] = n - idx; // count of frequencies greater than qFreq
        }
        return answer;
    }
}

