import java.util.*;

public class Solution {
    public int[] recoverArray(int n, int[] sums) {
        return recover(n, sums);
    }

    private int[] recover(int n, int[] sums) {
        Arrays.sort(sums);
        if (n == 0) {
            return new int[0];
        }
        int candidate1 = sums[1] - sums[0];
        int candidate2 = sums[sums.length - 1] - sums[sums.length - 2];

        int[] result = tryRecover(n, sums, candidate1);
        if (result != null) {
            return result;
        }
        result = tryRecover(n, sums, candidate2);
        if (result != null) {
            return result;
        }
        // According to problem statement, this should never happen
        return new int[0];
    }

    private int[] tryRecover(int n, int[] sums, int x) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int s : sums) {
            freq.put(s, freq.getOrDefault(s, 0) + 1);
        }

        List<Integer> withoutX = new ArrayList<>();
        for (int s : sums) {
            int cntS = freq.getOrDefault(s, 0);
            if (cntS == 0) {
                continue;
            }
            freq.put(s, cntS - 1);
            int t = s + x;
            int cntT = freq.getOrDefault(t, 0);
            if (cntT == 0) {
                return null; // cannot partition with this x
            }
            freq.put(t, cntT - 1);
            withoutX.add(s);
        }

        int[] withoutXArray = new int[withoutX.size()];
        for (int i = 0; i < withoutX.size(); i++) {
            withoutXArray[i] = withoutX.get(i);
        }

        int[] rest = recover(n - 1, withoutXArray);
        int[] result = new int[n];
        System.arraycopy(rest, 0, result, 0, rest.length);
        result[rest.length] = x;
        return result;
    }
}

