public class Solution {
    public int[] recoverArray(int n, int[] sums) {
        if (n == 0) return new int[0];
        Arrays.sort(sums);
        int first = sums[0];
        int second = sums[1];
        int x = second - first; // smallest element

        // Frequency map for sums
        Map<Long, Integer> freq = new HashMap<>();
        for (int s : sums) {
            freq.put((long) s, freq.getOrDefault((long) s, 0) + 1);
        }

        List<Integer> withoutX = new ArrayList<>();
        for (int s : sums) {
            long key = s;
            Integer cnt = freq.get(key);
            if (cnt == null || cnt == 0) continue;

            // use this sum as part of group without x
            withoutX.add(s);
            freq.put(key, cnt - 1);

            // reduce count of sum + x
            long with = key + x;
            freq.put(with, freq.getOrDefault(with, 0) - 1);
        }

        int[] rest = recoverArray(n - 1, withoutX.stream().mapToInt(Integer::intValue).toArray());

        int[] ans = new int[n];
        ans[0] = x;
        System.arraycopy(rest, 0, ans, 1, rest.length);
        return ans;
    }
}

