public class Solution {
    public int[] recoverArray(int n, int[] sums) {
        Arrays.sort(sums);
        TreeMap<Integer, Integer> freq = new TreeMap<>();
        for (int val : sums) {
            freq.put(val, freq.getOrDefault(val, 0) + 1);
        }

        List<Integer> result = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            int min1 = freq.firstKey();
            Integer min2Obj = freq.higherKey(min1);
            int min2 = min2Obj != null ? min2Obj : min1; // just to avoid NPE, will not happen before last iteration
            int d = min2 - min1;

            if (d == 0) { // zero element
                result.add(0);
                TreeMap<Integer, Integer> newFreq = new TreeMap<>();
                for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {
                    int cnt = entry.getValue();
                    int half = cnt / 2;
                    if (half > 0) {
                        newFreq.put(entry.getKey(), half);
                    }
                }
                freq = newFreq;
                continue;
            }

            TreeMap<Integer, Integer> newFreq = new TreeMap<>();
            for (Integer key : freq.keySet()) {
                int cnt = freq.get(key);
                while (cnt > 0) {
                    // Remove one occurrence of key
                    freq.put(key, freq.get(key) - 1);
                    // Remove one occurrence of key + d
                    int paired = key + d;
                    freq.put(paired, freq.get(paired) - 1);
                    // Add key to newFreq
                    newFreq.put(key, newFreq.getOrDefault(key, 0) + 1);
                    cnt--;
                }
            }
            freq = newFreq;
            result.add(d);
        }

        int[] ans = new int[n];
        for (int i = 0; i < n; i++) {
            ans[i] = result.get(i);
        }
        return ans;
    }
}

