public class Solution {
    public boolean canBeIncreasing(int[] nums) {
        int n = nums.length;
        if (n <= 2) return true;

        int idx = -1;
        for (int i = 1; i < n; i++) {
            if (nums[i - 1] >= nums[i]) {
                if (idx != -1) return false; // more than one violation
                idx = i;
            }
        }

        if (idx == -1) return true; // already strictly increasing

        // Check if removing one of the violating elements fixes the array
        if (idx == 1 || idx == n - 1) return true;

        return nums[idx - 2] < nums[idx] || nums[idx - 1] < nums[idx + 1];
    }
}

