public class Solution {
    public int minStoneSum(int[] piles, int k) {
        // Max-heap to always pick the pile with the largest number of stones
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
        int total = 0;
        for (int stone : piles) {
            maxHeap.offer(stone);
            total += stone;
        }

        while (k-- > 0) {
            int largest = maxHeap.poll();
            int reduced = largest / 2; // floor division
            int removed = largest - reduced;
            total -= removed;
            maxHeap.offer(reduced);
        }

        return total;
    }
}

