public class Solution {
    public int eliminateMaximum(int[] dist, int[] speed) {
        int n = dist.length;
        int[] limits = new int[n];
        for (int i = 0; i < n; i++) {
            // The monster must be eliminated before the minute it arrives.
            // If it arrives at minute t, it cannot be killed at minute t.
            // So the latest minute we can kill it is t - 1.
            // Since dist[i] / speed[i] gives the arrival minute (floor division),
            // subtract 1 to get the last allowed kill minute.
            limits[i] = dist[i] / speed[i] - 1;
        }
        Arrays.sort(limits);

        int kills = 0;
        for (int limit : limits) {
            if (limit < kills) {
                break;
            }
            kills++;
        }
        return kills;
    }
}

