public class Solution {
    public int minSwaps(String s) {
        int balance = 0; // number of unmatched '['
        int swaps = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '[') {
                balance++;
            } else { // c == ']'
                if (balance == 0) {
                    // need to swap this ']' with a '[' from the left
                    swaps++;
                    balance = 1; // after swap, we have one unmatched '['
                } else {
                    balance--;
                }
            }
        }
        return swaps;
    }
}

