public class Solution {
    public int[][] rotateGrid(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;
        int layers = Math.min(m, n) / 2;

        for (int layer = 0; layer < layers; layer++) {
            int top = layer;
            int left = layer;
            int bottom = m - 1 - layer;
            int right = n - 1 - layer;

            List<Integer> elements = new ArrayList<>();

            // top row
            for (int j = left; j <= right; j++) {
                elements.add(grid[top][j]);
            }
            // right column
            for (int i = top + 1; i <= bottom - 1; i++) {
                elements.add(grid[i][right]);
            }
            // bottom row
            for (int j = right; j >= left; j--) {
                elements.add(grid[bottom][j]);
            }
            // left column
            for (int i = bottom - 1; i >= top + 1; i--) {
                elements.add(grid[i][left]);
            }

            int len = elements.size();
            int shift = k % len;
            if (shift != 0) {
                List<Integer> rotated = new ArrayList<>(len);
                for (int i = 0; i < len; i++) {
                    rotated.add(elements.get((i + shift) % len));
                }
                elements = rotated;
            }

            int idx = 0;
            // write back top row
            for (int j = left; j <= right; j++) {
                grid[top][j] = elements.get(idx++);
            }
            // right column
            for (int i = top + 1; i <= bottom - 1; i++) {
                grid[i][right] = elements.get(idx++);
            }
            // bottom row
            for (int j = right; j >= left; j--) {
                grid[bottom][j] = elements.get(idx++);
            }
            // left column
            for (int i = bottom - 1; i >= top + 1; i--) {
                grid[i][left] = elements.get(idx++);
            }
        }

        return grid;
    }
}

