public class Solution {
    public int maxCompatibilitySum(int[][] students, int[][] mentors) {
        int n = students.length;
        int m = mentors.length; // same as n
        int[][] match = new int[n][m];
        // precompute compatibility matrix
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int count = 0;
                for (int k = 0; k < students[i].length; k++) {
                    if (students[i][k] == mentors[j][k]) count++;
                }
                match[i][j] = count;
            }
        }
        int size = 1 << m;
        int[] dp = new int[size];
        Arrays.fill(dp, -1);
        return dfs(0, match, dp, m);
    }

    private int dfs(int mask, int[][] match, int[] dp, int m) {
        if (mask == (1 << m) - 1) return 0;
        if (dp[mask] != -1) return dp[mask];
        int student = Integer.bitCount(mask);
        int best = 0;
        for (int mentor = 0; mentor < m; mentor++) {
            if ((mask & (1 << mentor)) == 0) {
                int newMask = mask | (1 << mentor);
                int val = match[student][mentor] + dfs(newMask, match, dp, m);
                if (val > best) best = val;
            }
        }
        dp[mask] = best;
        return best;
    }
}

