public class Solution {
    public int maxCompatibilitySum(int[][] students, int[][] mentors) {
        int n = students.length;
        int[][] score = new int[n][n];
        int q = students[0].length;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                int s = 0;
                for (int k = 0; k < q; ++k) {
                    if (students[i][k] == mentors[j][k]) {
                        s++;
                    }
                }
                score[i][j] = s;
            }
        }

        int fullMask = (1 << n) - 1;
        int[] memo = new int[1 << n];
        Arrays.fill(memo, -1);

        return dfs(0, score, memo, fullMask);
    }

    private int dfs(int mask, int[][] score, int[] memo, int fullMask) {
        if (mask == fullMask) {
            return 0;
        }
        if (memo[mask] != -1) {
            return memo[mask];
        }
        int i = Integer.bitCount(mask); // next student index
        int best = 0;
        for (int j = 0; j < score.length; ++j) {
            if ((mask & (1 << j)) == 0) {
                int nextMask = mask | (1 << j);
                int val = score[i][j] + dfs(nextMask, score, memo, fullMask);
                if (val > best) {
                    best = val;
                }
            }
        }
        memo[mask] = best;
        return best;
    }
}

