public class Solution {
    public int[] longestObstacleCourseAtEachPosition(int[] obstacles) {
        int n = obstacles.length;
        int[] ans = new int[n];
        int[] tails = new int[n];
        int len = 0;
        for (int i = 0; i < n; i++) {
            int h = obstacles[i];
            int idx = upperBound(tails, 0, len, h);
            tails[idx] = h;
            if (idx == len) len++;
            ans[i] = idx + 1;
        }
        return ans;
    }

    private int upperBound(int[] arr, int low, int high, int target) {
        while (low < high) {
            int mid = (low + high) >>> 1;
            if (arr[mid] <= target) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return low;
    }
}

