    public int[] longestObstacleCourseAtEachPosition(int[] obstacles) {
        int n = obstacles.length;
        int[] ans = new int[n];
        int[] tail = new int[n + 1]; // tail[1..len] used
        int len = 0; // current maximum length

        for (int i = 0; i < n; i++) {
            int x = obstacles[i];
            // Binary search for the first index j such that tail[j] > x
            int l = 0, r = len;
            while (l < r) {
                int mid = (l + r) >>> 1;
                if (tail[mid + 1] <= x) {
                    l = mid + 1;
                } else {
                    r = mid;
                }
            }
            // l is the length of the longest non‑decreasing subsequence ending before i
            int curLen = l + 1;
            ans[i] = curLen;
            if (curLen > len) {
                len = curLen;
            }
            tail[curLen] = x;
        }
        return ans;
    }
}

