                int m = (l + r) >>> 1;
                if (tails[m] <= h) {
                    l = m + 1;
                } else {
                    r = m;
                }
            }
            int pos = l;           // position to place h
            ans[i] = pos + 1;      // length of longest subsequence ending at i
            if (pos == size) {
                size++;
            }
            tails[pos] = h;
        }
        return ans;
    }
}

