import java.util.*;

public class Solution {
    public int[] longestObstacleCourseAtEachPosition(int[] obstacles) {
        int n = obstacles.length;
        int[] dp = new int[n];
        int[] ans = new int[n];
        int len = 0;
        for (int i = 0; i < n; i++) {
            int x = obstacles[i];
            int pos = upperBound(dp, 0, len, x);
            dp[pos] = x;
            if (pos == len) {
                len++;
            }
            ans[i] = pos + 1;
        }
        return ans;
    }

    // Find first index in dp[0..len) where dp[idx] > target
    private int upperBound(int[] dp, int left, int right, int target) {
        while (left < right) {
            int mid = (left + right) >>> 1;
            if (dp[mid] <= target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }
}

