            } else if (rightVal > curVal) {
                left = mid + 1;
            } else {
                // Choose side with larger neighbor
                if (leftVal > rightVal) {
                    right = mid - 1;
                } else {
                    left = mid + 1;
                }
            }
        }
        return new int[]{-1, -1};
    }
}

