public class Solution {
    public int maxProductDifference(int[] nums) {
        int n = nums.length;
        long maxProd = Long.MIN_VALUE;
        int maxI = -1, maxJ = -1;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                long prod = (long) nums[i] * nums[j];
                if (prod > maxProd) {
                    maxProd = prod;
                    maxI = i;
                    maxJ = j;
                }
            }
        }

        long minProd = Long.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (i == maxI || i == maxJ || j == maxI || j == maxJ) {
                    continue;
                }
                long prod = (long) nums[i] * nums[j];
                if (prod < minProd) {
                    minProd = prod;
                }
            }
        }

        return (int) (maxProd - minProd);
    }
}

